class Main {
  import java.io._
  import java.util.StringTokenizer
  import java.util.Arrays

  import scala.collection.mutable
  import scala.util.Sorting
  import math.{abs, max, min}
  import mutable.{ArrayBuffer, ListBuffer}
  import scala.reflect.ClassTag

  val MOD = 1000000007
  val out = new PrintWriter(System.out)

  def solve(): Unit = {
    val N, Q = ni()
    val S = ns(N)
    val t, d = Array.ofDim[Char](Q)
    REP(Q) { i =>
      t(i) = nc()
      d(i) = nc()
    }

    def count(s: Array[Char], m: Int): Int = {
      def test(x: Int): Boolean = {
        x == 0 || {
          var p = x - 1
          REP(Q) { i =>
            if (s(p) == t(i)) {
              if (d(i) == 'L') p -= 1 * m
              else p += 1 * m
            }
            if (p == -1) return true
            if (p == N) return false // 逆から出た場合は失敗あつかい
          }
          false
        }
      }

      findMax(test, 0, N)
    }

    val L = count(S, 1)
    val R = count(S.reverse, -1)
    debug(s"L:$L R:$R")
    val ans = max(0, N - L - R)
    out.println(ans)
  }

  def findMax(f: Int => Boolean, min: Int, max: Int): Int = {
    var l = min
    var h = max + 1
    while(h - l > 1) {
      val x = (h + l) / 2
      if (f(x)) l = x
      else h = x
    }
    l
  }

  private val oj = System.getenv("ATCODER_DEBUG") == null

  def DEBUG(f: => Unit): Unit = {
    if (!oj){ f }
  }

  def debug(as: Array[Boolean]): Unit = DEBUG {
    debug(as.map(x => if(x) "1" else "0").mkString)
  }

  def debug(as: Array[Int]): Unit = DEBUG {
    debug(as.mkString(" "))
  }

  def debug(as: Array[Long]): Unit = DEBUG {
