    def readInts(n: Int): Array[Int] = Array.fill(n) { sc.nextInt() }
    def readLongs(n: Int): Array[Long] = Array.fill(n) { sc.nextLong() }
    def readLineStrings: Array[String] = sc.nextLine().split(' ')
    def readLineInts: Array[Int] = readLineStrings.map(_.toInt)
    def readLineLongs: Array[Long] = readLineStrings.map(_.toLong)
  }

  def main(args: Array[String]): Unit = solve(new Scanner(System.in))

  def solve(sc: Scanner): Unit = {
    val Array(n, q) = sc.readLineInts
    val s = sc.nextLine()
    val td = Array.fill(q) { val Array(t, d) = sc.readLineStrings; (t.charAt(0), d.charAt(0)) }

    val map = (0 until n).groupBy(s(_)).mapValues(_.toSet)

    import scala.collection.mutable
    class GolemImage(initialPosition: Int) {
      var imagePositions: Set[Int] = Set(initialPosition)
    }

    val images = mutable.Set.empty[GolemImage]
    td.reverse.foreach { case (t, d) =>
      images.filter { golemImage =>
        val imagePositions = golemImage.imagePositions
        golemImage.imagePositions = {
          val directlyAbove = imagePositions.filter(k => s.charAt(k) != t)
          val moved = {
            if (d == 'L') {
              imagePositions.map(_ + 1).filter { k =>
                k != n && s.charAt(k) == t
              }
            } else {
              imagePositions.map(_ - 1).filter { k =>
                k != -1 && s.charAt(k) == t
              }
            }
          }
          directlyAbove.union(moved)
        }
        golemImage.imagePositions.isEmpty
      }

      if (d == 'L' && s.head == t) {
        images.add(new GolemImage(0))
      } else if (d == 'R' && s.last == t) {
        images.add(new GolemImage(n - 1))
      }
    }

    println(n - images.map(_.imagePositions.size).sum)
  }
}

