import scala.io.{StdIn => in}
import scala.annotation.tailrec

object Main extends App {
  val Array(n, q) = in.readLine.split(" ").map(_.toInt)
  val s = in.readLine.toCharArray

  val op = Iterator.continually(in.readLine)
    .take(q)
    .map(_.split(" ").map(_.head.toInt))
    .toArray

  op.foreach(e => e(1) = if(e(1) == 'L') -1 else 1)

  def f(pos:Int):Int = {
    @tailrec
    def rec(cnt:Int, pos:Int):Int = {
      if(pos < 0 || n <= pos || cnt == q) pos match {
        case p if p < 0 => 0
        case p if 0 <= p && p < n => 1
        case p if n <= p => 2
      }
      else if(s(pos) == op(cnt)(0)) rec(cnt+1, pos + op(cnt)(1))
      else rec(cnt+1, pos)
    }
    rec(0,pos)
  }

  val left = binarySearch(n,0)
  val right = binarySearch(n,1)

  // println(left + " " + right)
  val ans = right - left
  println(ans)

  def binarySearch(num:Int, find:Int):Int = {
    var left = 0
    var right = num

    @tailrec
    def loop(left:Int, right:Int):Int = {
      if(right - left < 2) left
      else {
        val mid = (left + right) / 2
        if(f(mid) <= find) loop(mid,right)
        else loop(left, mid)
      }
    }
    loop(left, right)
  }
}

