void dfs(int pos, int turn){
    if (turn >= 0 && pos<N-1){
        for(int i=turn-1; i>=0; --i){
            if(pos+1<N && t[i][0]==s[pos+1] && d[i]==L){
                if(!visited[pos+1]){
                    visited[pos+1]=true;
                    dfs(pos+1, i);
                }else{
                    break;
                }
            }
        }
    }
    if (turn >= 0 && pos > 1){
        for(int i=turn-1; i>=0; --i){
            if(pos-1>=0 && t[i][0]==s[pos-1] && d[i]==R){
                if(!visited[pos-1]){
                    visited[pos-1] = true;
                    dfs(pos-1, i);
                }else{
                    break;
                }
            }
        }
    }
}

