  cin >> N >> Q;
  cin >> s;
  for(int i=0; i<Q; i++){
    string t_temp, d_temp;
    cin >> t_temp >> d_temp;
    wizerd.push_back(t_temp+d_temp);
  }
  long long int lower_limit = BinarySearch(-1, N, -1);
  long long int higher_limit = BinarySearch(lower_limit, N, 1);
  cout << higher_limit - lower_limit << endl;
  return 0;
}

