int getint() { //10進数字の入力をint型で返す関数
    char C;
    while (!isdigit(C = getchar())); //10進数字でない入力を飛ばす部分
    int x = C - '0'; //1桁目を入力、数字のASCIIコードの引き算でint型へ変換
    while (isdigit(C = getchar())) x = x * 10 + C - '0'; //次の桁の数字を処理、以前の入力を10倍した上で次の入力を加算している。
    return x;
}


int main() {
    cin.tie(0); //iostreamスピードアップ
    ios::sync_with_stdio(false); //iostreamスピードアップ


    int N, Q;
    N = getint();
    Q = getint();
    char S[200000]; //標準入力の最大値2*10^5
    rep(i, N) S[i] = getchar(); //charの配列に標準入力を1文字ずつ格納
    char T[200000], D[200000]; //tとdを格納する配列
    rep(i, Q) {
        getchar(); //標準入力の改行を飛ばす部分
        T[i] = getchar(); 
        getchar(); //標準入力のスペースを飛ばす部分
        D[i] = getchar();;
    }
    int L = 0; //生き残っているゴーレムの左端のスライス
    int R = N-1; //生き残っているゴーレムの右端のスライス
    for (int i = Q - 1; i >= 0; i--) { //標準入力を逆からたどり、生き残るゴーレムの左端と右端を動かしていく、O(Q)で終了
        if (R > 0 && D[i] == 'R' && S[R] == T[i]) R--;
        else if (R < N && D[i] == 'L' && S[R + 1] == T[i]) R++;
        if (L > 0 && D[i] == 'R' && S[L - 1] == T[i]) L--;
        else if (L < N && D[i] == 'L' && S[L] == T[i]) L++;
    }
    co(R - L + 1);
    return 0;
}

