	}
	return p;
}

bool leftBound(int n) { return !(finalPos(n) == -1); }
bool rightBound(int n) { return !(finalPos(n) == N); }

template<typename T>
T BinarySearch(T ng, T ok, function<bool(T)> func) {
	while (abs(ok - ng) > 1) {
		T mid = (ng + ok) / 2;
		(func(mid) ? ok : ng) = mid;
	}
	return ok;
}

int solve() {
