    vector<pair<char,char>> v(q);//呪文を格納
    int l=-1,r=s.size(),lb=l,rb=r;//lbは左に落ちるゴレムのうち最も右にあるやつ
    for(int i=0;i < v.size();i++){
        cin >> v.at(i).first >> v.at(i).second;
    }

    reverse(v.begin(),v.end());//逆から実行して、どこまでいくかしらべればok(追い越さないので)

    for(int j=0;j < v.size();j++){

        if(v.at(j).second == 'R'){
            if(r-1 >= 0 && v.at(j).first==s.at(r-1)){
                r--;
                rb=min(r,rb);
            }
            if(l-1>=0 && v.at(j).first==s.at(l-1)){
                l--;
            }
        }else{//Lの時
            if(r+1 < s.size() && v.at(j).first==s.at(r+1)){
                r++;//境界が逆に動く場合もある
            }
            if(l+1<s.size() && v.at(j).first==s.at(l+1)){
                l++;
                lb=max(lb,l);
            }   
        }
    }//既に持ってかれてる可能性

    if(lb<rb){
        cout << rb-lb-1 << endl;
    }else{
        cout << s.size() << endl;
    }
}

