int syori(int x, int q, string s, char t[], char d[]){
    rep(i,q){
        if(s[x]==t[i]){
            if(d[i]=='L'){
                x--;
            }else{
                x++;
            }
            if(x==-1){
                return 1;
            }
            if(x==s.size()){
                return 3;
            }
        }
    }
    return 2;
}

