int check(const string &s, const vector<pchar> &td, int pos) {
  //範囲for文という表現　配列やコンテナを簡潔に扱うためのfor文の別表現である。　
  // 範囲for文は配列または、begin()およびend()で表される範囲内の全ての要素に対して、処理を実行する。
  for (auto c : td) {
    if (c.first == s[pos]) {  //クエリに該当するものだった場合
      if (c.second == 'R')
        pos++;
      else if (c.second == 'L')
        pos--;

      if (pos < 0)
        return -1;
      else if (s.length() <= pos)
        return 1;
    }
  }

  return 0;
}

