  string s;
  cin >> s;

  vector<pchar> td(Q);
  FOR(i, 0, Q) cin >> td[i].first >> td[i].second;

  int fall_left, fall_right;

  //[low,high) //[ok,ng)
  int low, mid, high;
  low = 0;
  high = N;

  while (high - low > 1) {  //右側に落ちる下限
    mid = (high + low) / 2;
    if (check(s, td, mid) == 1)
      high = mid;  //落ちた
    else
      low = mid;
  }

  fall_right = (N - 1) - low;

  low = 0;
  high = N;
  //(low,high]

  while (high - low > 1) {  //左側に落ちる上限
    mid = (high + low) / 2;
    if (check(s, td, mid) == -1)
      low = mid;  //落ちた場合
    else
      high = mid;
  }

  fall_left = high;

  cout << N - (fall_left + fall_right) << endl;
}

