        cin >> qu.t >> qu.d;

    int ans = n;

    int lt = -1, rt = n - 1;
    while (lt < rt - 1) {
        int mid = (lt + rt) / 2;
        if (where(mid, s, qs) == LEFT)
            lt = mid;
        else
            rt = mid;
    }
    cerr << "last LEFT: " << lt << endl;
    ans -= rt;

    lt = rt;
    rt = n;
    while (lt < rt - 1) {
        int mid = (lt + rt) / 2;
        if (where(mid, s, qs) == STAY)
            lt = mid;
        else
