// 0残り、1左溢れ、2右溢れ
int check(int pos) {
	for (int i = 0; i < Q; i++) {
		if (pos < 0) return 1;
		if (pos >= N) return 2;
		if (s[pos] == t[i]) {
			if (d[i] == 'L') {
				pos--;
			}
			if (d[i] == 'R') {
				pos++;
			}
		}
	}
	if (pos < 0) return 1;
	if (pos >= N) return 2;
	return 0;
}

void solve() {

	cin >> N >> Q >> s;
	int ans = N;
	for (int i = 0; i < Q; i++) {
		cin >> t[i] >> d[i];
	}

	// 左溢れチェック
	int top = N - 1;
	int bottom = 0;
	int mid;
	int overL = top;
	while (top >= bottom) {
		mid = (top + bottom) / 2;
		int tmp = check(mid);
		int tmp2 = check(mid + 1);
		if (tmp == 1 && tmp2 != 1) {
			overL = mid;
			break;
		}
		if (tmp == 1 && tmp2 == 1) bottom = mid + 1;
		else top = mid - 1;
	}
	top = N - 1;
	bottom = 0;
	int overR = bottom;
	while (top >= bottom) {
		mid = (top + bottom) / 2;
		int tmp = check(mid);
		int tmp2 = check(mid + 1);
		if (tmp != 2 && tmp2 == 2) {
			overR = mid;
			break;
		}
		if (tmp == 2 && tmp2 == 2) top = mid - 1;
		else bottom = mid + 1;
	}

	ans = overR - overL;
	if (ans < 0) ans = 0;

	cout << ans << endl;

	return;

}

int main() {

	cin.tie(0);
	ios::sync_with_stdio(false);

	solve();

	return 0;

}

