// 左に落ちないならtrue
bool CL(int x, int Q, int N, string S, vector<char> t, vector<char> d){
    for(int i=0; i<Q; i++){
        if(S[x-1]==t[i]){
            if(d[i]-'L'==0){
                x = x-1;
            }else{
                x++;
            }
        }
        if(x < 1){
            return false;
        }
        if(x > N){
            return true;
        }
    }
    return true;
}

// 右に落ちないならtrue
bool CR(int x, int Q, int N, string S, vector<char> t, vector<char> d){
    for(int i=0; i<Q; i++){
        if(S[x-1]==t[i]){
            if(d[i]-'L'==0){
                x--;
            }else{
                x++;
            }
        }
        if(x < 1){
            return true;
        }
        if(x > N){
            return false;
        }
    }
    return true;
}


