map<int, int> memo[201010];
int f(int i, int q) {
	if (memo[i].count(q)) return memo[i][q];
	if (Q == q) return 0;

	if (T[q] == S[i]) {
		if (D[q] == 'L' and i == 0) return memo[i][q] = 1;
		if (D[q] == 'R' and i == N - 1) return memo[i][q] = 1;

		if (D[q] == 'L') return memo[i][q] = f(i - 1, q + 1);
