int simulation(int pos){
  for (int i = 0; i < Q; ++i) {
    if (pos==0)
      return -1;
    if(pos==N+1)
      return 1;

    if(s[pos-1]==t[i]){
      if(d[i]=='R')
        pos++;
      else
        pos--;
    }
  }

  if (pos==0)
    return -1;
  if(pos==N+1)
    return 1;
  return 0;
}

