const int N = 2e2 + 7, M = 1e5 + 7;
const LL MOD = 1e9 + 7;

LL f[N][M], inv[M], tmp[M];
int a[N];

LL qpow(LL x, LL y){
	LL z = 1;
	while (y){
		if (y % 2) z = z * x % MOD;
		x = x * x % MOD;
		y /= 2;
	}
	return z;
}

int main(){

	int n, X;
	scanf("%d%d", &n, &X);
	for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
	sort(a + 1, a + n + 1);
	reverse(a + 1, a + n + 1);

	inv[0] = 1;
	for (int i = 1; i <= n; i++) inv[i] = qpow(i, MOD - 2);


	LL t = 1;
	for (int i = 1; i <= n; i++) t = t * i % MOD;

	tmp[X] = inv[n];
	for (int i = 1; i <= n; i++){
		for (int j = 0; j < a[i]; j++){
			for (int k = j; k <= X; k += a[i]){
				f[i][j] += tmp[k];
			}
			//printf("%d %d %lld\n", i, j, f[i][j] * t % MOD);
		}
		//if (i == 2) printf("%lld^*^\n", tmp[5] * t % MOD);
		for (int j = 0; j < a[i]; j++){
			tmp[j] = (tmp[j] + f[i][j] * inv[n - i]) % MOD;
		}
	}
	LL ans = 0;

	for (int i = 0; i < a[n]; i++){
		ans = (ans + f[n][i] * i) % MOD; 
		//printf("%d %lld\n", i, f[n][i] * t % MOD);
	}
	for (int i = 1; i <= n; i++) ans = ans * i % MOD;

	printf("%lld", ans);
	return 0;
}
