bool check(int position, vector<char[2]> &work_list, string road_list,bool go_left) {
	for (int i = 0; i < work_list.size(); ++i) {
		char key = work_list[i][0];
		int direction = work_list[i][1] == 'L' ? -1 : 1;
		if (key == road_list[position]) {
			position += direction;
			if (go_left) {
				if (position == -1) {
					return true;
				}
				else if (position == road_list.size()) {
					return false;
				}
			}
			else {
				if (position == road_list.size()) {
					return true;
				}
				else if (position == -1) {
					return false;
				}
			}
		}
	}
	return false;
}

