template<class T, class U>
T lower_bound_on(T first, T last, const U& value, const function<U(T)>& fn) {
	T it, count, step;
	count = last - first;
	while (count > 0) {
		it = first;
		step = count / 2;
		it += step;
		if (fn(it) < value) {
			first = ++it;
			count -= step + 1;
		} else {
			count = step;
		}
	}
	return first;
}

template<class T, class U>
T upper_bound_on(T first, T last, const U& value, const function<U(T)>& fn) {
	T it, count, step;
	count = last - first;
	while (count > 0) {
		it = first;
		step = count / 2;
		it += step;
		if (!(value < fn(it))) {
			first = ++it;
			count -= step + 1;
		} else {
			count = step;
		}
	}
	return first;
}

