bool check_r(int index) {
  rep(i, Q) {
    if (T[i] == s[index]) {
      if (D[i] == 'L') {
        if (index == 0) {
          return false;
        }
        index--;
      } else {
        if (index == s.size() - 1) {
          return true;
        }
        index++;
      }
    }
  }
  return false;
}

void solve_l() {
  int low = 0;
  int high = s.size() - 1;
  while (low <= high) {
    int mid = (low + high) / 2;
    if (check_l(mid)) {
      if (mid == s.size() - 1 || !check_l(mid + 1)) {
        left_g = mid + 1;
        // cout << "mid " << mid << " left_g " << left_g << endl;
        break;
      }
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
}

void solve_r() {
  int low = 0;
  int high = s.size() - 1;
  while (low <= high) {
    int mid = (low + high) / 2;
    if (check_r(mid)) {
      if (mid == 0 || !check_r(mid - 1)) {
        right_g = s.size() - (mid);
        // cout << "mid " << mid << " right_g " << right_g << endl;
        break;
      }
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
}

