            REP(jj, m[t].size()) {
                int j = m[t][m[t].size() - jj - 1];
                if (j < N-1) g[j+1] += g[j];
                g[j] = 0;
            }
        }
    }

    long sum = 0;
    REP(j, N) {
        sum += g[j];
    }

    cout << sum << endl;
}

