// 左に落ちないならtrueを返す関数
bool CL(int x, vector<char> t, vector<char> d){
    for(int i=0; i<Q; i++){
        if(S[x-1] == t[i]){
            if(d[i] == 'L'){
                x--;
            }else{
                x++;
            }
        }
        if(x < 1){
            return false;
        }
        if(x > N){
            return true;
        }
    }
    return true;
}

// 右に落ちないならtrueを返す関数
bool CR(int x, vector<char> t, vector<char> d){
    for(int i=0; i<Q; i++){
        if(S[x-1] == t[i]){
            if(d[i] == 'L'){
                x--;
            }else{
                x++;
            }
        }
        if(x < 1){
            return true;
        }
        if(x > N){
            return false;
        }
    }
    return true;
}


int main(){
    cin >> N >> Q >> S;
    vector<char>t(Q);
    vector<char>d(Q);
    for(int i=0; i<Q; i++){
        cin >> t[i] >> d[i];
    }

    // 左に落ちない最小値ubL
    // ubL == N+1の時は全部落ちる
    int lbL=0, ubL = N + 1;
    while( ubL-lbL > 1 ){
        int mid = (lbL+ubL)/2;
        if(CL(mid, t, d)){
            ubL = mid;
        }else{
            lbL = mid;
        }
    }

    // 右に落ちない最大値lbR
    // lbL == 0の時は全部落ちる
    int lbR=0, ubR = N + 1;
    while( ubR-lbR > 1 ){
        int mid = (lbR + ubR) / 2;
        if (CR(mid, t, d)) {
            lbR = mid;
        } else {
            ubR = mid;
        }
    }

    // 出力
    int ans;
    if(lbR == 0 || ubL == N + 1){
        cout << 0;
    }else{
        ans = lbR - ubL + 1;
        cout << ans;
    }
    return 0;
}

