int main(){
  int n,q;
  cin>>n>>q;
  string s;
  cin>>s;

  vector<pair<char,char>> que;
  rep(i,q){
    string x,y;
    cin>>x>>y;
    que.push_back({x[0], y[0]});
  }

  auto sim = [&](int p){
    rep(i,q){
      if(s[p] == que[i].first){
        if(que[i].second == 'R') p++;
        else p--;
      }
      if(p<0) return -1;
      if(p>=n) return 1;
    }
    return 0;
  };

  int ans = n;

  // left
  {
    int l=-1, r=n;
    while(r-l>1){
      int m = (l+r)/2;
      if(sim(m) >= 0) r = m;
      else l = m;
    }
    ans -= r;
  }

  // right
  {
    int l=-1, r=n;
    while(r-l>1){
      int m = (l+r)/2;
      if(sim(m) <= 0) l = m;
      else r = m;
    }
    ans -= n-r;
  }

  cout << ans << endl;

  return 0;
}

