using namespace std;

int main(){
    int n, q;
    cin >> n >> q;
    string s;

    cin >> s;

    pair<char, char> p[200010];

    for(int i = 0;i < q;i++){
        cin >> p[i].first >> p[i].second;
    }

    int die[200010] = {};

    memset(die, -1, sizeof(die));
    int l = -1, r = n;

    int maxl = -1;
    int maxr = n;

    for(int i = q-1;i >= 0;i--){
        if(p[i].second == 'L'){
            if(l+1 < n && s[l+1] == p[i].first){
                l++;
                if(die[l] == -1){
                    die[l] = i;
                }
                maxl = max(l, maxl);
            }

            if(r+1 < n && s[r+1] == p[i].first){
                r++;
                if(die[r] == -1){
                    die[r] = i;
                }
                maxr = min(r, maxr);
            }
        }else{
            if(l-1 >= 0 && s[l-1] == p[i].first){
                l--;
                if(die[l] == -1){
                    die[l] = i;
                }
                maxl = max(l, maxl);
            }

            if(r-1 >= 0 && s[r-1] == p[i].first){
                r--;
                if(die[r] == -1){
                    die[r] = i;
                }
                maxr = min(r, maxr);
            }
        }
    }

    maxl++;
    maxr--;
    for(int i = q-1;i >= 0;i--){
        if(p[i].second == 'L'){
            if(s[maxr+1] == p[i].first && die[maxr+1] > i){
                maxr++;
            }
        }else{
            if(s[maxl-1] == p[i].first && die[maxl-1] > i){
                maxl--;
            }
        }
    }

    maxl--;
    maxr++;

    int die2[200010] = {};
    for(int i = 0;i <= maxl;i++){
        die2[i] = 1;
    }

    for(int i = n-1;i >= maxr;i--){
        die2[i] = 1;
    }

    int cnt = 0;
    for(int i = 0;i < n;i++){
        cnt += die2[i];
    }

    cout << n-cnt << endl;
    return 0;
}

