		std::deque<FL> nextfallpos;
		char t = td[q].first;
		char d = td[q].second;
		if (d == 'L') {
			if (s[0] == t)
				nextfallpos.push_back({0, 1});
			for (auto it = fallpos.begin(), end = fallpos.end(); it != end; ++it) {
				auto pos = *it;
				if (s[pos.first] == t)
					++pos.first;
				if (pos.last < N && s[pos.last] == t)
					++pos.last;
				if (!nextfallpos.empty() && nextfallpos.rbegin()->last == pos.first)
					nextfallpos.rbegin()->last = pos.last;
				else
					nextfallpos.push_back(pos);
			}
		} else {
			if (s[N-1] == t) {
				nextfallpos.push_front({N-1, N});
			}
			for (auto it = fallpos.rbegin(), end = fallpos.rend(); it != end; ++it) {
				auto pos = *it;
				if (s[pos.last-1] == t)
					--pos.last;
				if (pos.first > 0 && s[pos.first-1] == t)
					--pos.first;
				if (!nextfallpos.empty() && nextfallpos.begin()->first == pos.last)
					nextfallpos.begin()->first = pos.first;
				else
					nextfallpos.push_front(pos);
			}
		}
		fallpos = std::move(nextfallpos);
	}

	int fallen = 0;
	for (auto& pos: fallpos) {
		fallen += pos.last - pos.first;
	}
	std::cout << (N-fallen) << "\n";
}

