using namespace std;

int n, q, ans, ds[200020];
string s;
map<int, int> memo[200020];
set<int> mv[26];

int dfs(int pos, int turn)
{
	auto &res = memo[turn][pos];
	if (res)
	{
		return res;
	}
	int c = s[pos] - 'A';
	auto it = lower_bound(mv[c].begin(), mv[c].end(), turn);
	if (it == mv[c].end())
	{
		return res = 1;
	}
	int k = *it;
	pos += ds[k];
	if (pos < 0 || pos >= n)
	{
		return res = -1;
	}
	turn = k + 1;
	return res = dfs(pos, turn);
}

void solve(void)
{

	cin >> n >> q >> s;

	for (int i = 0; i < q; i++)
	{
		char a, d;
		cin >> a >> d;
		mv[a-'A'].insert(i);
		ds[i] = d == 'R' ? 1 : -1;
	}
	ans = n;
	for (int i = 0; i < n; i++)
	{
		if (dfs(i, 0) < 0) ans--;
	}
	cout << ans << endl;
}

int main(void)
{
	solve();
	//cout << "yui(*-v・)yui" << endl;
	return 0;
}

