    REP(i, q) cin >> t[i] >> d[i];

    auto f = [&](int m, int num){
        REP(i, q)
        {
            if(t[i] == s[m])
            {
                m += (d[i] == 'L' ? -1 : 1);
            }
            if(m == num) return true;
            else if(m >= n) return false;
            else if(m < 0) return false;
        }
        return false;
    };

    int r, l;
    int ok = 0, ng = n+1;
    while(abs(ok - ng) > 1)
    {
        int mid = (ok + ng) / 2;
        if(f(mid-1, -1)) ok = mid;
        else ng = mid;
    }
    l = ok;

    ok = 0, ng = n+1;
    while(abs(ok - ng) > 1)
    {
        int mid = (ok + ng) / 2;
        if(f(n - mid, n)) ok = mid;
        else ng = mid;
    }
    r = ok;
    cout << max(0, n - l - r) << endl;
}

