bool leftfall (int x) {
    if (x < 1) return true;
    if (x > N) return false;
    rep(i,Q) {
        if (S[x-1] == t[i]) {
            if (d[i] == 'L') x--;
            else x++;
        }
        if (x < 1) return true;
        if (x > N) return false;
    }
    return false;
}

bool rightfall (int x) {
    if (x < 1) return false;
    if (x > N) return true;
    rep(i,Q) {
        if (S[x-1] == t[i]) {
            if (d[i] == 'L') x--;
            else x++;
        }
        if (x > N) return true;
        if (x < 1) return false;
    }
    return false;
}
