    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> N >> Q >> S;
    t.resize(Q); d.resize(Q);
    rep(i,Q) cin >> t[i] >> d[i];

    int left = 0;
    int right = N+1;
    while(right - left > 1) {
        int mid = (right + left) / 2;
        if (leftfall(mid)) left = mid;
        else right = mid;
    }
    int ansl = left;

    left = 0;
    right = N+1;
    while(right - left > 1) {
        int mid = (right + left) / 2;
        if (rightfall(mid)) right = mid;
        else left = mid;
    }
    int ansr = left;

    cout << max(0,ansr - ansl) << endl;
}

