vector<vector<int> > query(30);
vector<P> Query;
int N, Q;
string s;

int dfs(int time, int i, int last){
  if(i == -1 || i == N) return i == last;
  time = *lower_bound(query[s[i] - 'A'].begin(), query[s[i] - 'A'].end(), time);
  if(time == Q) return 0;

  char t = Query[time].first, d = Query[time].second;
  assert(t == s[i]);
  int res = 0;
  if(d == 'L') res = dfs(time+1, i - 1, last);
  else res = dfs(time + 1, i + 1, last);
  return res;
}

