	for(int i = 1; i < N + 1; i++)
	{
		golemNum[0][i] = 1;
		golemNum[1][i] = 0;
	}

	for(int i = 0; i < Q; i++)
	{
		std::cin >> t >> d;

		if(d[0] == 'L')
		{
			for(int j = 1; j < N + 1; j++)
			{
				if(s[j - 1] == t[0])
				{
					golemNum[(i + 1) % 2][j - 1] += golemNum[i % 2][j];
				}
				else
				{
					golemNum[(i + 1) % 2][j] += golemNum[i % 2][j];
				}
			}
		}
		else
		{
			for(int j = 1; j < N + 1; j++)
			{
				if(s[j - 1] == t[0])
				{
					golemNum[(i + 1) % 2][j + 1] += golemNum[i % 2][j];
