int find_me(int left ,int right, bool direction) {
    int ans = left - 1;
    if (!direction) ans = right + 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (check(mid, direction)) {
            ans = mid;
            if (direction) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        } else {
            if (direction) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
    } 


    return ans;
}

