int main() {
  int n, q; cin >> n >> q;

  vector<int> golems(n, 1);

  string s; cin >> s;
  vector<vector<int>> ranges(26);
  for (int i = 0; i < n; i++) {
    int alph = s[i] - 'A';
    ranges[alph].push_back(i);
  }

  for (int i = 0; i < q; i++) {
    char t, d; cin >> t >> d;
    int alph = t - 'A';
    vector<int> obj;
    if (!ranges[alph].empty()) obj = ranges[alph];

    if (d == 'L') {
      for (int index : obj) {
        if (index != 0) golems[index - 1] += golems[index];
        golems[index] = 0;
      }
    }

    if (d == 'R') {
      vector<pair<int, int>> changes;
      for (int index : obj) {
        if (index != n - 1 && golems[index] != 0) {
          changes.emplace_back(index + 1, golems[index]);
        }
        golems[index] = 0;
      }
      for (auto ch : changes) {
        golems[ch.first] += ch.second;
      }
    }
  }

  int ans = accumulate(golems.begin(), golems.end(), 0);
  cout << ans << endl;
}

