int main() {
    int N, Q;
    char t, d;
    string s;
    vector<int> alphabet_idxes[26];
    unsigned int golem[100000];
    unsigned int sum=0;
    cin >> N >> Q;
    cin >> s;
    // initialize golem
    for (int i = 0; i < N; i++) golem[i] = 1;
    // stock char --> index hash
    for (int i = 0; i < N; ++i) {
        alphabet_idxes[s[i] - 'A'].push_back(i);
    }

    for (int q = 0; q < Q; ++q) {
        cin >> t >> d;
        // search position to move golem
        // move left
        for (int idx : alphabet_idxes[t - 'A']) {
            if (d == 'L') {
                if (idx == 0) golem[idx] = 0;
                else {
                    golem[idx - 1] += golem[idx];
                    golem[idx] = 0;
                }
            }
            // move right
            else {
                if (idx == N - 1) golem[idx] = 0;
                else {
                    golem[idx + 1] += golem[idx];
                    golem[idx] = 0;
                }
            }
        }
    }

    // output
    for (int j = 0; j < N; ++j) {
        sum += golem[j];
    }
    cout << sum << endl;

    return 0;
}

