int solveNaiveFast(int N, int Q, string s, vector<char> t, vector<char> d) {

	for (int p = 0; p < N; p++) {
		int c = s[p] - 'A';
		pos[c][sz[c]++] = p + 1;
	}

	REP(i, N + 2) cnt[i] = 1;
	for (int q = 0; q < Q; q++) {
		int c = t[q] - 'A';
		if (d[q] == 'L') {
			for (int i = 0; i < sz[c]; i++) {
				int p = pos[c][i];
				cnt[p - 1] += cnt[p];
				cnt[p] = 0;
			}
		}
		else {
			for (int i = sz[c] - 1; i >= 0; i--) {
				int p = pos[c][i];
				cnt[p + 1] += cnt[p];
				cnt[p] = 0;
			}
		}
	}

	int ans = 0;
	for (int p = 1; p <= N; p++)
		ans += cnt[p];

	return ans;
}

