		pos[s[p] - 'A'].push_back(p + 1);

	vector<int> cnt(N + 2, 1);
	for (int q = 0; q < Q; q++) {
		int c = t[q];
		const vector<int>& v = pos[c - 'A'];
		if (d[q] == 'L') {
			for (int i = 0; i < v.size(); i++) {
				int p = v[i];
				cnt[p - 1] += cnt[p];
				cnt[p] = 0;
			}
		}
		else {
			for (int i = (int)v.size() - 1; i >= 0; i--) {
				int p = v[i];
				cnt[p + 1] += cnt[p];
				cnt[p] = 0;
			}
		}
	}

	int ans = 0;
	for (int p = 1; p <= N; p++)
		ans += cnt[p];

	return ans;
}

