int check(int x, int N, int Q, string S, char* T, int* D) {
  REP(i, Q) {
    if(S[x] == T[i]) {
      x += D[i];
      if(x < 0) return -1;
      if(x >= N) return 1;
    }
  }
  return 0;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int N, Q;
  cin >> N >> Q;
  string S;
  cin >> S;
  char T[200000];
  int D[200000];
  REP(i, Q) {
    char d;
    cin >> T[i] >> d;
    D[i] = d == 'L' ? -1 : 1;
  }

  int L, R;
  { //左に消えない右端
    int min = 0, max = N;
    while(min < max) {
      int mid = (max + min) / 2;
      if(check(mid, N, Q, S, T, D) == -1) {
        min = mid + 1;
      } else {
        max = mid;
      }
    }
    L = min;
  }
  { //右に消える左端
    int min = 0, max = N;
    while(min < max) {
      int mid = (max + min) / 2;
      if(check(mid, N, Q, S, T, D) == 1) {
        max = mid;
      } else {
        min = mid + 1;
      }
    }
    R = min;
  }
  cout << R - L << endl;
}

