int check_over(int n)
{
    pair<char, int> a = mp[n];

    int now = n;

    for (unsigned int i = 0; i < spel.size(); i++)
    {
        if (mp[now].first == spel[i].first)
        {
            if (spel[i].second == 'R')
                now += 1;
            else
                now -= 1;
        }
    }

    return now;
}

int main(int argc, char *argv[])
{
    int N, Q;
    cin >> N >> Q;

    char a, b;

    for (int i = 0; i < N; i++)
    {
        cin >> a;
        mp.push_back(make_pair(a, 1));
    }

    for (int i = 0; i < Q; i++)
    {
        cin >> a >> b;
        spel.push_back(make_pair(a, b));
    }

    int c, d;
    d = 1;

    int n = 0, m = N - 1;

    if (check_over(0) == -1)
    {
        while (true)
        {
            c = (n + m) / 2;
            d = check_over(c);
            if (d < -1)
                n = (n + m) / 2;
            else if (d > -1)
                m = (n + m) / 2;
            else
            {
                if (check_over(c + 1) != -1)
                    break;
                else
                    n += 2;
            }
        }
    }
    else
    {
        c = -1;
    }


    int c2;

    n = 0;
    m = N - 1;

    if (check_over(N - 1) == N)
    {
        while (true)
        {
            c2 = (n + m) / 2;
            d = check_over(c2);
            if (d < N)
                n = (n + m) / 2;
            else if (d > N)
                m = (n + m) / 2;
            else
            {
                if (check_over(c - 1) != N)
                    break;
                else
                    n -= 2;
            }
        }
    }else{
        c2 = N;
    }

    int ans;

    ans = N - (c+1) - (N - c2);
    cout << ans;

    return 0;
}

