int solve(int now){
    for(int i=0;i<q;i++){
        if(s[now]==t[i]){
            if(d[i]=='L') now--;
            else now++;
            if(now==-1) return -1;
            else if(now==n) return 1;
        }
    }
    return 0;
}

int main(){
    cin>>n>>q;
    cin>>s;
    for(int i=0;i<q;i++){
        cin>>t[i]>>d[i];
    }

    long long int low=-1,up=n,mid;
    while(up-low>1){
        mid=(up+low)/2;
        //上半分か下半分の条件を求める
        //上半分の時
        if(solve(mid)<1){
            low=mid;
        }

        //下半分の時
        else{
            up=mid;
        }
    }
    int ans=n;
    ans-=n-low;

