    for (int i = 0; i < Q; ++i) {
        if (s[p] == td[i].first) {
            if (td[i].second == 'L') {
                --p;
            } else {
                ++p;
            }
        }
        if (p >= N) {
            return true;
        }
    }
    return false;
}

bool checkR(const vector<pair<char, char>>& td, int p) {
    for (int i = 0; i < Q; ++i) {
        if (s[p] == td[i].first) {
            if (td[i].second == 'R') {
                ++p;
            } else {
                --p;
            }
        }
        if (p < 0) {
            return true;
        }
    }
    return false;
}

