  fill(check,check+200000,2);//2は未定
  //cout << bsl(0,N-1) << endl;
  //cout << bsr(0,N-1) << endl;

  int l = bsl(0,N-1);
  int r = bsr(0,N-1);
  int ans = N;
  if(l != -1){
    ans -= l + 1;
  }
  if(r != -1){
    ans -= N - r;
  }

  cout << ans << endl;
  return 0;
}

