#include <stdio.h>
#include <stdlib.h>

#define MAX_N (200000)
#define MAX_Q (200000)
#define SIZE_BUF (30)

using namespace std;

int binary_search(int N, int Q, const char *cs, const char *ts, const char *ds,
                  int x) {
  int le = -1, ri = N - 1;
  while (ri > le + 1) {
    const int m = (le + ri) / 2;
    int pos = m;
    for (int q = 0; q < Q; q++) {
      const char t = ts[q], d = ds[q];
      if (t == cs[pos]) {
        if (d == 'L') {
          pos--;
        } else {
          pos++;
        }
        if (pos < 0) {
          pos = -1;
          break;
        }
        if (pos >= N) {
          pos = N;
          break;
        }
      }
    }
    if (pos >= x) {
      ri = m;
    } else {
      le = m;
    }
    if (ri == le + 1 && pos < x) {
      ri = N;
    }
  }
  return ri;
}

int main(int argc, char *argv[]) {
  // read inputs
  int N, Q;
  char cs[MAX_N + 1], ts[MAX_Q], ds[MAX_Q], buf[SIZE_BUF];
  scanf("%d %d", &N, &Q);
  fgets(buf, SIZE_BUF, stdin);
  scanf("%s", cs);
  fgets(buf, SIZE_BUF, stdin);
  for (int q = 0; q < Q; q++) {
    ts[q] = fgetc(stdin);
    fgetc(stdin);
    ds[q] = fgetc(stdin);
    fgets(buf, SIZE_BUF, stdin);
  }

  // solve binary
  const int l = binary_search(N, Q, cs, ts, ds, 0),
            r = binary_search(N, Q, cs, ts, ds, N);
  // printf("l = %d, r = %d\n", l, r);
  printf("%d\n", r - l);

  return 0;
}

