                    g.at(j) += g.at(j+1);
                    g.at(j+1) = 0;
                } else continue;
            }
        }
    }
    int sum = accumulate(g.begin(), g.end(), 0);
    int ans = sum - g.at(0) - g.at(s.size() + 1);
    cout << ans << endl;
}

