bool checkLeft(int x, int k, string &s, vector<char> &t, vector<char> &d)
{
	for(int i = 0; i < t.size(); ++i)
	{
		if(t[i] == s[x])
		{
			x += (d[i] == 'L' ? -1 : 1);
		}

		if(s[x] == '_')
		{
			return x == k;
		}
	}

	return false;
}

