char simulation(const string &s, vector<pair<char, char>> magics, int pos)
{
    if (s.size()<=pos) return 'R';
    if (pos<0) return 'L';

    for (auto magic: magics)
    {
        if (s[pos] == magic.first)
        {
            if (magic.second == 'L')
                --pos;
            else
                ++pos;

            if (pos == s.size()) return 'R';
            if (pos == -1) return 'L';
        }
    }
    return 'C';
}

int main()
{
    int n, q;
    cin >> n >> q;
    if (n == 0)
        return 0;

    string s;
    cin >> s;

    vector<pair<char, char>> magics(q);
    rep(i, 0, q)
        cin >> magics[i].first >> magics[i].second;

    int cnt = 0;
    // count gollems who will fall into right side
    {
        int left = 0;
        int right = n;
        while (left<right)
        {
            int center = (left+right)>>1;

            char result = simulation(s, magics, center);
            if (result == 'C' or result == 'L')
                left = center+1;
            else
                right = center;
        }
        cnt += n-left;
    }

    // count gollems who will fall into left side
    {
        int left = -1;
        int right = n-1;
        while (left<right)
        {
            int center = (left+right+1)>>1;

            char result = simulation(s, magics, center);
            if (result == 'C' or result == 'R')
                right = center-1;
            else
                left = center;
        }
        cnt += left+1;
    }

    cout << n - cnt << endl;
    return 0;
}

