int check( int i, int lr, int num )
{
	if( i < 0 || N <= i ) {
		if( lr ) {
			if( N <= i ) {
				return 1;
			}
		}
		else {
			if( i < 0  ) {
				return 1;
			}
		}
		return 0;
	}
	int n = s[i] - 'A';
	int res = 0;
	for( int j = 0; j < v[n].size(); j++ ) {
		int k = v[n][j];
		if( k <= num ) {
			continue;
		}
		int dd = d[k];
		if( dd ) {
			res |= check( i + 1, lr, k );
		}
		else {
			res |= check( i - 1, lr, k );
		}
	}
	return res;
}

