using QU = vector<pair<char, int>>;


bool moved_out(const string& s, const QU& qs, int left, bool checkleft) {
    const int n = s.size();
    int i = left;
    for (const auto& qi: qs) {
        if (qi.first == s[i]) {
            if (qi.second == 1) {
                ++i;
                if (i == n)
                    return !checkleft;
            }
            else {
                --i;
                if (i < 0)
                    return checkleft;
            }
        }
    }
    return false;
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    string s;
    cin >> s;
    QU qs(q);
    for (int i=0; i<q; ++i) {
        char di;
        cin >> qs[i].first >> di;
        if (di == 'R')
            qs[i].second = 1;
        else
            qs[i].second = 0;
    }

    int leftlow = -1;
    int lefthigh = n;
    while (lefthigh-leftlow > 1) {
        int leftmid = leftlow + (lefthigh-leftlow)/2;
        if (moved_out(s, qs, leftmid, true))
            leftlow = leftmid;
        else
            lefthigh = leftmid;
    }
    //left ans is leftlow+1 (last out is at leftlow). right analogous

    int rightlow = -1;
    int righthigh = n;
    while (righthigh-rightlow > 1) {
        int rightmid = rightlow + (righthigh-rightlow)/2;
        if (moved_out(s, qs, rightmid, false))
            righthigh = rightmid;
        else
            rightlow = rightmid;
    }
    // last out is righthigh, so right ans is n-righthigh

    int ans = leftlow+1 + (n - righthigh);
    cout << n-ans << "\n";
    //cerr << "DBG: " << leftlow << " " << lefthigh << " " << rightlow << " " << righthigh << "\n";
}

