//右に落ちるか左に落ちるか落ちないか判定する
int jud(int n){
  int pos = n;
  for(int i=0;i<Q;i++){
    char now = s[pos];
    if(t[i] == now){
      if(d[i] == 'L') pos--;
      if(d[i] == 'R') pos++;
    }
    if(pos == -1){
      return -1;
    } else if(pos == N){
      return 1;
    }
  }
  return 0;
}

int bsl(int a, int b){
  //cout << "l " << a << b << endl;
  int p = (a + b) / 2;
  if(check[p] == 2) check[p] = jud(p);

  if(check[p] == -1 && p == N-1) return p;
  else if((check[p]==0 || check[p]==1) && p==0) return -1;
  else if(check[p] == -1 && (check[p+1] == 0 || check[p+1] == 1)) return p;
  else if((check[p] == 0 || check[p] == 1) && check[p-1] == -1) return p-1;
  else if(check[p] == -1){
    return bsl(p,b);
  }
  else if(check[p] == 1 || check[p] == 0){
    return bsl(a,p);
  }
}

int bsr(int a, int b){
  //cout << "r " << a << b << endl;
  int p = (a + b + 1) / 2;
  if(check[p] == 2) check[p] = jud(p);

  if(check[p] == 1 && p == 0) return p;
  else if((check[p]==-1 || check[p]==0) && p==N-1) return -1;
  else if(check[p] == 1 && (check[p-1] == 0 || check[p-1] == -1)) return p;
  else if((check[p] == 0 || check[p] == -1) && check[p+1] == 1) return p+1;
  else if(check[p] == 1){
    return bsr(a,p);
  }
  else if(check[p] == -1 || check[p] == 0){
    return bsr(p,b);
  }
}

int main(){
  cin >> N >> Q;
  cin >> s;
  for(int i=0;i<Q;i++) cin >> t[i] >> d[i];

  //左右に落ちる部分を見つける
  fill(check,check+200000,2);//2は未定
  //cout << bsl(0,N-1) << endl;
  //cout << bsr(0,N-1) << endl;
  check[0] = jud(0);
  check[N-1] = jud(N-1);
  int l = bsl(0,N-1);
  int r = bsr(0,N-1);
  int ans = N;
  if(l != -1){
    ans -= l + 1;
  }
  if(r != -1){
    ans -= N - r;
  }

  cout << ans << endl;
  return 0;
}

