using namespace std;

string s;
vector<pair<char, char>> a;

char simulate(int x) {
  for (auto p : a) {
    if (s[x] == p.first) {
      if (p.second == 'L') x--;
      if (p.second == 'R') x++;
      if (x == -1) return 'L';
      if (x == s.size()) return 'R';
    }
  }
  return '0';
}

int main() {
  int n,q;
  cin >> n >> q;
  cin >> s;
  a.resize(q);
  for (auto& p : a) cin >> p.first >> p.second;
  int la = 0;
  int ra = n-1;
  int lb = 0;
  int rb = n-1;

  while (la < ra) {
    int m = (la + ra) / 2;
    char c = simulate(m);
    if (c == 'L') {
      la = m + 1;
    } else {
      ra = m;
    }
  }

  while (lb < rb) {
    int m = (lb + rb+1) / 2;
    char c = simulate(m);
    if (c == 'R') {
      rb = m-1;
    } else {
      lb = m;
    }
  }
  int ans;
  if (la >= lb) {
    if (simulate(la) == '0') {
      ans = 1;
    } else {
      ans = 0;
    }
  } else {
    ans = lb-la+1;
  }
  cerr << la << " " << ra << " " << lb << " " << rb << endl;
  cout << ans;
}

