int main() {
	int n, q; reader(n, q);
	string s; reader(s);
	vector<pair<char, char>> vp;
	FOR(i, q) {
		string a, b; reader(a, b);
		vp.emplace_back(a[0], b[0]);
	}

	auto sim = [&](int id) {
		for (auto& kv : vp) {
			if (s[id] == kv.first) {
				if (kv.second == 'L') id--;
				else id++;
				if (id < 0) return -1;
				if (id >= n) return n;
			}
		}
		return id;
	};

	int leftOut;
	{
		int l = -1, r = n;
		while (r - l != 1) {
			int md = (l + r) / 2;
			int last = sim(md);
			if (last < 0) l = md;
			else r = md;
		}
		leftOut = l;
	}
	int rightOut;
	{
		int l = -1, r = n;
		while (r - l != 1) {
			int md = (l + r) / 2;
			int last = sim(md);
			if (last == n) r = md;
			else l = md;
		}
		rightOut = l;
	}
	int ans = (rightOut - leftOut);
	writerLn(ans);
}

