typedef tuple<char, char> tcc;

ll solve_left_drop(const string &s, const V<tcc> &tdlist, ll n)
{
    ll left = 0LL;
    ll right = n - 1LL;
    ll start = (left + right) / 2LL;
    ll ret = -1LL;

    for ( ; left <= right; start = (left + right) / 2LL) {
        ll now = start;
        for (auto td : tdlist) {
            char t = get<0>(td);
            char d = get<1>(td);
            if (s[now] == t) {
                if (d == 'L') now--;
                if (d == 'R') now++;
            }
            if (now < 0LL || n <= now) break;
        }
        if (now < 0LL) {
            ret = max(ret, start);
            left = start + 1LL;
        }
        else {
            right = start - 1LL;
        }
    }

    return ret + 1LL;
}

ll solve_right_drop(const string &s, const V<tcc> &tdlist, ll n)
{
    ll left = 0LL;
    ll right = n - 1LL;
    ll start = (left + right) / 2LL;
    ll ret = n;

    for ( ; left <= right; start = (left + right) / 2LL) {
        ll now = start;
        debug_printf("------ start=%lld\n", start);
        for (auto td : tdlist) {
            char t = get<0>(td);
            char d = get<1>(td);
            debug_printf("-- now %lld ", now);
            if (s[now] == t) {
                if (d == 'L') now--;
                if (d == 'R') now++;
            }
            debug_printf("-> %lld\n", now);
            if (now < 0LL || n <= now) break;
        }
        debug_printf("!! now = %lld %lld\n", now, n);
        if (now >= n) {
            debug_printf("!! update\n");
            ret = min(ret, start);
            right = start - 1LL;
        }
        else {
            left = start + 1LL;
        }
    }

    return n - ret;
}

int _main()
{
    ll n; llin(n);
    ll q; llin(q);
    string s; CIN(s);
    V<tcc> tdlist;
    rep (i, q) {
        char t, d;
        CIN(t); CIN(d);
        tdlist.pb(tcc(t, d));
    }

    ll left_drop = solve_left_drop(s, tdlist, n);
    debug_printf("---- left_drop=%lld\n", left_drop);

    ll right_drop = solve_right_drop(s, tdlist, n);
    debug_printf("---- right_drop=%lld\n", right_drop);

    cout << n - left_drop - right_drop << endl;

    return 0;
}

