int N, Q;
vector<pair<char, char>> spel;
vector<char> mp;

int check_over(int n)
{
    int now = n;

    for (unsigned int i = 0; i < spel.size(); i++)
    {
        if (mp[now] == spel[i].first)
        {
            if (spel[i].second == 'R')
                now += 1;
            else
                now -= 1;

            if(now == -1) break;
            if(now == N) break;
        }
    }

    return now;
}

int main(int argc, char *argv[])
{

    cin >> N >> Q;

    char a, b;

    for (int i = 0; i < N; i++)
    {
        cin >> a;
        mp.push_back(a);
    }

    for (int i = 0; i < Q; i++)
    {
        cin >> a >> b;
        spel.push_back(make_pair(a, b));
    }

    int c, d,d2=1;
    d = 1;

    int n = 0, m = N - 1;

    if (check_over(0) == -1)
    {
        while (true)
        {
            d = check_over((n + m) / 2);
            if(d2 == -1 && d != -1) break;
            if (d < -1)
                n = (n + m) / 2;
            else if (d > -1)
                m = (n + m) / 2;
            else {
                c = (n + m) / 2;
                d2 = d;
                n += 2;
            }
        }
    }
    else
    {
        c = -1;
    }

    int c2;

    n = 0;
    m = N - 1;

    if (check_over(N - 1) == N)
    {
        while (true)
        {
            d = check_over((n + m) / 2);
            if(d2 == N && d != N) break;
            if (d < N)
                n = (n + m) / 2;
            else if (d > N)
                m = (n + m) / 2;
            else
            {
                c2 = (n + m) / 2;
                d2 = N;
                n -= 2;
            }
        }
    }else{
        c2 = N;
    }
    int ans;

    ans = N - (c+1) - (N - c2);
    cout << ans;

    return 0;
}

