        for(int i=1;i<=Q;++i) if(mov[i][1]==arr[pos]){
            pos += mov[i][2]=='L'? -1:1;
            if(!pos) break;
        }
        if(pos) r = 0;
    }
    ans -= r;
    l = 1, r = N, mid;
    while(l<r){
        mid = (l+r)/2; int pos = mid;
        for(int i=1;i<=Q;++i) if(mov[i][1]==arr[pos]){
            pos += mov[i][2]=='L'? -1:1;
            if(pos>N) break;
        }
        if(pos>N) r = mid;
        else l = mid+1;
    }
    if(l==N&&r==N){
