#include <iostream>
#include<vector>
using namespace std;
using pchar=pair<char, char>;
int simulate(const string& s, const vector<pchar>& td, int pos) {
	for (auto c : td) {
		if (s[pos] !=c.first) {
			continue;
		}
		if (c.second == 'L') {
			pos--;
		}
		else {
			pos++;
		}
		if (pos < 0) {
			return -1;//左に落ちる

		}
		if (pos >= (int)s.size()) {
			return 1;
		}
	}
	return 0;
}
int solve(int N, const string& s, const vector<pchar>& td) {
	//左側の境目
	int low = -1;
	int high = N;
	while (high - low > 1) {
		int mid = (high - low) / 2;
		if (simulate(s, td, mid) == -1) {
			low = mid;
		}
		else {
			high = mid;
		}

	}
	int left_fall = high;
	//右側の境目
	low = -1;
	high = N;
	while (high - low > 1) {
		int mid = (low + high) / 2;
		if (simulate(s, td, mid) == 1) {
			high = mid;
		}
		else {
			low = mid;
		}
	}
	int right_fall = N - 1 - low;

	return N - (left_fall + right_fall);
}


int main() {
	int N, Q;
	string s;
	cin >> N >> Q;
	cin >> s;
	vector<pchar>td(Q);
	for (int i = 0; i < Q; i++) {
		cin >> td[i].first >> td[i].second;
	}
	cout << solve(N, s, td) << endl;
}

