			}
			if (tmp == -1) {
				flag = true;
				break;
			}
			if (tmp == n)
				break;
		}
		if (flag)
			l = mid;
		else
			r = mid;
	}
	return r;
}

int bs2() {
	int l = -1, r = n - 1;
	while (l + 1 < r) {
		int mid = (l + r) / 2;
		int tmp = mid;
		bool flag = false;
		for (auto i : qu) {
			if (i.ff == s[tmp]) {
				if (i.ss == 'L')
					tmp--;
				else
					tmp++;
			}
			if (tmp == -1)
				break;
			if (tmp == n) {
				flag = true;
				break;
			}
		}
		if (flag)
			r = mid;
		else
			l = mid;
	}
	return l;
}
