bool Check(int poz, bool dir) {
    int i;
    for (i = 1; i <= M; i++) {
        if (a[i].c == s[poz]) {
            if (a[i].d == 'R')poz++;
            else poz--;
        }
        if (poz < 0 && dir == 0) return true;
        else if (poz >= N && dir == 0) return false;
        if (poz >= N && dir == 1)return true;
        else if (poz < 0 && dir == 1)return false;
    }
    return false;
}

void CautBin(int st, int dr, bool dir) {
    int mid = (st + dr) / 2;
    if (st == dr && dir == 0)solst = mid;
    else if (st == dr)soldr = mid;
    else if (dir == 0) {
        if (Check(mid + 1, dir) == 0)CautBin(st, mid, dir);
        else CautBin(mid + 1, dr, dir);
    } else {
        if (Check(mid, dir) == 0)CautBin(mid + 1, dr, dir);
        else CautBin(st, mid, dir);
    }
}

