int moveS(int poz, int Q, std::vector<std::pair<char, char>>squareMoves, std::string s)
{
    if(poz < 0)
    {
        return -1;
    }
    if(poz >= s.size())
    {
        return 1;
    }
    for(int i = 0; i < Q; i++)
    {
        if(squareMoves[i].first != s[poz]) continue;
        if(squareMoves[i].second == 'L')
        {
            poz--;
        }
        else
        {
            poz++;
        }
        if(poz >= s.size())
        {
            return 1;
        }
        if(poz < 0)
        {
            return -1;
        }
    }

    return 0;
}


