        if (check(mid,0)) l=mid;
        else r=mid;
    }
    if (check(r,0)) ans-=r;
    else if (check(l,0)) ans-=l;
    while (L+1<R){
        int mid=(L+R)>>1;
        if (check(mid,n+1)) R=mid;
        else L=mid;
