        if(l == n - 1){
            continue;
        }
        l++;
    }

    int r = n;
    for(int i = q - 1; i >= 0; i--){
        if(r < n && query[i].first == s[r] && query[i].second == 1){
            r++;
            continue;
        }
        if(r > 0 && query[i].first != s[r-1] - 'A'){
            continue;
        }
        if(query[i].second == 1){
            continue;
        }
        if(r == 0){
            continue;
        }
        r--;
    }

    cout << n - (l + 1 + n - r) << endl;

    return 0;
}

