template<typename iterator>

void majicshift(string s, iterator begin, int N){
  char t,d;
  cin >> t >> d;
  int p = s.find_first_of(t);
  while(p>=0){
    if(d=='L'){
      if(p>0)
        *(begin+(p-1)) += *(begin+p);
    }
    else{
      if(p<(N-1))
        *(begin+(p+1)) += *(begin+p);
    }
    *(begin+p) = 0;
    p = find(++p,s,t);
  }
}

