int n,Q;
const int N=1e5+10;
char S[N];
char opt[N];int LR[N];
inline char Gc(){char ch=getchar();while(!(ch>='A'&&ch<='Z')) ch=getchar();return ch;}
inline bool checkL(int p){
	for(int i=1;i<=Q;++i){
		if(opt[i]==S[p]) p+=LR[i];
		if(p<=0) return 1;if(p>n) return 0;
	}return 0;
}
inline bool checkR(int p){
	for(int i=1;i<=Q;++i){
		if(opt[i]==S[p]) p+=LR[i];
		if(p>n) return 1;if(p<=0) return 0;
	}return 0;
}
