	for(int i=1;i<=Q;++i) {char ch=Gc();opt[i]=ch;ch=Gc();LR[i]=(ch=='L')? (-1):1;}
	int l=1,r=n,pos=0;
	while(l<=r){
		int mid=(l+r)>>1;
		if(checkL(mid)) pos=mid,l=mid+1;else r=mid-1;
	}
	int ans=pos;l=pos+1,r=n;pos=n+1;
	while(l<=r){
