int N, Q;
string S;
vector<pair<char, char>> V;

int l, m, r;

int goWhere(int num){
	for(int i = 0; i < Q; i ++){
		if(S[num] == V[i].first){
			if(V[i].second == 'L')num --;
			else num ++;
			if(num < 0)return -1;
			if(num >= N)return 1;
		}
	}
	return 0;
}
//左に消えるもののうち一番右のものを探す
int searchLeft(){
	l = 0;
	r = N - 1;
	if(goWhere(r) == -1)return r;//全部左に消える
	if(goWhere(l) != -1)return -1;//ひとつも左に消えない
	while(true){
		m = (l + r) / 2;
		if(goWhere(m) == -1){
			if(goWhere(m + 1) != -1){
				return m;
			}
			l = m + 1;
		}
		else{
			r = m - 1;
		}
	}
}
//右に消えるもののうち一番左のものを探す
int searchRight(){
	l = 0;
	r = N - 1;
	if(goWhere(l) == 1)return l;//全部右に消える
	if(goWhere(r) != 1)return -1;//ひとつも右に消えない
	while(true){
		m = (l + r) / 2;
		if(goWhere(m) == 1){
			if(goWhere(m - 1) != 1){
				return m;
			}
			r = m - 1;
		}
		else{
			l = m + 1;
		}
	}
}
int main(){

	cin >> N >> Q >> S;
	char t, d;
	for(int i = 0; i < Q; i ++){
		cin >> t >> d;
		V.pm(t, d);
	}
	int ansl = searchLeft();
	int ansr = searchRight();
	if(ansl == -1){
		if(ansr == -1){
			cout << N << endl;
			return 0;
		}
		cout << ansr << endl;
		return 0;
	}
	if(ansr == -1){
		cout << N - ansl - 1 << endl;
		return 0;
	}
	cout << ansr - ansl - 1 << endl;

	return 0;
}

