  while (cin >> N >> Q) {
    string S;
    cin >> S;
    vector<char> T(Q), D(Q);
    for (int q = 0; q < Q; q++) cin >> T[q] >> D[q];
    auto simulate = [&](int i, int edge) {
      for (int q = 0; q < Q; q++) {
        if (S[i] == T[q]) {
          i += D[q] == 'L' ? -1 : +1;
        }
        if (i < 0 || i >= N) return i == edge;
      }
      return false;
    };
    auto bsearch = [&](int edge, int pass, int fail) {
      while (abs(pass - fail) > 1) {
        int i = (pass + fail) / 2;
        if (simulate(i, edge)) {
          pass = i;
        } else {
          fail = i;
        }
      }
      return pass;
    };
    int res = N;
    if (simulate(0, -1)) {
      res -= bsearch(-1, 0, N) + 1;
    }
    if (simulate(N - 1, N)) {
      res -= N - bsearch(N, N - 1, -1);
    }
    cout << res << endl;
  }
  return 0;
}

