					if (d == L) {
						P[j - 1].second += P[j].second;
						P[j].second = 0;
					}
					else {
						P[j + 1].second += P[j].second;
						P[j].second = 0;
					}
				}
			}
		}
	}

	REP(i, N) {
		ans += P[i].second;
	}

	cout << ans << endl;


}

