bool solve(ll g) {
  for (auto q : query) {
    if (S[g] == q.first) {
      if (q.second == 'L') {
        g--;
      } else {
        g++;
      }
      if (g < 0 || g >= N) {
        return true;
      }
    }
  }

  return false;
}

