  }

  ll ok = N;
  ll ng = -1;
  while (abs(ok - ng) > 1) {
    ll c = (ok + ng) / 2;
    if (solve(c)) {
      ok = c;
    } else {
      ng = c;
    }
  }

  ll right = ok;

  ok = -1;
