int func(int start,string s,char *t,char *d,int Q,int N){
    for(int i=0;i<Q;i++){
        if(i>0){
            ++t;++d;
        }
        if(*t==s[start]){
            if(*d=='R'){
                start++;
            }else{
                start=start-1;
            }
            if(start<0||start>=N){
                return start;
                break;
            }
        }
    }

    return start;
}

