    ll c = (ok + ng) / 2;
    if (solve(c)) {
      ok = c;
    } else {
      ng = c;
    }
  }

  ll right = ok;
  if (ok == ng) {
    right = N;
  }

  ok = -1;
  ng = N;
  while (abs(ok - ng) > 1) {
    ll c = (ok + ng) / 2;
    if (solve(c)) {
      ok = c;
    } else {
      ng = c;
    }
  }

  ll left = ok;
  if (ok == ng) {
    left = -1;
  }

  cout << (right - left - 1) << endl;

  return 0;
}

