        // move left
        for (int idx : alphabet_idxes[t - 'A']) {
            if (d == 'L') {
                if (idx == 0) golem[idx] = 0;
                else {
                    golem[idx - 1] += golem[idx];
                    golem[idx] = 0;
                }
            }
            // move right
            else {
                if (idx == N - 1) golem[idx] = 0;
                else {
                    golem[idx + 1] += golem[idx];
                    golem[idx] = 0;
                }
            }
        }
    }

    // output
    for (int j = 0; j < N; ++j) {
        sum += golem[j];
    }
    cout << sum << endl;

    return 0;
