	// もし反対側に行ってしまったら次のマスをその数だけ増やす

	// むっず！

	// 取りあえず、左から抜けれる場合と右から抜けれる場合を考える

	// 反対から見る？
	// そのマスに進んだゴーレム達がどんな運命を辿ったかがすぐわかる

	// 消滅できる場所をtrueとするとか
	vector<bool> board(n, false);
	int left = 0;
	int right = n - 1;
	for (int i = q - 1; i >= 0; i--) {
		// 消滅できなければどんなにあがいていても関係ない
		if (t[i] == s[left] && d[i] == 'L') {
			board[left] = true;
			left++;
		}
		if (t[i] == s[right] && d[i] == 'R') {
			board[right] = true;
			right--;
		}
	}

	// これで、ゴーレムが自分からtrueに突っ込んだ時点で消滅
	/*rep(i, n) {
		cout << board[i] << endl;
	}*/

	// 中心側のマスに逃げられている場合を考える
	// 外側に行く前に、内側に行ったかを調べる
	vector<pair<int, int>> which(26, { 0,0 });
	// 1なら左が先 2なら右が先
	// secondで番号もつける
	rep(i, q) {
		if (which[t[i] - 'A'].first == 0) {
			if (d[i] == 'L') {
				which[t[i] - 'A'].first = 1;
				which[t[i] - 'A'].second = i;
			}
			else {
				which[t[i] - 'A'].first = 2;
				which[t[i] - 'A'].second = i;
			}
		}
	}

	ll ans = n;

	vector<int> map(n, 1);
	// すべてのゴーレムについて考える
	// 左から脱出
	rep(i, n) {
		if (!board[i]) break;
		if (which[s[i] - 'A'].first == 1) {
			if (i == 0) {
				ans--;
				map[i] = 0;
			}
			else if (board[i - 1] == true) {
				ans -= map[i];
				map[i] = 0;
			}
		}
		else {
			map[i + 1] += map[i];
			map[i] = 0;
		}
	}
	/*
	rep(i, n) {
		map[i] = 1;
	}*/

	// 右から脱出
	for(int i = n - 1 ; i >= 0; i--){
		if (!board[i]) break;
		if (which[s[i] - 'A'].first == 2) {
			if (i == n - 1) {
				ans--;
				map[i] = 0;
			}
			else if (board[i + 1] == true) {
				ans -= map[i];
				map[i] = 0;
			}
		}
		else {
			map[i - 1] += map[i];
			map[i] = 0;
		}
	}

	cout << ans << endl;

	return 0;
}

