int n, q;

int Side(int at) {
	for (int i = 1; i <= q; i++) {
		if (at < 0) return -1;
		if (at >= n) return 1;
		if (S[at] == t[i][0]) {
			if (d[i][0] == 'R') at++;
			else at--;
		}
	}
	if (at < 0) return -1;
	if (at >= n) return 1;
	return 0;
}

int SideLeft() {
	int lo = -1, hi = n - 1;
	while (lo < hi) {
		int mid = (lo + hi + 1) / 2;
		if (Side(mid) == -1) {
			lo = mid;
		}
		else {
			hi = mid - 1;
		}
	}
	return lo;
}

int SideRight() {
	int lo = 0, hi = n;
	while (lo < hi) {
		int mid = (lo + hi) / 2;
		if (Side(mid) == 1) {
			hi = mid;
		}
		else {
			lo = mid + 1;
		}
	}
	return hi;
}

void solve(int ks) {
	scanf("%d %d", &n, &q);
	scanf("%s", S);
	for (int i = 1; i <= q; i++) {
		scanf("%s %s", t[i], d[i]);
	}

	if (Side(0) == 1 || Side(n - 1) == -1) {
		printf("%d\n", 0);
	}
	else {
		int left = SideLeft();
		int right = SideRight();
		printf("%d\n", right - left - 1);
	}
}

