bool rgt(vector<int>& vs, vector<int>& t, vector<int>& d, int ptr){
    if (ptr >= vs.size()) return true;
    for (int i=0; i<t.size(); ++i){
        if(vs[ptr] != t[i]) continue;
        ptr += d[i];
        if (ptr < 0)break;
        if (ptr == vs.size()) return true;
    }
    return false;
}

bool lft(vector<int>& vs, vector<int>& t, vector<int>& d, int ptr){
    if (ptr >= vs.size()) return false;
    if (ptr <0) return true;
    for (int i=0; i<t.size(); ++i){
        if(vs[ptr] != t[i]) continue;
        ptr += d[i];
        if (ptr < 0)return true;
        if (ptr == vs.size()) break;
    }
    return false;
}

int main(){
    int n,q;
    cin >> n >> q;
    string s;
    cin >> s;
    vector<int> vs;
    for (auto ch : s){
        vs.push_back(ch-'A');
    }
    vector<int> t(q),d(q);
    for (int i=0; i<q; ++i){
        char ch;
        cin >> ch;
        t[i] = ch-'A';
        cin >> ch;
        d[i] = (ch=='R') ? 1 : -1;
    }

    int ptr = n/2;
    int stp = ptr/2;
    while(true){
        bool hr = rgt(vs,t,d,ptr);
        bool nx = rgt(vs,t,d,ptr+1);
        if((!hr)& nx) break;
        if(hr){
            ptr = max(ptr - stp - 1,0);
        }else{
            ptr = min(n-1, ptr + stp + 1);
        }
        stp/=2;
    }
    auto r = ptr;
    ptr = n/2;
    stp = ptr/2;
    while(true){
        bool hr = lft(vs,t,d,ptr);
        bool nx = lft(vs,t,d,ptr-1);
        if(nx& !hr) break;
        if(!hr){
            ptr = max(ptr - stp - 1,0);
        }else{
            ptr = min(n-1, ptr + stp + 1);
        }
        stp/=2;
    }
    cout << r - ptr + 1 << endl;

    return 0;
}

