struct solver {
	map<string, pair<int, int>> memo;
	pii calc(string s) {

		if (s == "" || s == "()") {
			return memo[s] = pii(0, 0);
		}
		else if (s == "((") return memo[s] = pii(1, 1);
		else if (s == "))") return memo[s] = pii(1, 0);

		auto res = rec(s);
		if (s.size() == 2) {
			res.first = 0;
			res.second = 0;
			if (s[0] == ')') {
				res.first = 1;
			}
			if (s[1] == '(') {
				res.first++;
				res.second = 1;
			}
		}

		return res;
	}
	pair<int, int> rec(string s) {

		if (memo.count(s)) return memo[s];
		pii res;
		res.first = INF;
		res.second = INF;
		int n = s.size();
		if(n == 0) return res = pii(0, 0);
		res = calc(s.substr(1, n - 2));
		if (res.first > 0) {
			res.second++;
		}

		if (s[0] == ')') {
			res.first++;
		}
		if (s[s.size() - 1] == '(') {
			res.first++;
			res.second = s.size() - 1;
		}
		for (int i = s.size() - 2; i > 1; i -= 2)
		{
			//if (s == "()()") {
			//	cout << endl;
			//}
			//if (s == "()()()") {
			//	cout << endl;
			//}
			string ls = s.substr(0, i);
			auto left = calc(ls);
			string rs = s.substr(i, n - i);
			auto right = calc(rs);

			int lval = left.first + right.first;
			int rval = left.second;
			if (right.first > 0)
				rval = i + right.second;
			if ((res.first + res.second) > (lval + rval))
			{
				res.first = lval;
				res.second = rval;
			}
		}

		return memo[s] = res;
	}

};
