ll N,Q;
string s;

bool is_left_ok(ll pos,char *t,char *d){
    for(ll i = 0; i < Q; i++){
        if(t[i] == s[pos]){
            if(d[i] == 'L')
                pos--;
            else
                pos++;
        }
        if(pos < 0)
            return false;
    }
    return true;
}

bool is_right_ok(ll pos,char *t,char *d){
    for(ll i = 0; i < Q; i++){
        if(t[i] == s[pos]){
            if(d[i] == 'L')
                pos--;
            else
                pos++;
        }
        if(pos >= N )
            return false;
    }
    return true;
}

int main(){
    cin >> N >> Q >> s;
    char t[Q];
    char d[Q];
    for(ll i = 0; i < Q; i++) cin >> t[i] >> d[i];

    ll border_left,border_right;

    ll left = -1, right = N;
    while(right - left > 1){// [left, right)
        ll mid = left + (right - left) / 2;

        if(is_left_ok(mid, t, d)) right = mid;
        else left = mid;
    }
    border_left = right;

    left = -1, right = N;
    while(right - left > 1){
        ll mid = left + (right - left) / 2;

        if(is_right_ok(mid, t, d)) left = mid;
        else right = mid;
    }
    border_right = right;

    ll ans = border_right - border_left;
    cout << ans << "\n";
    return 0; 
}

