int simulate(const string &s, const vector<char> &t, const vector<char> &d, int pos) {
	rep(i, (int)t.size()) {
		if (s[pos] != t[i]) continue;
		if (d[i] == 'L') pos--;
		else pos++;
		if (pos < 0) return 1;
		if (pos >= (int)s.size()) return -1;
	}
	return 0;
}

int main() {
