inline ll pow_mod(const ll a, const ll b, const ll MOD) {
	if (b == 0) return 1;
	if (b == 1) return a % MOD;
	ll res = pow_mod(a * a % MOD, b >> 1, MOD);
	if (b & 1) res = res * a % MOD;
	return res % MOD;
}

