class CSnukeTheWizard {
	class Solver {
		io::input_reader in;
		io::output_writer out;

	public:
		Solver(std::istream &in, std::ostream &out) : in(in), out(out) {}

		int solve(const string &s, const vector<vector<int>> &goodAction, const vector<vector<int>> &badAction) {
			auto next = [](const vector<vector<int>> &list, int turn, char S) {
				S -= 'A';
				auto val = lower_bound(all(list[S]), turn);
				if (val == list[S].end()) return -1;
				else return *val;
			};
			auto nextGood = [&](int turn, char S) {
				return next(goodAction, turn, S);
			};
			auto nextBad = [&](int turn, char S) {
				return next(badAction, turn, S);
			};
			auto can = [&](int m) {
				int turn = 0;
				while (m >= 0 && m < s.size()) {
					auto ng = nextGood(turn, s[m]);
					auto nb = nextBad(turn, s[m]);
					if (ng == -1 && nb == -1) break;
					else if (nb == -1 || (ng != -1 && ng < nb)) {
						m--, turn = ng + 1;
					} else {
						m++, turn = nb + 1;
					}
				}
				return m < 0;
			};
			int l = -1, r = s.size();
			while (l + 1 < r) {
				int m = (l + r) / 2;
				if (can(m)) {
					l = m;
				} else {
					r = m;
				}
			}
			return l + 1;
		}

		void solve() {
			int n, q;
			string s;
			in.read(n, q, s);
			vector<vector<int>> actionsL(26);
			vector<vector<int>> actionsR(26);
			fori(i, q) {
				char a, b;
				in.read(a, b);
				auto l = (b == 'L') ? &actionsL : &actionsR;
				(*l)[a - 'A'].pb(i);
			}
			int res = solve(s, actionsL, actionsR);
			reverse(all(s));
			res += solve(s, actionsR, actionsL);
			out << (n - res);
		}
	};

public:
	void solve(std::istream &in, std::ostream &out) {
		Solver(in, out).solve();
	}
};

