ll solve(const string &s, const V<string> &ops, ll n, ll qcnt, ll idx)
{
    for (auto op : ops) {
        char c = op[0];
        char dir = op[1];
        if (s[idx] != c) continue;
        if (dir == 'L') idx--;
        else idx++;
        if (idx < 0) return -1;
        if (idx >= n) return 1;
    }

    return 0;
}

