void _main()
{
    ll n; llin(n);
    ll qcnt; llin(qcnt);
    S string s; CIN(s);
    V<string> ops;
    rep (i, qcnt) {
        string tmps;
        char tmpc;
        CIN(tmpc); tmps += tmpc;
        CIN(tmpc); tmps += tmpc;
        ops.pb(tmps);
    }

    ll left = 0;
    ll right = n-1;
    ll now = (left + right) / 2LL;
    ll ans1 = -1;
    for ( ; left <= right; now = (left + right) / 2LL) {
        if (solve(s, ops, n, qcnt, now) == -1) {
            ans1 = max(ans1, now);
            left = now + 1;
        }
        else {
            right = now - 1;
        }
    }

    debug_printf("---- ans1 = %lld\n", ans1);

    left = 0;
    right = n-1;
    now = (left + right) / 2LL;
    ll ans2 = n;
    for ( ; left <= right; now = (left + right) / 2LL) {
        if (solve(s, ops, n, qcnt, now) == 1) {
            ans2 = min(ans2, now);
            right = now - 1;
        }
        else {
            left = now + 1;
        }
    }

    debug_printf("---- ans2 = %lld\n", ans2);

    debug_printf("---- ans\n");
    cout << ans2 - ans1 - 1 << endl;
}

