            }
        }
    }
    return target;
}

int findL(int l, int r) {
    if (l > r) return -1;
    int mid = (l+r)/2;
    if (calc(mid) == -1) {
        if (calc(mid+1) == mid+1) {
            return mid;
        }
        return findL(mid+1, r);
    }
    return findL(l, mid-1);
}

int findR(int l, int r) {
    if (l > r) return -1;
    int mid = (l+r)/2;
    if (calc(mid) == N) {
        if (calc(mid-1) == mid-1) {
            return mid;
        }
        return findR(l, mid-1);
    }
    return findR(mid+1, r);
}

