    }

    int l = findL(0, N-1);
    int r = findR(0, N-1);

    int count = N;
    if (l != -1) {
        count = count - (l + 1);
    }
    if (r != -1) {
        count = count - (N - r);
    }

    cout << count << endl;

    return 0;
}

