struct query {
    char t;
    char d;
};

enum result {
    LEFT,
    STAY,
    RIGHT
};

result where(int i, const string& s, const vector<query>& qs) {
    for (const query& q : qs) {
        if (q.t == s[i]) {
            if (q.d == 'L')
                i--;
            else
                i++;
        }
        if (i < 0)
            return LEFT;
        else if (i >= (int)s.size())
            return RIGHT;
    }
    return STAY;
}

int main() {
