    int n, q;
    cin >> n >> q;
    string s;
    cin >> s;

    vector<query> qs(q);
    for (query& qu : qs)
        cin >> qu.t >> qu.d;

    int ans = n;

    int lt = -1, rt = n - 1;
    while (lt < rt - 1) {
        int mid = (lt + rt) / 2;
        if (where(mid, s, qs) == LEFT)
            lt = mid;
        else
            rt = mid;
    }
    cerr << "last LEFT: " << lt << endl;
    ans -= rt;

    rt = n;
    while (lt < rt - 1) {
        int mid = (lt + rt) / 2;
        if (where(mid, s, qs) == STAY)
            lt = mid;
        else
            rt = mid;
    }
    cerr << "first RIGHT: " << rt << endl;
    ans -= n - rt;

    cout << ans << endl;

    return 0;
}

