    int forwardAns = -1;
    while(high - low > 1)
    {
        mid = (low + high)/2;
        // cout << "mid " << mid << endl;
        if(binarySearch(mid, 1))
        {
            low = mid;
        }
        else
        {
            high = mid;
        }
    }
    forwardAns = high;

    // cout << forwardAns << endl;
    low = -1, high = n;
    int backwardAns = n;
    while(high - low > 1)
    {
        mid = (low + high)/2;
        // cout << "mid " << mid << " " << low << " " << high << endl;
        if(binarySearch(mid, 0))
        {
            high = mid;
        }
        else
        {
            low = mid;
        }
    }
    backwardAns = n - high;
    // cout << backwardAns << endl;
    cout << n - (forwardAns + backwardAns) << endl;
    return 0;
}

