		vector<int> squares = mapper[input[0]];
		vector<int> preGolems(golems);
		for(int& inx : squares)
		{
			if(sum <= 0)
			{
				std::cout << std::to_string(sum) << std::endl;
				return 0;
			}
			if(input[2] == 'L')
			{
				if(inx > 0)
				{
					golems[inx - 1] += preGolems[inx];
				}
					golems[inx] -= preGolems[inx];
				if(inx == 0)
				{
					sum -= preGolems[inx];
				}
			}
			else
			{
				if(inx < N - 1)
				{
					golems[inx + 1] += preGolems[inx];
				}
					golems[inx] -= preGolems[inx];
				if(inx == N - 1)
				{
					sum -= preGolems[inx];
				}
			}
		}
	}

	std::cout << std::to_string(sum) << std::endl;

	return 0;
}

