inline bool judge(int pos, bool left_judge) {
    if(pos < 0) return left_judge;
    if(pos >= N) return !left_judge;
    REP(i, Q) {
        if(S[pos]==ts[i]) {
            pos += ds[i];
            if(pos < 0) return left_judge;
            if(pos >= N) return !left_judge;
        }
    }
    return false;
}

inline int solve() {
    int l, r, m, res=0;
    for(l=-1, r=N; r-l>1; m=(r+l)/2) {
        if(judge(m, true)) l=m;
        else r=m;
    }
    res -= l+1;
    for(l=-1, r=N; r-l>1; m=(r+l)/2) {
        if(judge(m, false)) r=m;
        else l=m;
    }
    res += r;
    return res;
}

