int main() {
  int n, q; cin >> n >> q;

  vector<int> golems(n, 1);
  multimap<char, int> map;

  string s; cin >> s;
  for (int i = 0; i < n; i++) {
    map.emplace(s[i], i);
  }

  for (int i = 0; i < q; i++) {
    char t, d; cin >> t >> d;
    auto it = map.lower_bound(t);
    auto last = map.upper_bound(t);

    if (d == 'L') {
      for (it; it != last; it++) {
        int index = (*it).second;
        if (index != 0) golems[index - 1] += golems[index];
        golems[index] = 0;
      }
    }

    if (d == 'R') {
      vector<pair<int, int>> changes;
      for (it; it != last; it++) {
        int index = (*it).second;
        if (index != n - 1 && golems[index] != 0) {
          changes.emplace_back(index + 1, golems[index]);
        }
        golems[index] = 0;
      }
      for (auto ch : changes) {
        golems[ch.first] += ch.second;
      }
    }
  }

  int ans = accumulate(golems.begin(), golems.end(), 0);
  cout << ans << endl;
}

