int process(int pos) {
	REP(i, 0, q) {
		if (s[pos] == sym[i][0]) {
			if (t[i][0] == 'L') {
				pos--;
			} else if (t[i][0] == 'R') {
				pos++;
			}
		}
	}
	return pos;
}

void solve(){
	scanf("%d%d%s", &n, &q, &s[1]);
	REP(i, 0, q) {
		scanf("%s%s", &sym[i][0], &t[i][0]);
	}
	int l1 = 0, r1 = n + 1;
	for(; l1 + 1 < r1; ) {
		int m = (l1 + r1) / 2;
		int v = process(m);
		if (v == 0) {
			l1 = m;
		} else {
			r1 = m;
		}
