	int l2 = 0, r2 = n + 1;
	for(; l2 + 1 < r2; ) {
		int m = (l2 + r2) / 2;
		int v = process(m);
		if (v <= n) {
			l2 = m;
		} else {
			r2 = m;
		}
	}
	printf("%d\n", r2 - l1 - 1);
}   

