vector<int> find_all(const string str, const string subStr);


vector<int> find_all(const string str, const string subStr) {
    vector<int> result;

    int subStrSize = subStr.size();
    int pos = str.find(subStr);

    while (pos != std::string::npos) {
        result.push_back(pos);
        pos = str.find(subStr, pos + subStrSize);
    }

    return result;
}


