bool rgt(vector<int>& vs, vector<int>& t, vector<int>& d, int ptr){
    if (ptr >= vs.size()) return true;
    for (int i=0; i<t.size(); ++i){
        if(vs[ptr] != t[i]) continue;
        ptr += d[i];
        if (ptr < 0)break;
        if (ptr == vs.size()) return true;
    }
    return false;
}

bool lft(vector<int>& vs, vector<int>& t, vector<int>& d, int ptr){
    if (ptr >= vs.size()) return false;
    if (ptr <0) return true;
    for (int i=0; i<t.size(); ++i){
        if(vs[ptr] != t[i]) continue;
        ptr += d[i];
        if (ptr < 0)return true;
        if (ptr == vs.size()) break;
    }
    return false;
}

int main(){
