    int left = -1;

    while (1) {
        int search = a + ((b - a) / 2);
        if (exit_from(search, 'L')) {
            left = search;
            a = search + 1;
        } else {
            b = search - 1;
        }

        if (b < a) {
            break;
        }

    }

    // 右から退場する一番左のマス
    a = 0;
    b = n - 1;

    int right = n;

    while (1) {
        int search = a + ((b - a) / 2);
        if (exit_from(search, 'R')) {
            right = search;
            b = search - 1;
        } else {
            a = search + 1;
        }

        if (b < a) {
            break;
        }
    }

    cout << n - (left + 1) - (n - right) << endl;

    return 0;
}

