int goal(int pos, vector<char>& t, vector<char>& d) {
    if (memo.count(pos) > 0) return memo[pos];

    REP(i, Q) {
        if (s[pos] == t[i]) {
            d[i] == 'L' ? pos-- : pos++;
        }

        if (pos < 0) {
            return memo[pos] = 1;
        }

