    int res = 0;

    if (goal(0, t, d) == 1) {
        int l = 0;
        int r = N - 1;
        while (r - l > 1) {
            int m = (l + r) / 2;
            if (goal(m, t, d) == 1) {
                l = m;
            } else {
                r = m;
            }
        }

        res += l + 1;
    }

    if (goal(N - 1, t, d) == 2) {
        int l = 0;
