int check(int ind, int ro) {

	if (ind == -1) return -1;
	if (ind == n) return n;
	if (lmemo[ro] >= ind) return -1;
	if (rmemo[ro] <= ind) return n;
	if (q == ro) return 1;
	if (memo[ind].count(ro)) {
		return memo[ind][ro]; 
	}
	int& res = memo[ind][ro];

	if (s[ind] == qp[ro].first) {
		res = check(ind + qp[ro].second, ro + 1);
	}
	else {
		res = check(ind, ro + 1);
	}

	if (res == -1) {
		lmemo[ro] = max(ind, lmemo[ro]);
	}
	if (res == n) {
		rmemo[ro] = min(ind, rmemo[ro]);
	}
	return res;
}
