int run(int i) {

	int curI = i;
	LP(qi, 0, Q)
	{
		if (ins[qi].first != (s[curI] - 'A')) {
			continue;
		}

		//cout << qi << " " << curI << endl;

		if (ins[qi].second) {
			curI--;
			if (curI < 0)
				return -1;
		} else {
			curI++;
			if (curI >= N)
				return 1;
		}
	}

	return 0;
}

int findToR(int c) {

	int subN = cis[c].size();
	int low = 0;
	int high = subN - 1;

	while (low < high) {
		int mid = (low + high) / 2;

		int res = run(cis[c][mid]);

		if (res == 1) {
			high = mid;
		} else {
			low = mid + 1;
		}
	}

	if (low == high) {
		int res = run(cis[c][low]);
		if (res == 1) {
			return subN - low;
		}
	}

	return 0;
}

int findToL(int c) {
	int subN = cis[c].size();
	if(subN == 0)
		return 0;
	int low = 0;
	int high = subN - 1;

	while (low < high) {
		int mid = (low + high) / 2;

		int res = run(cis[c][mid]);

		if (res == -1) {
			if (run(cis[c][mid + 1]) == -1) {
				low = mid + 1;
			} else {
				return mid + 1;
			}
		} else {
			high = mid;
		}
	}

	//cout << c << " " << low << " " << cis[c][low] << " "<< high << endl;

	if (low == high) {
		int res = run(cis[c][low]);
		if (res == -1) {

//	cout << c << " " << low << " " << cis[c][low] << " "<< high << endl;
			return low + 1;
		}
	}

	return 0;
}

