bool die(int pos, int N, int Q, std::string text, bool isLeft) {
    for( int i = 0; i < Q; ++i ) {
        if( text[pos] == query[i][0] ) {
            if( query[i][1] == 'L' ) { --pos; }
            else { ++pos; }
            if( pos < 0 ) {
                return isLeft;
            }
            if( pos >= N ) {
                return !isLeft;
            }
        }
    }
    return false;
}

