}

int caut_bin_left(int st, int dr, char s[],
                  int q, pair <char, char> v[]) {
    while (st <= dr) {
        int mij = (st + dr) / 2;
         if (verif(mij, s, q, v) > 0)    dr = mij - 1;
         else   st = mij + 1;
    }
    return dr;
}

int caut_bin_right(int st, int dr, char s[],
                   int q, pair <char, char> v[]) {
    int n = dr;
    while (st <= dr) {
        int mij = (st + dr) / 2;
        if (verif(mij, s, q, v) < n + 1)    st = mij + 1;
        else   dr = mij - 1;
    }
    return st;
}

