pi L, R;
vector<pair<char,char>> res;

int sim(int x) {
    trav(t,res) if (t.f == S[x]) {
        if (t.s == 'L') x --;
        else x ++;
        if (x < 0) return -1;
        if (x == N) return 1;
    }
    return 0;
}

void red(int x) {
    int t = sim(x);
    // ps("HA",x,t);
    if (t == -1) {
        ckmax(L.f,x);
        ckmax(R.f,x+1);
    }
    if (t == 0) {
        ckmin(L.s,x-1);
        ckmax(R.f,x+1);
    }
    if (t == 1) {
        ckmin(R.s,x);
        ckmin(L.s,x-1);
    }
}

int main() {
    setIO(); re(N,Q,S);
    F0R(i,Q) {
        char t,d; re(t,d);
        res.pb({t,d});
    }
    L = {-1,N-1};
    R = {0,N};
    while (L.f < L.s) red((L.f+L.s+1)/2);
    while (R.f < R.s) red((R.f+R.s)/2);
    // ps("??",L,R);
    ps(N-(L.f+1)-(N-R.s));
}


