	cin >> n >> m >> s;
	vector<pii> qs(m);
	for(int i = 0; i < m; ++i){
		string t, d;
		cin >> t >> d;
		qs[i] = pii(t[0], d[0] == 'L' ? -1 : 1);
	}
	int alive_left = 0, alive_right = n;
	{	// left
		int lo = 0, hi = n;
		while(lo < hi){
			const int mid = lo + (hi - lo) / 2;
			bool alive = true;
			int p = mid;
			for(const auto& q : qs){
				if(s[p] != q.first){ continue; }
				p += q.second;
				if(p <  0){ alive = false; break; }
				if(p >= n){ break; }
			}
			if(alive){
				hi = mid;
			}else{
				lo = mid + 1;
			}
		}
		alive_left = lo;
	}
	{	// right
		int lo = 0, hi = n;
		while(lo < hi){
			const int mid = lo + (hi - lo) / 2;
			bool alive = true;
			int p = mid;
			for(const auto& q : qs){
				if(s[p] != q.first){ continue; }
				p += q.second;
				if(p >= n){ alive = false; break; }
				if(p <  0){ break; }
			}
			if(alive){
				lo = mid + 1;
			}else{
				hi = mid;
			}
		}
		alive_right = lo;
	}
	const int answer = max(0, alive_right - alive_left);
	cout << answer << endl;
	return 0;
}

