		if(tou(mid1) < 0){
			first1 = mid1;
		}
		else{
			last1 = mid1;
		}
		mid1 = (last1 - first1) / 2 + first1;
	}
	int mid2 = N / 2;
	int last2 = N - 1;
	int first2 = 0;
	while(last2 - first2 > 0){
		if(last2 - first2 == 1){
			if(tou(first2)>=N){
				last2 = first2;
				mid2 = first2;
			}
			else{
				first2 = last2;
				mid2 = last2;
			}
			break;
		}
		if(tou(mid2) >= N){
			last2 = mid2;
		}
		else{
			first2 = mid2;
		}
		mid2 = (last2 - first2) / 2 + first2;
	}
	cout << mid2 - mid1 - 1 << endl;
}

