  }
  int start=-1,end=N,mid,f,S,E;

  //落ちない最小値を探す(S)
  //落ちないものがない場合は右側に落ちる最小値
  while(true){
    mid = (start + end)/2;
    f = fall(mid);
    if(!f) end = mid;
    else if(f==1) start = mid;
    else end = mid;
    if(end-start <= 1) break;
  }
  S = end;

  start=-1,end=N;
  //右側に落ちる最小値を探す(E)
  while(true){
    mid = (start+end)/2;
    f = fall(mid);
    if(!f)start = mid;
    else if(f==1) start = mid;
    else end = mid;
    if(end-start <= 1) break;
  }
  E = end;
  cout << E-S << endl;
  return 0;
}

