        REP(i, q) {
            if (s[p] == t[i]) {
                if (d[i] == 'L') p--;
                else p++;
                if (p < 0) return true;
            }
        }
        return false;
    };

    auto check_r = [&](int m) {
        int p = m;
        REP(i, q) {
            if (s[p] == t[i]) {
                if (d[i] == 'L') p--;
                else p++;
                if (p >= n) return true;
            }
        }
        return false;
    };

    BinarySearch<int> bs(-1, n, check);
    int l = bs.calc();

    BinarySearchR<int> bs_r(-1, n, check_r);
    int r = bs_r.calc();
    cout << n - (l + 1 + n - r) << EOL;
}

