    for (int i = 0; i < Q; i++) { std::cin >> t[i] >> d[i]; }
    int linf = -1, lsup = N;
    auto ok = [&](int pos, const bool l) {
        for (int i = 0; i < Q; i++) {
            if (l and pos < 0) { return true; }
            if (l and pos >= N) { return false; }
            if (!l and pos >= N) { return true; }
            if (!l and pos < 0) { return false; }
            if (d[i] == 'L') {
                if (S[pos] == t[i]) {
                    pos--;
                }
            } else {
                if (S[pos] == t[i]) {
                    pos++;
                }
            }
        }
        if (l and pos < 0) { return true; }
        if (l and pos >= N) { return false; }
        if (!l and pos >= N) { return true; }
        if (!l and pos < 0) { return false; }
        return false;
    };
    while (lsup - linf > 1) {
        const int lmid = (linf + lsup) / 2;
        (ok(lmid, true) ? linf : lsup) = lmid;
    }
    int rinf = -1, rsup = N;
    while (rsup - rinf > 1) {
        const int rmid = (rinf + rsup) / 2;
        (ok(rmid, false) ? rsup : rinf) = rmid;
    }
    std::cout << std::max(0, rinf - linf) << std::endl;
    return 0;
}

