signed main() {
	INIT;

	VAR(int, n, q);
	VAR(std::string, s);
	VEC_ROW(char, q, t, d);

	auto run = [&](int p) { // O(Q)
		REP(i, q) {
			if (s[p] == t[i]) {
				if (d[i] == 'L') --p;
				else ++p;
				if (p < 0) return -1;
				if (p >= n) return 1;
			}
		}
		return 0;
	};

	int ans = n;
	[&] {
		if (run(0) != -1) return;
		int ok = 0, ng = n;
		while (ng - ok > 1) {
			int me = (ok + ng) / 2;
			if (run(me) == -1) ok = me;
			else ng = me;
		}
		ans -= ok + 1;
	}();
	[&] {
		if (run(n - 1) != 1) return;
		int ok = n - 1, ng = -1;
		while (ok - ng > 1) {
			int me = (ok + ng) / 2;
			if (run(me) == 1) ok = me;
			else ng = me;
		}
		ans -= n - ok;
	}();
	OUT(ans)BR;
	return 0;
}

