	while (l_high - l_low > 1) {
		int mid = (l_low + l_high) / 2;
		int pos = mid;
		for (int i = 0; i < Q; ++i) {
			if ((pos < 0) || (pos >= N)) { break; }

			if (s[pos] == t[i]) {
				if (d[i] == 'L') { --pos; }
				else { ++pos; }
			}
		}
		if (pos < 0) { l_low = mid; }
		else { l_high = mid; }
	}

	int r_low = -1, r_high = N;
	while (r_high - r_low > 1) {
		int mid = (r_low + r_high) / 2;
		int pos = mid;
		for (int i = 0; i < Q; ++i) {
			if ((pos < 0) || (pos >= N)) { break; }

			if (s[pos] == t[i]) {
				if (d[i] == 'L') { --pos; }
				else { ++pos; }
			}
		}
		if (pos >= N) { r_high = mid; }
		else { r_low = mid; }
	}

	int res = max(0, r_low - l_high + 1);
