				which[t[i] - 'A'].second = i;
			}
		}*/
		if (d[i] == 'L') {
			which[t[i] - 'A'].push_back({ 1,i });
		}
		else {
			which[t[i] - 'A'].push_back({ 2,i });
		}
	}

	ll ans = n;

	vector<int> map(n, 1);
	// すべてのゴーレムについて考える
	// 左から脱出
	rep(i, n) {
		if (!board[i]) break;
		if (which[s[i] - 'A'][0].first == 1) {
			if (i == 0) {
				ans--;
				map[i] = 0;
			}
			else if (board[i - 1] == true) {
				ans -= map[i];
				map[i] = 0;
			}
		}
		else {
			if (i == n - 1) break;
			if (which[s[i + 1] - 'A'][0].first == 2 && which[s[i] - 'A'][0].second > which[s[i + 1] - 'A'][0].second) {
				for (auto p : which[s[i + 1] - 'A']) {
					if (which[s[i] - 'A'][0].second < p.second && p.first == 2) break;
					if (which[s[i] - 'A'][0].second < p.second && p.first == 1) {
						ans -= map[i];
						map[i] = 0;
					}
				}
			}
			else {
				map[i + 1] += map[i];
				map[i] = 0;
			}
		}
	}
	/*
	rep(i, n) {
		map[i] = 1;
	}*/

	// 右から脱出
	for(int i = n - 1 ; i >= 0; i--){
		if (!board[i]) break;
		if (which[s[i] - 'A'][0].first == 2) {
			if (i == n - 1) {
				ans--;
				map[i] = 0;
			}
			else if (board[i + 1] == true) {
				ans -= map[i];
				map[i] = 0;
			}
		}
		else {
			if (i == 0) break;
			if (which[s[i - 1] - 'A'][0].first == 1 && which[s[i] - 'A'][0].second > which[s[i - 1] - 'A'][0].second) {
				for (auto p : which[s[i - 1] - 'A']) {
					if (which[s[i] - 'A'][0].second < p.second && p.first == 1) break;
					if (which[s[i] - 'A'][0].second < p.second && p.first == 2) {
						ans -= map[i];
						map[i] = 0;
					}
				}
			}
			else {
				map[i - 1] += map[i];
				map[i] = 0;
			}
		}
	}

	cout << ans << endl;

	return 0;
}

