vector<int> find_all(string str, string subStr);


vector<int> find_all(const string str, const string subStr) {
    vector<int> result;

    int subStrSize = (int)subStr.length();
    int pos = (int)str.find(subStr);

    while (pos != std::string::npos) {
        result.push_back(pos);
        pos = (int)str.find(subStr, pos + subStrSize);
    }

    return result;
}


