template <class T>
vector<pair<T,int> > RLE(vector<T> const& v) {
    if (v.empty()) return {};
    vector<pair<T,int> > ret;
    int ii = -1, n = v.size();
    rep (i,n) if (i == n-1 || v[i] != v[i+1]) {
        ret.emplace_back(v[i],i-ii);
        ii = i;
    }
    return ret;
}
