  else if((check[p] == 0 || check[p] == 1) && check[p-1] == -1) return p-1;
  else if(check[p] == -1){
    return bsl(p+1,b);
  }
  else if(check[p] == 1 || check[p] == 0){
    return bsl(a,p-1);
  }
}

int bsr(int a, int b){
  //cout << "r " << a << b << endl;
  int p = (a + b + 1) / 2;
  if(check[p] == 2) check[p] = jud(p);

  if(check[p] == 1 && p == 0) return p;
  else if((check[p]==-1 || check[p]==0) && p==N-1) return -1;
  else if(check[p] == 1 && (check[p-1] == 0 || check[p-1] == -1)) return p;
  else if((check[p] == 0 || check[p] == -1) && check[p+1] == 1) return p+1;
  else if(check[p] == 1){
    return bsr(a,p-1);
  }
  else if(check[p] == -1 || check[p] == 0){
    return bsr(p+1,b);
  }
}

