            leftIdx--;
        }

        if(c == charVec[rightIdx] && d == 'R') {
            rightIdx--;
        } else if( (rightIdx < charVec.size()-1) && charVec[rightIdx+1] == c && d == 'L') {
            rightIdx++;
        }

        if(leftIdx > rightIdx) {
