void solve() {
    //const i64 mod = 1'000'000'007;

    i64 N,Q;
    string s;
    cin >> N >> Q >> s;

    vector<char> t(Q),d(Q);
    rep(i,0,Q){
        cin >> t[i] >> d[i];
    }

    auto simulate_left=[&](i64 i){
        i64 p=i;
        rep(j,0,Q){
            if(t[j]!=s[p]) continue;
            if(d[j]=='L') --p;
            else ++p;
            if(p<0) return false;
            if(p==N) return true;
        }
        return true;
    };
    auto simulate_right=[&](i64 i){
        i64 p=i;
        rep(j,0,Q){
            if(t[j]!=s[p]) continue;
            if(d[j]=='L') --p;
            else ++p;
            if(p>=N) return false;
            if(p<0) return true;
        }
        return true;
    };

    i64 left,right;
    {
        if(!simulate_left(N-1)){
            cout << 0 << endl;
            return;
        }
        i64 lb=-1,ub=N-1;
        while(ub-lb>1){
            i64 mid=(lb+ub)/2;
            if(simulate_left(mid)) ub=mid;
            else lb=mid;
        }
        left=ub;
        // left以上なら左に落ちない
    }
    {
        if(!simulate_right(0)){
            cout << 0 << endl;
            return;
        }
        i64 lb=0,ub=N;
        while(ub-lb>1){
            i64 mid=(lb+ub)/2;
            if(simulate_right(mid)) lb=mid;
            else ub=mid;
        }
        right=ub;
        // right以下なら右に落ちない
    }

    if(left>right){
        cout << 0 << endl;
        return;
    }
    assert(left<=right);
    cout << right-left << endl;
}

