void solve() {
  // TODO: fix input
  cin >> n >> q >> s;
  for(int i = 0; i < q; i++) {
    cin.ignore();
    cin >> desire[i] >> dir[i];
  }
  {
    // prefix
    int lhs = -1;
    int rhs = n-1;
    while(lhs != rhs) {
      int mid = (lhs+rhs+1)/2;
      int curr = mid;
      for(int i = 0; i < q && curr >= 0 && curr < n; i++) {
        if(desire[i] == s[curr]) {
          if(dir[i] == 'L') curr--;
          else curr++;
        }
      }
      if(curr < 0) lhs = mid;
      else rhs = mid-1;
    }
    for(int i = 0; i <= lhs; i++) {
      valid[i] = true;
    }
  }
  {
    // suffix
    int lhs = 0;
    int rhs = n;
    while(lhs != rhs) {
      int mid = (lhs+rhs)/2;
      int curr = mid;
      for(int i = 0; i < q && curr >= 0 && curr < n; i++) {
        if(desire[i] == s[curr]) {
          if(dir[i] == 'L') curr--;
          else curr++;
        }
      }
      if(curr >= n) rhs = mid;
      else lhs = mid+1;
    }
    for(int i = lhs; i < n; i++) {
      valid[i] = true;
    }
  }
  int ret = 0;
  for(int i = 0; i < n; i++) {
    ret += valid[i];
  }
  cout << n - ret << "\n";
}

