int n, q, ans, ds[200020];
string s;
map<int, int> memo[200020];
set<int> mv[26];

int dfs(int pos, int turn)
{
	auto &res = memo[turn][pos];
	if (res)
	{
		return res;
	}
	int c = s[pos] - 'A';
	if (mv[c].empty())
	{
		return res = 1;
	}
	auto it = lower_bound(mv[c].begin(), mv[c].end(), turn);
	if (it == mv[c].end())
	{
		return res = 1;
	}
	int k = *it;
	pos += ds[k];
	if (pos < 0 || pos >= n)
	{
		return res = -1;
	}
	turn = k + 1;
	return res = dfs(pos, turn);
}

