bool left_down(int l){
    int i = 0;
    while(i < T.size()) {
        if(l < 0) return true;
        if (S[l] == T[i]) {
            if (D[i] == 'L') { l--; }
            else { l++; }
        }
        i++;
    }
    if(l < 0) return true;
    return false;
}

bool right_down(int l){
    int i = 0;
    while(i < T.size()) {
        if(l >= S.size()) return true;
        if (S[l] == T[i]) {
            if (D[i] == 'L') { l--; }
            else { l++; }
        }
        i++;
    }
    if(l >= S.size()) return true;
    return false;
}

