struct Query {
  char c, d;
};

int n, q;
std::string s;
std::vector<Query> query;

bool BinarySearch_Comp_L(const int key, const std::string& vec) {
  int target = vec[key];
  // need to implement
  int pos = key;
  for (int i = 0; i < q; i++) {
    if (vec[pos] == query[i].c) {
      if (query[i].d == 'L') {
        pos--;
      } else {
        pos++;
      }
    }
    if (pos == n)
      return false;
    else if (pos == -1)
      return true;
  }
  return false;
}
bool BinarySearch_Comp_R(const int key, const std::string& vec) {
  int target = vec[key];
  // need to implement
  int pos = key;
  for (int i = 0; i < q; i++) {
    if (vec[pos] == query[i].c) {
      if (query[i].d == 'L') {
        pos--;
      } else {
        pos++;
      }
    }
    if (pos == n)
      return true;
    else if (pos == -1)
      return false;
  }
  return false;
}

// Return index number whose element is the LOWER limit returning true in
// BS_Comp().
int BinarySearch_LowerLimit(const std::string& vec) {
  int left  = -1;
  int right = vec.size();
  int mid;
  while (right - left > 1) {
    mid = left + (right - left) / 2;
    if (BinarySearch_Comp_R(mid, vec)) {
      right = mid;
    } else {
      left = mid;
    }
  }
  return right;
}

// Return index number whose element is the UPPER limit returning true in
// BS_Comp().
int BinarySearch_UpperLimit(const std::string& vec) {
  int left  = -1;
  int right = vec.size();
  int mid;
  while (right - left > 1) {
    mid = left + (right - left) / 2;
    if (BinarySearch_Comp_L(mid, vec)) {
      left = mid;
    } else {
      right = mid;
    }
  }
  return left;
}

