int nibun1(int n,int M){
    //printf("%d\n",M-n);
    int new = (M+n+1)/2;
    int g = new;
    for(int i = 0;i < Q;i++){
        if(d[i]=='R' && t[i]==S[g] && g>0 && g<N+1)g++;
        if(d[i]=='L' && t[i]==S[g] && g>0 && g<N+1)g--;
    }
    if(g != 0 && M-n <= 1)return n;
    if(g == 0 && M-n <= 1)return M;
    if(g != 0)return nibun1(n,(new+M)/2);
    if(g == 0)return nibun1((n+new+1)/2,M);
}
