int solve(int N, int Q, char* s, vector<char>& t, vector<char>& d) {
  assert(strlen(s) >= N);
  s[N] = 0;
  auto f = [&](int ix) -> int {
    assert(IN(ix, 0, N - 1));
    rep(i, Q) {
      if (ix == -1 || ix == N) break;
      char letter = s[ix];
      if (letter == t[i]) {
        if (d[i] == 'L')
          --ix;
        else
          ++ix;
      }
    }
    return ix;
  };

  int fL = f(0), fR = f(N - 1);

  if (fL == N) return 0;
  if (fR == -1) return 0;

  int leftmost;
  {
    if (fL >= 0)
      leftmost = 0;
    else {
      int ng = 0, ok = N - 1;
      while (ng + 1 < ok) {
        int x = (ng + ok) / 2;
        int fx = f(x);
        if (fx >= 0) {
          ok = x;
        } else {
          ng = x;
        }
      }
      leftmost = ok;
    }
  }

  int rightmost;
  {
    if (fR <= N - 1)
      rightmost = N - 1;
    else {
      int ok = 0, ng = N - 1;
      while (ok + 1 < ng) {
        int x = (ok + ng) / 2;
        int fx = f(x);
        if (fx <= N - 1) {
          ok = x;
        } else {
          ng = x;
        }
      }
      rightmost = ok;
    }
  }
  if (leftmost <= rightmost)
    return rightmost - leftmost + 1;
  else
    return 0;
}

int main() {
  int N, Q;
  scanf("%d %d%*c", &N, &Q);
  char s[N + 3];
  fgets(s, N + 3, stdin);
  vector<char> t(Q), d(Q);
  rep(i, Q) { scanf("%c %c%*c", &t[i], &d[i]); }
  printf("%d\n", solve(N, Q, s, t, d));
  return 0;
}

