template<typename T>
pair<map<T, int>, map<int, T>> MAPPING(const vector<T> v) {
    map<T, int> conv;
    map<int, T> rev;
    for (int i = 0; i < v.size(); i++) conv[v[i]] = i;
    for (int i = 0; i < v.size(); i++) rev[i] = v[i];
    return make_pair(conv, rev);
}

