bool check(int mid,int k) {
	if (mid<1 || mid>n) return 1;
	for (int i=1;i<=m;i++) {
		if (s[mid]!=si[i][0]) continue;
		if (di[i][0]=='L') mid--; else mid++;
		if (k==1) if (mid<1) return 1;
		if (k==2) if (mid>n) return 1;
	}
	return 0;
}

