	for (int i=1;i<=m;i++) scanf("%s%s",&si[i],&di[i]);

	int L=0,R=n,ans=0;
	while (L<R) {
		int mid=L+R+1>>1;
		if (check(mid,1)) L=mid; else R=mid-1;
	}
	ans+=L;

	L++; R=n+1;
	while (L<R) {
		int mid=L+R>>1;
		if (check(mid,2)) R=mid; else L=mid+1;
	} 
	ans+=(n-R+1);

	cout<<n-ans<<endl;
	return 0;
}

