  int mid = (L+R)/2;
  int zero = 0;

  while(L<R){
    if(check(mid)) {
      R = mid;
    }
    else {
      L = mid+1;
    }
    mid = (L+R)/2;
    if(mid==0) zero++;
    if(zero >= 3) return 0;
  }

  return mid;
}



