signed main() {
    int N, Q;
    cin >> N >> Q;
    string S;
    cin >> S;
    vector<pair<char, char>> move(Q);
    for (int i = 0; i < Q; i++) {
        char t, d;
        cin >> t >> d;
        move[i] = {t, d};
    }
    reverse(move.begin(), move.end());
    vector<bool> ans(N, true);
    int left = -1, right = N;
    for (auto now : move) {
        if (now.second == 'L') {
            if (S[left + 1] == now.first) {
                left++;
                ans[left] = false;
            }
            if (right < N - 1 && S[right + 1] == now.second) right++;
        } else {
            if (S[right - 1] == now.first) {
                right--;
                ans[right] = false;
            }
            if (left >= 1 && S[left - 1] == now.first) left--;
        }
        if (left == right) break;
    }
    int count = 0;
    for (int i = 0; i < N; i++) count += ans[i];
    cout << count << endl;
}

