	for (int i = 0; i < q; i ++)
	{
		char cc;
		cin >> c[i] >> cc;
		d[i] = (cc == 'R');
	}

	int ans1 = bs();
	reverse(s, s + n);
	for (int i = 0; i < q; i ++)
		d[i] ^= 1;
	int ans2 = bs();

	cout << n - min(ans1 + ans2, n) << endl;

	return 0;
}

