using namespace std;

bool in_range(int a, int b){
  return a >= 0 && a < b;
}

int simulate(string S, int v, const vector<char> &T, const vector<char> &D, int d){
  int N = S.length();
  for(size_t i = 0; i < T.size(); ++i){
    if(S[v] != T[i]) continue;
    if(D[i] == 'R') v += d;
    else v -= d;
    if(not in_range(v,N)) return v;
  }
  return v;
}

int solve(string S, vector<char> &T, vector<char> &D){
  int N = S.length();
  int ng = N, ok = -1;
  int ans = N;
  while(ng-ok > 1){
    int m = (ok+ng)/2;
    int v_ = simulate(S,m,T,D,1);
    if(v_ == -1) ok = m;
    else ng = m;
  }
  ans -= ng;
  reverse(S.begin(), S.end());
  ng = N, ok = -1;
  while(ng-ok > 1){
    int m = (ok+ng)/2;
    int v_ = simulate(S,m,T,D,-1);
    if(v_ == -1) ok = m;
    else ng = m;
  }
  ans -= ng;
  return ans;
}

