        int mid = (ok + ng) / 2;
        int cur = mid;
        rep(i,q){
            if(s[cur] == t[i]){
                if(d[i] == 'L') --cur;
                else ++cur;
            }
        }
        if(cur == n+1) ok = mid;
        else ng = mid;
    }
    ans += n + 1 - ok;
    ans = n - ans;
    cout << ans << endl;
    return 0;
}

