//２分探索　単調的に範囲が取れることに着目して思いつくべき。

bool isnotFall(const string &s, const vector<pchar> &td, int pos) {
  //範囲for文という表現　配列やコンテナを簡潔に扱うためのfor文の別表現である。　
  // 範囲for文は配列または、begin()およびend()で表される範囲内の全ての要素に対して、処理を実行する。
  for (auto c : td) {
    if (c.first == s[pos]) {  //クエリに該当するものだった場合
      if (c.second == 'R') pos++;
      if (c.second == 'L') pos--;
      if (pos < 0 || s.length() <= pos) return false;
    }
  }

  return true;
}

int main() {
  int N, Q;
  cin >> N >> Q;

  string s;
  cin >> s;

  vector<pchar> td(Q);
  FOR(i, 0, Q) cin >> td[i].first >> td[i].second;

  int fall_left, fall_right;

  //[low,high) //[ok,ng)
  int low, mid, high;
  low = 0;
  high = N;

  while (high - low > 1) {  //右側に落ちる下限
    mid = (high + low) / 2;
    if (isnotFall(s, td, mid))
      low = mid;  //落ちなかった
    else
      high = mid;
  }

  fall_right = (N - 1) - low;

  low = 0;
  high = N;
  //(low,high]

  while (high - low > 1) {  //左側に落ちる上限
    mid = (high + low) / 2;
    if (isnotFall(s, td, mid))
      high = mid;  //落ちなかった場合
    else
      low = mid;
  }

  fall_left = high;

  cout << N - (fall_left + fall_right) << endl;
}

