            else
            {
                if(spell.d == 'L')
                    golems[x - 1] += golems[x];
                else
                    golems[x + 1] += golems[x];
            }
            golems[x] = 0;
        }
    }

    cout << n - fallen << endl;
    return 0;
}

#include<bits/stdc++.h>
