bool check(int n, const string & in, vector<char> & pos, vector<int> & order, bool isCountLeft, int my_pos){
  const int q = pos.size();
  rep(i,q){
    if (in[my_pos] == pos[i]){
      my_pos += order[i];
    }
    if (my_pos < 0 || my_pos >= n)break;
  }

  if (isCountLeft && my_pos < 0)return true;
  if (!isCountLeft && my_pos >= n)return true;
  return false;
}

int solve(int n, const string & in, vector<char> & pos, vector<int> & order, bool isCountLeft){
  int l = 0, r = n;
  if (isCountLeft && !check(n, in, pos, order, isCountLeft, 0)){
    return 0;
  } else if (!isCountLeft && !check(n, in, pos, order, isCountLeft, n-1)){
    return 0;
  }
  if (!isCountLeft){
    l = -1;
    r = n-1;
  }
  //while(l < r){
  rep(i,50){
    int mid = (l + r) / 2;
    bool isGone = check(n, in, pos, order ,isCountLeft, mid);
    //cout << isCountLeft <<" " << l  <<" " << r << " " << mid << " " << isGone << endl;
    if (isGone){
      if (isCountLeft){
	l = mid; // find max
      } else {
	r = mid; // find min
      }
    } else {
      if (isCountLeft){
	r = mid; // find max
      } else {
	l = mid; // find min
      }
    }
  }
  //cout << isCountLeft <<" l = " << l <<" r = " << r <<" " << l << " " << n-r << endl;
  if (isCountLeft){
    return l + 1;
  }
  else {
    return n - r;
  }
}


