int fdo(int pos){
	rep(i, q){
		if(s[pos] != t[i]) continue;
		pos += d[i]=='L'? -1: 1;
		if(pos < 0 ) return 2;
		if(pos >=n ) return 3;
	}
	return 1;
}

int fncl(){
	int hi=n, lw=-1;
	while(hi - lw >1){
		int md = (hi + lw) >>1;
		(fdo(md) == 2? lw: hi) = md;
	}
	return hi;
}
int fncr(){
	int hi=n, lw=-1;
	while(hi - lw >1){
		int md = (hi + lw) >>1;
		(fdo(md) == 3? hi: lw) = md;
	}
	return hi;
}


