int N, Q; string S;
char T[201010], D[201010];
//---------------------------------------------------------------------------------------------------
int check(int x) {
	rep(i, 0, Q) {
		if (T[i] == S[x]) {
			if (D[i] == 'L') x--;
			else x++;
		}

		if (x < 0 or N <= x) return 1;
	}
	return 0;
}
//---------------------------------------------------------------------------------------------------
void _main() {
	cin >> N >> Q >> S;
	rep(q, 0, Q) cin >> T[q] >> D[q];

	int ans = N;

	if (check(0)) {
		int ok = 0, ng = N;
		while (ok + 1 != ng) {
			int md = (ok + ng) / 2;
			if (check(md)) ok = md;
			else ng = md;
		}
		ans -= ok + 1;
	}

	if (check(N - 1)) {
		int ng = 0, ok = N - 1;
		while (ng + 1 != ok) {
			int md = (ok + ng) / 2;
			if (check(md)) ok = md;
			else ng = md;
		}
		ans -= N - ok;
	}

	chmax(ans, 0);
	cout << ans << endl;
}

