bool ope(int c, string &S, vector<pair<char,char>> &O, int f) {
    for (int i = 0; i < O.size(); i++) {
        if (S[c] == O[i].first) {
            c += (O[i].second == 'L' ? -1 : 1);
        }
        if (f == 0 && c >= (int)S.size()) return true;
        if (f == 1 && c < 0) return true;
        if (f == 0 && c < 0) return false;
        if (f == 1 && c >= (int)S.size()) return false;
    }
    return true;
}

void solve() {
    int N, Q;
    cin >> N >> Q;
    string S;
    cin >> S;
    vector<pair<char,char>> O(Q);
    for (int i = 0; i < Q; i++) {
        char c, d;
        cin >> c >> d;
        O[i] = {c, d};
    }

    int l = -1, r = N + 1;
    while(r - l > 1) {
        int c = (r + l) / 2;
        bool ok = ope(c, S, O, 0);

        if (ok) {
            r = c;
        } else {
            l = c;
        }
    }
    int ok_l = r;

    l = -1, r = N + 1;
    while(r - l > 1) {
        int c = (r + l) / 2;
        bool ok = ope(c, S, O, 1);
        if (ok) {
            l = c;
        } else {
            r = c;
        }
    }
    int ok_r = l;

    cout << ok_r - ok_l + 1 << endl;
}

