bool is_die(int pos, int N, int Q, string s, vector<char> t, vector<char> d) {
    rep(i, Q) {
        if (s[pos] == t[i]) {
            if (d[i] == 'L') pos--;
            else pos++;
        }
        if (pos < 0 or N <= pos) {
            return true;
        }
    }
    return false;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, Q;
    string s;
    vector<char> t(Q), d(Q);

    cin >> N >> Q;
    cin >> s;
    rep(i, Q) cin >> t[i] >> d[i];

    int lb = 0, ub = N;
    while (ub - lb > 1) {
        int mid = (lb + ub)/2;
        if (is_die(mid, N, Q, s, t, d) == true) {
            ub = mid;
        } else {
            lb = mid;
        }
    }
    int die_lb = ub;
    if (is_die(die_lb - 1, N, Q, s, t, d) == true) die_lb--;

    lb = 0; ub = min(N, die_lb);
    while (ub - lb > 1) {
        int mid = (lb + ub)/2;
        if (is_die(mid, N, Q, s, t, d) == true) {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    int die_ub = ub;
    if (is_die(die_ub - 1, N, Q, s, t, d) == false) die_ub--;

    cout << max(0, die_lb - die_ub) << endl;
    return 0;
}

