int drop(int n, int N, int Q, string s, char t[], char d[])
{
	int i, posi = n;

	for (i = 1; i <= Q; i++)
	{
		if (s[posi - 1] == t[i])
		{
			if (d[i] == 'R')
			{
				posi++;
				if (posi > N)
					return 1;
			}
			else
			{
				posi--;
				if (posi < 1)
					return -1;
			}
		}
	}
	return 0;
}

