  while(abs(ok-ng)>1){
    int mid=(ok+ng)/2;
    if(solve(s,Q,mid,0))ok=mid;
    else ng=mid;
  }
  ans-=ok;

  ok=n+1,ng=1;
  while(abs(ok-ng)>1){
    int mid=(ok+ng)/2;
    if(solve(s,Q,mid,n+1))ok=mid;
    else ng=mid;
  }
  ans-=(n-ok+1);

  cout<<ans<<endl;
  return 0;
}

