bool fl(int k,int N,int Q,string s,vector<char> t,vector<char> d){
    int now = k;
    bool ok = false;
    rep(i,Q){
        if(t[i] == s[now]){
            if(d[i] == 'R') now++;
            else now--;
        }
        if(now == -1) ok = true;
    }
    return ok;
}

bool fr(int k,int N,int Q,string s,vector<char> t,vector<char> d){
    int now = k;
    bool ok = false;
    rep(i,Q){
        if(t[i] == s[now]){
            if(d[i] == 'R') now++;
            else now--;
        }
        if(now == N) ok = true;
    }
    return ok;
}

