    while(ng-ok > 1){
        int mid = (ng+ok)/2;
        if(fl(mid,N,Q,s,t,d)) ok = mid;
        else ng = mid;
    }
    int ok2 = N,ng2 = -1;
    while(ok2-ng2 > 1){
        int mid2 = (ng2+ok2)/2;
        if(fr(mid2,N,Q,s,t,d)) ok2 = mid2;
        else ng2 = mid2;
    }
    int ans = N-(ok+1)-(N-ok2);
    cout << ans << endl;
}

