        cin >> t[i] >> d[i];
    }

    int a[n];
    // -1:uncertain 1:fall left 2:stand 3:fall right
    rep(i,n){
        a[i] = -1;
    }


    int l = 0;
    int r = n-1;

    while(true){
        if(a[(l+r)/2]==-1){
            a[(l+r)/2] = syori((l+r)/2,q,s,t,d);
            if(a[(l+r)/2]==1){
                rep(i,(l+r)/2){
                    a[i] = 1;
                }
                l = (l+r)/2+1;
            }
            if(a[(l+r)/2]==3){
                srep(i,(l+r)/2,n){
                    a[i] = 3;
                }
                r = (l+r)/2-1;
            }
            if(a[(l+r)/2]==2){
                r = (l+r)/2-1;
            }
        }else{
            break;
        }
    }
    l = 0;
    r = n-1;
    while(a[l]==1||a[l]==2){
        l++;
    }
    while(true){
        a[(l+r)/2] = syori((l+r)/2,q,s,t,d);
        if(a[(l+r)/2]==2){
            l = (l+r)/2+1;
        }
        if(a[(l+r)/2]==3){
            srep(i,(l+r)/2,n){
                a[i] == 3;
            }
            r = (l+r)/2-1;
        }
        if(r<l)break;
    }

    int ans = n;
    rep(i,n){
        if(a[i]==1||a[i]==3)ans--;
    }

    cout << ans << endl;

