	int r=n-1;
	if(kekka(0)>=0){
		ll=-1;
	}else if(kekka(n-1)==-1){
		ll=n-1;
	}else{
		for(int i=0;true;i++){
			if(l+1==r){
				ll=l;
				break;
			}

			if(kekka((l+r)/2)==-1)l=(l+r)/2;
			else r=(l+r)/2;
		}
