// 左から消滅できるなら true
static inline bool check_l(ll ind) {
    ll cur = ind;   // 現在地
    REP(i, Q) {
        if(T[i] == S[ind]) {
            if(D[i] == 'L') {
                ind--;
                if(ind < 0) { return true; }
            }
            else {
                ind++;
            }
        }
    }
    return false;
}
// 右から消滅できるなら true
static inline bool check_r(ll ind) {
    ll cur = ind;   // 現在地
    REP(i, Q) {
        if(T[i] == S[ind]) {
            if(D[i] == 'L') {
                ind--;
            }
            else {
                ind++;
                if(ind >= N) { return true; }
            }
        }
    }
    return false;
}

ll solve() {
    // 左側に消える最大のインデックス
    ll del_l = -1;
    ll lb = 0, rb = N-1;
    while(rb - lb > 1) {
        ll mid = (lb + rb) / 2;
        if(check_l(mid)) { lb = mid; }
        else { rb = mid; }
    }
    if(check_l(rb)) { del_l = rb; }
    else if(check_l(lb)) { del_l = lb; }

    // 右側に消える最大のインデックス
    ll del_r = -1;
    lb = 0;
    rb = N - 1;
    while(rb - lb > 1) {
        ll mid = (lb + rb) / 2;
        bool ret = check_r(mid);
        if(ret) { rb = mid; }
        else { lb = mid; }
    }
    if(check_r(lb)) { del_r = lb; }
    else if(check_r(rb)) { del_r = rb; }

    if(del_l == -1) {
        if(del_r == -1) { return N; }
        return del_r;
    }
    if(del_r == -1) {
        return N - (del_l + 1);
    }
    if(del_l >= del_r) { return 0; }
    return N - (del_l + 1) - (N - del_r);
}

