    c = s[k];

  }

  return 1;

}

int binary(){
  int L = -1,R = n;  //  [L,R]の範囲内に解
  int mid = (L+R)/2;

  while(L<R){
    if(check(mid)) {
      R = mid;
    }
    else {
      L = mid+1;
    }
    mid = (L+R)/2;
  }

  return mid;
}



