                    else if(val<0) return n+2;
                    square=s[val-1];
                }
        }
    //fout<<"\n check \n";
    return 1;
}

int best_left_out_right()
{
    int st=1;
    int dr=n;
    int sol;
    while(st<=dr)
        {
            //fout<<"st="<<st<<" dr="<<dr<<" ";
            int mij=(st+dr)/2;
            //fout<<mij<<" ";
            if(verif(mij)==0)
                {
                    sol=mij;
                }
            dr=mij-1;
            //fout<<"\n";
        }
    return sol;
}

int best_right_out_left(int val)
{
    int st=1;
    int dr=val;
    int sol;
    while(st<=dr)
        {
            //fout<<"st="<<st<<" dr="<<dr<<" ";
            int mij=(st+dr)/2;
            //fout<<mij<<" ";
            if(verif(mij)==0)
                {
                    sol=mij;
                }
            st=mij+1;
            //fout<<"\n";
        }
    return sol;
}

