vector<vector<char>>t_d;
int n, q;
string s;

int simulate(int p){
	int now = p;
	rep(i, 0, q) {
		if (s[now] == t_d[i][0]) {
			if (t_d[i][1]== 'R')now++;
			else now--;
		}
		if (now < 0)return 0;
		else if (now >= n)return 1;
	}
	return 2;
}

int bisectL() {
	if (simulate(0) != 0)return 0;
	else if (simulate(n - 1) == 0)return n;

	int ok = 0;
	int ng = n - 1;
	while (ng - ok > 1) {
		int mid = (ng + ok) / 2;
		if (simulate(mid)==0)ok = mid;
		else ng = mid;
	}
	return ok + 1;
}
int bisectR() {
	if (simulate(n-1) != 1)return 0;
	else if (simulate(0) == 1)return n;

	int ok = n-1;
	int ng = 0;
	while (ok - ng > 1) {
		int mid = (ng + ok) / 2;
		if (simulate(mid) == 1)ok = mid;
		else ng = mid;
	}
	return n - ok;
}


