int displacement(string &S, int position, vector <move> &M)
{ //cout << position << " final = ";
    for(int i = 1; i < M.size(); i++)
    {
        if(S[position] == M[i].ch)
        {
            position += (M[i].direction == 'L' ? -1 : 1);
        }

        if(position == 0 || position == S.size() - 1)
        {
            break;
        }
    }// cout << position << endl;

    return position;
}

int main()
{
