    for(int i = 1; i <= no_of_moves; i++)
    {
        cin >> moves[i].ch >> moves[i].direction;
    }

    int left = 0, right = length + 1;
    while(right - left > 1)
    {
        int mid = (left + right)/2;

        if(displacement(S, mid, moves) == 0)
        {
            left = mid;
        }
        else
        {
            right = mid;
        }
    }
    int rightmost_to_fall_left = left; //cout << "R = " << rightmost_to_fall_left << endl;

    left = 0, right = length;
    while(right - left > 1)
    {
        int mid = (left + right)/2;

        if(displacement(S, mid, moves) == length + 1)
        {
            right = mid;
        }
        else
        {
            left = mid;
        }
    }
    int leftmost_to_fall_right = right; //cout << "L = " << leftmost_to_fall_right << endl;

    int remaining = (leftmost_to_fall_right - 1) - rightmost_to_fall_left;
    cout << remaining;

    return 0;
