const int maxn = 2e5 + 9;
int n, q;
string s;
pair<char, char> query[maxn];

int fall(int pos) {
    for (int i = 0; i < q; i++) {
        if (query[i].first == s[pos]) {
            pos += (query[i].second == 'L' ? -1 : 1);
        }
        if (pos < 0) {
            return 1;
        } else if (pos >= n) {
            return 3;
        }
    }
    return 2;
}

int lower_bound(int x) {
    int start = 0, end = n - 1;
    while (end > start) {
        int mid = (start + end) / 2;
        if (fall(mid) >= x) {
            end = mid;
        } else {
            start = mid + 1;
        }
    }
    return end;
}

int upper_bound(int x) {
    int start = 0, end = n - 1;
    while (end > start) {
        int mid = (start + end) / 2;
        if (fall(mid) > x) {
            end = mid;
        } else {
            start = mid + 1;
        }
    }
    return end;
}

