			if(d[i]=='R') pos++;
			else pos--;
			if(pos<0){
				return searchL(m,b);
			}
		}
	}
	return searchL(a,m);
}
int searchR(int a, int b){
	// cout << pair(a,b) << endl;
	if(a+1==b){
		if(b==N-1 && !RR(N-1)){
			cout << "RR" <<endl;
			return 0;
		}else if(a==0 && RR(0))
			return N;
		return N-b;
	}
	int m = (a+b)/2;
	int pos = m;
	rep(i,Q){
		if(t[i]==s[pos]){
			if(d[i]=='R') pos++;
			else pos--;
			if(N<=pos)
				return searchR(a,m);
		}
	}
	return searchR(m,b);
}

