int bs1() {
    int ub = N, lb = -1;
    while(ub - lb > 1) {
        int mid = (ub + lb) / 2;
        if(get_state(mid) == 1) lb = mid;
        else ub = mid;
    }
    return lb;
}

int bs2() {
    int ub = N, lb = -1;
    while(ub - lb > 1) {
        int mid = (ub + lb) / 2;
        if(get_state(mid) == 2) ub = mid;
        else lb = mid;
    }
    return ub;
}

