    int ret = 0;
    for (int i = 0; i < Q; i++){
        if (S[crt] == q[i].first){
            if (q[i].second){
                crt++;
            }else{
                crt--;
            }
        }
        if (crt == N){
            ret = 1;
            break;
        }
        if (crt < 0) break;
    }
    return ret;
}

int check_left(int key){
    int crt = key;
    int ret = 0;
    for (int i = 0; i < Q; i++){
        if (S[crt] == q[i].first){
            if (q[i].second){
                crt++;
            }else{
                crt--;
            }
        }
        if (crt == -1){
            ret = 1;
            break;
        }
        if (N <= crt) break;
    }
    return ret;
}

