int ans_minus(std::vector<std::vector<int> > &A, 
        std::vector<int> &B, int t2, int c, int n){

    for(int j=0; j<(int)A[t2].size(); j++){
        int p = A[t2][j];
        if(p+c<=-1 or p+c>=n) {
            B[p] = 0;
        } else {
            B[p+c] += B[p]; 
            B[p] = 0;
        }
    }
}

int ans_plus(std::vector<std::vector<int> > &A, 
        std::vector<int> &B, int t2, int c, int n){

    for(int j = (int)A[t2].size()-1; j>=0; j--){
        int p = A[t2][j];
        if(p+c<=-1 or p+c>=n) {
            B[p] = 0;
        } else {
            B[p+c] += B[p]; 
            B[p] = 0;
        }
    }
}

