            if(l-1 >= 0 && s[l-1] == p[i].first){
                l--;
                if(die[l] == -1){
                    die[l] = i;
                }
                maxl = max(l, maxl);
            }

            if(r-1 >= 0 && s[r-1] == p[i].first){
                r--;
                if(die[r] == -1){
                    die[r] = i;
                }
                maxr = min(r, maxr);
            }
        }
    }

    maxl++;
    maxr--;
    for(int i = q-1;i >= 0;i--){
        if(p[i].second == 'L'){
            if(maxr+1 < n && s[maxr+1] == p[i].first && die[maxr+1] > i){
                maxr++;
            }
            if(maxl+1 < n && s[maxl+1] == p[i].first && die[maxl+1] > i){
                maxl++;
            }
        }else{
            if(maxl-1 >= 0 && s[maxl-1] == p[i].first && die[maxl-1] > i){
                maxl--;
            }
            if(maxr-1 >= 0 && s[maxr-1] == p[i].first && die[maxr-1] > i){
                maxr--;
            }
        }
    }

    maxl--;
    maxr++;

    int die2[200010] = {};
    for(int i = 0;i <= maxl;i++){
        die2[i] = 1;
    }

    for(int i = n-1;i >= maxr;i--){
        die2[i] = 1;
    }

    int cnt = 0;
    for(int i = 0;i < n;i++){
        cnt += die2[i];
    }

    cout << n-cnt << endl;
    return 0;
}

