int elegantSolution(vector<char> & charVec, vector<char> & squareVec, vector<char> & dirVec) {

    char lhs, rhs, c, d;
    lhs = charVec.front();
    rhs = charVec.back();

    int leftIdx = 0;
    int rightIdx = charVec.size()-1;


    for(int i = squareVec.size()-1; i >= 0; i--) {
        c = squareVec[i];
        d = dirVec[i];

        if(c == lhs && d == 'L') {
            leftIdx++;
            lhs = charVec[leftIdx];
        }

        if(c == rhs && d == 'R') {
            rightIdx--;
            rhs = charVec[rightIdx];
        }
    }

//    printf("%i:%i\n", leftIdx, rightIdx);

    int result = 0;

    if(rightIdx > leftIdx) {
        result = (rightIdx+1) - leftIdx;
    }

    return result;
}

