int N,Q;
string s;
vector<pair<char,char> > v;

int fall(int x){
  int i;
  REP(i,v.size()){
    if(v[i].first == s[x]){
      if(v[i].second == 'L') x--;
      else x++;
    }
    if(x<0) return 1;
    else if(x>=N) return 2;
  }
  return 0;
}

//mode 0 落ちない最小値，mode 1 落ちない最大値
int binary_search(int start,int end, int mode){
  while(true){
    int mid = (start+end)/2;
    int f = fall(mid);
    if(end-start<=1) break;
    if(mode){
      if(!f) start=mid;
      else end=mid;
    }else{
      if(!f) end=mid;
      else start=mid;
    }
  }
  while(start==N-1&&!fall(start+1))start++;
  if(mode) return start;
  else return end;
}

int main(void){
  int i,j;
  cin >> N >> Q;
  cin >> s;
  REP(i,Q){
    char x,y;
    cin >> x >> y;
    if( i == 0|| v[v.size()-1].first != x) v.push_back(pair<char,char>(x,y));
  }
  int start=0,end=N-1,mid;

  //xが落ちない位置になるようにする．
  while(true){
    mid = (start + end)/2;
    if(end-start < 1) break;
    int f = fall(mid);
    if(!f) break;
    else if(f==1) start = mid+1;
    else end = mid-1;
  }

  int S = binary_search(start, mid, 0); 
  int E = binary_search(mid, end,1);
  E++;
  cout << E-S << endl;
  return 0;
}

