    else spellD[i]=1;
  }

  int left = 0;
  int right = n;
  while(right-left>1){
    int mid = (right+left)/2;
    if(isRemoved(mid)==-1)left=mid;
    else right=mid;
  }
  int mostLeft = right;
  left = 0;
  right = n;
  while(right-left>1){
    int mid = (right+left)/2; 
    if(isRemoved(mid)==1)right=mid;
    else left=mid;
  }
