bool check(const string &s, const vector<pair<char, char>> &v, int x) {
    for (const auto &p : v) {
        if (s[x] == p.first) {
            x += (p.second == 'R' ? 1 : -1);
            if (x == -1)
                return true;
            if (x == s.size())
                return false;
        }
    }
    return false;
}

int get_rightmost(const string &s, const vector<pair<char, char>> &v) {
    int l = -1, r = s.size();
    while (r - l > 1) {
        int p = (l + r) >> 1;
        if (check(s, v, p))
            l = p;
        else
            r = p;
    }
    return l;
}

