int main() {
    int N,Q;
    string s;
    cin >> N >> Q >> s;

    int cnt_golem[N]; //添え字のマスにいるゴーレムの数
    long long ans = N; //最初はN体
    //各マスにゴーレム1体ずつ配置
    for(int i = 0; i < N; i++)
    {
        cnt_golem[i] = 1;
    }
    //呪文入力
    string t, d;
    for(int i = 0; i < Q; i++)
    {
        cin >> t[i] >> d[i];
    }

    //各呪文
    for(int i = 0; i < Q; i++)
    {
        //各マスについて
        for(int j = 0; j < N; j++)
        {
            //マス文字 == 呪文の文字 なら
            if (s[j] == t[i]) {

                //Lなら左へ移動する
                if (d[i] == 'L') {
                    //さらに、jが0ならj番目のマスにいるゴーレムを消す
                    if (j == 0) {
                        ans -= cnt_golem[j];
                    } else {
                        //jが0でないならj-1番目のマスを加算
                        cnt_golem[j-1] += cnt_golem[j];
                    }
                    //対象のマスのゴーレムはすべて移動した
                    cnt_golem[j] = 0;
                }

                //Rなら
                if (d[i] == 'R') {
                    //jがN-1なら全体数からゴーレムが消える
                    if (j == N-1) {
                        ans -= cnt_golem[j];
                    } else {
