int N, Q;
char s[200003];
char t[200003];
char d[200003];

inline int f(int ix) {
  assert(IN(ix, 0, N - 1));
  rep(i, Q) {
    if (ix == -1 || ix == N) break;
    char letter = s[ix];
    if (letter == t[i]) {
      if (d[i] == 'L')
        --ix;
      else
        ++ix;
    }
  }
  return ix;
}

int solve() {
  assert(strlen(s) >= N);
  s[N] = 0;

  int fL = f(0), fR = f(N - 1);

  if (fL == N) return 0;
  if (fR == -1) return 0;

  int leftmost;
  {
    if (fL >= 0)
      leftmost = 0;
    else {
      int ng = 0, ok = N - 1;
      while (ng + 1 < ok) {
        int x = (ng + ok) / 2;
        int fx = f(x);
        if (fx >= 0) {
          ok = x;
        } else {
          ng = x;
        }
      }
      leftmost = ok;
    }
  }

  int rightmost;
  {
    if (fR <= N - 1)
      rightmost = N - 1;
    else {
      int ok = 0, ng = N - 1;
      while (ok + 1 < ng) {
        int x = (ok + ng) / 2;
        int fx = f(x);
        if (fx <= N - 1) {
          ok = x;
        } else {
          ng = x;
        }
      }
      rightmost = ok;
    }
  }
  if (leftmost <= rightmost)
    return rightmost - leftmost + 1;
  else
    return 0;
}

