using namespace std;

typedef pair<int, int> P;

int N, Q;
string s;

map<int, int> memo;


int goal(int pos, vector<char>& t, vector<char>& d) {
    int original = pos;
    if (memo.count(pos) > 0) return memo[original];

    REP(i, Q) {
        if (s[pos] == t[i]) {
            d[i] == 'L' ? pos-- : pos++;
        }

        if (pos < 0) {
            return memo[original] = 1;
        }

        if (pos >= N) {
            return memo[original] = 2;
        }
    }

    return memo[original] = 0;
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    cin >> N >> Q;
    cin >> s;

    vector<char> t(Q), d(Q);
    REP(i, Q) {
        cin >> t[i] >> d[i];
    }

    if (goal(0, t, d) == 2 || goal(N - 1, t, d) == 1) {
        return 0;
    }

    int res = 0;

    if (goal(0, t, d) == 1) {
        int l = 0;
        int r = N - 1;
        while (r - l > 1) {
            int m = (l + r) / 2;
            if (goal(m, t, d) == 1) {
                l = m;
            } else {
                r = m;
            }
        }

        res += l + 1;
    }

    if (goal(N - 1, t, d) == 2) {
        int l = 0;
        int r = N - 1;
        while (r - l > 1) {
            int m = (l + r) / 2;
            if (goal(m, t, d) == 2) {
                r = m;
            } else {
                l = m;
            }
        }

        res += N - r;
    }

    cout << N - res << endl;

    return 0;
}

