template<typename A, size_t N, typename T>
void Fill(A(&array)[N], const T &val) {
	std::fill((T*)array, (T*)(array + N), val);
}

//変数
ll N,Q;
string S;

vector<vector<ll>> vec(26,vector<ll>());

//解法
void solve() {

	rep(i, S.size()) {
		vec[S[i] - 'A'].emplace_back(i);
	}

	vector<ll> ans(N, 1);

	ll del = 0;

	rep(i, Q) {
		char t, d;
		cin >> t >> d;

		if (d == 'R') {

			for (auto itr = vec[t - 'A'].end()-1;; --itr) {

				if (*itr == N - 1) {
					del += ans[*itr];
					ans[*itr] = 0;
				}
				else {
					ans[*itr + 1] += ans[*itr];
					ans[*itr] = 0;
				}

				if (itr == vec[t - 'A'].begin()) break;
			}

		}

		if (d == 'L') {
			for (auto itr = vec[t - 'A'].begin(); itr != vec[t - 'A'].end(); ++itr) {

				if (*itr == 0) {
					del += ans[*itr];
					ans[*itr] = 0;
				}
				else {
					ans[*itr - 1] += ans[*itr];
					ans[*itr] = 0;
				}

			}
		}

	}

	cout << N - del;

	return;
}

int main() {

	//入力
	cin >> N >> Q >> S;

	solve();
	cout << endl;
	return 0;
}

