bool rgt(vector<int>& vs, vector<int>& t, vector<int>& d, int ptr){
    auto n = vs.size();
    auto q =t.size();
    if (ptr >= n) return true;
    for (int i=0; i < q; ++i){
        if(vs[ptr] != t[i]) continue;
        ptr += d[i];
        if (ptr+q-i < n)break;
        if (ptr == n) return true;
    }
    return false;
}

bool lft(vector<int>& vs, vector<int>& t, vector<int>& d, int ptr){
    auto n = vs.size();
    auto q =t.size();
    if (ptr >= n) return false;
    if (ptr <0) return true;
    for (int i=0; i<q; ++i){
        if(vs[ptr] != t[i]) continue;
        ptr += d[i];
        if (ptr < 0)return true;
        if (q-i < ptr) break;
    }
    return false;
}

