            ptr = min(n-1, ptr + stp);
        }
        stp = (stp+1)/2;
    }
    auto r = ptr;
    ptr = r/2;
    stp = ptr/2+1;
    while(true){
        bool hr = lft(vs,t,d,ptr);
        bool nx = lft(vs,t,d,ptr-1);
        if(nx& !hr) break;
        if(!hr){
            ptr = max(ptr - stp,0);
        }else{
            ptr = min(n-1, ptr + stp);
        }
        stp = (stp+1)/2;
    }
    cout << r - ptr + 1 << endl;

    return 0;
}

