int solve(int N, int Q, string &s, vi&t, vi&q) {

    int x, leftmost=0, rightmost=N-1;
    {
        int lo=-1, hi=N;
        while (lo+1 < hi) {
            int mi=(lo+hi)/2, x = mi;
            bool good=false;
            rep(i,Q){
                if (x<0) { good=true; break; }
                if (x == N) { break ;}
                if (t[i]==s[x]) {
                    if (q[i]=='R') ++x; else --x;
                }
            }
            if (x < 0) good = true;
            if (good) lo=mi;
            else hi=mi;
        }
        leftmost = lo+1;
    }
    {
        int lo=-1, hi=N;
        while (lo+1 < hi) {
            int mi=(lo+hi)/2, x = mi;
            bool good=false;
            rep(i,Q){
                if (x == N) { good=true; break; }
                if (x < 0) { break ;}
                if (t[i]==s[x]) {
                    if (q[i]=='R') ++x; else --x;
                }
            }
            if (x == N) good = true;
            if (good) hi=mi;
            else lo=mi;
        }
        rightmost = hi-1;
    }
    return max(0, rightmost - leftmost + 1);
}

