#define forN(n, N) for(int n=0; n<N; n++)
#define res_out(ans) cout << ans << "\n";
#define ll long long

ll DIV = 1e9 + 7;
int N, S[int(2e5)];

ll dfs(int mod, int n){
    ll mdn = mod % S[n];
    if(mod == 0 || mod == S[n])return 0;
    else if(n == 0)return mdn;
    //else if(mod < S[n])return (dfs(mod, n - 1) * (n + 1)) % DIV;
    else {
        ll sum = dfs(mdn, n - 1);
        int fac = n;
        for(int i=n-1; i>0; i--){
            sum += dfs(mod % S[i], i - 1) * fac;
            fac *= i;
            if(sum > DIV)sum %= DIV;
        }
        sum += mod % S[0] * fac;
        return sum % DIV;
    }
}
int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int X;
    cin >> N >> X;
    forN(n, N)cin >> S[n];
    sort(S, S + N);
    res_out(dfs(X, N-1))
    return 0;
}

