// 二分探索をする
// { TTTTTFF } => output: 5
// funcを満たさない最小のIndexを返す
template<typename T>
T binarySearchFunction( int begin, int end, function<bool(T index)> func )
{
	T lb = begin-1, ub = end-1;
	while( lb < ub - 1 )
	{
		T mid = ( lb + ub ) / 2;
		if( func( mid ) ) lb = mid;
		else ub = mid;
	}
	if( func( ub ) ) return end;
	return ub;
}

int main()
{
	ll n, q;
	string s;
	cin >> n >> q >> s;
	vector<pair<char, bool>> v(q);
	REP(i,q)
	{
		char a,b;
		cin >> a >> b;
		v[i] = pair<char,bool>( a, b == 'R' );
	}

	auto is = [n, q, v, s] ( int idx ) -> bool
	{
		REP( i, q )
		{
			if( s[idx] == v[i].first )
			{
				idx += v[i].second ? 1 : -1;
				if( idx == -1 || idx == n )
					return true;
			}
		}
		return false;
	};
	auto isn = [is]( int idx ) 
	{
		return !is(idx);
	};

	ll ans = 0;

	ll mid = n / 2;
	ll midd = binarySearchFunction<ll>( 0, mid + 1, is );
	if( midd == mid + 1 )
	{
		midd = binarySearchFunction<ll>( mid, n, isn ) - 1;
		midd = max(midd, 0ll);
	}
	ans += binarySearchFunction<ll>( 0, midd + 1, is );
	ans += n - binarySearchFunction<ll>( midd, n, isn );

	cout << n - ans << endl;
	return 0;
}

