int N, Q;
string s;
char t[200000], d[200000];

bool check(int pos, bool left) {
    REP(i, Q) {
        if (s[pos] == t[i]) {
            if (d[i] == 'L') pos--;
            else pos++;
        }
        if (pos <= 0) return left;
        if (pos >= N + 1) return !left;
    }
    return false;
}

int binary_search(int ok, int ng, bool left) {
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;
        if (check(mid, left)) ok = mid;
        else ng = mid;
    }
    return ok;
}

int main() {
    cin >> N >> Q >> s;
    s = " " + s + " ";
    REP(i, Q) cin >> t[i] >> d[i];
    int left = binary_search(0, N + 1, true);
    int right = binary_search(N + 1, 0, false);
    cout << right - left - 1 << endl;
    return 0;
}

