            else l_go[ind] -= 1;
        }
    }
    return l_go[ind];
}

// 最後に0未満になる
int binsearch_zero(int first, int last) {
    int mid = (first+last)/2;
    if(mid == first) return first;
    if(posi(mid) < 0) {
        return binsearch_zero(mid, last);
    } else {
        return binsearch_zero(first, mid);
    }
}

// n-1以下になる最大のもの
int binsearch_n(int first, int last) {
    int mid = (first+last)/2;
    if(mid == first) return last;
    if(posi(mid) > n-1) {
        return binsearch_n(first, mid);
    } else {
        return binsearch_n(mid, last);
    }
}

