int Serch(int check) {
	for (int i = 0; i < q; i++) {
		if (t[i] == s[check]){
			if (d[i] == 'L') {
				check--;
			}
			else {
				check++;
			}
		}
		if (check < 0) { return -1; }
		if (check >= n) {
			return -2;
		}
	}
	return -3;
}


