using namespace std;

void move_left (int* _lrm, int* _moved_lrm, bool* _success_lrm, int lrm_idx, int _t, string _s, string mode) {
    if (!_success_lrm[lrm_idx]) {
        if (_t == _s[_moved_lrm[lrm_idx]]) {  // if the target golem is moved
            _moved_lrm[lrm_idx]--;
            if (_moved_lrm[lrm_idx] < 0) {  // golem steps out left side
                if (mode == "LeftSideOut") _success_lrm[lrm_idx] = true;
            }
        }
    }
}

void move_right (int* _lrm, int* _moved_lrm, bool* _success_lrm, int lrm_idx, int _t, string _s, string mode, int _N) {
    if (!_success_lrm[lrm_idx]) {
        if (_t == _s[_moved_lrm[lrm_idx]]) {  // if the target golem is moved
            _moved_lrm[lrm_idx]++;
            if (_moved_lrm[lrm_idx] > _N - 1) {  // golem steps out left side
                if (mode == "RightSideOut") _success_lrm[lrm_idx] = true;
            }
        }
    }
}


int main() {
    int N, Q;
    string s;
    int lrm[3];  // left, right, mid (margin)
    int moved_lrm[3]; // position of golem (simulation)
    bool success_lrm[3];
    int max_idx, min_idx;

    cin >> N >> Q;
    cin >> s;
    max_idx = -1, min_idx = N;
    // load queries
    char t_i[Q], d_i[Q];
    for (int q = 0; q < Q; ++q) {
        cin >> t_i[q] >> d_i[q];
    }

    // main calculation
    // search maximum index where golem step out left side (by binary search)
    // initialize
    lrm[0] = 0, lrm[1] = N-1, lrm[2] = (lrm[0] + lrm[1]) / 2;
    for (int k = 0; k < 3; ++k)  {
        success_lrm[k] = false;
    }
    while (lrm[0] != lrm[2]) {
        // printf("max_left_side_out: %d\n", max_idx);
        // initialize
        for (int k = 0; k < 3; ++k)  {
            moved_lrm[k] = lrm[k];
        }
        // printf("l, m, r = %d, %d, %d\n", lrm[0], lrm[2], lrm[1]);
        // simulation: move target golem
        for (int q = 0; q < Q; ++q) {
            // printf("moved: l, m, r = %d, %d, %d\n", moved_lrm[0], moved_lrm[2], moved_lrm[1]);
            // search position to move golem
