            if (d_i[q] == 'L') {
                if (lrm[0] == 0 && lrm[1] == N -1) {
                    for (int i = 0; i < 3; ++i) move_left(lrm, moved_lrm, success_lrm, i, t_i[q], s, "LeftSideOut");
                }
                else {
                    move_left(lrm, moved_lrm, success_lrm, 2, t_i[q], s, "LeftSideOut");  // we can reuse previous result for l and r
                    if (success_lrm[2]) break;
                }
            }
            // move right
            else {
                if (lrm[0] == 0 && lrm[1] == N -1) {
                    for (int i = 0; i < 3; ++i) move_right(lrm, moved_lrm, success_lrm, i, t_i[q], s, "LeftSideOut", N);
                }
                else {
                    move_right(lrm, moved_lrm, success_lrm, 2, t_i[q], s, "LeftSideOut", N);   // we can reuse previous result for l and r
                    if (success_lrm[2]) break;
                }
            }
        }

        // decide next mid
