            else if (success_lrm[0] && !success_lrm[2] && !success_lrm[1]) {
                // assign r m
                lrm[1] = lrm[2];
                success_lrm[1] = success_lrm[2];
                max_idx = lrm[0];
            }
            else { // anything does not change
                break;
            }
            // assign m
            lrm[2] = (lrm[0] + lrm[1]) / 2;
            success_lrm[2] = false;
        }
    }
