bool cmp1(int a, int b) {
    return a >= b;
}

bool cmp2(int a, int b) {
    return a > b;
}

int fall(int pos) {
    for (int i = 0; i < q; i++) {
        if (query[i].first == s[pos]) {
            pos += (query[i].second == 'L' ? -1 : 1);
        }
        if (pos < 0) {
            return 1;
        } else if (pos >= n) {
            return 3;
        }
    }
    return 2;
}

int bound(int x, bool (*cmp)(int a, int b)) {
    int start = 0, end = n - 1;
    while (end > start) {
        int mid = (start + end) / 2;
        if (cmp(fall(mid), x)) {
            end = mid;
        } else {
            start = mid + 1;
        }
    }
    return end;
}

