int main() {
    int N, Q;
    std::string S;
    std::cin >> N >> Q >> S;

    std::vector<std::pair<char, char>> query(Q);
    for (auto& p : query) std::cin >> p.first >> p.second;

    // idxが左(右)に出るなら-1(1)、出ないなら0を返す
    auto judge = [&](int idx) {
        for (auto& p : query) {
            if (S[idx] != p.first) continue;
            idx += (p.second == 'L' ? -1 : 1);
            if (idx < 0) return -1;
            if (idx >= N) return 1;
        }
        return 0;
    };

    // 左に出る中で一番右のやつ
    int l;
    {
        int ok = -1, ng = N;
        while (ng - ok > 1) {
            int mid = (ng + ok) / 2;
            (judge(mid) < 0 ? ok : ng) = mid;
        }
        l = ok;
    }

    // 右に出る中で一番左のやつ
    int r;
    {
        int ok = N, ng = -1;
        while (ok - ng > 1) {
            int mid = (ng + ok) / 2;
            (judge(mid) > 0 ? ok : ng) = mid;
        }
        r = ok;
    }

    std::cout << r - l - 1 << std::endl;
    return 0;
}

