  int L = 0;
  for(int i=Q-1; i>=0; i--){
    char t = td[i].first;
    char d = td[i].second;
    if(d=='L'){
      L = L + (t == s[L]);
    } else if(L>0) {
      L = L - (t == s[L-1]);
    }
    if(L<0){
      L=0;
    } else if(L>=N){
      L=N-1;
    }
  }


  int R = N-1;
  for(int i=Q-1; i>=0; i--){
    char t = td[i].first;
    char d = td[i].second;

    if(d=='R'){
      R = R - (t == s[R]);
    } else if(R<N-1) {
      R = R + (t == s[R+1]);
    }
    if(R<0){
      R=0;
    } else if(R>=N){
      R=N-1;
    }
  }

