int n, q;
string s;
char t[200100], d[200100];

bool check(int k) {
    int pos = k-1;
    for (int i = 0; i < q; i++) {
        if (pos < 0) return true;
        if (pos >= n) return false;

        if (s[pos] == t[i]) {
            if (d[i] == 'L') {
                pos--;
            } else {
                pos++;
            }
        }
    }
    if (pos < 0) return true;
    return false;
}

int calc() {
    int lb = 0, ub = n+1;
    while (ub - lb > 1) {
        int mid = (lb + ub) / 2;
        if (check(mid)) {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    return lb;
}

int solve() {
    int res = n;
    res -= calc();

    reverse(s.begin(), s.end());
    for (int i = 0; i < q; i++) {
        if (d[i] == 'L') d[i] = 'R';
        else d[i] = 'L';
    }
    res -= calc();
    return res;
}

void input() {
    cin >> n >> q >> s;
    for (int i = 0; i < q; i++) cin >> t[i] >> d[i];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(15);

    input();
    cout << solve() << endl;
}

