#define REP(i, n) for(int i=0; i<n; i++)

bool L[200100];
char T[200100];
int N, Q;
string S;

bool solvel(int mid){
    if(mid < 0) return false;
    if(mid >= N) return true;

    int v = mid;
    for(int i = 0; i < Q; i++){
        char t = T[i];
        bool left = L[i];

        if(t == S[v]){
            if(left) v--;
            else v++;
            if(v < 0) return false;
        }
    }
    return true;
}

bool solver(int mid){
    if(mid < 0) return true;
    if(mid >= N) return false;

    int v = mid;
    for(int i = 0; i < Q; i++){
        char t = T[i];
        bool right = !L[i];

        if(t == S[v]){
            if(right) v++;
            else v--;
            if(v >= N) return false;
        }
    }
    return true;
}

int main(){
    cin >> N >> Q;
    cin >> S;
    REP(i,Q){
        char t, d;
        cin >> t >> d;
        T[i] = t;
        L[i] = d == 'L';
    }

    int right = N;
    int left = 0;
    while(right - left > 1){
        int mid = (right+left)/2;
        bool valid = solvel(mid);
        if(valid){
            right = mid;
        }
        else{
            left = mid;
        }
    }

    int lim_left = left;
    //cout << lim_left << endl;


    right = N;
    left = 0;
    while(right - left > 1){
        int mid = (right+left)/2;
        bool valid = solver(mid);
        if(valid){
            left = mid;
        }
        else{
            right = mid;
        }
    }

    int lim_right = right;

    int ans = N;
    ans -= min(N, (lim_left+1) + (N-lim_right));

    cout << ans << endl;
    return 0;
}

