ll finalPos(ll mid, string s, vector<string> t, vector<string> d) {
    ll currentPos = mid;
    rep(i, sz(t)) {
        if (s[currentPos] == char(t[i][0])) {
            if (d[i] == "L") currentPos--;
            else currentPos++;
        }
        if (currentPos < 0 || currentPos >= sz(s)) break;
    }
    return currentPos;
}


void solve(ll N, ll Q, string s, vector<string> t, vector<string> d){
    ll l = -1;
    ll r = sz(s);
    while (r > l + 1) {
        ll mid = (r + l) / 2;
        if (finalPos(mid, s, t, d) < 0) {
            l = mid;
        } else {
            r = mid;
        }
    }
    ll left = r;
    l = -1;
    r = sz(s);
    while (r > l + 1) {
        ll mid = (r + l) / 2;
        if (finalPos(mid, s, t, d) >= sz(s)) {
            r = mid;
        } else {
            l = mid;
        }
    }
    ll right = l;
    cout << right - left + 1 << endl;
}

