int main()
{
    int N, Q;
    string s;
    cin >> N >> Q >> s;
    vector<char> t(Q);
    vector<char> d(Q);
    REP(i, Q) cin >> t[i] >> d[i];

    int L = -1, R = N;
    IREP(i, Q)
    {
        if (d[i] == 'L')
        {
            if (L + 1 < N and s[L + 1] == t[i]) L++;
            if (R < N and s[R] == t[i]) R++;
        }
        else
        {
            if (L >= 0 and s[L] == t[i]) L--;
            if (R > 0 and s[R - 1] == t[i]) R--;
        }
        if (L + 1 >= R) break;
