int BinarySearch(string &s) {
  int ok = -1, ng = n + 1;
  while (ng - ok > 1) {
    int mid = (ng + ok) / 2;
    auto check = [&](int mid) {
      if (mid == -1) return true;
      int now = mid;
      char nowc = s[mid];
      rep(i, 0, q) {
        if (nowc != t[i]) continue;
        if (d[i] == 'L') {
          now--;
        } else {
          now++;
        }
        if (now < 0) return false;
        if (now > n - 1) return true;
        nowc = s[now];
      }
      if (now >= 0) return true;
    };
    if (check(mid)) ng = mid;
    else ok = mid;
  }
  return ok;
}

