class UnionFind {
public:
  explicit UnionFind(int _n) : n(_n) {
    par.resize(_n);
    rank.resize(_n);
    sizes.resize(_n);
    for (int i = 0; i < _n; i++) {
      par[i] = i;
      rank[i] = 0;
      sizes[i] = 1;
    }
  }
  int find(int a) {
    if (par[a] == a) return a;
    return par[a] = find(par[a]);
  }
  bool same(int a, int b) {
    return find(a) == find(b);
  }
  void unite(int a, int b) {
    link(find(a), find(b));
  }
  int size(int a) {
    return sizes[find(a)];
  }
  void view() {
    for (int i = 0; i < n; i++) {
      cout << " par" << "[" << i << "]=" << par[i] << ((i == n - 1) ? "\n" : ",");
    }
    for (int i = 0; i < n; i++) {
      cout << "size" << "[" << i << "]=" << sizes[i] << ((i == n - 1) ? "\n" : ",");
    }
    cout << endl;
  }
private:
  void link(int a, int b) {
    if (same(a, b)) return;
    if (rank[a] > rank[b]) {
      par[b] = a;
      sizes[a] += sizes[b];
      sizes[b] = 0;
    } else {
      par[a] = b;
      if (rank[a] == rank[b]) rank[b]++;
      sizes[b] += sizes[a];
      sizes[a] = 0;
    }
  }
  int n;
  vector<int> par;
  vector<int> rank;
  vector<int> sizes;
};

template <typename T>
class IntervalTree {
  using F = function<T(T, T)>;
public:
  IntervalTree(int n, const F func, const T init) : func(func), init(init) {
    size = 1;
    while ((int)size < n) size <<= 1;
    table.assign(2 * size, init);
  }
  void set(int k, T x) {
    table[size + k] = x;
  }
  void build() {
    for (int i = size - 1; i >= 0; --i) {
      table[i] = func(table[i * 2], table[i * 2 + 1]);
    }
  }
  void update(int k, const T &x) {
    k += size;
    table[k] = x;
    while (k >>= 1) {
      table[k] = func(table[k * 2], table[k * 2 + 1]);
    }
  }
  T query(int a, int b) {
    T L = init, R = init;
    for (a += size, b += size; a < b; a >>= 1, b >>= 1) {
      if (a & 1) L = func(L, table[a++]);
      if (b & 1) R = func(table[--b], R);
    }
    return func(L, R);
  }
  T operator[](const int k) const {
    return table[k + size];
  }
private:
  unsigned int size;
  vector<T> table;
  const F func;
  const T init;
};

template <typename T, typename S = T>
class LazyIntervalTree {
  using F = function<T(T, T)>;
  using G = function<T(T, S, int)>;
  using H = function<S(S, S)>;
public:
  LazyIntervalTree(int n, const F f, const G g, const H h, const T &init, const S OM)
    : f(f), g(g), h(h), init(init), OM(OM) {
    size = 1;
    while (size < n) size <<= 1;
    data.assign(2 * size, init);
    lazy.assign(2 * size, OM);
  }
  void set(int k, const T &x) {
    data[k + size] = x;
  }
  void build() {
    for (int i = size - 1; i > 0; i--) {
      data[i] = f(data[2 * i], data[2 * i + 1]);
    }
  }
  void propagate(int k, int len) {
    if (lazy[k] != OM) {
      if (k < size) {
        lazy[2 * k] = h(lazy[2 * k], lazy[k]);
        lazy[2 * k + 1] = h(lazy[2 * k + 1], lazy[k]);
      }
      data[k] = g(data[k], lazy[k], len);
      lazy[k] = OM;
    }
  }
  T update(int a, int b, const S &x, int k, int l, int r) {
    propagate(k, r - l);
    if (r <= a || b <= l) {
      return data[k];
    } else if (a <= l && r <= b) {
      lazy[k] = h(lazy[k], x);
      propagate(k, r - l);
      return data[k];
    } else {
      return data[k] = f(update(a, b, x, 2 * k, l, (l + r) >> 1),
                         update(a, b, x, 2 * k + 1, (l + r) >> 1, r));
    }
  }
  T update(int a, int b, const S &x) {
    return update(a, b, x, 1, 0, size);
  }
  T query(int a, int b, int k, int l, int r) {
    propagate(k, r - l);
    if (r <= a || b <= l) {
      return init;
    } else if (a <= l && r <= b) {
      return data[k];
    } else {
      return f(query(a, b, 2 * k, l, (l + r) >> 1),
               query(a, b, 2 * k + 1, (l + r) >> 1, r));
    }
  }
  T query(int a, int b) {
    return query(a, b, 1, 0, size);
  }
  T operator[](const int &k) {
    return query(k, k + 1);
  }
private:
  int size;
  vector <T> data;
  vector <S> lazy;
  const F f;
  const G g;
  const H h;
  const T init;
  const S OM;
};

template <typename T>
class BIT {
public:
  BIT(int size) {
    BITTable.assign(++size, 0);
  }
  T sum(int k) {
    T res = 0;
    for (++k; k > 0; k -= k & -k) {
      res += BITTable[k];
    }
    return res;
  }
  T sum(int l, int r) { // [l, r]
    if (l == 0) return sum(r);
    return sum(r) - sum(l - 1);
  }
  void update(int k, T x) { // b[k] += x;
    for (++k; k < (int)BITTable.size(); k += k & -k) BITTable[k] += x;
