bool judgel(ll X) {
	for (query q: querys) {
		if (S[X] != q.s[0])continue;
		X += q.d;
	}
	return (X == 0);
}

bool judger(ll X) {
	for (query q : querys) {
		if (S[X] != q.s[0])continue;
		X += q.d;
	}
	return (X == N+1);
}

