	ll ls = 0, le = N+1;
	//ls以左の駒は<1に出て死ぬ le以右は死なない
	while (le - ls > 1) {
		ll m = (le + ls) / 2;
		if (judgel(m))ls = m;
		else le = m;
	}
	ll re = N + 1, rs = 0;
	//re以右の駒は>Nに出て死ぬ rs以左は死なない
	while (re - rs > 1) {
		ll m = (re + rs) / 2;
		if (judger(m))re = m;
		else rs = m;
	}
	cout << rs - le + 1 << "\n";
	return 0;
}

