int check_drop(int j, const std::vector<char> &t, const std::vector<char> &d,
               const int Q, const int N, const std::string &s) {
  assert(1 <= j and j <= N);
  for (int i = 1; i <= Q; ++i) {
    if (t[i] == s[j]) {
      if (d[i] == 'L') {
        if (j == 1) {
          return -1;
        } else {
          j -= 1;
        }
      } else if (d[i] == 'R') {
        if (j == N) {
          return 1;
        } else {
          j += 1;
        }
      }
    }
  }
  return 0;
}

