// 落ちるヤツの数
int check(int n, string &s, vector<Query> &queries) {
    int floor = 0;
    int ceil = n - 1;

    function<bool(int)> ch = [&](int i) {
        int now = i;
        for (Query &q : queries) {
            if (q.c != s[now]) continue;
            else if (q.d == 'L') now--;
            else if (q.d == 'R') now++;
            if (now == -1) return false;
        }
        return true;
    };

    if (ch(floor)) {
        return 0;
    }
    if (!ch(ceil)) {
        return n;
    }

    while (floor + 1 < ceil) {
        int mid = (floor + ceil) / 2;
        bool b = ch(mid);
        if (b) ceil = mid;
        else floor = mid;
    }

    return floor + 1;

}

