    if(C(mid))l=mid;
    else r=mid;
  }
  int left=l+1;
  l=-1,r=n;
  while(r-l>1){
    int mid=(l+r)/2;
    if(C2(mid))r=mid;
    else l=mid;
  }
  int right=n-r;
  int sub=min(n,left+right);
  cout<<n-sub<<endl;
}

