void solve() {
  int n, q; cin >> n >> q;
  string s; cin >> s;
  vector<pair<char, char>> g(q); cin >> g;

  int l = -1, r = n;
  int ans = n, memo = n;

  while (r - l > 1) {
    int mid = (l + r) / 2;
    int idx = mid;

    for (auto &p : g) {
      if (s[idx] == p.first) {
        if (p.second == 'L') {
          if (--idx == -1) {
            l = mid;
            break;
          }
        }
        else {
          if (++idx == n) {
            memo = mid;
            break;
          }
        }
      }
    }

    if (idx != -1) r = mid;
  }

  ans -= r;

  r = memo;

  while (r - l > 1) {
    int mid = (l + r) / 2;
    int idx = mid;

    for (auto &p : g) {
      if (s[idx] == p.first) {
        if (p.second == 'L') {
          --idx;
        }
        else {
          if (++idx == n) {
            r = mid;
            break;
          }
        }
      }
    }

    if (idx != n) l = mid;
  }

  ans -= n - r;

  cout << ans << endl;
}


