using namespace std;
#define int long long

bool check(int c, int N, int Q, string &s, vector<string> &t, vector<string> &d) {
    c--;
    for (int i = 0;i < Q; ++i) {
        if (s[c] == t[i][0]) {
            if (d[i][0] == 'L') {
                c--;
            } else {
                c++;
            }
        }
        if (c < 0) {
            return true;
        }
        if (c >= N) {
            return false;
        }
    }
    return false;
}

int func(int N, int Q, string &s, vector<string> &t, vector<string> &d) {
    int l = 0, r = N + 1;
    while(r - l > 1) {
        int c = (l + r) / 2;
        if (check(c, N, Q, s, t, d)) {
            l = c;
        } else {
            r = c;
        }
    }
    return l;
}

void solve(long long N, long long Q, std::string s, std::vector<std::string> t, std::vector<std::string> d){
    int res = 0;
    res += func(N,Q,s,t,d);
    reverse(ALL(s));
    for(int i = 0; i < Q; ++i) {
        if(d[i] =="L") {
            d[i] = "R";
        } else {
            d[i] = "L";
        }
    }
    res += func(N, Q, s, t, d);
    cout << N - res << endl;
}

