void doQuery(pair<char, char> q) {
	for (int i = 0; i < N; i++) {
		if (go[i] == -1 || go[i] == N) continue;

		if (s[go[i]] == q.first) {
			if (q.second == 'L') {
				go[i]--;
			}
			else {
				go[i]++;
			}
		}
	}
}

