void warshall_floyd(ll n)
{
    for (size_t i = 0; i < n; i++)
    {
        for (size_t j = 0; j < n; j++)
        {
            for (size_t k = 0; k < n; k++)
            {
                dist[j][k] = min(dist[j][k], dist[j][i] + dist[i][k]);
            }
        }
    }
}

class UnionFind
{
  public:
    vector<ll> Parent;

    UnionFind(ll N)
    {
        Parent = vector<ll>(N, -1);
    }
    ll find(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = find(Parent[A]);
    }

    ll size(ll A)
    {
        return -Parent[find(A)];
    }

    bool Union(ll A, ll B)
    {
        A = find(A);
        B = find(B);
        if (A == B)
        {
            return false;
        }
        if (size(A) < size(B))
            swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

ll powMod(ll a, ll p)
{
    if (p == 0)
    {
        return 1;
    }
    else if (p % 2 == 0)
    {
        ll half = powMod(a, p / 2);
        return mulMod(half, half);
    }
    else
    {
        return mulMod(powMod(a, p - 1), a);
    }
}

using pchar = pair<char, char>;
int simulate(string str, vector<pchar> td, int pos)
{

    for (auto &&i : td)
    {
        if (str[pos] != i.first)
            continue;
        if (i.second == 'L')
            --pos;
        else
            ++pos;
        if (pos < 0)
            return -1;
        if (pos >= (int)str.size())
            return 1;
    }
    return 0;
}

int main()
{
    long long N;
    scanf("%lld", &N);
    long long Q;
    scanf("%lld", &Q);
    std::string s;
    std::cin >> s;
    vector<pchar> td(Q);

    for (int i = 0; i < Q; i++)
    {
        cin >> td[i].first >> td[i].second;
    }

    int low = -1, high = N;
    while (high - low > 1)
    {
        int mid = (high + low) / 2;
        if (simulate(s, td, mid) == -1)
            low = mid;
        else
            high = mid;
    }
    int left_fall = high;

    low = -1, high = N;
    while (high - low > 1)
    {
        int mid = (high + low) / 2;
        if (simulate(s, td, mid) == 1)
            high = mid;
        else
            low = mid;
    }
    int right_fall = N - 1 - low;

    cout << N - (left_fall + right_fall) << endl;
    return 0;
}

