string s;

int fall(int index,vector<char> v){//調べる位置、呪文
    for(int i=0;i < v.size();i+=2){
        if(s.at(index)==v.at(i)){
            if(v.at(i+1)=='L'){
                index--;
                if(index<0){
                    return 1;
                }
            }
            else{
                index++; 
                if(index>=s.size()){
                    return 2;
                }
            }
        }
    }
    return false;
}//indexの位置のゴレムが左に落ちるなら1,右なら2,そうでないなら0を返す

int main(){
