        cin >> v.at(j);
    }//input

    int ok = -1,ng = s.size();//条件を満たすほうをok、そうでない方をngとする

    while(abs(ok-ng)>1){
        int mid = (ok+ng)/2;

        if(fall(mid,v)==1){
            ok=mid;
        }
        else{
            ng=mid;
        }
    }
    lb = ok;

    ng = -1;
    ok = s.size();

    while(abs(ok-ng)>1){
        int mid = (ok+ng)/2;

        if(fall(mid,v)==2){
            ok=mid;
        }
        else{
            ng=mid;
        }
    }
    rb = ok;


    cout << s.size()-min(lb+1+s.size()-rb,s.size())<< endl;
}

