pair<char,char> orders[200010];

int dfs (int index,int order) {
  if(order == q-1){
    return 1;
  }
  if(index == -1 || index == N) {
    return 0;
  }
  if(orders[order + 1].first == s[index]) {
    return 0;
  } else {
    if(orders[order + 1].first == s[index+1] && orders[order + 1].second == 'L') {
      return dfs(index+1,order+1) + dfs(index,order+1);
    }
    else if(orders[order + 1].first == s[index-1] && orders[order + 1].second == 'R') {
      return dfs(index-1,order+1) + dfs(index,order+1);
    }
    else {
      return dfs(index,order+1);
    }
  }
}

