  }
  int ans = 0;
  rep(i,q){
    if(orders[i].first == s[0] && orders[i].second == 'L'){
      ans += dfs(0,i);
    }
    if(orders[i].first == s[N-1] && orders[i].second == 'R') {
      ans += dfs(N-1,i);
    }
  }
  cout << N - ans << endl;
  return 0;
}

