int main() {
    int n, m; cin >> n >> m;

    string s; cin >> s;

    vector<char> qColor(m, 0), qType(m, 0);

    for(int i = 0; i < m; i += 1) {
        cin >> qColor[i] >> qType[i];
    }

    auto get = [&] (int who) {
        for(int i = 0; i < m; i += 1) {
            if(qColor[i] == s[who]) {
                if(qType[i] == 'L') {
                    who--;
                    if(who < 0)
                        return -1;
                } else {
                    who++;
                    if(who >= n)
                        return 1;
                }
            } 
        }

        return 0;
    };

    int st = -1, dr = -1;

    for(int lf = 0, rt = n - 1; lf <= rt;) {
        int mid = (lf + rt) / 2;
        int value = get(mid);

        if(value == 0) {
            st = mid;
            rt = mid - 1;
        } else if(value == 1) {
            rt = mid - 1;
        } else {
            lf = mid + 1;
        }
    }

    if(st == -1) {
        cout << "0\n";
        return 0;
    }

    for(int lf = 0, rt = n - 1; lf <= rt;) {
        int mid = (lf + rt) / 2;
        int value = get(mid);

        if(value == 0) {
            dr = mid;
            lf = mid + 1;
        } else if(value == -1) {
            lf = mid + 1;
        } else {
            rt = mid - 1;
        }
    }

    cout << (dr - st + 1) << "\n";
