int simulate(const string &s, const vector<P> &td, int pos) {
    for (auto c : td) {
        if (s[pos] != c.first) continue;
        if (c.second == 'L') --pos;
        else ++pos;
        if (pos < 0) return -1; // 左に落ちる
        if (pos >= s.size()) return 1; // 右に落ちる
    }
    return 0;
}

