typedef long long int ll;

string s;
int n, q;
char command[200000][2];

bool gotoleft(int i){
    int pointer = i;
    char nowchar = s[pointer];
    for(int i=0; i<q; i++){
        if(command[i][0] == nowchar){
            if(command[i][1] == 'L'){
                pointer --;
                if(pointer < 0){
                    return true;
                }
                nowchar = s[pointer];
            }else{
                pointer ++;
                if(pointer >= n){
                    return false;
                }
                nowchar = s[pointer];
            }
        }
    }

    return false;
}

bool gotoright(int i){
    int pointer = i;
    char nowchar = s[pointer];
    for(int i=0; i<q; i++){
        if(command[i][0] == nowchar){
            if(command[i][1] == 'L'){
                pointer --;
                if(pointer < 0){
                    return false;
                }
                nowchar = s[pointer];
            }else{
                pointer ++;
                if(pointer >= n){
                    return true;
                }
                nowchar = s[pointer];
            }
        }
    }

    return false;
}

int main(){

    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> q;

    cin >> s;

    for(int i=0; i<q; i++){
        cin >> command[i][0] >> command[i][1];
    }

    if(n <= 3){
        int res_count = 0;
        for(int i=0; i<n; i++){
            if(gotoleft(i) || gotoright(i)){
                res_count++;
            }
        }

        cout << n - res_count << endl;
        return 0;
    }
    int left = 0; 
    int right = n-1;
    int leftans;
    while(true){
        bool res = gotoleft((right+left)/2);
        if(res==true){
            left = (right+left)/2;
        }else{
            right = (right+left)/2;
        }

        if(right-left==1){
            leftans = right;
            break;
        }
    }


    left = 0;
    right = n-1;
    int rightans;
    while(true){
        bool res = gotoright((right+left)/2);
        if(res==true){
            right = (right+left)/2;
        }else{
            left = (right+left)/2;
        }

        if(right-left==1){
            rightans = left;
            break;
        }
    }


    if(n-1-rightans+leftans> n){
        cout << 0 << endl;
    }else{
        cout << n - (n-1-rightans) - (leftans-0) << endl;
    }

    return 0;
