const int N = 2e5+5;
int n, Q;
char s[N], t[N][2], d[N][2];

int move(int p){
    int i;
    for(i = 1; i <= Q && 1 <= p && p <= n; i++){
        if(s[p] != t[i][0]) continue;
        if(d[i][0] == 'L') p--;
        else p++;
    }
    return p;
}

int findL(int l, int r){
    if(l > r) return 0;
    int m = (l+r)/2, p;
    p = move(m);
    if(p < 1){
        int t = findL(m+1, r);
        return max(m, t);
    }
    else return findL(l, m-1);
}

int findR(int l, int r){
    if(l > r) return n+1;
    int m = (l+r)/2, p;
    p = move(m);
    if(p > n){
        int t = findR(l, m-1);
        return min(m, t);
    }
    else return findR(m+1, r);
}

