                        break;
                    }
                }
            }
            if (!c)
                ok = -1;
            else
                ok = 0;
        }
        left = ok + 1;

    }
    ll right = 0;
    {
        //! 左に落ちる最大値
        ll ok = N - 1, ng = -1;
        while (abs(ok - ng) > 1)
        {
            ll mid = (ok + ng) / 2;
            if (checkR(mid))
                ok = mid;
            else
                ng = mid;
