int simulate(int idx) {
  for (int i = 0; i < Q; i++) {
    if (t[i] != s[idx]) continue;

    (d[i] == 'L' ? idx-- : idx++);
    if (idx < 0 || idx >= N) break;
  }

  return idx;
}

bool isLeftFall(int idx) {
  return simulate(idx) < 0;
}

bool isRightFall(int idx) {
  return simulate(idx) >= N;
}

