#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

int simulate(int j, const std::string &arrayChar,
             const std::vector<char> &queryChar,
             const std::vector<char> &queryDirection) {
  const int numArray = arrayChar.length() - 1;
  const int numQuery = queryChar.size() - 1;
  assert(numQuery == static_cast<int>(queryDirection.size()) - 1);
  assert(1 <= j and j <= numArray);
  // move j by queries
  for (int i = 1; i <= numQuery; ++i) {
    // query hit
    if (queryChar[i] == arrayChar[j]) {
      switch (queryDirection[i]) {
      case 'L': // move left
        if (j == 1)
          return -1;
        --j;
        break;
      case 'R': // move right
        if (j == numArray)
          return +1;
        ++j;
        break;
      default:
        assert(false);
      }
    }
  }
  return 0;
}

int main() {
  // Input
  int numArray; // index: j
  int numQuery; // index: i
  std::cin >> numArray >> numQuery;
  assert(1 <= numArray and numArray <= 2 * 1.0e+5);
  assert(1 <= numQuery and numQuery <= 2 * 1.0e+5);
  std::string arrayChar;
  std::cin >> arrayChar;
  arrayChar.insert(arrayChar.begin(), '-');
  assert(static_cast<int>(arrayChar.length()) == 1 + numArray);
  std::vector<char> queryChar(1 + numQuery);
  std::vector<char> queryDirection(1 + numQuery);
  for (int i = 1; i <= numQuery; ++i) {
    std::cin >> queryChar[i] >> queryDirection[i];
    assert(queryDirection[i] == 'L' or queryDirection[i] == 'R');
  }

  // left drop
  int ng = numArray + 1;
  int ok = 0;
  while (abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;
    if (simulate(mid, arrayChar, queryChar, queryDirection) == -1)
      ok = mid;
    else
      ng = mid;
  }
  assert(abs(ok - ng) == 1);
  const int leftDrop = ok;

  // right drop
  ng = 0;
  ok = numArray + 1;
  while (abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;
    if (simulate(mid, arrayChar, queryChar, queryDirection) == +1)
      ok = mid;
    else
      ng = mid;
  }
  assert(abs(ok - ng) == 1);
  const int rightDrop = ok;

  std::cout << rightDrop - leftDrop - 1 << std::endl;

  return 0;
}

