int N, Q;
std::string S;
char t[200100], d[200100];

bool can(int x){
    for(int i=0;i<Q;++i){
        if(S[x] == t[i]){
            if(d[i] == 'L'){
                x -= 1;
            }else{
                x += 1;
            }

            unless(0 <= x && x < N){
                return true;
            }
        }
    }

    return false;
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N >> Q >> S;

    for(int i=0;i<Q;++i){
        std::cin >> t[i] >> d[i];
    }

    int cnt = N;

    if(can(0)){
        int lb = 0, ub = N;
        while(ub - lb > 1){
            int m = (lb + ub) / 2;
            if(can(m)){
                lb = m;
            }else{
                ub = m;
            }
        }

        cnt -= lb + 1;
    }

    if(cnt > 0 && can(N - 1)){
        int lb = -1, ub = N - 1;
        while(ub - lb > 1){
            int m = (lb + ub) / 2;
            if(can(m)){
                ub = m;
            }else{
                lb = m;
            }
        }

        cnt -= N - ub;
    }

    std::cout << cnt << std::endl;
}

