unsigned long long memo[100][100] = {};
unsigned long long nCr(const int n, const int r){
	if(n<r) return 0;
	if(r==0 || n==r) return 1;
	if(memo[n][r]>0) 
		return memo[n][r];
	else
		return memo[n][r] = nCr(n-1,r) + nCr(n-1,r-1);
}
