int N,Q;
string s;
char t[200001],d[200001];
bool LL(int pos){
	rep(i,Q){
		if(s[pos]==t[i] && d[i]=='R')
			pos++;
		else
			pos--;
		if(pos<0)
			return true;
		if(N<=pos)
			return false;
	}
	return false;
}
bool RR(int pos){
	rep(i,Q){
		if(s[pos]==t[i] && d[i]=='L')
			pos++;
		else
			pos--;
		if(pos<0)
			return false;
		if(N<=pos)
			return true;
	}
	return false;
}
int searchL(int a, int b){
	// cout << pair(a,b) << endl;
	if(a+1==b){
		if(a==0 && !LL(0)){
			return 0;
		}else if(b==N-1 && LL(N-1))
			return N;
		return b;
	}
	int m = (a+b)/2;
	int pos = m;
	rep(i,Q){
		if(t[i]==s[pos]){
			if(d[i]=='R') pos++;
			else pos--;
			if(pos<0){
				return searchL(m,b);
			}
		}
	}
	return searchL(a,m);
}
int searchR(int a, int b){
	// cout << pair(a,b) << endl;
	if(a+1==b){
		if(b==N-1 && !RR(N-1)){
			// cout << "RR" <<endl;
			return 0;
		}else if(a==0 && RR(0))
			return N;
		return N-b;
	}
	int m = (a+b)/2;
	int pos = m;
	rep(i,Q){
		if(t[i]==s[pos]){
			if(d[i]=='R') pos++;
			else pos--;
			if(N<=pos)
				return searchR(a,m);
		}
	}
	return searchR(m,b);
}

int main(){
	cin >> N>>Q>>s;
	rep(i,Q)
		cin >> t[i] >> d[i];

	int posL = searchL(0,N-1);
	// cout << posL << endl;

	int posR = searchR(0,N-1);
	// cout << posR <<endl;

	cout << N-(posR+posL) << endl;


}

