	for (int i = q; i >= 1; i--) {
		if (l + 1 >= r) {
			printf("%d\n", 0);
			return;
		}
		if (d[i][0] == 'L' && l + 1 < n && t[i][0] == S[l + 1]) {
			l++;
		}
		if (d[i][0] == 'R' && r - 1 >= 0 && t[i][0] == S[r - 1]) {
			r--;
		}
		if (l + 1 >= r) {
			printf("%d\n", 0);
			return;
		}
	}

	int ans = r - l - 1;
	printf("%d\n", ans);
}

