}

bool check2(int ans, int N, int Q) {
     int cur = ans;
     for (int i = 0; i < Q; i++) {
         if (s[cur] - 'A' != t[i]) continue;
         cur += d[i];
         if (cur >= N) return true;
     }
     return false;
}

