    }
    int l = 0, r = N + 1, ans1 = -1, ans2 = -1;
    while (l < r) {
          int mid = (l + r) / 2;
          if (check1(mid, N, Q)) {
             ans1 = mid;
             l = mid + 1;
          } else r = mid;
    }
    l = 0, r = N + 1;
