vector<pair<char, char>> spells; // pair of <t, d>

// Check the destination of x. Return true if x does not reach to -1.
bool checkL(ll x) {
  rep(i, q) {
    char t, d;
    tie(t, d) = spells[i];
    if (s[x] == t) { // match
      if (d == 'L') { --x; } else { ++x; }
    }
    if (x < 0) { return false; }
    if (x >= n) { return true; }
  }
  return true;
}

// Check the destination of x. Return true if x does not reach to n.
bool checkR(ll x) {
  rep(i, q) {
    char t, d;
    tie(t, d) = spells[i];
    if (s[x] == t) { // match
      if (d == 'L') { --x; } else { ++x; }
    }
    if (x >= n) { return false; }
    if (x < 0) { return true; }
  }
  return true;
}

int main(int argc, char** argv) {
  cin.tie(NULL);
  cout.tie(NULL);
  ios_base::sync_with_stdio(false);
  //cout << setprecision(10) << fixed;

  cin >> n >> q;
  cin >> s;
  spells.resize(q);
  rep(i, q) {
    cin >> spells[i].first >> spells[i].second;
  }

  // Here, we do binary search to calculate left boundary.
  ll left;
  {
    ll l = -1, r = n;
    // search in (l, r]
    while (r-l > 1) {
      ll mid = (r+l)/2;
      if (checkL(mid)) { // mid does not go to -1
        r = mid;
      } else {
        l = mid;
      }
    }
    // Here, l is out. r is in.
    left = r;
  }

  // Here, we do binary search to calculate right boundary
  ll right;
  {
    ll l = -1, r = n;
    // search in [l, r)
    while (r-l > 1) {
      ll mid = (r+l)/2;
      if (checkR(mid)) { // mid does not go to n
        l = mid;
      } else {
        r = mid;
      }
    }
    // Here, r is out. l is in.
    right = l;
  }

  if (right >= left) {
    cout << (right-left+1) << endl;
  } else {
    cout << 0 << endl;
  }
}

