    for(int i=1;i<=Q;i++)
    {
        if(pos==0)return 1;
        if(pos==n+1)return 0;
        if(A[i][0]==ch){pos+=(B[i][0]=='L')?-1:1;ch=s[pos];}
    }
    return (pos==0);
}
bool check2(int pos)
{
    char ch=s[pos];
    for(int i=1;i<=Q;i++)
    {
        if(pos==n+1)return 1;
        if(pos==0)return 0;
        if(A[i][0]==ch){pos+=(B[i][0]=='L')?-1:1;ch=s[pos];}
    }
