tuple<char, int> calc(int target) {
    int index = target;
    for (int i = 0; i < Q; i++) {
        char c = s[index];
        if (t[i] == c) {
            if (d[i] == 'L') {
                index--;
            } else {
                index++;
            }
            if (index == -1) {
                return forward_as_tuple('L', target);
            } else if (index == N) {
                return forward_as_tuple('R', target);
            }
        }
    }
    if (target > 0) {
        return calc(target-1);
    } else if (target < N) {
        return calc(target+1);
    }

    return forward_as_tuple('C', -1);
}

