        cout << fall(i) << '\n';
    }
     */
    // cout << lower_bound(2) << ' ' << lower_bound(3) << '\n';
    int pos1 = lower_bound(2), pos2 = lower_bound(3);
    int ans = 0;
    if (pos1 - 1 >= 0 && fall(pos1 - 1)) {
        ans += pos1;
    }
    if (fall(pos2) == 3) {
        ans += (n - pos2);
    }
