			plc += rd[i].second;
		if (plc >= n)
			return true;
		if (plc < 0)
			return false;
	}
	return false;
}
bool isvalL(int plc) {
	for (int i = 0; i < q; i++) {
		if (rd[i].first == s[plc]) 
			plc += rd[i].second;
		if (plc < 0)
			return true;
