			return false;
	}
	return false;
}
int getBSL() {
	int up = n, dw = -1;
//	cout << "L = " << endl;
	while (up - dw > 1) {
		int md = (up + dw) / 2;
//		cout << "md = " << md << endl;
		if (isvalL(md)) {
			dw = md;
		}
		else {
			up = md;
		}
	}
	return dw;
}
int getBSR() {
	int up = n, dw = -1;	
//	cout << "r = " << endl;
	while (up - dw > 1) {
		int md = (up + dw) / 2;
