  }
  int start=0,end=N-1,mid;

  //xが落ちない位置になるようにする．
  while(true){
    mid = (start + end)/2;
    if(end-start < 1) break;
    int f = fall(mid);
    if(!f) break;
    else if(f==1) start = mid+1;
    else end = mid-1;
  }
  int S,E;
  if(!fall(start)) S=start;
  else S = binary_search(start+1, mid, 0); 
  if(!fall(end)) E = end+1;
  else E = binary_search(mid, end,1);
  cout << E-S << endl;
  return 0;
}

