int fall(vector<char> &t, vector<char> &d, const string &s, int N, int pos){
  rep(i, t.size()){
    if(t[i]==s[pos]){
      pos += (d[i]=='L')?-1:1;
    }
    if(pos<0) return -1;
    if(pos>N-1) return 1;
  }
  return 0;
}

int main(){
  cin.tie(0); ios::sync_with_stdio(false);    // Magic for faster cin

  ll N, Q;
  cin >> N >> Q;
  string s;
  cin >> s;
  vector<char> t(Q);
  vector<char> d(Q);
  rep(i,Q) cin >> t[i] >> d[i];

  // cout << "debug" << endl;
  // rep(i,N){
  //   cout << fall(t,d,s,N,i) << " ";
  // }
  // cout << endl << "debug end" << endl;


  int res = N;

  int a=0; int b=N-1; int c;
  // int xa = fall(t,d,s,N,a);
  // int xb = fall(t,d,s,N,b);

  int target = 0;

  // leftmost binary search
  while(true){
    if(a==b) break;
    c = (a+b)/2;
    int xc = fall(t,d,s,N,c);
    //printf("%d %d %d %d %d\n", a, b, c, xc, target);
    if(xc<target) a = c+1;
    else b = c;
  }

  int leftmost = a;

  // rightmost binary search
  a=0; b=N-1;
  while(true){
    //printf("%d %d %d %d %d\n", a, b, c, xc, target);
    if(a==b) break;

    c = (a+b+1)/2;
    int xc = fall(t,d,s,N,c);

    if(xc>target) b = c-1;
    else a = c;
  }

  int rightmost = a;

  //cout << leftmost << "\t" << rightmost << endl;

  cout << rightmost - leftmost + 1 << endl;

  return 0;
}

