#include <bits/stdc++.h>
using namespace std;


class Solution {
  vector<int> V;
  vector<pair<int, int>> td;
  int n, q;
  string s;
  bool searchLeft(int v) {
    for (auto t_d : td) {
      char t, d; tie(t, d) = t_d;
      if (t == s[v]) v += d == 'L' ? -1 : 1;
    }
    return v == 0;
  }
  bool searchRight(int v) {
    for (auto t_d : td) {
      char t, d; tie(t, d) = t_d;
      if (t == s[v]) v += d == 'L' ? -1 : 1;
    }
    return v == n + 1;
  }
public:
  void run() {
    cin >> n >> q;
    V.resize(n + 2);
    cin >> s;
    s = " " + s + " ";
    for (int i = 0; i < q; ++i) {
      char t, d; cin >> t >> d;
      td.emplace_back(t, d);
    }
    int L, R;
    {
      int l = 0, r = n + 1;
      while (r - l > 1) (searchLeft(l + r >> 1) ? l : r) = l + r >> 1;
      L = l;
    }
    {
      int l = 0, r = n + 1;
      while (r - l > 1) (searchRight(l + r >> 1) ? r : l) = l + r >> 1;
      R = r;
    }
    cout << R - L - 1 << '\n';
  }     
};
int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);
  Solution().run();
}

