    v.push_back(pair<char,char>(x,y));
  }
  int start=0,end=N,mid;

  //xが落ちない位置になるようにする．
  while(true){
    mid = (start + end)/2;
    int f = fall(mid);
    if(!f) break;
    else if(f==1) start = mid;
    else end = mid;
    if(end-start < 1) break;
  }
  int S,E;
  //S左側に落ちない最初
  //E右側に落ちる最初
  if(fall(start)%2==0) S=start;
  else S = binary_search(start, mid, 0); 
  if(fall(end)!=2) E = end+1;
  else E = binary_search(mid, end,1);
  cout << E-S << endl;
  return 0;
}

