int dfs(int pos, int turn)
{
	auto &res = memo[turn][pos];
	if (res)
	{
		return res;
	}
	int c = s[pos] - 'A';
	auto it = lower_bound(mv[c].begin(), mv[c].end(), turn);
	if (it == mv[c].end())
	{
		return res = 1;
	}
	int k = *it;
	pos += ds[k];
	if (pos < 0 || pos >= n)
	{
		return res = -1;
	}
	turn = k + 1;
	res = dfs(pos, turn);
	return res = res;
}

