typedef tuple<char, char> tcc;

ll solve_left_drop(const string &s, const V<tcc> &tdlist)
{
    ll left = 0LL;
    ll right = s.size() - 1LL;
    ll start = (left + right) / 2LL;
    ll ret = -1LL;

    for ( ; left <= right; start = (left + right) / 2LL) {
        ll now = start;
        for (auto td : tdlist) {
            char t = get<0>(td);
            char d = get<1>(td);
            if (s[now] == t) {
                if (d == 'L') now--;
                if (d == 'R') now++;
            }
            if (now < 0LL || s.size() <= now) break;
        }
        if (now < 0LL) {
            ret = max(ret, start);
            left = start + 1LL;
        }
        else {
            right = start - 1LL;
        }
    }

    return ret + 1LL;
}

ll solve_right_drop(const string &s, const V<tcc> &tdlist)
{
    ll left = 0LL;
    ll right = s.size() - 1LL;
    ll start = (left + right) / 2LL;
    ll ret = s.size();

    for ( ; left <= right; start = (left + right) / 2LL) {
        ll now = start;
        for (auto td : tdlist) {
            char t = get<0>(td);
            char d = get<1>(td);
            if (s[now] == t) {
                if (d == 'L') now--;
                if (d == 'R') now++;
            }
            if (now < 0LL || s.size() <= now) break;
        }
        if (now >= s.size()) {
            ret = min(ret, start);
            right = start - 1LL;
        }
        else {
            left = start + 1LL;
        }
    }

    return s.size() - ret;
}

