long N, Q;
string s;
vector<unsigned char> t, d;

bool simulate(int i, unsigned char dir) {
    for (int q = 0; q < Q; q++) {
        if (t[q] == s[i]) {
            if (d[q] == 'L') i--;
            else             i++;
        }
        if (dir == 'L' && i < 0) return true;
        if (dir == 'R' && i >= N) return true;
    }
    return false;
}

int main() {
    cin >> N >> Q >> s;
    t.resize(Q);
    d.resize(Q);
    for (int q = 0; q < Q; q++) cin >> t[q] >> d[q];

    // left
    long Lmin = -1;
    long Lmax = N;
    long L;
    while (true) {
        L = (Lmin + Lmax) / 2;
        if (simulate(L, 'L')) {
            Lmin = L;
            if (Lmax - Lmin == 1) break;
        } else {
            Lmax = L;
            if (Lmax - Lmin == 1) {
                L--;
                break;
            }
        }
    }

    // right
    long Rmin = -1;
    long Rmax = N;
    long R;
    while (true) {
        R = (Rmin + Rmax) / 2;
        if (simulate(R, 'R')) {
            Rmax = R;
            if (Rmax - Rmin == 1) break;
        } else {
            Rmin = R;
            if (Rmax - Rmin == 1) {
                R++;
                break;
            }
        }
    }

    cout << N - (L+1) - (N-R) << endl;

    return 0;
}

