auto solve() {
    int N,Q;
    cin>>N>>Q;
    string s;
    cin>>s;
    vector<pair<char,char>> mvs(Q);
    for(auto&&e:mvs) {
        cin >> e.first >> e.second;
    }

    auto bins = [&]() -> int
    {
        int lb = 0, rb = N+1;

        while(rb - lb > 1) {
            int _med = ((ll)rb + lb) / 2;
            int p = _med - 1;
            bool ok = false;

            for(auto&&e:mvs) {
                int c = s[p];

                if(c == e.first) {
                    if(e.second == 'R') p++;
                    else p--;
                }

                if(p < 0 || p >= N) {
                    ok = true;
                    break;
                }
            }

            if(ok) lb = _med;
            else rb = _med;
        }

        return lb;
    };

    // to left
    int leftp = bins();
    reverse(all(s));
    REP(i,Q) {
        if(mvs[i].second == 'R') mvs[i].second = 'L';
        else mvs[i].second = 'R';
    }
    int rightp = bins();

    return N - min(N, leftp+rightp);
}


