    for (int i = 0; i < N; i++) golem[i] = 1;
    // stock char --> index hash
    for (int i = 0; i < N; ++i) {
        alphabet_idxes[s[i] - 'A'].push_back(i);
    }

    for (int q = 0; q < Q; ++q) {
