char IsEliminated(vector<char> t, vector<char> d, string s, int n){
  char now;
  int pos;
  pos = n;
  now = s[pos];
  for (int i=0; i<t.size(); i++) {
    if (t[i] == now) {
      if (d[i] == 'L') {
        pos--;
      }else{
        pos++;
      }
    }
    if (pos > (int)s.size()-1) {
      return 'R';
    }else if (pos < 0) {
      return 'L';
    }
    now = s[pos];
  }
  return '0';
}

int leftedge_elim(vector<char> t, vector<char> d, string s){
  int ok, ng, mid;
  ok = -1;
  ng = (int)s.size();
  while(abs(ok-ng) > 1){
    mid = (ok+ng)/2;
    char ans = IsEliminated(t, d, s, mid);
    if (ans == 'L')
      ok = mid;
    else
      ng = mid;
  }
  return ok;
}

int rightedge_elim(vector<char> t, vector<char> d, string s){
  int ok, ng, mid;
  ok = (int)s.size();
  ng = -1;
  while(abs(ok-ng) > 1){
    mid = (ok+ng)/2;
    if (IsEliminated(t, d, s, mid) == 'R')
      ok = mid;
    else
      ng = mid;
  }
  return ok;
}

