int solveL(const string& s, const vector<pair<char,char>>& v){
  int lb = 0, ub = s.size();
  while(ub-lb>1){
    int m = (lb+ub)/2;
    {
      int pos = m;
      rep(i,v.size()){
        if(s[pos] == v[i].first){
          if(v[i].second == 'L') pos--;
          else pos++;
        }
        if(pos <= 0) break;
      }
      if(pos <= 0) lb = m;
      else ub = m;
    }
  }
  return ub;
}

int solveR(const string& s, const vector<pair<char,char>>& v){
  int lb = 0, ub = s.size();
  while(ub-lb>1){
    int m = (lb+ub)/2;
    {
      int pos = m;
      rep(i,v.size()){
        if(s[pos] == v[i].first){
          if(v[i].second == 'L') pos--;
          else pos++;
        }
        if(pos >= s.size()-1) break;
      }
      if(pos >= s.size()-1) ub = m;
      else lb = m;
    }
  }
  return lb;
}

