//左から押し出されるなら-1
//押し出されないなら0
//右から押し出されるなら1を返す
int simulate(int index){
	int p = index;
	for(int i=0;i<Q;i++){
		if(S[p]==T[i]){
			if(D[i]=='L') p--;
			if(D[i]=='R') p++;
			if(p<0) return -1;
			if(p>=N) return 1;
		}
	}
	return 0;
}

void solve(){
	//左から何番目までが左から押し出されるか
	int L;
	{
		int left = 0;
		int right = N;
		while(left+1<right){
			int center = (left+right)/2LL;
			if(simulate(center)==-1) left = center;
			else right = center;
		}
		L = left;
	}

	//右から何番目までが左から押し出されるか
	int R;
	{
		int left = 0;
		int right = N;
		while(left+1<right){
			int center = (left+right)/2LL;
			if(simulate(center)==1) right = center;
			else left = center;
		}
		R = right;
	}

	ans = R - L - 1;
}

