template<class Func>auto order_by(Func func)
{
	return [=](auto x, auto y)
	{
		return func(x) < func(y);
	};
}


void Main()
{
	int N, Q;
	std::cin >> N >> Q;
	std::string map;
	std::cin >> map;
	std::vector<std::pair<char, bool>> query(Q);
	for (auto& p : query)
	{
		char a, b;
		std::cin >> a >> b;
		p.first = a;
		p.second = b == 'R';
	}
	auto left = boost::upper_bound(boost::irange(0, N), false, order_by([&](int i)
		{
			for (auto p : query)
			{
				if (p.first == map[i])
				{
					i += p.second ? 1 : -1;
				}
				if (i < 0)
				{
					return false;
				}
				else if (N <= i)
				{
					return true;
				}
			}
			return true;
		}));
	auto right = boost::upper_bound(boost::irange(0, N), false, order_by([&](int i)
		{
			for (auto p : query)
			{
				if (p.first == map[i])
				{
					i += p.second ? 1 : -1;
				}
				if (i < 0)
				{
					return false;
				}
				else if (N <= i)
				{
					return true;
				}
			}
			return false;
		}));
	std::cout << right - left << std::endl;
}

