int main()
{
	int N,Q;
	int ans;
	string s;
	char t,d;

	cin >> N >> Q;
	cin >> s;
	vector<int> sin(N,1);

	for (int i = 0; i < Q; i++){
		cin >> t >> d;
		if (d == 'L'){
			for (int j = 0; j < N; j++){
				if (s.at(j) == t){
					if (j){
						sin.at(j-1) = sin.at(j - 1) + sin.at(j);
						sin.at(j) = 0;
					}else{
						sin.at(j) = 0;
					}
				}
			}
		}else if (d == 'R'){
			for (int j = 0; j < N; j++){
				if (s.at(N - 1 - j) == t){
					if (j){
						sin.at (N - j) = sin.at(N - j) + sin.at(N - j - 1);
						sin.at(N - j - 1) = 0;
					}else{
						sin.at(N - 1) = 0;
					}
				}
			}
		}
	}

	ans = 0;
	for ( int i = 0; i < N; i++){
		ans = ans + sin.at(i);
	}

	cout << ans << endl;

	return 0;
}

