const int MAX = 2e5+10;

int N, Q;
string s;
int S[MAX];
int t[MAX], d[MAX];

bool alive(int n, bool left) {
    REP (q, Q) if (S[n] == t[q]) {
        n += d[q];
        if (left) {
            if (n < 0) return false;
        } else {
            if (n >= N) return false;
        }
    }
    return true;
}

int main() {
    cin >> N >> Q >> s;
    REP (i, N) S[i] = s[i] - 'A';
