    }

    int l = -1, // 左で死ぬ
        r = N-1; // 左で死なない
    while (r - l > 1) {
        int m = (r+l) / 2;
        if (alive(m, true)) r = m;
        else l = m;
    }
    int left = l;

    l = 0, // 右で死なない
    r = N; // 右で死ぬ
    while (r - l > 1) {
        int m = (r+l) / 2;
        if (alive(m, false)) l = m;
        else r = m;
    }
    cout << r - left - 1 << endl;
}

