            if(idx == 0){
                leftside = true;
                break;
            }
            else if(idx == N) break;
        }

        if(leftside) ok = mid;
        else ng = mid;
    }

    ans -= ok;

    ok = N+1, ng = 0;
    while(ok - ng > 1){
        int mid = (ok + ng) / 2;

        int idx = mid;
        bool rightside = false;
        rep(i,Q){
            if(S[idx] == T[i]){
                if(D[i] == 'R') idx++;
                else idx--;
            }
            if(idx == N+1){
                rightside = true;
                break;
            }
            else if(idx == 0) break;
        }

        if(rightside) ok = mid;
        else ng = mid;
    }

    ans -= N+1-ok;

    cout << ans << endl;
}

