    while (pnt < q && 0 <= x) {
        if (st[x] == Spell[pnt].first)
            x += Spell[pnt].second;
        if (x >= n)
            return false;
        pnt++;
    }

    if (x < 0)
        return true;
    return false;
}

int BinSearch(int l, int r) {
    while (r - l > 1) {
        int mid = (l + r) / 2;
        if (f(mid))
            l = mid;
        else
            r = mid;
    }
    return r;
}

