using namespace std;

int func(string &s, vector<pair<char, char> > &vp, int pos)
{
  int N = s.size();
  int Q = vp.size();
  for (int i = 0; i < Q; ++i) {
    char t = vp[i].first;
    char d = vp[i].second;
    if (s[pos] == t) {
      if (d == 'L') --pos;
      else ++pos;
      if (pos < 0) return -1;
      if (pos >= N) return N;
    }
  }
  return pos;
}

int myfind(string &s, vector<pair<char, char> > &vp, int num)
{
  int N = s.size();
  if (func(s, vp, 0) >= num) return 0;
  if (func(s, vp, N - 1) < num) return N;
  int L = 0;
  int R = N - 1;
  while (R - L > 1) {
    int M = (L + R) / 2;
    if (func(s, vp, M) < num) {
      L = M;
    }
    else {
      R = M;
    }
  }
  return R;
}

int main()
{
  int N, Q;
  cin >> N >> Q;
  string s;
  cin >> s;
  vector<pair<char, char> > vp;
  for (int i = 0; i < Q; ++i) {
    char t, d;
    cin >> t >> d;
    vp.push_back(make_pair(t, d));
  }

  int begin = myfind(s, vp, 0);
  int end = myfind(s, vp, N);
  cout << end - begin << endl;

  return 0;
}

