bool okl(int ind) {
  char t = s[ind];
  for(int i = 0; i < q; ++i) {
    char c = ops[i].first;
    char op = ops[i].second;
    if(t == c){
      if(op == 'L'){
        ind--;
      }else{
        ind++;
      }
      if(ind == n) return false;
      if(ind == -1) return true;
      t = s[ind];
    }
  }
  return false;
}

int bs_left()
{
  int l = 0, r = n;
  while(l < r) {
    int m = (l + r) >> 1;
    if(!okl(m)) {
      r = m;
    } else {
      l = m + 1;
    }
  }
  return l;
}

bool okr(int ind) {
  char t = s[ind];
  for(int i = 0; i < q; ++i) {
    char c = ops[i].first;
    char op = ops[i].second;
    if(t == c){
      if(op == 'R'){
        ind++;
      }else{
        ind--;
      }
      if(ind == n) return true;
      if(ind == -1) return false;
      t = s[ind];
    }
  }
  return false;
}

