        cout << 0 << endl;
        return 0;
    }

    int l = findL(-1, N);
    int r = findR(-1, N);

    // if (l == -1) l = 0;
    // if (r == -1) r = N - 1;

    cout << r - l + 1 << endl;

    return 0;
}

