struct Box{
  int number;
  int golem;
  char str;
};

struct Spell{
  char str;
  char direction;
};

int main(){
  int N,Q;
  cin >> N >> Q;
  Box box[N + 2];
  Spell spell[Q];
  int counter = 0;
  box[0].golem = 0;
  box[N + 1].golem = 0;

  //ゴーレムを格納
  for(int i = 1;i <= N;i++){
    cin >> box[i].str;
    box[i].number = i;
    box[i].golem = 1;
  }
  //呪文を格納
  for(int i = 0;i < Q;i++){
    cin >> spell[i].str >> spell[i].direction;
  }

  //呪文で移動させる
  for(int i = 0;i < Q;i++){
    for(int j = 1;j <= N;j++){
      if(spell[i].str == box[j].str){
        //左右にゴーレムを移動させる
        if(spell[i].direction == 'R')box[j + 1].golem += box[j].golem;
        else box[j - 1].golem += box[j].golem;
        //自分のゴーレムを減らす
        box[j].golem = 0;
      } 
    }
  }

  //ゴーレムの数を数える
  counter = N - box[0].golem - box[N + 1].golem;

  cout << counter << endl;
}

