int n, q;
string s;
string t[MAX_Q], d[MAX_Q];

bool left(int i){
  if(i == 0) return true;
  for(int j = 0; j < q; j++){
    if(t[j][0] == s[i - 1]){
      if(d[j] == "R") ++i;
      else --i;
    }
    if(i == n + 1) return false;
    if(i == 0) return true;
  }
  return false;
}

bool right(int i){
  if(i == n + 1) return true;
  for(int j = 0; j < q; j++){
    if(t[j][0] == s[i - 1]){
      if(d[j] == "R") ++i;
      else --i;
    }
    if(i == 0) return false;
    if(i == n + 1) return true;
  }
  return false;
}

