  cin >> n >> q;
  cin >> s;
  for(int i = 0; i < q; i++){
    cin >> t[i] >> d[i];
  }

  int low = 0, high = n;
  while(high - low > 1){
    int mid = (low + high) / 2;
    if(left(mid)) low = mid;
    else high = mid;
  }
  int left = high;

  low = 1, high = n + 1;
  while(high - low > 1){
    int mid = (low + high) / 2;
    if(right(mid)) high = mid;
    else low = mid;
  }
  int right = high;

  int ans = (right - left);

  cout << ans << endl;

  return 0;
}

