void solve() {
    i64 N = RD();
    i64 Q = RD();
    auto S = RD<string>();

    auto ops = vec_reserve<pair<char,i64>>(Q);
    REP(_, Q) {
        char t = RD<char>();
        char d = RD<char>();
        if(d == 'L')
            ops.emplace_back(t, -1);
        else if(d == 'R')
            ops.emplace_back(t, 1);
        else
            ASSERT(false);
    }

    auto simulate = [N,&S,&ops](i64 x) -> i64 {
        if(x <  0) return -1;
        if(x >= N) return  1;

        for(const auto& op : ops) {
            char t; i64 dx; tie(t,dx) = op;
            if(S[x] == t) {
                x += dx;
                if(x <  0) return -1;
                if(x >= N) return  1;
            }
        }
        return 0;
    };

    i64 l_drop;
    {
        i64 lo = -1;  // 左から落ちる
        i64 hi =  N;  // 左から落ちない
        while(lo+1 < hi) {
            i64 mid = (lo+hi) / 2;
            if(simulate(mid) == -1)
                lo = mid;
            else
                hi = mid;
        }
        l_drop = hi;
    }

    i64 r_drop;
    {
        i64 lo = -1;  // 右から落ちない
        i64 hi =  N;  // 右から落ちる
        while(lo+1 < hi) {
            i64 mid = (lo+hi) / 2;
            if(simulate(mid) == 1)
                hi = mid;
            else
                lo = mid;
        }
        r_drop = N - hi;
    }

    DBG(l_drop, r_drop);
    i64 ans = N - l_drop - r_drop;

    PRINTLN(ans);
}

signed main() {


    solve();

    return 0;
}

