int bi_search_left(vector<char> &t,vector<char> &d,string s,int left,int right){
	if(left>right)	return left;
	int mid=left+(right-left)/2;
	int now=mid;
	for(int i=0;i<t.size();i++){
		if(now<0 || now>=s.size())	break;
		if(s.at(now)==t.at(i)){
			if(d.at(i)=='L')	now--;
			else if(d.at(i)=='R')	now++;
		}
	}
	if(now<0)	return bi_search_left(t,d,s,mid+1,right);
	else	return bi_search_left(t,d,s,left,mid-1);
}

int bi_search_right(vector<char> &t,vector<char> &d,string s,int left,int right){
	if(left>right)	return left;
	int mid=left+(right-left)/2;
	int now=mid;
	for(int i=0;i<t.size();i++){
		if(now<0 || now>=s.size())	break;
		if(s.at(now)==t.at(i)){
			if(d.at(i)=='L')	now--;
			else if(d.at(i)=='R')	now++;
		}
	}
	if(now>=s.size())	return bi_search_right(t,d,s,left,mid-1);
	else	return bi_search_right(t,d,s,mid+1,right);
}

