{
  if( a < b )
    {
      return gcd( b , a );

    }

  if( a % b == 0 )
    {
      return b;

    }

  return gcd( b , a % b );

}

int lcm( int a , int b ) // assuming a,b >= 1
{
  return  a * b / gcd( a , b );

}


