bool die(int ind) {
    int i = 0;
    while (i < Q) {
        while (Comd[i].first != s[ind] && i < Q)i++;
        if(i == Q)return 0;
        ind += Comd[i].second;
        if(ind < 0)return 1;
        if(ind > N - 1)return 0;
        i ++;
    }
    return 0;
}

bool dieR(int ind) {
    int i = 0;
    while (i < Q) {
        while (Comd[i].first != s[ind] && i < Q)i++;
        if(i == Q)return 0;
        ind += Comd[i].second;
        if(ind > N - 1)return 1;
        if(ind < 0)return 0;
        i ++;
    }
    return 0;
}

