			}
		}
		return false;
	};
	/* どんな二分探索でもここの書き方を変えずにできる！ */
	while (right - left > 1)
	{
		int mid = left + (right - left) / 2;

		if (ngR(mid))
			right = mid;
		else
			left = mid;
	}

	/* left は条件を満たさない最大の値、right は条件を満たす最小の値になっている */
	int ng_r = right;

	//左からあふれるものを探す。
	left = -1; //「index = 0」が条件を満たすこともあるので、初期値は -1
	right = n; // 「index = a.size()-1」が条件を満たさないこともあるので、初期値は a.size()

	auto ngL = [&](int now) {
		for (int i = 0; i < q; ++i)
		{
			if (v[i].first == s[now])
			{
				if (v[i].second == 'R')
				{
