int N, Q;

int falldir(int i, vector<vector<int>> &cmap, vector<pair<char,char>> &spells){
  for(auto s : spells){
    char t = s.first; char d = s.second;
    if(find(cmap[t-'A'].begin(), cmap[t-'A'].end(), i) != cmap[t-'A'].end()){
      // hit
      i += (d=='L'?-1:1);
      if(i<0){ return -1; }
      else if(i>=N){ return 1; }
    }
  }
  return 0;
}

int main(){
