  string s;
  cin>>s;

  vector<vector<int>> cmap(26);
  vector<pair<char,char>> spells;

  for(int i=0;i<N;i++){
    cmap[s[i]-'A'].push_back(i);
  }
  for(int h=1;h<=Q;h++){
    char t,d; cin>>t>>d;
    spells.push_back(make_pair(t,d));
  }

  int l=0, u=N;
  while(u-l>1){
    int m = (u+l)/2;
    if(falldir(m,cmap,spells)<0) l=m;
    else u=m;
  }
  int lower = l;

  l=0; u=N;
