using namespace std;
int biSearchLeft(string s, vector<char>qchar, vector<int> qdir){
    //二分探索
    int left,right,center;
    for(center = s.size()/2, left = 0, right = s.size(); left<right; center = (left+right)/2){
        //たどる処理
        char* pos = &s[center];
        for(int turn = 0; turn<qchar.size(); turn++){
            if(qchar[turn]==*pos){
                pos += qdir[turn];
            }
        }
        //探索範囲絞る
        if(*pos=='l'){
            left = center+1;
        }else{
            right = center;
        }
    }
    return center;
}
int biSearchRight(string s, vector<char>qchar, vector<int> qdir){
    //二分探索
    int left,right,center;
    for(center = s.size()/2, left = 0, right = s.size(); left<right; center = (left+right)/2){
        //たどる処理
        char* pos = &s[center];
        for(int turn = 0; turn<qchar.size(); turn++){
            if(qchar[turn]==*pos){
                pos += qdir[turn];
            }
        }
        //探索範囲絞る
        if(*pos=='r'){
            right = center-1;
        }else{
            left = center;
        }
    }
    return center;
}
