int Tofront(){
	int l = 1, r = n, mid, ans = 0;
	while( l <= r ){
		mid = l+r >> 1;
		if( Simulate(mid) == 0 ){
			ans = mid;
			l = mid+1;
		}else{
			r = mid-1;
		}
	}
	return ans;
}

// XXXXXOOOOO
int Toback(){
	int l = 1, r = n, mid, ans = n+1;
	while( l <= r ){
		mid = l+r >> 1;
		if( Simulate(mid) == n+1 ){
			ans = mid;
			r = mid-1;
		}else{
			l = mid+1;
		}
	}
	return ans;
}

