lli func(vector<pair<char,char>> *v){
	/*まず左から落ちるものを探し出す*/
	lli high=n;
	lli low=-1;
	lli middle;
	while(high-low>1){
		middle = (low+high)/2;
		if(calc(middle,v,L)){
			low = middle;
		}
		else high = middle-1;
	}
	lli left = high;

	high=n;
	low =-1;
	while(high-low>1){
		middle = (low+high)/2;
		if(calc(middle,v,R)){
			high=middle;
		}
		else low = middle+1;
	}
	lli right = low;
	if(DEBUG)cout<<"left="<<left<<" right="<<right<<endl;
	return right-left-1;
