    int ok_l = ok;

    // 右に抜けるケース
    ok = N, ng = -1;
    while(abs(ng - ok) > 1) {
        int c = (ng + ok) / 2;

        if(isOK(c, s, t, d) == 3) ok = c;
        else ng = c;
    }
    int ok_r = ok;

    cout << (ok_r - ok_l - 1) << endl;

    return 0;
}

