bool check(int x, int type) {
	char cur = s[x];
	for (int i = 0; i < q; ++i) {
		if (t[i] == cur) {
			x += (d[i] == 'L') ? -1 : +1;
			if (x >= 0 && x < n) cur = s[x];
		}
		if (x < 0 || x >= n) {
			if (type == 0 && x < 0) return true;
			if (type == 1 && x >= n) return true;
			return false;
		}
	}
	return false;
}

