	}

	int res = n;

	int low = 0, high = n - 1;
	while(low < high) {
		int mid = ((low + high + 1) >> 1);
		if (check(mid, 0)) low = mid;
		else high = mid - 1;
	}
	if (check(low, 0)) res -= low + 1;
	cerr << low << endl;

	low = 0, high = n - 1;
	while(low < high) {
		int mid = ((low + high) >> 1);
		if (check(mid, 1)) high = mid;
		else low = mid + 1;
	}
	if (check(low, 1)) res -= n - low;
	cerr << low << endl;

	cout << res << endl;
}

