const int Qlim = 2 * POW_10_5;
int N, Q;
string s;
char t[Qlim], d[Qlim];

bool LeftHamide(int pos) {
  REP(i, Q) {
    if (t[i] == s[pos]) {
      if (d[i] == 'L') {
        --pos;
        if (pos < 0) { return true; }
      } else {
        ++pos;
        if (pos >= N) { return false; }
      }
    }
  }
  return false;
}

bool RightHamide(int pos) {
  REP(i, Q) {
    if (t[i] == s[pos]) {
      if (d[i] == 'L') {
        --pos;
        if (pos < 0) { return false; }
      } else {
        ++pos;
        if (pos >= N) { return true; }
      }
    }
  }
  return false;
}

int Ans() {
  int ans = N;

  if (LeftHamide(0)) {
    int l = 0, r = N;
    while (l+1 != r) {
      int m = (l + r) / 2;
      if (LeftHamide(m)) {
        l = m;
      } else {
        r = m;
      }
    }
    ans -= l + 1;
  }

  // (l, r]
  if (RightHamide(N-1)) {
    int l = -1, r = N-1;
    while (l != r-1) {
      int m = (l + r) / 2;
      if (RightHamide(m)) {
        r = m;
      } else {
        l = m;
      }
    }
    ans -= N - r;
  }

  return ans;
}

