bool safe_left(int pos){  // s[pos] が左に落ちずに生き残るかどうか？ 左に落ちない最初のものを探す
  int left = 0, num = 0;
  char cur = s[pos];
  rep(i, q){
    if (t[i] == cur){
      if (d[i] == 'L') {
        if (pos == 0) return false;
        --num; left = min(left, num);
        cur = s[pos - 1];
      }
      else {
        ++num; cur = s[pos + 1];
      }
    }
  }
  if (pos + left >= 0) return true;
  else return false;
}

bool fall_right(int pos){  // s[pos] が右に落ちるどうか？ 右に落ちる最小のものを探す
  int right = 0, num = 0;
  char cur = s[pos];
  rep(i, q){
    if (t[i] == cur){
      if (d[i] == 'R') {
        if (pos == n - 1) return true;
        ++num; right = max(right, num);
        cur = s[pos + 1];
      }
      else {
        --num; cur = s[pos - 1];
      }
    }
  }
  if (pos + right > n - 1) return true;
  else return false;
}

