  while (r1 - l1 > 1){
    int m1 = (r1 + l1) / 2;
    if (safe_left(m1)) r1 = m1;
    else l1 = m1;
  }

  while (r2 - l2 > 1){
    int m2 = (r2 + l2) / 2;
    if (fall_right(m2)) r2 = m2;
    else l2 = m2;
  }

  //print(l1); print(l2); print(r1); print(r2);  
  print(n - (r1 + (n - r2)));

  return 0;
}

