void solve() {
    //const i64 mod = 1'000'000'007;

    i64 N,Q;
    string s;
    cin >> N >> Q >> s;

    vector<map<i64,i64>> color(26);
    rep(i,0,N){
        color[s[i]-'A'][i]++;
    }

    vector<char> t(Q),d(Q);
    vector<vector<pair<i64,char>>> query(26); // 色 -> (時間, 方向)
    rep(i,0,Q) {
        cin >> t[i] >> d[i];
        query[t[i]-'A'].emplace_back(make_pair(i,d[i]));
    }

    vector<map<i64,bool>> memo(N);
    vector<map<i64,bool>> done(N);
    function<bool(i64,i64)> rec=[&](i64 i,i64 j){
        if(i<0 or N<=i) return false;
        if(j>=Q) return true;

        auto& res=memo[i][j];
        if(done[i][j]) return res;
        done[i][j]=true;

        auto it=lower_bound(begin(query[s[i]-'A']),end(query[s[i]-'A']),make_pair(j,char(0)));
        if(it==query[s[i]-'A'].end()){
            return res=true;
        }
        i64 nj=it->first;
        char dist=it->second;
        return res=rec(i+(dist=='L'?-1:1),nj+1);
    };

    i64 ans=0;
    rep(i,0,N){
        if(rec(i,0)) ++ans;
    }

    cout << ans << endl;
}

