int main() {
    int N(in()), Q(in());
    uint64_t gs[N];

    for (int i : LR(0, N)) {
        char c;
        cin >> c;
        auto ite = pos.find(c);
        if (ite == pos.end()) {
            deque<int> temp;
            temp.push_back(i);
            pos.insert(make_pair(c, temp));            
        } else {
            ite->second.push_back(i);
        }
        gs[i] = 1;            
