int fall(int x){
  int i;
  REP(i,v.size()){
    if(v[i].first == s[x]){
      if(v[i].second == 'L') x--;
      else x++;
    }
    if(x<0) return 1;
    else if(x>=N) return 2;
  }
  return 0;
}

//mode 0 落ちない最小値，mode 1 落ちる最小値
int binary_search(int start,int end, int mode){
  while(true){
    int mid = (start+end)/2;
    int f = fall(mid);
    if(end-start<=1) break;
    if(mode){
      if(!f) start=mid;
      else end=mid;
    }else{
      if(!f) end=mid;
      else start=mid;
    }
  }
  return end;
}

