int check_golem_pos(int mid, string str, char t[], char d[]){
    int golem_pos = mid;

    for(int i = 0; i < Q; i++){
        if(golem_pos == -1 || golem_pos == N) break;

        if(str[golem_pos] == t[i]){
            if(d[i] == 'R'){
                golem_pos++;
            }
            else{
                golem_pos--;
            }
        }
    }

    return golem_pos;
}

