	vector <char> masu(n);
	vector <int> go(n, 1);

	for (int i = 0; i < n; i++)
	{
		char c;
		cin >> c;
		masu[i] = c;
	}

	int cnt = n;
	for (int i = 0; i < q; i++)
	{
		char t;
		char d;

		cin >> t >> d;

		auto migi = masu.begin();
		auto itr = find(migi, masu.end(), t);
		vector <int> taihi(n, 0);

		while (itr != masu.end())
		{
			if (d == 'R')
			{
				if (itr == masu.end() -1)
				{
					cnt -= go[n - 1];
					go[n - 1] = 0;
				}
				else
				{
					int basyo = itr - masu.begin();
					taihi[basyo + 1] = go[basyo];
					go[basyo] = 0;
				}
			}
			else
			{	
				if (itr == masu.begin())
				{
					cnt -= go[0];
					go[0] = 0;
				}
				else
				{
					int basyo = itr - masu.begin();
					taihi[basyo - 1] = go[basyo];
					go[basyo] = 0;
				}
			}
			migi = itr + 1;
			itr = find(migi, masu.end(), t);
		}
		for (int j = 0; j < n; j++)
		{
			go[j] += taihi[j];
		}
	}

	cout << cnt << endl;

	return 0;
}

