const int MAXN = 100 * 1000 + 10;
int n, q;
char c[MAXN], s[MAXN];
bool d[MAXN];

bool dead(int ind)
{
	for (int i = 0; i < q; i ++)
	{
		if (c[i] == s[ind])
			ind += (d[i] ? +1 : -1);
		if (ind < 0)
			return true;
	}
	return false;
}

int bs()
{
	int l = 0, r = n + 1;
	while (r - l > 1)
	{
		int mid = (l + r) / 2;
		if (dead(mid - 1))
			l = mid;
		else
			r = mid;
	}
	return l;
}

