	bool ok=false;
	rep(i,q){
		if(t[i]==s[p]){
			if(d[i]=='R'){
				p++;
			}else{
				p--;
			}
		}
		if((a==0 && p==0)||(a==1 && p==n+1)){
			ok=true;
			break;
		}
	}
