			ans=n;
		}else{
			ll ok=1,ng=n;
			while(ng-ok>1){
				ll mid = (ng+ok)/2;
				if(f(mid,0)){
					ok=mid;
				}else{
					ng=mid;
				}
			}
			ans+=ok;
