int main() {
  int N,Q;
  cin >> N >> Q;
  vector<char> s(N), t(Q), d(Q);
  vector<vector<int>> vec(26, vector<int>(0,{}));
  string alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  vector<int> gore(N,1);

  for (int i = 0; i < N; i++) {
    cin >> s.at(i);
  }
  for (int i = 0; i < Q; i++) {
    cin >> t.at(i) >> d.at(i);
  }

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < 26; j++) {
      if(s.at(i) == alpha.at(j)){
        vec.at(j).push_back(i);
      }
    }
  } 

  vector< vector<int> > tempgore(1, vector<int>(2));
  for (int i = 0; i < Q; i++) {
    int k = 0;
    for (int j = 0; j < 26; j++) {
      if(t.at(i) == alpha.at(j)){
        k = j;
      }
    }
    int masusuu = vec.at(k).size();
    if(masusuu == 0){
      continue;
    }

    for (int j = 0; j < masusuu; j++) {
      int p = vec.at(k).at(j);
      int q;
      if(d.at(i) == 'L'){
        q = -1;
      }
      else{
        q = 1;
      }
      if(p == 0 && q == -1) {
        gore.at(p) = 0;
        continue;
      }
      if(p == N-1 && q == 1) {
        gore.at(p) = 0;
        continue;
      }

      int place = p + q;
      tempgore.push_back({place,gore.at(p)});
      gore.at(p) = 0;  
    }

    int masusuu2 = tempgore.size();
    if (masusuu2 == 0) {
      for(int j = 0; j < masusuu2; j++) {
        tempgore.erase(tempgore.begin());
      }
      continue;
    }
    for (int j = 0; j < masusuu2; j++) {
      int x = tempgore.at(j).at(0), y = tempgore.at(j).at(1);
      gore.at(x) += y;
    }
    for(int j = 0; j < masusuu2; j++) {
      tempgore.erase(tempgore.begin());
    }
  }

