Query qs[MAXN];

bool death(int pos, int dir) {
	int i = 0;
	while (i < Q && 0 <= pos && pos < N) {
		if (qs[i].c == s[pos]) {
			pos += qs[i].dir;
		}
		i++;
	}

	return pos == dir;
}

