	}

	int l = 0, r = N - 1, ans1 = -1;
	while (l <= r) {
		int m = (l + r) >> 1;
		if (death(m, -1)) {
			ans1 = m;
			l = m + 1;
		}
		else {
			r = m - 1;
		}
	}

	int ans2 = N;
	l = 0, r = N - 1;
	while (l <= r) {
		int m = (l + r) >> 1;
		if (death(m, N)) {
			ans2 = m;
			r = m - 1;
		}
		else {
			l = m + 1;
		}
	}

	int ans = N - (ans1 + 1) - (N - ans2);
