bool is_die(int pos, int N, int Q, string s, vector<char> t, vector<char> d) {
    rep(i, Q) {
        if (s[pos] == t[i]) {
            if (d[i] == 'L') pos--;
            else pos++;
        }
        if (pos < 0 or N <= pos) {
            return true;
        }
    }
    return false;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, Q;
    string s;
    vector<char> t(Q), d(Q);

    cin >> N >> Q;
    cin >> s;
    rep(i, Q) cin >> t[i] >> d[i];

    int lb = 0, ub = N;
    int live_lb = 0, live_ub = N;
    if (is_die(0, N, Q, s, t, d) == true) {
        while (ub - lb > 1) {
            int mid = (lb + ub)/2;
            if (is_die(mid, N, Q, s, t, d) == false) {
                ub = mid;
            } else {
                lb = mid;
            }
        }
        live_lb = ub;
        if (is_die(live_lb - 1, N, Q, s, t, d) == false) live_lb--;
    }

    lb = live_lb; ub = N;
    if (is_die(N - 1, N, Q, s, t, d) == true) {
        while (ub - lb > 1) {
            int mid = (lb + ub)/2;
            if (is_die(mid, N, Q, s, t, d) == false) {
                lb = mid;
            } else {
                ub = mid;
            }
        }
        live_ub = ub;
    }

    cout << max(0, live_ub - live_lb) << endl;
    return 0;
}

