{
    int N, Q;
    cin >> N >> Q;

    string s;
    cin >> s;

    unordered_map<char, vector<int>> indices;
    for (int i = 0; i < N; ++i) {
        indices[s[i]].emplace_back(i);
    }

    vector<int> golems(N, 1);

    for (int i = 0; i < Q; ++i) {
        char ti, di;
        cin >> ti >> di;

        for (int index : indices[ti]) {
            if (index == 0 && di == 'L') {
                golems[index] = 0;
                continue;
            }

            if (index == N-1 && di == 'R') {
                golems[index] = 0;
                continue;
            }

            if (di == 'L') {
                golems[index-1] += golems[index];
                golems[index] = 0;
            } else {
                golems[index+1] += golems[index];
                golems[index] = 0;
            }
        }
    }

    int ans = accumulate(begin(golems), end(golems), 0);
    cout << ans << endl;

    return 0;
}

