      if (v[i].se == 'L') {
        k--;
        if (k < 0) return 1;
      } else {
        k++;
        if (k >= n) return 0;
      }
    }
  }

  return 0;
}

bool okr(int k) {
  if (k == 0) return 1;
  k = n - k;

  REP(i,q) {
    if (s[k] == v[i].fi) {
      if (v[i].se == 'L') {
        k--;
        if (k < 0) return 0;
      } else {
        k++;
        if (k >= n) return 1;
      }
    }
  }

  return 0;
}


