    // 呪文の適用範囲をマップにする
    vector<vector<int>> applies(26, vector<int>(0));
    for(int i = 0 ; i < s.length(); ++i) {
        char c = s[i];
        applies[c - 'A'].push_back(i);
    }

    // 頭からやる
    for(int i = 0 ; i < q ; ++i) {
        char t; // 適用するマス
        char d; // 方向 L or R
