            // 普通にやる
            for(int j = 0 ; j < applies[index].size() ; ++j) {
                auto target = applies[index][j];
                if(target == 0) {
                    golems[target] = 0;
                } else {
                    golems[target - 1] += golems[target];
                    golems[target] = 0;
                }
            }
        } else {
            // 右からやる
            for(int j = applies[index].size() - 1 ; j >= 0 ; --j) {
                auto target = applies[index][j];
                if(target == n - 1) {
                    golems[target] = 0;
                } else {
                    golems[target + 1] += golems[target];
                    golems[target] = 0;
                }
            }
        }
    }

