void up(const string str, const int size, const char c,vector<int>& vec){
  for (int i = size - 1;i > 0;i --){
    if(c == str.at(i - 1)){
      vec.at(i) += vec.at(i - 1);
      vec.at(i - 1) = 0;
    }
  }
}
