	int ng_l = -1, ok_l = n - 1;

	while(abs(ok_l - ng_l) > 1){
		const int mid = (ok_l + ng_l) / 2;
		int cur = mid;
		rep(i, q){
			if(cur < 0 or n <= cur) break;
			if(t[i] == s[cur]){
