	};

	inp inp1; // input one

	// T は返り値の型
	template<typename T>
	T BinarySearch(T left, T right, function<bool(T)> Check) {
		while (right - left > 1) {
			int mid = (right + left) / 2;
			if (Check(mid)) left = mid; // 右を探す
			else right = mid;                       // 左を探す
		}
		// mid = left, mid = right - 1 となっている
		return left;
	}
}


int main() {

	int n, q;
	string s;
	cin >> n >> q >> s;
	vector<char> t(q), d(q);
	rep(i, q) cin >> t[i] >> d[i];

	int left_drop = BinarySearch<int>(0, n, [&](int mid)->bool {
		// midが左にドロップするかどうか
		int pos = mid;
		bool drop = false;
		rep(i, q) {
			if (s[pos] != t[i]) continue;
			// 移動する番
			if (d[i] == 'L') --pos;
			else ++pos;

			if (pos < 0) {
				drop = true;
				break;
			}
			if (pos >= n) {
				break;
			}
		}
		return drop;
		});

	int right_drop = BinarySearch<int>(0, n, [&](int mid)->bool {
		// midが右にドロップするかどうか
		int pos = mid;
		bool drop = false;
		rep(i, q) {
			if (s[pos] != t[i]) continue;
			// 移動する番
			if (d[i] == 'L') --pos;
			else ++pos;

			if (pos < 0) {
				//drop = true;
				break;
			}
			if (pos >= n) {
				drop = true;
				break;
			}
		}
		return !drop;
		}) + 1;

	int ans = right_drop - left_drop - 1;
	Cout(ans);

	return 0;
}

