string s;
vector<pair<char, char>> v;

int check(int idx){
    for(auto e: v){
        if(s[idx] == e.first){
            if(e.second == 'R')idx++;
            else idx--;
        }
        if(idx < 0)return -1;
        else if(idx >= s.size())return 1;
    }
    return 0;
}

int bsearch(bool left){
    int ok = (left ? -1 : s.size()), ng = (left ? s.size() : -1);
    while(abs(ok-ng) > 1){
        int mid = (ok+ng) / 2;
        if(left){
            if(check(mid) == -1)ok = mid;
            else ng = mid;
        }else{
            if(check(mid) == 1)ok = mid;
            else ng = mid;
        }
    }
    return ok;
}

