bool right_fall_flag(ll pos){
  for(int i=0; i<Q; ++i){
    if(str[pos] == t[i]){
      if(d[i]=='R'){
        pos++;
        if(pos>=N) return true;
      }else{
        pos--;
        if(pos<0) return false;
      }
    }
  }
  return false;
}

bool left_fall_flag(ll pos){
  for(int i=0; i<Q; ++i){
    if(str[pos] == t[i]){
      if(d[i]=='R'){
        pos++;
        if(pos>=N) return false;
      }else{
        pos--;
        if(pos<0) return true;
      }
    }
  }
  return false;
}

ll right_search(void){
  ll left = 0;
  ll right = N-1;
  if(right_fall_flag(left)) return 0;
  if(!right_fall_flag(right)) return N;
  while(right-left>1){
    ll mid = (left+right)/2;
    if(right_fall_flag(mid)) right = mid;
    else left = mid;
  }
  if(right_fall_flag(left)) return left;
  return right;
}

ll left_search(void){
  ll left = 0;
  ll right = N-1;
  if(!left_fall_flag(left)) return -1;
  if(left_fall_flag(right)) return N-1;
  while(right-left>1){
    ll mid = (left+right)/2;
    if(left_fall_flag(mid)) left = mid;
    else right = mid;
  }
  if(left_fall_flag(right)) return right;
  return left;
}

