ll binSearch1(ll st, ll en, char t[], char d[], ll q, ll n)
{
    if(st==en)
    {
        bool ans = 0;
        ans = seeAns(st,t,d,q,n);

        if(ans)
        {
            // cout << "F";
            return st;
        }
        // cout << st << endl;
        return st-1;
    }

    ll mid = (st+en)/2;

    bool ans = seeAns(mid,t,d,q,n);

    if(!ans)
        return binSearch1(st,mid,t,d,q,n);
    return binSearch1(mid+1,en,t,d,q,n);
}

ll binSearch2(ll st, ll en, char t[], char d[], ll q, ll n)
{
    if(st==en)
    {
        bool ans = 0;
        if(st!=0)
            ans = seeAns2(st-1,t,d,q,n);

        if(ans)
            return st-1;

        if(seeAns2(st,t,d,q,n))
            return st;
        return st+1;
    }

    ll mid = (st+en)/2;

    bool ans = seeAns2(mid,t,d,q,n);

    if(ans)
        return binSearch2(st,mid,t,d,q,n);
    return binSearch2(mid+1,en,t,d,q,n);
}

