}
pair<vec<Weight>,bool> bellmanFord(const Graph &g, int s){
	int n = g.size();
	const Weight inf = numeric_limits<Weight>::max()/8;

	Edges es;
	rep(v,n)
		for(auto &e:g[v]) es.emplace_back(e);
	vector<Weight> dist(n,inf);
	dist[s] = 0;

	bool negCycle = false;
	for(int i=0;;i++){
		bool update = false;
		for(auto &e:es)
			if(dist[e.src]!=inf && dist[e.dst] > dist[e.src]+e.weight){
				dist[e.dst] = dist[e.src]+e.weight;
				update = true;
			}
		if(!update) break;
		if(i>n){
			negCycle = true;
			break;
		}
	}
	return make_pair(dist,!negCycle);
}

