int N,Q;
string s;
char t[200001],d[200001];
bool LL(){
	int pos = 0;
	rep(i,Q){
		if(s[pos]==t[i] && d[i]=='R')
			pos++;
		else
			pos--;
		if(pos<0)
			return true;
		if(N<=pos)
			return false;
	}
	return false;
}
bool RR(){
	int pos = N-1;
	rep(i,Q){
		if(s[pos]==t[i] && d[i]=='L')
			pos++;
		else
			pos--;
		if(pos<0)
			return false;
		if(N<=pos)
			return true;
	}
	return false;
}
int searchL(int a, int b, char c){
	if(a+1==b){
		if(a==0 && !LL()){
			// cout << "LL" <<endl;
			return 0;
		}
		return b;
	}
	int m = (a+b)/2;
	int pos = m;
	rep(i,Q){
		if(t[i]==s[pos]){
			if(d[i]=='R') pos++;
			else pos--;
			if(pos<0)
				return searchL(m,b,c);
		}
	}
	return searchL(a,m,c);
}
int searchR(int a, int b, char c){
	if(a+1==b){
		if(b==N-1 && !RR()){
			// cout << "RR" <<endl;
			return 0;
		}
		return N-b;
	}
	int m = (a+b)/2;
	int pos = m;
	rep(i,Q){
		if(t[i]==s[pos]){
			if(d[i]=='R') pos++;
			else pos--;
			if(N<=pos)
				return searchR(a,m,c);
		}
	}
	return searchR(m,b,c);
}

int main(){
	cin >> N>>Q>>s;
	rep(i,Q)
		cin >> t[i] >> d[i];

	int posR = searchR(0,N-1,s[(N-1)/2]);
	int posL = searchL(0,N-1,s[(N-1)/2]);
	// cout << pair(posL,posR) << endl;
	cout << N-(posR+posL) << endl;


}

