                    activate(idx+1);
                }
            } else {
                golems[idx]+=golems[idx+1];
                if (idx-1 >=0) {
                    activate(idx-1);
                }
            }
            golems[idx+1] = 0;
            deactivate(idx);
        }
    }
    //cout << golems << endl;
    cout << (n - golems[0] - golems[n+1]) << endl;
    return 0;
}

