	return (curpos == 0);
}


bool checkright(ll x) {
	ll curpos = x;
	for (int i = 1; i <= q; i++) {
		if (curpos == 0 || curpos == n + 1)
			break;
		if (a[curpos] == s[i]) {
			if (d[i] == 'L')
				curpos--;
			else
				curpos++;
		}		
	}
	return (curpos == n + 1);
}


