using namespace std;

constexpr int kSize = 200000;
int N = 0;
int Q = 0;
char ch[kSize];
int dir[kSize];

bool find(const string& s, int p, bool left, bool right) {
  for (int i = 0; i < Q; i++) {
    if (s[p] == ch[i]) {
      p += dir[i];
      if (N <= p) return right;
      if (p < 0) return left;
    }
  }
  return false;
}

int main() {
  string s;
  cin >> N >> Q >> s;
  for (int i = 0; i < Q; i++) {
    char t, d;
    cin >> t >> d;
    ch[i] = t;
    dir[i] = d == 'L' ? -1 : 1;
  }

  int ans = N;
  int l = -1;
  int r = N;
  while (r - l > 1) {
    int mid = (l + r) / 2;
    if (find(s, mid, true, false)) {
      l = mid;
    } else {
      r = mid;
    }
  }
  ans -= r;

  l = -1;
  r = N;
  while (r - l > 1) {
    const int mid = (l + r) / 2;
    if (find(s, mid, false, true)) {
      r = mid;
    } else {
      l = mid;
    }
  }
  ans -= N - r;

  cout << ans << endl;
  return 0;
}

