const int MAX_N=1e6+1;
int N,Q;
string S;
char T[MAX_N],D[MAX_N];

bool okl(int i) {
  REP(j,Q) if(S[i]==T[j]) {
    int d=D[j]=='R'?1:-1;
    i+=d;
    if(i==-1) return true;
  }
  return false;
}
bool okr(int i) {
  REP(j,Q) if(S[i]==T[j]) {
    int d=D[j]=='R'?1:-1;
    i+=d;
    if(i==N) return true;
  }
  return false;
}
void solve() {
  int L=0,R=0;
  int good=-1,bad=N;
  while(abs(good-bad)>1) {
    int m=(good+bad)/2;
    (okl(m)?good:bad)=m;
  }
  L=good;
  good=N,bad=-1;
  while(abs(good-bad)>1) {
    int m=(good+bad)/2;
    (okr(m)?good:bad)=m;
  }
  R=good;
//  dump(L,R);
  cout<<max(0,R-L-1)<<endl;
}

