int fall(vector<char> &t, vector<char> &d, const string &s, int N, int pos){
  rep(i, t.size()){
    if(t[i]==s[pos]){
      pos += (d[i]=='L')?-1:1;
    }
    if(pos<0) return -1;
    if(pos>N-1) return 1;
  }
  return 0;
}

