int N, Q;
char field[200009];
vector<pair<char, bool>> V;

// pos番目のゴーレムは左に抜けられるか
bool canLeft(int n) {
	bool flag = false;
	int pos = n;
	if (n == 0) flag = true;
	for (int i = 0; i < Q && !flag; i++) {
		if (V[i].first == field[pos]) {
			if (V[i].second) pos++;
			else pos--;
		}

		if (pos == 0) flag = true;
		if (pos == N + 1) break;
	}

	return flag;
}

// pos番目のゴーレムは右に抜けられるか
bool canRight(int n) {
	bool flag = false;
	int pos = n;
	if (pos == N+1) flag = true;
	for (int i = 0; i < Q && !flag; i++) {
		if (V[i].first == field[pos]) {
			if (V[i].second) pos++;
			else pos--;
		}

		if (pos == N + 1) flag = true;
		if (pos == 0) break;
	}

	return flag;
}


