	for (int i = 1; i <= N; i++) cin >> field[i];


	for (int i = 0; i < Q; i++) {
		char c; cin >> c;
		char d; cin >> d;
		bool way = (d == 'R');
		V.push_back(pair<char, bool>(c, way));
	}

	int ans = 0;

	// 0に到達できる最大のposを探す
	int left = 0; int right = N + 1; // left <= 解 < right
	while (left + 1 != right) {
		int mid = (left + right) / 2;
		if (canLeft(mid)) left = mid;
		else right = mid;
	}
	//cout << left << " ";

	ans += left;


	// N+1に到達できる最小のNを探す
	// left < 解 <= right
	right = N + 1;
	while (left + 1 != right) {
		int mid = (left + right) / 2;
		if (canRight(mid)) right = mid;
		else left = mid;
	}
	//cout << right << " ";

	ans += (N - right + 1);

	cout << N-ans << endl;


	return 0;
}

