int N, Q;

int sim(int p) {
	if(!(p >= 0 && p < N))
		return p;
	for(int i = 0; i < Q; i++) {
		if(q[i][0] == s[p]) {
			if(q[i][1] == 'L') {
				if(--p < 0)
					return p;
			} else {
				if(++p >= N)
					return p;
			}
		}
	}
	return p;
}

int main() {
	cin >> N >> Q >> s;
	for(int i = 0; i < Q; i++)
		cin >> q[i][0] >> q[i][1];
	int l = 0, r = N - 1;
	while(l<r) {
		int m = (l + r) / 2;
		if(sim(m) == -1)
			l = m + 1;
		else
			r = m;
	};
	int m = (l+r)>>1;
	l = sim(m)==-1?m:-1;
	int ans = l;
	l = 0, r = N-1;
	while(l<r) { 
		int m = (l + r) / 2;
		if(sim(m) == N)
			r = m ;
		else
			l = m + 1;
	};
	m = (l+r) >>1;
	l=sim(m)==N?m:N;

	ans += N - l;
	ans = N - ans;
	cout << ans << endl;
}

