char t[MAX_N + 2], d[MAX_N + 2];

bool fallLeft(int x) {
  if(x == 0) return true;
  for(int i = 0; i < q; ++i) {
    if(t[i] == s[x - 1]) {
      if(d[i] == 'L') {
        --x;
      } else {
        ++x;
      }
      if(x == 0) return true;
      if(x == n + 1) return false;
    }
  }

  return false;
}

bool fallRight(int x) {
  if(x == n + 1) return true;
  for(int i = 0; i < q; ++i) {
    if(t[i] == s[x - 1]) {
      if(d[i] == 'L') {
        --x;
      } else {
        ++x;
      }
      if(x == n + 1) return true;
      if(x == 0) return false;
    }
  }

  return false;
}

int main() {
  std::cin >> n >> q;
  std::cin >> s;
  for(int i = 0; i < q; ++i) {
    std::cin >> t[i] >> d[i];
  }

  int l = 0, r = n + 1, m = (l + r) / 2, cnt = 0;
  while(r - l > 1) {
    if(fallRight(m)) {
      r = m;
    } else {
      l = m;
    }
    m = (l + r) / 2;
  }
  cnt += n + 1 - r;

  l = 0, r = n + 1, m = (l + r) / 2;
  while(r - l > 1) {
    if(fallLeft(m)) {
      l = m;
    } else {
      r = m;
    }
    m = (l + r) / 2;
  }
  cnt += l;

  std::cout << n - cnt << std::endl;
}

