}

int binary_search() {
  int left = 0, right = n + 1;
  {
    int ng = n + 1;
    while(abs(ng - left) > 1) {
      int mid = (left + ng) / 2;
      if(fanc(mid, true)) left = mid;
      else ng = mid;
    }
  }
  {
    int ng = left;
    while(abs(right - ng) > 1) {
      int mid = (right + ng) / 2;
      if(fanc(mid, false)) right = mid;
      else ng = mid;
    }
  }
  return n - (n + 1 - right) - left;
}

