//mode 0 落ちない最小値，mode 1 落ちない最大値
int binary_search(int start,int end, int mode){
  while(true){
    int mid = (start+end)/2;
    int f = fall(mid);
    if(end-start<=1) break;
    if(mode){
      if(!f) start=mid;
      else end=mid;
    }else{
      if(!f) end=mid;
      else start=mid;
    }
  }
  if(!fall(start))start++;
  if(mode) return start;
  else return end;
}

