		scanf("%s", ch);
		op[i] = ch[0];
		scanf("%s", ch);
		dir[i] = (ch[0] == 'R');
	}

	int pre_board = 0;
	int suf_board = n + 1;
	int lb = 0, ub = n + 1;
	while(ub - lb > 1) {
		int mid = (lb + ub) / 2;
		int p = mid;
		for(int i = 1; i <= Q; i ++) {
			if(op[i] != s[p]) continue;
			if(dir[i] == 0) p --;
			else p ++;
			if( p < 1 || p > n) break;
		}
		if( p < 1 ) lb = mid;
		else { ub = mid; if(p > n) suf_board = min(suf_board, p); }
	}
	pre_board = max(pre_board, lb);

	lb = 0, ub = n + 1;
	while(ub - lb > 1) {
		int mid = (lb + ub) / 2;
		int p = mid;
		for(int i = 1; i <= Q; i ++) {
			if(op[i] != s[p]) continue;
			if(dir[i] == 0) p --;
			else p ++;
			if( p < 1 || p > n) break;
		}
		if( p > n ) ub = mid;
		else { lb = mid; if(p < 1) pre_board = max(pre_board, p); }
	}
	suf_board = min(suf_board, ub);

	cout << max(0, n - (pre_board + (n - suf_board + 1))) << endl;

