bool check(int k, string s, const vector<char>& t, const vector<char>& d) {
  int N = s.length();
  int Q = t.size();
  int pos = k;
  REP(i,Q) {
    if(t[i] == s[pos]) {
      if(d[i] == 'L') --pos;
      if(d[i] == 'R') ++pos;
    }
    if(pos < 0) return true;
    if(pos >= N) return false;
  }
  return false;
}

int solve(string s, const vector<char>& t, const vector<char>& d) {
  if(!check(0, s, t, d)) return 0;

  int N = s.length();
  int lb = 0, ub = N;
  while(ub - lb > 1) {
    int mid = (ub + lb) / 2;
    if(check(mid, s, t, d)) lb = mid;
    else ub = mid;
  }
  return ub;
}

