bool checkleft(ll a){
    if (a < 0 || a > N-1) return false;
    ll active = a;
    rep(i,Q){
        if (Move[active] == t[i]){
            if (d[i] == 'R'){
                active++;
            }
            else active--;
            if (active > N-1) return false;
            if (active < 0) return true;
        }
    }
    return false;
}

bool checkright(ll a){
    if (a < 0 || a > N-1) return false;
    ll active = a;
    rep(i,Q){
        if (Move[active] == t[i]){
            if (d[i] == 'R'){
                active++;
            }
            else active--;
            if (active < 0) return false;
            if (active > N-1) return true;
        }
    }
    return false;
}

