    rep(i,Q) cin >> t[i] >> d[i];
    rep(i,N){
        Move[i] = s[i];
    }
    ll left = -1;
    ll right = N;

    ll le1=0;
    ll ri1 = N;
    while(le1+1<ri1){
        ll mid = (le1+ri1)/2;
        if (checkleft(mid)){
            le1 = mid;
        }
        else ri1 = mid;
    }
    if (checkleft(ri1)) left = ri1;
    else if(checkleft(le1)) left = le1;

    ll le2=0;
    ll ri2 = N;
    while(le2+1<ri2){
        ll mid = (le2+ri2)/2;
        if (checkright(mid)){
            ri2 = mid;
        }
        else le2 = mid;
    }
    if (checkright(le2)) right = le2;
    else if(checkright(ri2)) right = ri2;
    ll ans = right-left-1;
    cout << ans << endl;
    return 0;
}

