	    GolemSum -= Golem[posIndex];
	    Golem[posIndex]=0;
	  }
	  else{
	    Golem[posIndex+1] += Golem[posIndex];
	    Golem[posIndex] = 0;
	  }
	}
      }
    }//end of posIndex loop
  }//end of trial loop
  cout << GolemSum << endl;
  return 0;
}

