int main() {
  int N, Q;
  cin >> N >> Q;
  char s[N];
  cin >> s;
  char t, d;
  int g[N];
  for (int i = 0; i < N; i++) {
    g[i] = 1;
  }
  for (int i = 0; i < Q; i++) {
    cin >> t >> d;
    if (d == 'L') {
      for (int i = 0; i < N; i++) {
        if (s[i] == t && g[i] > 0) {
          if (i > 0) g[i-1] += g[i];
          g[i] = 0;
        }
      }
    } else if (d == 'R') {
      for (int i = 0; i < N; i++) {
        if (s[i] == t && g[i] > 0) {
          if (i < N-1) g[i+1] += g[i];
          g[i] = 0;
        }
      }
    }
  }
  int sum = 0;
  for (int i = 0; i < N; i++) {
    sum += g[i];
  }
  cout << sum << endl;
  return 0;
