const int MAXN=200000;
const int MAXQ=200000;

int n,nq;
char s[MAXN+1];
int qc[MAXQ],qdir[MAXQ];

int sim(int at) {
	REP(i,nq) {
		if(s[at]==qc[i]) { if(qdir[i]=='L') --at; if(qdir[i]=='R') ++at; }
		if(at<0||at>=n) return at;
	}
	return at;
}

int calcleft() {
	int lo=0,hi=n+1;
	while(lo+1<hi) {
		int mi=lo+(hi-lo)/2;
		int pos=sim(mi-1);
		if(pos==-1) lo=mi; else hi=mi;
	}
	return lo;
}

int calcright() {
	int lo=0,hi=n+1;
	while(lo+1<hi) {
		int mi=lo+(hi-lo)/2;
		int pos=sim(n-mi);
		if(pos==n) lo=mi; else hi=mi;
	}
	return lo;
}

int solve() {
	return n-calcleft()-calcright();
}

