int solve(int N, int Q, char* s, vector<char>& t, vector<char>& d) {
  assert(strlen(s) >= N);
  s[N] = 0;
  auto f = [&](int ix) -> int {
    assert(IN(ix, 0, N - 1));
    rep(i, Q) {
      if (ix == -1 || ix == N) break;
      char letter = s[ix];
      if (letter == t[i]) {
        if (d[i] == 'L')
          --ix;
        else
          ++ix;
      }
    }
    return ix;
  };

  int fL = f(0), fR = f(N - 1);

  if (fL == N) return 0;
  if (fR == -1) return 0;

  if (fL == -1 && fR == N) {
    int leftmost, rightmost;
    {
      int lo = 0, hi = N - 1;
      while (lo + 1 < hi) {
        int x = (lo + hi) / 2;
        int fx = f(x);
        if (0 <= fx) {
          hi = x;
        } else {
          lo = x;
        }
      }
      leftmost = hi;
    }
    {
      int lo = 0, hi = N - 1;
      while (lo + 1 < hi) {
        int x = (lo + hi) / 2;
        int fx = f(x);
        if (fx <= N - 1) {
          lo = x;
        } else {
          hi = x;
        }
      }
      rightmost = lo;
    }
    if (leftmost <= rightmost) {
      return rightmost - leftmost + 1;
    } else {
      return 0;
    }
  }
  if (fL == -1) {
    assert(IN(fR, 0, N - 1));
    int ng = 0, ok = N - 1;
    while (ng + 1 < ok) {
      int x = (ng + ok) / 2;
      int fx = f(x);
      if (IN(fx, 0, N - 1)) {
        ok = x;
      } else {
        ng = x;
      }
    }
    int leftmost = ok, rightmost = fR;
    return rightmost - leftmost + 1;
  }
  if (fR == N) {
    assert(IN(fL, 0, N - 1));
    int ok = 0, ng = N - 1;
    while (ok + 1 < ng) {
      int x = (ok + ng) / 2;
      int fx = f(x);
      if (IN(fx, 0, N - 1)) {
        ok = x;
      } else {
        ng = x;
      }
    }
    int leftmost = fL, rightmost = ok;
    return rightmost - leftmost + 1;
  }

  return N;
}

