inline bool check(int x, int opt) {
    for (int i = 1; i <= q; ++i) {
        if (t[i][0] == s[x])
            x += (t[i][1] == 'L') ? -1 : 1;
    }
    return opt == 0 ? (x == 0) : (x == n + 1);
}

inline int Get(int x) {
    int l = 1, r = n, res = (x == 0) ? 0 : n;
    while (l <= r) {
        int mid = (l + r) >> 1;
        //if (x == 1 && mid == 6) cout << check(mid, x) << res << endl;
        if (check(mid, x)) x == 0 ? (l = (res = mid) + 1) : (r = res = (mid) - 1);
        else x == 0 ? (r = mid - 1) : (l = mid + 1);
    }
    return res;
}

