string s;
INT n, m, ans;
char x[200020], q[200020];
bool f(int v)
{
    for(int i = 0 ; v >= 0 and i < m ; i++ )
        if( s[v] == x[i] )
        {
            if( q[i] == 'L' ) v--;
            if( q[i] == 'R' ) v++;
        }
    return v < 0;
}
bool g(INT v)
{
    for(int i = 0 ; v < n and i < m ; i++ )
        if( s[v] == x[i] )
        {
            if( q[i] == 'L' ) v--;
            if( q[i] == 'R' ) v++;
        }
    return v > n-1;
}
int main()
{
    ios::sync_with_stdio(false);
    cin>>n>>m>>s;
    for(int i = 0 ; i < m ; i++ ) cin>>x[i]>>q[i];
    INT lb = -1, rb = n, md;
    while( lb < rb )
    {
        md = (lb+rb+1)/2;
        if( f(md) ) lb = md;
        else rb = md-1;
    }
    ans = rb+1;
    lb = -1, rb = n;
    while( lb < rb )
    {
        md = (lb+rb-1)/2;
        if( g(md) ) rb = md;
        else lb = md+1;
    }
    ans += ((n-1)-lb+1);
    ans = n-ans;
    if( ans < 0 ) ans = 0;
    cout<<ans<<endl;
