bool lcond(int x){
	int ok = N;
	int ng = -1;
	int pos = x;
	if(pos <= ng) return false;
	if(pos >= ok) return true;

	for(int i = 0; i < Q; i++){
		if(t[i] == s[pos]){
			if(d[i] == 'L'){
				pos--;
			}else{
				pos++;
			}
			// cout << x << "," << i << "," << pos << endl;
		}

		if(pos == ng) return false;
		if(pos == ok) return true;
	}
	return false;
}

bool ucond(int x){
	int ok = -1;
	int ng = N;
	int pos = x;
	if(pos >= ng) return false;
	if(pos <= ok) return true;

	for(int i = 0; i < Q; i++){
		if(t[i] == s[pos]){
			if(d[i] == 'L'){
				pos--;
			}else{
				pos++;
			}
			// cout << x << "," << i << "," << pos << endl;
		}

		if(pos == ng) return false;
		if(pos == ok) return true;
	}
	return false;
}

// condを満たす最小のxを求める(lower_bound)
// 全てのxが条件を満たさない場合はnを返す(nはとりえない値)
int lower_bound_cond(){
	int lb = -1, ub = max_N;

	while(ub - lb > 1){
		int mid = (lb + ub) / 2;
		bool ok = lcond(mid);
		// cout << mid << "," << ok << endl;
		if(ok) ub = mid;   // Answer is in (lb, mid]
		else lb = mid;            // Answer is in (mid, ub]
	}

	// now lb + 1 = ub
	return ub;
}

// condを満たす最大のxを求める(upper_bound)
// 全てのxが条件を満たさない場合は-1を返す(-1はとりえない値)
int upper_bound_cond(){
	int lb = -1, ub = max_N;

	while(ub - lb > 1){
		int mid = (lb + ub) / 2;
		bool ok = ucond(mid);
		// cout << mid << "," << ok << endl;
		if(ok) lb = mid;   // Answer is in [mid, ub)
		else ub = mid;            // Answer is in [lb, mid)
	}

	// now lb + 1 = ub
	return lb;
}

int main()
{
