		t.push_back(a[0]);
		d.push_back(b[0]);
	}

	// cout << "calc lfall:" << endl;
	int lfall = upper_bound_cond();
	// cout << "lfall = " << lfall << endl;
	// cout << "calc ufall:" << endl;
	int rfall = lower_bound_cond();
	// cout << "rfall = " << rfall << endl;

	int fall = (lfall == max_N ? 0 : lfall + 1) + (rfall == -1 ? 0 : N - rfall);
	cout << N - fall << endl;
}

