bool checkL (int idx) {
  for (auto i : v) {
    if (idx < 0) break;
    if (i.first == s[idx]) {
      if (i.second == 'L') idx--;
      else idx++;
    }
  }

  return (idx < 0);
}

bool checkR (int idx) {
  for (auto i : v) {
    if (idx > n - 1) break;
    if (i.first == s[idx]) {
      if (i.second == 'R') idx++;
      else idx--;
    }
  }

  return (idx > n - 1);
}

int main () {
