int mv(int p){
    if(p >= n) return n;
    if(p < 0) return -1;
    for(int i = 0; i < q; i++){
        char t = tv[i], d = dv[i];
        if(s[p] == t){
            if(d == 'L'){
                if(p == 0) return -1;
                p--;
            }else{
                if(p == n - 1) return n;
                p++;
            }
        }
    }
    return p;
}

