        dv.push_back(d);
    }
    int safe_l, safe_r, mid;
    int l = 0, r = n;
    while(1){
        mid = (l + r) / 2;
        if(mv(mid) == -1 && mv(mid+1) == -1){
            l = mid + 1;
        }
        else if(mv(mid) != -1 && mv(mid+1) != -1){
            r = mid;
        }
        else break;
