int sim(int p)
{
    if (p <= 0)
    {
        return 1;
    }
    else if (p >= N + 1)
    {
        return 2;
    }
    for (int i = 0; i < Q;i++)
    {   
        if(t[i] == s[p-1])
        {
            p += d[i] == 'L' ? -1 : 1;
        }
        if (p <= 0)
        {
            return 1;
        }
        else if (p >= N + 1)
        {
            return 2;
        }
    }
    return 0;
}

