void solve()
{
	int n, q; cin >> n >> q;
	string s; cin >> s;
	int freq[n];
	fr0(i, n) freq[i] = 1;
	while (q--)
	{
		char d, t; cin >> t >> d;
		fr0(i, n)
		{
			if (s[i] == t)
			{
				if (d == 'L')
				{
					if (i > 0) freq[i - 1] += freq[i];
					freq[i] = 0;
				}
				if (d == 'R')
				{
					if (i != n - 1) freq[i + 1] += freq[i];
					freq[i] = 0;
				}
			}
		}
	}
	int sum = 0;
	fr0(i, n) sum += freq[i];
	cout << sum;
}


