bool leftOut(int pos){
    rep(i,Q){
        if(s[pos]==t[i]){
            if(d[i]=='L'){
                pos--;
                if(pos<0) return true;
            } 
            else{
                pos++;
                if(pos>N-1) return false;
            }
        }
    }
    return false;
}

bool rightOut(int pos){
    rep(i,Q){
        if(s[pos]==t[i]){
            if(d[i]=='L'){
                pos--;
                if(pos<0) return false;
            } 
            else{
                pos++;
                if(pos>N-1) return true;
            }
        }
    }
    return false;
}

int Ans(){
    int ans=N;

    // [l,r)
    if(leftOut(0)){
        int l=0,r=N;
        while(l+1!=r){
            int m = (l+r)/2;
            if(leftOut(m)){
                l = m;
            }
            else{
                r = m;
            }
        }
        ans -= l+1;
    }

    // (l,r]
    if(rightOut(N-1)){
        int l=-1,r=N-1;
        while(l!=r-1){
            int m = (l+r)/2;
            if(rightOut(m)){
                r = m;
            }
            else{
                l = m;
            }
        }
        ans -= N-r;
    }
    return ans;
}

