        G[s[i]].insert(i);
    }

    for(int i = 0; i < Q;i++){
        char t,d; cin >> t >> d;
        t -= 'A';

        if(d == 'L'){
            vector<pii> add;
            for(auto it = G[t].begin(); it != G[t].end(); it++){
                int T = C[*it];
                C[*it] = 0;
                if(*it == 0) continue;
                add.push_back({*it,T});
            }


            for(auto p:add){
                int idx = p.first-1;
                G[s[idx]].insert(p.first-1);
                C[p.first-1] += p.second;
            }
        }
        if(d == 'R'){
            vector<pii> add;
            for(auto it = G[t].begin(); it != G[t].end(); it++){
                int T = C[*it];
                C[*it] = 0;
                if(*it == N-1) continue;
                add.push_back({*it,T});
            }


            for(auto p:add){
                int idx = p.first+1;
                G[s[idx]].insert(p.first+1);
                C[p.first+1] += p.second;
            }
        }
    }
    res = accumulate(C.begin(),C.end(),0);
