	vector<char> alpha(q);
	vector<char> d(q);


	for (int i = 0; i < q; i++) {
		char x, y; cin >> x >> y;
		alpha[i] = x;
		d[i] = y;
	}

	char prev = s[n - 1];
	int cnt = 0;
	int cl = 0;
	int idx = n - 1;

	int found = -1;
	for (int i = n-1; i >=0; i--) {
		if (alpha[i] == prev && d[i] == 'R') {
			found = i;
			cl = 1;
			break;
		}
	}

	for (int i = found-1; i >=1; i--) {
		if (alpha[i] == prev && d[i] == 'L') {
			prev = s[n - 1];
			cl = max(cl, cnt);
			cnt = 0;
			idx = n - 2;
		}

		if (idx >= n)continue;

		if (alpha[i] == s[idx] && d[i] == 'R') {
			cnt++;
			prev = s[idx];
			cl = max(cl, cnt);
			idx--;
		}
	}

	found = -1;
	prev = s[0];
	cnt = 0;
	idx = 1;
	int cr = 0;
	for (int i = n - 1; i >= 0; i--) {
		if (alpha[i] == prev && d[i] == 'L') {
			found = i;
			cr = 1;
			break;
		}
	}

	for (int i = found-1; i >= 1; i--) {
		if (alpha[i] == prev && d[i] == 'R') {
			prev = s[0];
			cr = max(cr, cnt);
			cnt = 0;
			idx = 1;
		}
		if (idx >= n)continue;

		if (alpha[i] == s[idx] && d[i] == 'L') {
			cnt++;
			prev = s[idx];
			cr = max(cr, cnt);
			idx++;
		}
	}

	int ans = max(n - cl - cr, 0);
	cout << ans << endl;

	return 0;
}

