const ll INF = 5e15;
ll N, Q;
using Magic = pair<char, bool>;

V<bool> solve(const string &s, const V<Magic> &magics) {
    ll ok = -1, ng = N;
    while(abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;
        ll pos = mid;
        for(const auto &m : magics) {
            if(pos == -1) break;
            char c;
            bool left;
            tie(c, left) = m;
            if(s[pos] != c) continue;
            pos += (left ? -1 : 1);
        }
        if(pos == -1) ok = mid;
        else ng = mid;
    }
    V<bool> ret(N, false);
    for(ll i = 0; i <= ok; i++) ret[i] = true;
    return move(ret);
}

int main() {
    init_io();
    cin >> N >> Q;
    string S;
    cin >> S;
    V<Magic> magics;
    for(ll i = 0; i < Q; i++) {
        char t, d;
        cin >> t >> d;
        magics.emplace_back(t, d == 'L');
    }
    auto left = solve(S, magics);
    reverse(ALL(S));
    for(auto &m : magics) m.second = !m.second;
    auto right = solve(S, magics);
    reverse(ALL(right));
    ll ans = S.size();
    for(ll i = 0; i < N; i++) if(left[i] || right[i]) ans--;
    cout << ans << endl;
    return 0;
}

