// モジュール
ll test(ll i, string &s, vector<char> &t, vector<char> &d) {
    ll q = t.size(), n = s.size();
    REP(j, q) {
        if (s[i] == t[j]) {
            switch (d[j]) {
                case 'L':
                    i--;
                    break;
                case 'R':
                    i++;
                    break;
            }
        }
        if (i < 0 || n <= i) break;
    }
    return i;
}

