    ll lng = -1, lok = n;
    while (abs(lok - lng) > 1) {
        ll lmd = (lng + lok) / 2;
        if (test(lmd, s, t, d) < 0) {
            lng = lmd;
        } else {
            lok = lmd;
        }
    }
    ll rng = n, rok = -1;
    while (abs(rok - rng) > 1) {
        ll rmd = (rng + rok) / 2;
        if (test(rmd, s, t, d) >= n) {
            rng = rmd;
        } else {
            rok = rmd;
        }
    }

    cout << max(0LL, rok - lok + 1) << endl;

}

