vector<vector<int> > query(30);
vector<P> Query;
map<P, int> mem;
int N, Q;
string s;

int dfs(int time, int i){
  if(i == -1 || i == N) return 0;
  time = *lower_bound(query[s[i] - 'A'].begin(), query[s[i] - 'A'].end(), time);
  if(time == Q) return 1;
  if(mem.count(P(time, i))) return mem[P(time, i)];

  char t = Query[time].first, d = Query[time].second;
  assert(t == s[i]);
  int res = 0;
  if(d == 'L') res = dfs(time+1, i - 1);
  else res = dfs(time + 1, i + 1);
  return mem[P(t, i)] = res;
}

