    query[t - 'A'].push_back(i);
    Query.push_back(P(t, d));
  }

  for(int i=0;i<30;i++) query[i].push_back(Q);

  int ans = 0;
  for(int i=0;i<N;i++) ans += dfs(0, i);
  cout<<ans<<endl;

  return 0;
}

