void solve() {
    int L, R;
    {
        int ok = N;
        int ng = -1;
        while (abs(ok - ng) > 1) {
            int mid = (ok + ng) / 2;
            if (checkL(mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
