        while (abs(ok - ng) > 1) {
            int mid = (ok + ng) / 2;
            if (checkR(mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        R = ok;
    }
    cout << max(R - L + 1, 0ll) << endl;
