ll N, Q;
string s;
vector<pair<char, char>> vec;

int func(ll pos) {
	rep(i, Q) {
		if (vec[i].first == s[pos]) {
			if (vec[i].second == 'L') pos--;
			if (vec[i].second == 'R') pos++;
		}
		if (pos == N) return 1;
		if (pos == -1) return -1;
	}
	return 0;
}

void solve() {
	cin >> N >> Q >> s;
	vec.resize(Q);
	rep(i, Q) cin >> vec[i].first >> vec[i].second;

	//binary search
	//最終的にL=Rはtrueの左端で止まる
	//←false→LR←true→
	ll L = 0, R = N;
	//全てtrueのときは普通に0が返る
	//全てfalseのとき，sizeが返る
	while (L != R) {
		ll F = (L + R) / 2;
		bool judge;

		//判定式
		if (func(F) == -1) {
			judge = false;
		}
		else {
			judge = true;
		}

		if (judge) { R = F; }
		else { L = F + 1; }

	}

	ll ans = R;

	L = 0, R = N;
	while (L != R) {
		ll F = (L + R) / 2;
		bool judge;

		//判定式
		if (func(F) == 1) {
			judge = true;
		}
		else {
			judge = false;
		}

		if (judge) { R = F; }
		else { L = F + 1; }

	}

	ans = R-ans;

	cout << ans;

}

int main() {
	solve();
	cout << endl;
	return 0;
}

