struct Spel {
	char c;
	int  d;
};

bool is_fall_dir(const string&s, const int n, const int p, const int dir, const vector<Spel>& spels)
{
	int c_p = p;

	for (auto &spel : spels) {
		if (spel.c != s[c_p]) continue;

		if (spel.d == -1) c_p--;
		if (spel.d == 1)  c_p++;

		if (c_p < 0)  return (dir == -1);
		if (n <= c_p) return (dir == 1);
	}

	return false;
}

int search_fallpos(const string&s, const vector<Spel>& spels, int n, int dir)
{
	int alive, fall;
	if (dir == 1) {
		alive = 0;
		fall  = n - 1;
	}
	else {
		alive = n - 1;
		fall  = 0;
	}

	if (is_fall_dir(s, n, alive, dir, spels)) return alive;
	if (!is_fall_dir(s, n, fall, dir, spels)) return -1;

	while (abs(fall - alive) != 1) {
		int m = (fall + alive) / 2;
		if (is_fall_dir(s, n, m, dir, spels)) {
			fall = m;
		}
		else {
			alive = m;
		}
	}

	return fall;
}

int main()
{
	int n, q; cin >> n >> q;
	string s; cin >> s;

	vector<Spel> spels(q);
	for (auto& spel : spels) {
		char c, d;
		cin >> c >> d;

		spel.c = c;
		spel.d = (d == 'L') ? -1 : 1;
	}

	int r_pos = search_fallpos(s, spels, n, 1);
	int l_pos = search_fallpos(s, spels, n, -1);

	int fall_r = (r_pos != -1) ? (n - r_pos) : 0;
	int fall_l = (l_pos != -1) ? l_pos + 1 : 0;

	int fall_count = min(n, fall_l + fall_r);
	cout << (n - fall_count) << endl;

	return 0;
}

