	cin >> N >> Q >> S;
	rep(q, 0, Q) cin >> T[q] >> D[q];

	int ans = N;

	if (check(0) < 0) {
		int ok = 0, ng = N;
		while (ok + 1 != ng) {
			int md = (ok + ng) / 2;
			if (check(md) < 0) ok = md;
			else ng = md;
		}
		ans -= ok + 1;
	}

	if (N <= check(N - 1)) {
		int ng = 0, ok = N - 1;
		while (ng + 1 != ok) {
			int md = (ok + ng) / 2;
			if (N <= check(md)) ok = md;
			else ng = md;
		}
		ans -= N - ok;
	}

