  //xが落ちない位置になるようにする．
  while(true){
    mid = (start + end)/2;
    if(end-start < 1) break;
    int f = fall(mid);
    if(!f) break;
    else if(f==1) start = mid+1;
    else end = mid-1;
  }
  int S,E;
  //S左側に落ちない最初
  //E右側に落ちる最初
  if(fall(start)%2==0) S=start;
  else S = binary_search(start, mid, 0); 
  if(fall(end)!=2) E = end+1;
  else E = binary_search(mid, end,1);
  cout << E-S << endl;
  return 0;
}

