    while (hi - lo > 1) {
	int mid = (hi + lo) / 2;
	if (GO(mid) == -1) lo = mid;
	else hi = mid;
    }
    return hi;
}

int RIGHT() {
    int lo = -1, hi = N;
    while (hi - lo > 1) {
	int mid = (hi + lo) / 2;
	if (GO(mid) == N) hi = mid;
	else lo = mid;
    }
    return lo;
}

