int solve1() {
  int ans = 0, ng, ok;

  ng = -1;
  ok = N;
  while(abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;
    if(emu(mid)>=0) ok = mid;
    else ng = mid;
  }
  ans += ng+1;

  ng = -1;
  ok = N;
  while(abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;
    if(emu(mid)>=N) ok = mid;
    else ng = mid;
  }
  ans += N-ok;

  return N-ans;
}

