void doQuery(pair<char, char> q) {
	for (int i = 0; i < N; i++) {
		if (go[i] == -1 || go[i] == N) continue;

		if (s[go[i]] == q.first) {
			if (q.second == 'L') {
				go[i]--;
			}
			else {
				go[i]++;
			}
		}
	}
}

int doInstOne(vector<pair<char, char>> inst, int index) {
	int now = index;
	for (auto q : inst) {
		if (q.first == s[now]) {
			if (q.second == 'L') now--;
			else now++;
		}
		if (now == -1 || now == N) {
			break;
		}
	}
	return now;
}

