bool drop(int pos, char* s, char* t, char* d, int N, int Q, bool left_check) {
  for (int i = 0; i < Q; i++) {
    if (t[i] == s[pos]) {
      pos += (d[i] == 'L') ? -1 : 1;
    }
    if (pos < 0 && left_check) {
      return true;
    } else if  (pos > N-1 && !left_check) {
      return true;
    }
  }
  return false;
}

int main() {
  int N, Q;
  cin >> N >> Q;
  char s[N];
  cin >> s;
  char t[Q], d[Q];
  int g_pos[N];
  vector<int> con_pos;
  for (int i = 0; i < N; i++) {
    g_pos[i] = i;
  }
  for (int i = 0; i < Q; i++) {
    cin >> t[i] >> d[i];
  }

  int ml, mr;
  int left = 0;
  int right = N;
  while (left < right) {
    int mid = (left + right) / 2;
    if (drop(mid, s, t, d, N, Q, true)) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  ml = left;
  left = 0;
  right = N;
  while (left < right) {
    int mid = (left + right) / 2;
    if (drop(mid, s, t, d, N, Q, false)) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  mr = left;
  cout << mr - ml << endl;
  return 0;
}

