	long long R_depth = N - 1;
	i = 0;
	while (i < Q) {
		if (S.at(R_depth) == T.at(i) && D.at(i) == 'R') {
			R_depth--;
		}
		else if (R_depth != N - 1) {
			if (S.at(R_depth + 1) == T.at(i) && D.at(i) == 'L') {
				R_depth++;
				break;
			}
		}
		i++;
	}
	long long zero = 0;
	if (L_depth > R_depth) {
		cout << 0;
	}
	else {
		cout << max(R_depth - L_depth + 1, zero);
	}
}

