// diel = 1, dier = 2, survive = 0
ll die(string& ts, string& ds, string& s, ll pos) {
  rep(i, q) {
    if (pos < 0)
      return 1;
    else if (pos >= n)
      return 2;
    if (s[pos] == ts[i]) {
      if (ds[i] == 'L')
        pos--;
      else
        pos++;
    }
  }
  if (pos < 0)
    return 1;
  else if (pos >= n)
    return 2;
  return 0;
}

int main() {
  // ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
  cout << fixed << setprecision(15);

  string s;
  cin >> n >> q >> s;
  string ts, ds;
  rep(i, q) {
    char t, d;
    cin >> t >> d;
    ts += t, ds += d;
  }

  ll ans = n;

  // chk diel
  ll l = -1, r = n;
  while (l + 1 < r) {
    ll m = (l + r) / 2;
    if (die(ts, ds, s, m) == 1)
      l = m;
    else
      r = m;
  }
  ans -= l + 1;

  // chk dier
  l = -1, r = n;
  while (l + 1 < r) {
    ll m = (l + r) / 2;
    if (die(ts, ds, s, m) == 2)
      r = m;
    else
      l = m;
  }
  ans -= n - r;

  cout << ans << endl;

  return 0;
}

