  }
  for (int i=1;i<=N;i++){
    S[i]=S2[i-1];
  }
  X=sub11(1,N);
  Y=sub12(1,N);
  long ans=N;
  if (sub2(1)==-1)ans-=X;
  if (sub2(N)==1) ans-=(N+1-Y);
  /*
