long sub11(long x,long y){
  if (x==y){
    return x;
  }
  long z=(x+y+1)/2;
  if (sub2(z)==-1){
    return sub11(z,y);
  }else{
    return sub11(x,z-1);
  }
}

long sub12(long x,long y){
  if (x==y){
    return x;
  }
  long z=(x+y)/2;
  if (sub2(z)==1){
    return sub12(x,z);
  }else{
    return sub12(z+1,y);
  }
}

long sub2(long x){
  for (int i=1;i<=Q;i++){
    if (S[x]==T[i]){
      if (D[i]=='L'){
        x--;
        if (x==0)return -1;
      }else{
        x++;
        if (x==N+1)return 1;
      }
    }
  }
  return 0;
}

