		VI t(Q), d(Q); // d:L->1
		REP(i, Q) {
			cin>>T>>D;
			t[i] = T[0]-'A';
			d[i] = D[0]=='L';
		}
		// [ rL[i], rR[i] ] をみる
		vector<PII> rn;
		ll lDone=0, rDone=0;
		REPR(i, Q) {
			REP(j, rn.size()) {
				if(0<=rn[j].first-1 && t[i]==S[rn[j].first-1]-'A' && d[i]==0) rn[j].first--;
				else if(rn[j].second+1<N && t[i]==S[rn[j].second+1]-'A' && d[i]==1) rn[j].second++;
			}
			// ←
			if(t[i]==S[0]-'A' && d[i]==1 && !lDone) {
				rn.PB(MP(0, 0));
				lDone=1;
			}
			// →
			if(t[i]==S[N-1]-'A' && d[i]==0 && !rDone) {
