					if(t[qi]==S[i]-'A') {
						if(d[qi]==1) { if(0<=i-1) w[i-1] += w[i]; w[i]=0; }
						if(d[qi]==0) { if(i+1<N) w[i+1] += w[i]; w[i]=0; }
					}
				}
			}
//			DD(w);
		}
		ll ans = accumulate(ALL(w), 0LL);
		cout<<ans<<endl;
	}

	return 0;
}

