int solve(int pos){
	for(int i = 0; i < q; ++i){
		if(s[pos] == t[i]){
			if(d[i]=='R'){
				pos++;
			}else{
				pos--;
			}
		}
		if(pos == -1) return -1;
		if(pos == n) return 1;
	}
	return 0;
}

