	t.resize(q); d.resize(q);
	for(int i = 0; i < q; ++i){
		cin >> t[i] >> d[i];
	}


	/* 
	 * Meguru's binary search
	 * [ok, ng)
	 */
	int ok = 0;
	int ng = n-1;
	while(abs(ok-ng)>1){
		int mid = (ok + ng) / 2;
		if(solve(mid) == -1){
			ok = mid;
		}else{
			ng = mid;
		}
	}
	int l = (solve(ok) == -1) ? ok : ok-1;

	/* 
	 * Meguru's binary search 
	 * (ng,ok]
	 */
	ok = n-1;
	ng = 0;
	while(abs(ok-ng)>1){
		int mid = (ok + ng) / 2;
		if(solve(mid) == 1){
			ok = mid;
		}else{
			ng = mid;
		}
	}
	int r = (solve(ok) == 1) ? ok : ok+1;

	cout << r-l-1 << endl;
	return 0;
}

