char d[N + N][2];

bool isLeftOk(int pos){
  for(int i = 0; i < Q; i++){
    if(s[pos] == t[i][0]){
      if(d[i][0] == 'L'){
        pos--;
      } else {
        pos++;
      }
      if(pos < 0){
        return 0;
      } else if(pos >= n){
        return 2;
      }
    }
  }
  if(pos < 0){
    return 0;
  } else if(pos >= n){
    return 2;
  }
  return 1;
}

bool isRightOk(int pos){
  for(int i = 0; i < Q; i++){
    if(s[pos] == t[i][0]){
      if(d[i][0] == 'L'){
        pos--;
      } else {
        pos++;
      }
      if(pos >= n){
        return 0;
      } else if(pos < 0){
        return 2;
      }
    }
  }
  if(pos >= n){
    return 0;
  } else if(pos < 0){
    return 2;
  }
  return 1;
}

int main(){
  fastScan(n);
  fastScan(Q);
  scanf("%s", s);
  for(int i = 0; i < Q; i++){
    scanf("%s %s", t[i], d[i]);
  }
  int low = 0, high = n - 1, lft = 0;
  while(low <= high){
    int mid = (low + high) >> 1;
    if(isLeftOk(mid) == 0){
      low = mid + 1;
    } else {
      high = mid - 1;
      lft = mid;
    }
  }
  cerr << lft << '\n';
  low = 0; high = n - 1; int rgt = n - 1;
  while(low <= high){
    int mid = (low + high) >> 1;
    if(isRightOk(mid) == 0){
      high = mid - 1;
    } else {
      low = mid + 1;
      rgt = mid;
    }
  }
  cerr << rgt << '\n';
  int ans = (lft <= rgt) ? (rgt - lft + 1) : 0;
  printf("%d\n", ans);
}

