    for(int i=0; i<q; i++) cin>>t[i]>>d[i];

    // [lb, ub)
    // go left
    int lb=0, ub=n;
    while(ub - lb > 1){
        int mid = (lb + ub) / 2;
        int cv = mid;
        char cc = s[mid];

        for(int i=0; i<q; i++){
            if(t[i] == cc){
                if(d[i] == 'R'){
                    cv++;
                    if(n - 1 < cv) break;
                }
