                }

                cc = s[cv];
            }
        }

        if(cv < 0) lb = mid;
        else ub = mid;
    }

    int lcnt = lb + 1;
    //cout << lcnt << endl;

    // go right
    lb=0, ub=n;
    while(ub - lb > 1){
        int mid = (lb + ub) / 2;
        int cv = mid;
        char cc = s[mid];

        for(int i=0; i<q; i++){
            if(t[i] == cc){
                if(d[i] == 'R'){
                    cv++;
                    if(n - 1 < cv) break;
                }
                else{
                    cv--;
                    if(cv < 0) break;
                }

                cc = s[cv];
            }
        }

        if(n - 1 < cv) ub = mid;
        else lb = mid;
    }

