/* constant */

const int MAX_N = 200000;
const int MAX_Q = 200000;

/* typedef */

typedef pair<char,int> pci;
typedef deque<bool> dqb;

enum { STAY, LOUT, ROUT };

/* global variables */

char s[MAX_N + 4];
pci ops[MAX_Q];

/* subroutines */

int check(int n, int q, int x) {
  for (int i = 0; i < q; i++)
    if (s[x] == ops[i].first) {
      x += ops[i].second;
      if (x < 0) return LOUT;
      if (x >= n) return ROUT;
    }
  return STAY;
}

/* main */

int main() {
  int n, q;
  scanf("%d%d%s", &n, &q, s);

  for (int i = 0; i < q; i++) {
    char st[4], sd[4];
    scanf("%s%s", st, sd);
    ops[i] = pci(st[0], (sd[0] == 'L') ? -1 : 1);
  }

  int l0 = -1, r0 = n;
  while (l0 + 1 < r0) {
    int x = (l0 + r0) / 2;
    if (check(n, q, x) == LOUT) l0 = x;
    else r0 = x;
  }
  //printf("l0=%d, r0=%d\n", l0, r0);

  int l1 = -1, r1 = n;
  while (l1 + 1 < r1) {
    int x = (l1 + r1) / 2;
    if (check(n, q, x) == ROUT) r1 = x;
    else l1 = x;
  }
  //printf("l1=%d, r1=%d\n", l1, r1);

  printf("%d\n", r1 - r0);
  return 0;
}

