#define D 200010
int m=0;
void compute(char s[],char t,char d,int N,int count[])
{
    for(int i=0; i<N; i++)
    {
        if(t==s[i])
        {
            if((i==0&&d=='L')||(i==N-1&&d=='R')) count[i]=0;//边界情况
            else
            {
                if(d=='L')
                {
                    count[i-1]+=count[i];//向左移
                    count[i]=0;
                }
                else
                {
                    count[i+1]+=count[i];//向右移
                    count[i]=0;
                }
            }
        }
    }
}
int main()
{
    int N,M,sum=0;
    int count[D];
    char t,d;
    char s[D];
    cin>>N>>M;
    getchar();
    cin.getline(s,N+1);
    for(int i=0; i<N; i++)
    {
        count[i]=1;
    }
    for(int j=0; j<M; j++)
    {
        cin>>t>>d;
        getchar();
        compute(s,t,d,N,count);
    }
    for(int i=0; i<N; i++)
    {
        sum+=count[i];
    }
    cout<<sum;
    return 0;
}

