      if (t[i] != s[tmp]) continue;

      if (d[i] == 'R') tmp ++;
      else tmp --;

      if (tmp == -1) flag = true;
    }
    if (flag) left = mid + 1;
    else right = mid;
  }
  if (flag) l = mid;
  else l = mid - 1;

  //右から落ちるゴーレムのうち、最も左端にいるものを探す
  left = 0, right = N;
  while (left < right) {
    mid = tmp = (left + right) / 2;
