    for (int i = 0; i < Q; i ++) {
      if (t[i] != s[tmp]) continue;

      if (d[i] == 'R') tmp ++;
      else tmp --;

      if (tmp == N) flag = true;
    }
    if (flag) right = mid;
    else left = mid + 1;
  }
  if (flag) r = mid;
  else r = mid + 1;

  int ans;
  if (r > l) ans = r - l - 1;
  else ans = 0;

