    else rb = mid - 1;
  }
  ans -= lb;
  lb = lb + 1,rb = n + 1;
  while(lb < rb){
    int mid = (lb + rb) >> 1;
    if(check_right(mid)) rb = mid;
    else lb = mid + 1;
  }
  ans -= n - lb + 1;
  printf("%d\n",ans);
  return 0;
}

