using namespace std;

int N, Q;
string s;
vector<char> t;
vector<char> d;

int calc(int target) {
    int index = target;
    for (int i = 0; i < Q; i++) {
        char c = s[index];
        if (t[i] == c) {
            if (d[i] == 'L') {
                index--;
            } else {
                index++;
            }
            if (index == -1) {
                return index;
            } else if (index == N) {
                return index;
            }
        }
    }
    return target;
}

int findL(int l, int r) {
    while (l <= r) {
        int mid = (l+r)/2;
        if (calc(mid) == -1) {
            if (calc(mid+1) == mid+1) return mid+1;
            l = mid+1;
        } else {
            r = mid-1;
        }
    }
    return -1;
}

int findR(int l, int r) {
    while (l <= r) {
        int mid = (l+r)/2;
        if (calc(mid) == N) {
            if (calc(mid-1) == mid-1) return mid-1;
            r = mid-1;
        } else {
            l = mid + 1;
        }
    }
    return -1;
}

