        t.push_back(tt);
        d.push_back(dd);
    }

    int l = findL(0, N-1);
    int r = findR(0, N-1);

    if (l == -1) l = 0;
    if (r == -1) r = N-1;

    int ans = r - l + 1;
    cout << ans << endl;

    return 0;
}

