int leftSolve(){
    int left = 0, right = N+1;
    int mid;
    while(right - left > 1){
        mid = (left+right)/2;
        int v = Check(mid);
        if(v == 1) left = mid;
        else right = mid;
    }

    return left;
}

int rightSolve(){
    int left = 0, right = N+1;
    int mid;
    while(right - left > 1){
        mid = (left+right)/2;
        int v = Check(mid);
        if(v == 2) right = mid;
        else left = mid;
    }

    return right;
}

