template <typename Comp> bool simulate(ll pos, ll threshold, Comp comp) {
  REP(i, Q) {
    if (s[pos] == t[i]) {
      pos += ((d[i] == 'L') ? -1 : 1);
    }
  }
  return comp(pos, threshold);
}

template <typename Comp> ll search(ll ok, ll ng, ll threshold, Comp comp) {
  while (abs(ok - ng) > 1) {
    ll mid = (ok + ng) / 2;
    (simulate(mid, threshold, comp) ? ok : ng) = mid;
  }
  return ok;
}

