    char x,y;
    cin >> x >> y;
    if( i == 0 || v[v.size()-1].first != x) v.push_back(pair<char,char>(x,y));
  }
  int start=-1,end=N,mid,f,S,E;

  //落ちない最小値を探す(S)
  while(true){
    mid = (start + end)/2;
    f = fall(mid);
    if(!f) end = mid;
    else if(f==1) start = mid;
    else end = mid;
    if(end-start <= 1) break;
  }
  if(f==2)S = start;
  else S = end;

  start=-1,end=N;
  //落ちる最小値を探す(E)
  while(true){
    mid = (start+end)/2;
    f = fall(mid);
    if(!f)start = mid;
    else if(f==1) start = mid;
    else end = mid;
    if(end-start <= 1) break;
  }
  E = end;
  cout << E-S << endl;
  return 0;
}

