//右に落ちるか左に落ちるか落ちないか判定する
int jud(int n){
  int pos = n;
  for(int i=0;i<Q;i++){
    char now = s[pos];
    if(t[i] == now){
      if(d[i] == 'L') pos--;
      if(d[i] == 'R') pos++;
    }
    if(pos == -1){
      return -1;
    } else if(pos == N){
      return 1;
    }
  }
  return 0;
}

int bsl(int a, int b){
  //cout << "l " << a << b << endl;
  int p = (a + b) / 2;
  int res = jud(p);
  if(res==-1) check[p] = -1;
  else if(res==0) check[p] = 0;
  else if(res==1) check[p] = 1;

  if((check[p]==0 || check[p]==1) && p==0) return -1;
  else if(check[p] == -1 && (check[p+1] == 0 || check[p+1] == 1)) return p;
  else if((check[p] == 0 || check[p] == 1) && check[p-1] == -1) return p-1;
  else if(check[p] == -1){
    return bsl(p,b);
  }
  else if(check[p] == 1 || check[p] == 0){
    return bsl(a,p);
  }
}

int bsr(int a, int b){
  //cout << "r " << a << b << endl;
  int p = (a + b + 1) / 2;
  int res = jud(p);
  if(res==-1) check[p] = -1;
  else if(res==0) check[p] = 0;
  else if(res==1) check[p] = 1;

  if((check[p]==-1 || check[p]==0) && p==N-1) return -1;
  else if(check[p] == 1 && (check[p-1] == 0 || check[p-1] == -1)) return p;
  else if((check[p] == 0 || check[p] == -1) && check[p+1] == 1) return p+1;
  else if(check[p] == 1){
    return bsr(a,p);
  }
  else if(check[p] == -1 || check[p] == 0){
    return bsr(p,b);
  }
}

