bool checkleft(int x) {
    for(int i=0;i<q;i++) {
        if(x == 0) return true;
        if(l[i] == code[x-1]) {
            if(d[i] == 'R') x++;
            else x--;
        }
    }

    if(x == 0) return true;
    else return false;
}

bool checkright(int x) {
    for(int i=0;i<q;i++) {
        if(x == n+1) return true;
        if(l[i] == code[x-1]) {
            if(d[i] == 'R') x++;
            else x--;
        }
    }

    if(x == n+1) return true;
    else return false;
}

int main() {
