    for(int cekor=n/2;cekor>0;cekor/=2) {
        while(l_most + cekor <= n && checkleft(l_most+cekor)) l_most += cekor;
    }

    int r_most = n+1;
    for(int cekor=n/2;cekor>0;cekor/=2) {
        while(r_most - cekor >= 0 && checkright(r_most-cekor)) r_most -= cekor;
    }
    cout<<r_most-l_most-1<<"\n";
