    // 左に落ちない最小値ubL
    int lbL=0, ubL = N + 1;
    while( ubL-lbL > 1 ){
        int mid = (lbL+ubL)/2;
        if(CL(mid, Q, N, S, t, d)){
            ubL = mid;
        }else{
            lbL = mid;
        }
    }

    // 右に落ちない最大値lbR
    int lbR=0, ubR = N + 1;
    while( ubR-lbR > 1 ){
        int mid = (lbR + ubR) / 2;
        if (CR(mid, Q, N, S, t, d)) {
            lbR = mid;
        } else {
            ubR = mid;
        }
    }

    int ans;
    ans = lbR - ubL + 1;
    if(lbR == 0){
        cout << 0;
    }else if(ubL == N + 1){
        cout << 0;
    }else{
        cout << ans;
    }
    return 0;
}

