// -1: 左から落ちる
// 0: 落ちない
// 1: 右から落ちる
long is_down(long pos) {
  if (pos == -1) return -1;
  if (pos == N) return 1;
  for (auto it: Qs) {
    if (s[pos] == it.first) {
      pos += it.second;
      if (pos == -1) return -1;
      if (pos == N) return 1;
    }
  }
  return 0;
}

// left は落ちること保証, right は落ちないこと保証
long search_left_down(long left, long right) {
  long middle = (left + right) / 2;
  //cerr << "search_left_down: left=" << left << ", right=" << right << ", middle=" << middle << endl;
  if (middle == left) return left;
  //cerr << "------- test" << endl;
  bool middle_left_down = is_down(middle) == -1;
  if (middle_left_down) return search_left_down(middle, right);
  else return search_left_down(left, middle);
}

// left は落ちないこと保証, right は落ちること保証
long search_right_down(long left, long right) {
  //cerr << "search_right_down: left=" << left << ", right=" << right << endl;
  long middle = (left + right) / 2;
  if (middle == left) return right;
  bool middle_right_down = is_down(middle) == 1;
  if (middle_right_down) return search_right_down(left, middle);
  else return search_right_down(middle, right);
}

