  //cerr << "is_down(0): " << is_down(0) << ", is_down(N-1): " << is_down(N-1) << endl;

  long left_down;
  if (not ml_left_down) left_down = -1;
  else if (mr_left_down) left_down = N-1;
  else left_down = search_left_down(0, N-1);
