using namespace std;

bool is_to_left(int pos, int N, int Q, string s, vector<char> t, vector<char> d) {
    if (pos == 0) {
        return true;
    } else if (pos == N + 1) {
        return false;
    }

    for (int i = 0; i < Q; i++) {
        if (s[pos] == t[i] and d[i] == 'L') {
            pos--;
        } else if (s[pos] == t[i] and d[i] == 'R') {
            pos++;
        }

        if (pos == 0) {
            return true;
        } else if (pos == N + 1) {
            return false;
        }
    }

    return false;
}

bool is_to_right(int pos, int N, int Q, string s, vector<char> t, vector<char> d) {
    if (pos == N + 1) {
        return true;
    } else if (pos == 0) {
        return false;
    }

    for (int i = 0; i < Q; i++) {
        if (s[pos] == t[i] and d[i] == 'L') {
            pos--;
        } else if (s[pos] == t[i] and d[i] == 'R') {
            pos++;
        }

        if (pos == N + 1) {
            return true;
        } else if (pos == 0) {
            return false;
        }
    }

    return false;
}

int main() {
    int N, Q;
    cin >> N >> Q;
    string s;
    cin >> s;
    s = 'a' + s + 'a';
    vector<char> t(Q), d(Q);
    for (int i = 0; i < Q; i++) {
        cin >> t[i] >> d[i];
    }

    int lb = 0, ub = N + 1;
    while (ub - lb > 1) {
        int mid = (lb + ub)/2;
        if (is_to_left(mid, N, Q, s, t, d)) {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    int live_lb = ub;

    lb = 0;
    ub = N + 1;
    while (ub - lb > 1) {
        int mid = (lb + ub)/2;
        if (is_to_right(mid, N, Q, s, t, d)) {
            ub = mid;
        } else {
            lb = mid;
        }
    }
    int live_ub = lb;

    cout << live_ub - live_lb + 1 << endl;
    return 0;
}

