int bsearch(int ok, int ng) {
    while (std::abs(ok - ng) > 1) {
        int mi = (ok + ng) / 2;
        if (goal(mi)) {
            ok = mi;
        } else {
            ng = mi;
        }
    } 
    return ok;
}


