bool to(int x,int to)
{
	for(int i=0;i<q;i++)
	{
		if(c[i]!=s[x]) continue;
		if(dir[i]) x++;
		      else x--;
		if(x==to) return 1;
		if(x==-1 || x==n) return 0;
	}
