int move_golem(int ini, string s, string t, string d){
    int golem_temp = ini;
    for (int i = 0; i < t.size(); i++){
        if ((golem_temp == -1) || (golem_temp == s.size())){
            break;
        } 
        if (s[golem_temp] == t[i]){
            if (d[i] == 'L'){
                golem_temp = golem_temp - 1;
            }
            else if (d[i] == 'R'){
                golem_temp = golem_temp + 1;
            }
        }
    }



    return golem_temp;

}

