//ここから編集する
class Solve {
public:
    int N;
    int Q;
    string s;
    using P = pair<char, char>;
    vector<P> td;

    void input() {
        cin >> N >> Q;
        cin >> s;
        rep(i, 0, Q) {
            char t, d;
            cin >> t >> d;
            td.emplace_back(t, d);
        }
    }

    bool left_die(int k) {
        int pt = k;
        for (auto e : td) {
            if (s[pt] == e.first) {
                if (e.second == 'R') pt++;
                else pt--;
            }
            if (pt >= N) return false;
            if (pt < 0) return true;
        }
        return false;
    }

    bool right_die(int k) {
        int pt = k;
        for (auto e : td) {
            if (s[pt] == e.first) {
                if (e.second == 'R') pt++;
                else pt--;
            }
            if (pt >= N) return true;
            if (pt < 0) return false;
        }
        return false;
    }


    void solve() {
        input();
        int lok = -1, lng = N; //lokは死ぬ場所 , lngは死なない場所
        while (lng - lok > 1) {
            int mid = (lok + lng) / 2;
            if (left_die(mid)) {
                lok = mid;
            } else {
                lng = mid;
            }
        }

        int rok = N, rng = -1;
        while (rok - rng > 1) {
            int mid = (rok + rng) / 2;
            if (right_die(mid)) {
                rok = mid;
            } else {
                rng = mid;
            }
        }

        int ans = max(0, rng - lng + 1);
        cout << ans << endl;


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


