#include<iostream>
#include<vector>

using namespace std;

vector<char> t, d;
int N, Q;
string s;

int check(int m) {
    for(int i = 0; i < Q; i++)
    {
        if (s[m] == t[i]) {
            m += (d[i] == 'R') ? 1 : -1;
        }
        if (0 > m){
            return -1;
        }else if (m > N - 1){
            return 1;
        }  
    }
    return 0;
}

int bin_search_left() {
    int l, r;
    l = 0;
    r = N - 1;

    while(r >= l){
        int m = (l + r) / 2;
        if (check(m) == -1){
            l = m + 1;
        } else
        {
            r = m - 1;
        }
    }
    return l;
}

int bin_search_right()
{
    int l, r;
    l = 0;
    r = N - 1;

    while (r >= l)
    {
        int m = (l + r) / 2;
        if (check(m) == 1)
        {
            r = m - 1;
        }
        else
        {
            l = m + 1;
        }
    }
    return r;
}

int main() {
    cin >> N >> Q;
    cin >> s;

    t.resize(Q);
    d.resize(Q);
    for(int i = 0; i < Q; i++) cin >> t[i] >> d[i];

    int left = bin_search_left();
    int right = bin_search_right();

    int ans = right - (left - 1);

    cout << ans << endl;
}

