int new,g;

int zero1(){
    for(int i = 0;i < Q;i++){
        if(d[i]=='L' && t[i]==S[1]) return 1;
    }
    return 0;
}
int nibun1(int n,int M){
    //printf("%d\n",M-n);
    new = (M+n+1)/2;
    g = new;
    for(int i = 0;i < Q;i++){
        if(d[i]=='R' && t[i]==S[g] && g>0 && g<N+1)g++;
        if(d[i]=='L' && t[i]==S[g] && g>0 && g<N+1)g--;
    }
    if(g != 0 && M-n <= 1)return n;
    if(g == 0 && M-n <= 1)return M;
    if(g != 0)return nibun1(n,(new+M)/2);
    if(g == 0)return nibun1((n+new+1)/2,M);
}
int zero2(){
    for(int i = 0;i < Q;i++){
        if(d[i]=='R' && t[i]==S[N]) return 1;
    }
    return 0;
}
int nibun2(int n,int M){
    //printf("%d\n",M-n);
    new = (M+n)/2;
    g = new;
    for(int i = 0;i < Q;i++){
        if(d[i]=='R' && t[i]==S[g] && g>0 && g<N+1)g++;
        if(d[i]=='L' && t[i]==S[g] && g>0 && g<N+1)g--;
    }
    if(g != N+1 && M-n <= 1)return M;
    if(g == N+1 && M-n <= 1)return n;
    if(g != N+1)return nibun2((n+new+1)/2,M);
    if(g == N+1)return nibun2(n,(new+M)/2);
}

