bool *judge(int N,int Q,string s,vector<char> t,vector<char> d){
    bool *hoge=new bool[N];
    for(int i=0;i<N;i++) hoge[i]=false;
    if(Q==1){
        if (s[0]==t[0] && d[0]=='L') hoge[0]=true;
        if (s[N-1]==t[0] && d[0]=='R') hoge[N-1]=true;
    } else{
        vector<char> tt,dd;
        tt=t;
        dd=d;
        tt.erase(tt.begin());
        dd.erase(dd.begin());
        bool *hogehoge=judge(N,Q-1,s,tt,dd);
        for(int i=0;i<N;i++){
            if(s[i]==t[0]){
                if(d[0]=='L'){
                    if(i==0) hoge[0]=true;
                    else if(hogehoge[i-1]) hoge[i]=true;
                }else{
                    if(i==N-1) hoge[N-1]=true;
                    else if(hogehoge[i+1]) hoge[i]=true;
                }
            }else if(hogehoge[i]) hoge[i]=true;
        }
        delete[] hogehoge;
    }
    return hoge;
}

