// 移動するゴーレムの場所を取得
map<char, vector<int>> get_idx_of_move_golem(string s) {
    map<char, vector<int>> rtn;
    for(int i=0; i<s.size(); i++) {
        char ch = s[i];
        if(rtn.count(ch) > 0) {
            rtn[ch].push_back(i);
        } else {
            vector<int> tmp{i};
            rtn[ch] = tmp;
        }
    }
    return rtn;
}

int main() {
    int n, q;
