    cin >> n >> q >> s;
    vector<int> golem_positions(n, 1);
    map<char, vector<int>> pos_map = get_idx_of_move_golem(s);
    int count = n;
    for(int i=0; i<q; i++) {
        char t, d; 
        cin >> t >> d;
        vector<int> moving_pos_indexes = pos_map[t];
        for(int j=0; j<moving_pos_indexes.size(); j++) {
            int idx = moving_pos_indexes[j]; 
            if(d == 'L') {
                if(idx!=0) {
                    golem_positions[idx-1] += golem_positions[idx];
                } else {
                    count -= golem_positions[idx];
                }
            } else { // Rのとき
                if(idx!=n-1) {
                    golem_positions[idx+1] += golem_positions[idx];
                } else {
                    count -= golem_positions[idx];
                }
            }
            golem_positions[idx] = 0; 
        }

    }
    cout << count << endl;
    return 0;
}

