int n;
void use(int v) {
    used[v] = true;
    g[0][s[v] - 'A'].erase(v);
    g[1][s[v] - 'A'].erase(v);
    int pr = v - 1;
    if (pr >= 0 && !used[pr]) {
        g[1][s[pr] - 'A'].insert(pr);
    }
    int nx = v + 1;
    if (nx < n && !used[nx]) {
        g[0][s[nx] - 'A'].insert(nx);
    }
}

void smain() {

    int  q;
    cin >> n >> q;
    cin >> s;
    vector<pii> queries;
    fori (i, q) {
        string f, s;
        cin >> f >> s;
        queries.push_back({f[0] - 'A', s[0] == 'R'});
    }
    g[0][s[0] - 'A'].insert(0);
    g[1][s[n - 1] - 'A'].insert(n - 1);
    reverse(ALL(queries));
    for (auto q : queries) {
        vi kek(ALL(g[q.second][q.first]));
        g[q.second][q.first].clear();
        for (auto v : kek) {
            use(v);
        }
    }
    int ans = 0;
    fori (i, n) ans += !used[i];
    cout << ans;
}

