using namespace std;



typedef enum Result {
    Left,Right,Exists,
};
Result solve(const vector<pair<char, int>>& magics, const string& src, int index) {
    for(const auto& magic: magics) {
        if (src[index] == magic.first) {
            index += magic.second;
        }
        if (index < 0) {
            return Result::Left;
        } else if(index >= src.length()) {
            return Result::Right;
        }
    }
    // cout << "[DEBUG] index:" << index << endl; 
    return Result::Exists;
}
int bin_search_left(const vector<pair<char, int>>& magics, const string& src) {
    // 左からどこまで死んでるか求める
    int begin = 0;
    int end = src.length() - 1;
    int old_target = -1;
    Result result;
    int dst = -1;
    while(begin != end) {
        int target = (end - begin) / 2 + begin;
        if(old_target == target) target++;
        // cout << "L:" << begin << "," << end << "," << target << endl;
        result = solve(magics, src, target);
        if(result == Result::Left) {
            dst = target;
            // 答えはもっと右
            if(begin == target) break;
            begin = target;
        } else {
            if(end == target) break;
            end = target;
        }
        old_target = target;
    }
    // にぶたんで見つけられなかったら-1
    return dst;
}
int bin_search_right(const vector<pair<char, int>>& magics, const string& src) {
    int begin = 0;
    int end = src.length() - 1;
    int old_target = -1;
    Result result;
    int dst = -1;
    while(begin != end) {
        int target = (end - begin) / 2 + begin;
        if(old_target == target) target++;
        // cout << "R:" << begin << "," << end << "," << target << endl;
        result = solve(magics, src, target);
        if(result == Result::Right) {
            dst = target;
            if(end == target) break;
            end = target;
        } else {
            if(begin == target) break;
            begin = target;
        }
        old_target = target;
    }
    // にぶたんで見つけられなかったら-1
    return dst;
}
int main(void) {
    int n; // マスの総数
    int q; // 呪文の数
    string s; // 各盤面のidentify
    cin >> n;
    cin >> q;
    cin >> s;

    vector<pair<char, int>> magics(q);
    for(int i = 0 ; i < q ; ++i) {
        char t; // 適用するマス
        char d; // 方向 L or R
        cin >> t;
        cin >> d;
        magics.push_back(make_pair(t, d == 'L' ? -1 : 1));
    }
    auto l = bin_search_left(magics, s);
    auto r = bin_search_right(magics, s);
    int removed = (l + 1) + (r < 0 ? 0 : (s.length() - r));
    int ans = s.length() - removed;
    // cout << l << endl;
    // cout << r << endl;
    // cout << removed << endl;
    cout << ans << endl;
    return 0;
}

