bool gitsag(int ind){
	if(ind == n + 1)
		return 1;
	for(int i = 1; i <= q; i++){
		if(x[i] == s[ind])
			ind = (y[i] == 'R') ? ind + 1 : ind - 1;
		if(ind == n + 1)
			return 1;
		if(ind == 0)
			return 0;
	}
	return 0;
}

bool gitsol(int ind){
	if(ind == 0)
		return 1;
	for(int i = 1; i <= q; i++){
		if(x[i] == s[ind])
			ind = (y[i] == 'R') ? ind + 1 : ind - 1;
		if(ind == 0)
			return 1;
		if(ind == n + 1)
			return 0;
	}
	return 0;
}

