int find_right(vector<T>& v, T elem) {
  return (int)(lower_bound(v.begin(), v.end(), elem) - v.begin());
}

int N, Q;
char s[200003];
char t[200003];
char d[200003];

inline int f(int ix) {
  assert(IN(ix, 0, N - 1));
  rep(i, Q) {
    if (ix == -1 || ix == N) break;
    char letter = s[ix];
    if (letter == t[i]) {
      if (d[i] == 'L')
        --ix;
      else
        ++ix;
    }
  }
  return ix;
}

int solve() {
  assert(strlen(s) >= N);
  s[N] = 0;

  if (f(N - 1) == -1) return 0;
  if (f(0) == N) return 0;

  int leftmost;
  {
    int ng = -1, ok = N - 1;
    while (ng + 1 < ok) {
      int x = (ng + ok) / 2;
      if (f(x) >= 0) {
        ok = x;
      } else {
        ng = x;
      }
    }
    leftmost = ok;
  }

  int rightmost;
  {
    int ok = 0, ng = N;
    while (ok + 1 < ng) {
      int x = (ok + ng) / 2;
      if (f(x) <= N - 1) {
        ok = x;
      } else {
        ng = x;
      }
    }
    rightmost = ok;
  }

  if (leftmost <= rightmost)
    return rightmost - leftmost + 1;
  else
    return 0;
}

int main() {
  scanf("%d %d%*c", &N, &Q);
  fgets(s, N + 3, stdin);
  rep(i, Q) { scanf("%c %c%*c", &t[i], &d[i]); }
  printf("%d\n", solve());
  return 0;
}

