                if(d[i]=='L') pos--;
                else pos++;
            }
            if(pos<0 || pos>=n) break;
        }
        if(pos<0) lfall = mid;
        else lrem = mid;
    }

    int rfall=n, rrem=-1;
    while(rfall-rrem>1){
        int mid=(rfall+rrem)/2;
        int pos=mid;
        for(int i=0;i<q;i++){
            if(s[pos]==t[i]){
                if(d[i]=='L') pos--;
                else pos++;
            }
            if(pos<0 || pos>=n) break;
        }
        if(pos>=n) rfall = mid;
        else rrem = mid;
    }

    int fall = (lfall+1)+(n-rfall);
    cout << n-fall << endl;

    return 0;
}

