int n, q;
string s;

int get(int idx, vector<pair<char, int> >& r) {
	rep(i,0,q) {
		if(s[idx] == r[i].F) {
			idx += r[i].S;
		}
		if(idx < 0 || idx >= n) return idx;
	}
	return idx;
}

int solve(vector<pair<char, int> >& r) {
	int ret = 0;
	int low = 0;
	int hig = n;
	while(low<hig) {
		int mid = (low+hig) / 2 + 1;
		if(get(mid,r) == -1) {
			low = mid;
		} else {
			hig = mid-1;
		}
	}
	if(get(low,r) == -1) {
		ret += (low + 1);
	}
	low = 0;
	hig = n;
	while(low<hig) {
		int mid = (low+hig)/2;
		if(get(mid,r) == n) {
			hig = mid;
		} else {
			low = mid+1;
		}
	}
	ret += (n - low);
	return n - ret;
}

