void solve()
{
    for (int i = 1; i <= N; i++) {
        P[i]++;
    }
    for (int i = 0; i < N; i++) {
        //cnt[c[i] - 'A'].push_back(i + 1);
        cnt[c[i] - 'A'][0]++;
        cnt[c[i] - 'A'][cnt[c[i] - 'A'][0]] = i + 1;
    }

    for (int i = 0; i < Q; i++) {
        int I = t[i] - 'A';
        if (d[i] == 'L') {
            for (int j = 1; j <= cnt[I][0]; j++) {
                P[cnt[I][j] - 1] += P[cnt[I][j]];
                P[cnt[I][j]] = 0;
            }
        }
        if (d[i] == 'R') {
            for (int j = cnt[I][0]; j >= 1; j--) {
                P[cnt[I][j] + 1] += P[cnt[I][j]];
                P[cnt[I][j]] = 0;
            }
        }
    }
    cout << N - P[0] - P[N + 1] << endl;
}


