bool isLeftFallen(int now){
    bool fall = false;
    for(int i = 0; i < q; i++){
        if(s[now] != T[i]) continue;

        if(D[i] == 'L') now--;
        else now++;

        if(now == -1){
            fall = true;
            break;
        }
        if(now == n){
            break;
        }
    }
    return fall;
}

bool isRightFallen(int now){
    bool fall = false;
    for(int i = 0; i < q; i++){
        if(s[now] != T[i]) continue;

        if(D[i] == 'L') now--;
        else now++;

        if(now == n){
            fall = true;
            break;
        }
        if(now == -1){
            break;
        }
    }
    return fall;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    cin >> n >> q;
    cin >> s;

    T.resize(q);
    D.resize(q);

    for(int i = 0; i < q; i++){
        cin >> T[i] >> D[i];
    }

    int l1 = -1, r1 = n;
    while(r1 - l1 > 1){
        int mid = (r1 + l1) / 2;
        if(isLeftFallen(mid)) l1 = mid;
        else r1 = mid;
    }

    int leftFallenIndex = r1;

    int l2 = -1, r2 = n;
    while(r2 - l2 > 1){
        int mid = (r2 + l2) / 2;
        if(isRightFallen(mid)) r2 = mid;
        else l2 = mid;
    }

