struct Union_Find{
  vi par;
  Union_Find(int N):par(N){
    rep(i,0,N) par[i]=i;
  }
  int root(int X){
    if(par[X]==X||par[X]==-1||par[X]==N) return par[X];
    return par[X]=root(par[X]);
  }
  void insert(int X,int Y){
    if(Y==-1){
      par[X]=-1;
      M[S[X]].erase(X);
    }
    else if(Y==N){
      par[X]=N;
      M[S[X]].erase(X);
    }
    else{
      par[X]=Y;
      M[S[Y]].insert(Y);
      M[S[X]].erase(X);
    }
  }
  bool safe(int X){
    if(root(X)==-1||root(X)==N) return 0;
    return 1;
  }
};
