		cin >> t[i] >> d[i];
	}


	int left_limit = n;		// from right
	int left = 0;
	int right = n - 1;
	if ('R' == Move(left, n, q, s, t, d)) {
		left_limit = left;
	}
	else if ('R' != Move(right, n, q, s, t, d)) {
		left_limit = n;
	}
	else {
		for (;;) {
			int mid = (left + right) / 2;
			if ('R' == Move(mid, n, q, s, t, d)) {
				if (left == mid) {
					left_limit = left;
					break;
				}
				right = mid;
			}
			else {
				if (left == mid) {
					left_limit = right;
					break;
				}
				left = mid;
			}
		}
	}



	int right_limit = -1;	// from left
	left = 0;
	right = n - 1;
	if ('L' == Move(right, n, q, s, t, d)) {
		right_limit = right;
	}
	else if ('L' != Move(left, n, q, s, t, d)) {
		right_limit = -1;
	}
	else {
		for (;;) {
			int mid = (left + right) / 2;
			if ('L' == Move(mid, n, q, s, t, d)) {
				if (left == mid) {
					right_limit = left;
