int main(void) {
	int64 N, Q;
	string s;
	cin >> N >> Q >> s;
	vector<char> t(Q), d(Q);
	REP(i, Q) cin >> t[i] >> d[i];

	auto ok = [&](int64 x) {
		REP(i, Q) {
			if (s[x] == t[i]) {
				if (d[i] == 'L') x--;
				else x++;
			}
			if (x < 0) return 1;
			if (x >= N) return 0;
		}
		return 0;
	};

	auto bs = [&]() {
		int64 l = -1, r = N, m;
		while (r - l > 1) {
			m = (l + r) >> 1;
			if (ok(m)) {
				l = m;
			} else {
				r = m;
			}
		}
		return l;
	};
	int64 rl = bs() + 1;
	reverse(all(s));
	REP(i, Q) d[i] = (d[i] == 'L' ? 'R' : 'L');
	int64 rr = bs() + 1;
	cout << N - rl - rr << endl;
