	ll N;
	cin >> N;
	ll Q;
	cin >> Q;
	string S;
	cin >> S;
	vector<char> T(Q);
	vector<char> D(Q);
	rep(i, Q) {
		cin >> T[i] >> D[i];
	}

	ll head = -1;
	ll tail = N;

	deps(i, Q - 1, 0) {
		if (D[i] == 'R') {
			if (S[tail - 1] == T[i]) {
				tail--;
				if (tail <= 0) { //全員落ちる
					break;
				}
			}

			if (head >= 0 && S[head] == T[i]) {
				head--;
			}
		}
		else{ //L
			if (S[head + 1] == T[i]) {
				head++;
				if (head >= N - 1) { //全員落ちる
					break;
				}
			}

			if (tail < N && S[tail] == T[i]) {
				tail++;
			}
		}
	}

	ll result = N - min(N, head + 1 + N - tail);
	cout << result << endl;

	return 0;
}

