// 二分探索をする
// { TTTTTFF } => output: 5
// { FFFFFFF } => output: 0
// { TTTTTTT } => ooutput: 7
// funcを満たさない最小のIndexを返す
template<typename T>
T binarySearchFunction( int begin, int end, function<bool(T index)> func )
{
	T lb = begin-1, ub = end-1;
	while( lb < ub - 1 )
	{
		T mid = ( lb + ub ) / 2;
		if( func( mid ) ) lb = mid;
		else ub = mid;
	}
	if( ub == end - 1 && func( ub ) ) return end;
	return ub;
}
template<typename T>
T BSF( int begin, int end, function<int(T index)> func )
{
	T lb = begin-1, ub = end-1;
	while( lb < ub - 1 )
	{
		T mid = ( lb + ub ) / 2;
		T f = func(mid);
		if( f < begin ) lb = mid;
		else if( f >= end ) ub = mid;
		else return mid;
	}
	T f = func(ub);
	if( f < begin || end <= f ) return -1;
	return ub;
}

int main()
{
	ll n, q;
	string s;
	cin >> n >> q >> s;
	vector<pair<char, bool>> v(q);
	REP(i,q)
	{
		char a,b;
		cin >> a >> b;
		v[i] = pair<char,bool>( a, b == 'R' );
	}

	auto last = [n, q, v, s] ( int idx ) -> int
	{
		REP( i, q )
		{
			if( s[idx] == v[i].first )
			{
				idx += v[i].second ? 1 : -1;
				if( idx == -1 || idx == n )
					return idx;
			}
		}
		return idx;
	};
	auto is = [n, last]( int idx )
	{
		ll f = last(idx);
		return 0 <= f && f < n;
	};
	auto isn = [is]( int idx ) 
	{
		return !is(idx);
	};

	ll mid = BSF<ll>( 0, n, last );
	if( mid == -1 )
		cout << 0 << endl;
	else
	{
		ll ans = 0;
		ans += binarySearchFunction<ll>( 0, mid + 1, isn );
		ans += n - binarySearchFunction<ll>( mid, n, is );
		cout << n - ans << endl;
	}

	return 0;
}

