bool is_left(int i) {
	int ti = i;
	for (int q = 0; q < Q; q++)
	{
		if (t[q] == s[ti]) {
			if (d[q] == 'L') {
				ti--;
			}
			else {
				ti++;
			}
		}
		if (ti == 0) {
			return true;
		}
		else if (ti == N + 1) {
			return false;
		}
	}
	return false;
}

bool is_right(int i) {
	int ti = i;
	for (int q = 0; q < Q; q++)
	{
		if (t[q] == s[ti]) {
			if (d[q] == 'L') {
				ti--;
			}
			else {
				ti++;
			}
		}
		if (ti == N + 1) {
			return true;
		}
		else if (ti == 0) {
			return false;
		}
	}
	return false;
}

int main() {
	cin >> N >> Q;
	s = string(N + 1, ' ');
	for (int i = 1; i <= N; i++)
	{
		cin >> s[i];
