	t = string(Q, ' ');
	d = string(Q, ' ');
	for (int i = 0; i < Q; i++)
	{
		cin >> t[i] >> d[i];
	}

	int lb1 = 0, ub1 = N + 1;
	int mid1;
	while (ub1 - lb1 > 1) {
		mid1 = (ub1 + lb1) / 2;
		if (is_left(mid1)) {
			lb1 = mid1;
		}
		else {
			ub1 = mid1;
		}
	}

	int lb2 = 0, ub2 = N + 1;
	int mid2;
	while (ub2 - lb2 > 1) {
		mid2 = (ub2 + lb2) / 2;
		if (is_right(mid2)) {
			ub2 = mid2;
		}
		else {
			lb2 = mid2;
		}
	}
	int ans = ub2 - lb1 - 1;
	cout << ans << endl;
	return 0;
}

