int last_pos(const string& s,vector<tuple<char,char>>& qs,int p)
{
	for(auto q:qs){
		char t,d; tie(t,d)=q;
		if(p<0||s.size()<=p||s[p]!=t)
			continue;
		p=d=='L'?p-1:p+1;
	}
	return p;
}

