template<typename D, class... A> class BinarySearch {
    D left;
    D right;
    function<bool(D, A...)> func;

    public:
        BinarySearch(D l, D r, function<bool(D, A...)> f) {
            left = l;
            right = r;
            func = f;
        }

        D calc(A... args) {
            while (abs(right - left) > 1) {
                D middle = (left + right) / 2;
                if (func(middle, args...)) {
                    left = middle;
                } else {
                    right = middle;
                }
            }
            return left;
        }
};

template<typename D, class... A> class BinarySearchR {
    D left;
    D right;
    function<bool(D, A...)> func;

    public:
        BinarySearchR(D l, D r, function<bool(D, A...)> f) {
            left = l;
            right = r;
            func = f;
        }

        D calc(A... args) {
            while (abs(right - left) > 1) {
                D middle = (left + right) / 2;
                if (func(middle, args...)) {
                    right = middle;
                } else {
                    left = middle;
                }
            }
            return right;
        }
};

void solve() {
    int n, q;
    string s;
    cin >> n >> q >> s;
    vector<char> t(q);
    vector<char> d(q);
    REP(i, q) cin >> t[i] >> d[i];

    auto check = [&](int m) {
        int p = m;
        REP(i, q) {
            if (s[p] == t[i]) {
                if (d[i] == 'L') p--;
                else p++;
                if (p < 0) return true;
            }
        }
        return false;
    };

    auto check_r = [&](int m) {
        int p = m;
        REP(i, q) {
            if (s[p] == t[i]) {
                if (d[i] == 'L') p--;
                else p++;
                if (p >= n) return true;
            }
        }
        return false;
    };

    BinarySearch<int> bs(-1, n, check);
    int l = bs.calc();

    BinarySearchR<int> bs_r(-1, n, check_r);
    int r = bs_r.calc();
    cout << n - (l + 1 + n - r) << endl;
}

