  if(v == -1) return true;
  rep(i, 0, Q) {
    if(t[i] != s[v]) continue;
    if(d[i] == 'R') v++;
    else v--;
    if(v == -1) return true;
    if(v == N) return false;
  }
  return false;
}

int bs_l() {
  int ng = N;
  int ok = -1;
  while(abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;
    if(isOK_l(mid)) ok = mid;
    else ng = mid;
  }
  return ok;
}

bool isOK_r(int v) {
  if(v == N) return true;
  rep(i, 0, Q) {
    if(t[i] != s[v]) continue;
    if(d[i] == 'R') v++;
    else v--;
    if(v == N) return true;
    if(v == -1) return false;
  }
  return false;
}

int bs_r() {
  int ng = -1;
  int ok = N;
  while(abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;
    if(isOK_r(mid)) ok = mid;
    else ng = mid;
  }
  return ok;
}

