        L--;
      }
    }else{
      if(R < n-1 && si[R+1] == t){
        R++;
      }
      if(L < n-1 && si[L+1] == t){
        L++;
      }
    }

    maxL = max(maxL, L);
    minR = min(minR, R);
  }


  int ans = 0;


