int memo[200001][200000];


int search(int time, int i)
{
	if (memo[time][i] != -1)
		return memo[time][i];

	if (time == Q)
	{
		return memo[time][i] = i;
	}

	else
	{
		if (s[i] == t[time])
		{
			if (d[time] == 'L')
			{
				if (i == 0)
					return memo[time][i] = -2;
				else
					return search(time + 1, i - 1);
			}
			else
			{
				if (i == N - 1)
					return memo[time][i] = -2;
				else
					return search(time + 1, i + 1);
			}
		}
		else
		{
			return search(time + 1, i);
		}
	}
}


