}q[N];
bool canmove(int pos)
{
    return pos > 0 && pos <= n;
}
void move(int pos, int v)
{
    for (int i = 0; i < 26; i ++){
        if (L[i] == pos)
            L[i] += v;
        if (R[i] == pos)
            R[i] += v;
    }
}
int check(int pos)
{
    for (int i = 0; i < 26 ;i ++)
        L[i] = l[pos][i], R[i] = r[pos][i];
    for (int i = 1 ; i <= m; i ++)
        if (q[i].sig == 'L')
        {
            if (L[q[i].c] == R[q[i].c]) {
                if (canmove(L[q[i].c]))
                    move(L[q[i].c], -1);
                continue;
            }
            if (canmove(L[q[i].c]))
                move(L[q[i].c], -1);
            if (canmove(R[q[i].c]))
                move(R[q[i].c], -1);
        } else
        {
            if (L[q[i].c] == R[q[i].c]) {
                if (canmove(R[q[i].c]))
                    move(R[q[i].c], 1);
                continue;
            }
            if (canmove(R[q[i].c]))
                move(R[q[i].c], 1);
            if (canmove(L[q[i].c]))
                move(L[q[i].c], 1);
        }
    if (canmove(L[s[pos]])) return 0;
    return (int)(L[s[pos]] == n + 1) * 2 - 1;
}
