            l[i][j] = l[i - 1][j];
        l[i][s[i]] = i;
    }
    for (int i = 0; i < 26;  i++)
        r[n + 1][i] = n + 1;
    for (int i = n; i >= 1; i --){
        for (int j = 0; j < 26; j ++)
            r[i][j] = r[i + 1][j];
        r[i][s[i]] = i;
    }
    for (int i = 1; i <= m ; i++)
        scanf(" %c %c", &q[i].c, &q[i].sig), q[i].c -= 'A';
    int L = 1 , R = n, mid, LL = n + 1, sig, RR = 0;
    while (L <= R)
    {
        mid = (L + R) / 2;
        sig = check(mid);
        if (!sig)
            LL = min(LL, mid), R = mid - 1;
        else
            if (sig < 0)
                L = mid + 1;
            else
                R = mid - 1;
    }
    L = 1 , R = n;
    while (L <= R)
    {
        mid = (L + R) / 2;
        sig = check(mid);
        if (!sig)
            RR = max(RR, mid), L = mid + 1;
        else
        if (sig < 0)
            L = mid + 1;
        else
            R = mid - 1;
    }

    printf("%d\n", max(0, RR - LL + 1));
