int main() {
    std::iostream::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    // code here
    int n = input<int>();
    int q = input<int>();

    string s = input<string>();

    vector<pair<char, int>> in(q);
    for (int i = 0; i != q; ++i) {
        cin >> in[i].first;
        in[i].second = (input<char>() == 'R' ? +1 : -1);
    }

    auto sim = [&](int i) {
        for (auto el: in) {
            if (el.first == s[i])
                i += el.second;

            if (i == n)
                return +1;
            if (i == -1)
                return -1;
        }

        return 0;
    };

    int lo = 0;
    int hi = n + 1;

    while (hi - lo > 1) {
        int mi = lo + (hi - lo) / 2;

        if (sim(mi - 1) == -1)
            lo = mi;
        else
            hi = mi;
    }

    int ans = lo;

    lo = 0;
    hi = n + 1;
    while (hi - lo > 1) {
        int mi = lo + (hi - lo) / 2;

        if (sim(n - mi) == +1)
            lo = mi;
        else
            hi = mi;
    }

    ans += lo;
    cout << n - ans << "\n";

    return 0;
}

