vector<pair<char, char>> spells;

int goneLeft() {
  int ans = -1;
  int low = 0, high = n - 1;
  while (low <= high) {
    int mid = (low + high) / 2;

    int ind = mid;
    for (const auto &spell : spells) {
      if (S[ind] == spell.first) {
        if (spell.second == 'L') {
          ind--;
        } else {
          ind++;
        }
        if (ind < 0 || ind >= n) {
          break;
        }
      }
    }
    if (ind < 0) {
      ans = mid;
      low = mid + 1;
    }
    else {
      high = mid - 1;
    }
  }
  return ans;
}
int goneRight() {
  int ans = n;
  int low = 0, high = n - 1;
  while (low <= high) {
    int mid = (low + high) / 2;

    int ind = mid;
    for (const auto &spell : spells) {
      if (S[ind] == spell.first) {
        if (spell.second == 'L') {
          ind--;
        } else {
          ind++;
        }
        if (ind < 0 || ind >= n) {
          break;
        }
      }
    }
    if (ind >= n) {
      ans = mid;
      high = mid - 1;
    }
    else {
      low = mid + 1;
    }
  }
  return ans;
}
int main() {
  scanf("%d%d", &n, &q);
  scanf("%s", S);
  for (int i = 0; i < q; i++) {
    char letter[30], direction[30];
    scanf("%s%s", letter, direction);
    spells.emplace_back(letter[0], direction[0]);
  }
  int L = goneLeft();
  int R = goneRight();
  int ans = R - L - 1;
  if (ans < 0) ans = 0;
  printf("%d\n", ans);
  return 0;
}

