  }
  int start=0,end=N-1,mid,f;

  //xが落ちない位置になるようにする．
  while(true){
    mid = (start + end)/2;
    if(end-start < 1) break;
    f = fall(mid);
    if(!f) break;
    else if(f==1) start = mid+1;
    else end = mid-1;
  }

  if(f){
    cout << 0 << endl;
    return 0;
  }
  int S,E;
  if(!fall(start)) S=start;
