int cal_pos(int pos) {
    for (int i = 1; i <= Q; i++) {
        if (t[i] == tile[pos]) {
            if (d[i] == 'L') {
                pos--;
            } else {
                pos++;
            }
        }
        if (pos == 0 || pos == N + 1) {
            break;
        }
    }
    return pos;
}

