        tile[i+1] = S[i];
    }

    int ret = N;
    BSR bsr = binary_search(1, N, [](int j){
        return cal_pos(j) == 0;
    });
    if (bsr.found) {
        ret -= bsr.end - bsr.begin + 1;
    }
    bsr = binary_search(1, N, [](int j){
        return cal_pos(j) == N + 1;
    });
    if (bsr.found) {
        ret -= bsr.end - bsr.begin + 1;
    }

    std::cout << ret << std::endl;

    return 0;
}

