// 位置 p のゴーレムが最終的に移動する位置
int finalPos(int p) {
	if (p < 0 || p >= N) return p;
	REP(q, Q) {
		if (s[p] != t[q]) continue;
		p += (d[q] == 'L' ? -1 : 1);
		if (p < 0 || p >= N) return p;
	}
	return p;
}

bool leftBound(int n) { return !(finalPos(n) == -1); }
bool rightBound(int n) { return !(finalPos(n) == N); }

template<typename T>
T BinarySearch(T ng, T ok, function<bool(T)> func) {
	while (abs(ok - ng) > 1) {
		T mid = (ng + ok) / 2;
		(func(mid) ? ok : ng) = mid;
	}
	return ok;
}

int solve() {
	int ans = 0;
	int l = BinarySearch<int>(-1, N - 1, leftBound);
	int r = BinarySearch<int>(N, 0, rightBound);
	return r - l + 1;
}

