bool solve(LL m, string &s, bool isL, vector<char> &t, vector<char> &d) {
    int q = t.size(), n = s.size();
    REP(i,0,q) {
        if (m < 0 || m >= n) break;
        if (t[i] != s[m]) continue;
        if (d[i] == 'L') --m;
        else ++m;
    }
    if (isL) return m < 0;
    else return m >= n;
}

long long meguru_bin(string &s, bool isL, vector<char> &t, vector<char> &d) {
    long long ok = -1;
    long long ng = s.size();
    if (isL == false) swap(ok, ng);

    while (abs(ok - ng) > 1) {
        long long mid = ng + (ok - ng) / 2;
        //cerr << ok << " " << mid << " " << ng << endl;
        if (solve(mid, s, isL, t, d)) ok = mid;
        else ng = mid;
    }

    return ok;
}

