int bin_left( vector<char>& t , vector<char>& d , string& s , int N , int Q , int left ,int right )
{

  if( left + 1 == right )
    {
      return left;
    }


  int mid = ( left + right )/ 2;

  int id = mid;

  REP(q,Q)
    {
      if( t[q] == s[id] )
	{
	  if( d[q] == 'L' )
	    {
	      -- id;
	    }
	  else
	    {
	      ++ id;
	    }


	}



      if( id < 0 )
	{
	  return bin_left( t , d , s , N , Q , mid + 1 , right );

	}

      if( id > N-1 )
	{
	  return bin_left( t , d , s , N , Q , left , mid );
	}

    }

  return bin_left( t , d , s , N , Q , left , mid );


}



int bin_right( vector<char>& t , vector<char>& d , string& s , int N , int Q , int left ,int right )
{

  if( left + 1 == right )
    {
      return left;
    }


  int mid = ( left + right )/ 2;

  int id = mid;

  REP(q,Q)
    {
      if( t[q] == s[id] )
	{
	  if( d[q] == 'L' )
	    {
	      -- id;
	    }
	  else
	    {
	      ++ id;
	    }


	}



      if( id > N-1 )
	{
	  return bin_right( t , d , s , N , Q , left , mid );

	}

      if( id < 0 )
	{
	  return bin_right( t , d , s , N , Q , mid+1 , right );
	}

    }

  return bin_right( t , d , s , N , Q , mid+1 , right );


}




