int bisection(int dst) {
    int ng = N + (-1) - dst;
    int ok = dst;

    while(abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;
        if (isOK(mid, dst)) ok = mid;
        else ng = mid;
    }
    return ok;
}

