int simulation(int pos) {
  for (int i = 1; i <= q; i++) {
    if (pos == 0) return -1;
    else if (pos == n+1) return 1;

    if (t[i] == s[pos]) {
      if (d[i] == 'L') pos--;
      else pos++;
    }
  }

  if (pos == 0) return -1;
  else if (pos == n+1) return 1;

  return 0;
}

int main() {
  int i, left, right, mid, pos, left_end, right_end, result;

  // input
  cin >> n >> q;
  cin >> s;
  s = ' ' + s + ' ';  // s[0], s[n]: dummy
  for (i = 1; i <= q; i++) cin >> t[i] >> d[i];

  // decide left_end
  left = 0;
  right = n+1;
  left_end = 0;

  while (left+1 < right) {
    mid = (left + right) / 2;
    pos = mid;

    result = simulation(pos);
    if (result == -1) {
      if (mid > left_end) left_end = mid;
      left = mid;
    } else {
      right = mid;
    }
  }

  // decide right_end
  left = 0;
  right = n+1;
  right_end = n+1;

  while (left+1 < right) {
    mid = (left + right) / 2;
    pos = mid;

    result = simulation(pos);

    if (result == 1) {
      if (mid < right_end) right_end = mid;
      right = mid;
    } else {
      left = mid;
    }
  }
  cout << right_end - left_end - 1 << endl;

  return 0;
}

