bool exit_from(int nn, char direction)
{
    int a = nn;

    for (int i = 0; i < q; i++) {
        if (t[i] != s[a]) {
            continue;
        }

        if (d[i] == 'L') {
            a--;
        } else {
            a++;
        }

        if (a < 0) {
            return true;
        }
        if (a > n - 1) {
            return true;
        }
    }

    return false;
}

