            if(t[i] == s[nl + 1]){
                nl++;
            }
        }
        else if(nl != 0){
            if(d[i] == 'R'){
                if(t[i] == s[nl] && t[i] == s[nl - 1]){
                    nl--;
                }
            }
        }
    }
    cout << max(0, n - nl - (n - nr + 1)) << endl;
}

