// マスstのゴーレムが最終的に至る座標
int final_idx(int st) {
	if (st < 0) return -1;
	if (st > N) return N;
	for (int i = 0; i < Q; ++i) {
		if (s[st] == spells[i].t) { // 移動の対象
			if (spells[i].d == 'L') --st;
			else ++st;
		}
		if (st < 0) return -1;
		if (st >= N) return N;
	}
	return st;
}

int main() {
