bool f(const string& S, const vector<pair<char, int> >& td, int index){
    if(index == -1){
        return true;
    }
    if(index >= S.size()){
        return false;
    }
    for(const auto&a: td){
        char t,d; tie(t,d) = a;
        if(t == S[index]){
            index += d;
            if(index < 0){
                return true;
            }
            if(index >= S.size()){
                return false;
            }
        }
    }
    return false;
}

int solve(string S, vector<pair<char, int> > td){
    int ok = -1;
    int ng = S.size();
    while(abs(ok-ng) > 1){
        int mid = (ok+ng)/2;
        if(f(S, td, mid)) {
            ok = mid;
        }
        else{
            ng = mid;
        }
    }
    return ok+1;
}

