    for(auto &a:td){
        char t; char d; cin >> t >> d;
        a.first = t;
        a.second = (d == 'L' ? -1 : 1);
    }
    int left = solve(S, td);
    reverse(S.begin(), S.end());
    for(auto &a:td){
        a.second *= -1;
    }
    int right = solve(S, td);
    cout << max((int(S.size()) - left - right), 0) << endl;
    return 0;
}

