  for (int i = 0; i < q; i++){
    char l, r;
    cin >> l >> r;
    Q.push_back(make_pair(l, r));
  }
  int left = SearchLeft(Q, N);
  int right = SearchRight(Q, N);
  if (left >= right) {
    cout << 0;
  }
  else {
    if (Ok(Q, N, right)) {
      cout << right - left - 1;
    }
    else {
      cout << right - left;
    }

  }
  return 0;
}

