  //xが落ちない位置になるようにする．
  while(true){
    mid = (start + end)/2;
    if(end-start < 1) break;
    int f = fall(mid);
    if(!f) break;
    else if(f==1) start = mid+1;
    else end = mid-1;
  }

  int S = binary_search(start, mid, 0); 
  int E = binary_search(mid, end,1);
  while(E!=N&&!fall(E))E++;
  cout << E-S << endl;
  return 0;
}

