int travelL(int N, int Q, string s, vector<char> t, vector<char> d)
{
  int lpos = -1;
  for (int i = Q-1; i >=0; i--)
  {
    if (lpos >= 0 && t[i] == s[lpos] && d[i] == 'R')
    {
      return lpos;
    }
    else if (lpos + 1 < N && t[i] == s[lpos + 1] && d[i] == 'L')
    {
      lpos++;
    }
  }
  return lpos + 1;
}
int travelR(int N, int Q, string s, vector<char> t, vector<char> d)
{
  int rpos = N;
  for (int i = Q-1; i >=0; i--)
  {
    if (rpos < N && t[i] == s[rpos] && d[i] == 'L')
    {
      return rpos;
    }
    else if (rpos - 1 >= 0 && t[i] == s[rpos - 1] && d[i] == 'R')
    {
      rpos--;
    }
  }
  return N - rpos;
}
