ll dfs(int mod, int n){
    ll mdn = mod % S[n];
    if(mod == 0 || mod == S[n])return 0;
    else if(n == 0)return mdn;
    //else if(mod < S[n])return (dfs(mod, n - 1) * (n + 1)) % DIV;
    else {
