        int fac = n;
        for(int i=n-1; i>0; i--){
            sum += dfs(mod % S[i], i - 1) * fac;
            fac *= i;
            if(sum > DIV)sum %= DIV;
        }
        sum += mod % S[0] * fac;
        return sum % DIV;
    }
}
