    int lb = right;

    // search right margin
    left = -1, right = N;
    while (right - left != 1) {
        mid = (left + right) / 2;
        if (sim(mid, S, N, Q, dist, td_list) == N) {
            right = mid;
        }
        else {
            left = mid;
        }
    }
    int rb = left;
    cout << rb - lb + 1 << endl;
    return 0;
}

