int getTable(int n, int q){
  auto itr = DP.find(n);
  if(itr == DP.end()){
    return -1;
  }else{
    map<int, int> temp = DP[n];
    auto itr2 = temp.find(q);
    if(itr2 == temp.end()){
      return -1;
    }else{
      return temp[q];
    }
  }
}
void setTable(int n, int q, int value){
  DP[n][q] = value;
}

int canStay(int n, int q){
  if(getTable(n, q) != -1) {
    return getTable(n, q);
  }else if(q == Q) {
    return 1;
  }else{
    int now = n;
    if(t[q+1] == cell[n]){
      //呪文を受ける
      if(d[q+1] == 'L'){
        now--;
      }else if(d[q+1] == 'R'){
        now++;
      }else{
        DEBUG("WRONG");
      }

      if(now == 0 || now == N+1){
        setTable(n,q,0);
        return 0;
      } else {
        int ans = canStay(now, q+1);
        setTable(n,q,ans);
        return ans;
      }
    }else{
      //呪文を受けない
      int ans = canStay(n, q+1);
      setTable(n,q,ans);
      return ans;
    }
  }
}

