void majicshift(string s, iterator begin, int N){
  char t,d;
  cin >> t >> d;
  int p,q=0;
  while((p=s.find_first_of(t))>=0){
    q += (p+1);
    if(d=='L'){
      if(q>1)
        *(begin+(q-2)) += *(begin+(q-1));
    }
    else{
      if(q<N)
        *(begin+q) += *(begin+(q-1));
    }
    *(begin+(q-1)) = 0;
    s.erase(s.begin(), s.begin()+p+1);
  }
}

