bool can_delete(int now, const string &S, const vector<pair<char, int>> &ope) {
    int N = S.size();

    FOE(p, ope) {
        if (p.first == S[now]) {
            now += p.second;
        }

        if (now < 0 or now >= N) {
            return true;
        }
    }

    return false;
}


// 消せないなかでもっとも左
int find_left(const string &S, const vector<int> &v, const vector<pair<char, int>> &ope, int idx) {

    // [low, high)
    long long low = -1, high = idx + 1, ans = idx;
    while (high - low > 1) {
        long long middle = (low + high) / 2;
        if (not can_delete(v[middle], S, ope)) {
            ans = v[middle];
            high = middle;
        }
        else {
            low = middle;
        }
    }

    return ans;
}

int find_right(const string &S, const vector<int> &v, const vector<pair<char, int>> &ope, int idx) {

    // [low, high)
    long long low = idx - 1, high = v.size(), ans = idx;
    while (high - low > 1) {
        long long middle = (low + high) / 2;
        if (not can_delete(v[middle], S, ope)) {
            ans = v[middle];
            low = middle;
        }
        else {
            high = middle;
        }
    }

    return ans;
}


int find(const string &S, const vector<int> &v, const vector<pair<char, int>> &ope) {
    auto l = find_left(S, v, ope, v.size() - 1);
    if (l != v.size() - 1) {
        return l;
    }
    auto r = find_right(S, v, ope, 0);
    if (r != 0) {
        return r;
    }
    return -1;
}


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, Q;
    cin >> N >> Q;
    string S;
    cin >> S;

    auto ope = make_v<pair<char, int>>(Q);
    unordered_set<char> alphabet;
    FOR(i, 0, Q) {
        char T, D;
        cin >> T >> D;
        if (D == 'L') {
            ope[i] = make_pair(T, -1);
        }
        else {
            ope[i] = make_pair(T, +1);
        }
        alphabet.insert(T);
    }

    unordered_map<char, vector<int>> v;
    FOR(i, 0, N) {
        v[S[i]].emplace_back(i);
    }

    unordered_map<char, pair<int, int>> memo;
    FOE(a, alphabet) {

        int idx = find(S, v[a], ope);
        if (idx == -1) {
            memo[a] = make_pair(-1, -1);
            continue;
        }

        idx = lower_bound(ALL(v[a]), idx) - v[a].begin();

        auto l = find_left(S, v[a], ope, idx);
        auto r = find_right(S, v[a], ope, idx);
        memo[a] = make_pair(l, r);
//        cout << a << ":" << l << "-" << r << endl;
    }

    int ans = 0;
    FOR(i, 0, N) {
        auto c = S[i];
        if (alphabet.find(c) == alphabet.end()) {
            ans++;
            continue;
        }

        int l = memo[c].first;
        int r = memo[c].second;
        if (l <= i and i <= r) {
            ans++;
        }
    }
    print(ans);

    return 0;
}

