int pos(const string& s, const string& t, const vector<bool>& dir, int i) {
  int q = t.size();
  REP(j,q) {
    if (s[i] == t[j]) {
      if (dir[j]) {
        --i;
      } else {
        ++i;
      }
    }
  }
  return i;
}

