  cin>>n>>q;
  string s;
  cin>>s;
  string t;
  vector<bool> dir(q);
  REP(i,q) {
    string c;
    string d;
    cin>>c>>d;
    t.push_back(c[0]);
    dir[i] = d[0] == 'L';
  }
  s = "$" + s + "$";
  int lo = 0;
  int hi = n+1;
  while (hi-lo > 1) {
    int mid = (hi+lo) / 2;
    if (pos(s, t, dir, mid) == 0) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  int left = lo;
  lo = 0;
  hi = n+1;
  while (hi-lo > 1) {
    int mid = (hi+lo) / 2;
    if (pos(s, t, dir, mid) == n+1) {
      hi = mid;
    } else {
      lo = mid;
    }
  }
  int right = n+1 - hi;
  cout << (n - left - right) << endl;
  return 0;
}

