      is_left = false;
    }

    if (edges.count(t) == 0) {
      tuple<long long, long long, long long> ttt = make_tuple(0, 0, 0);
      edges.emplace(t, move(ttt));
    }

    auto current = get<0>(edges[t]);
    auto lmin = get<1>(edges[t]);
    auto rmax = get<2>(edges[t]);

    if (is_left) {
      current--;
    } else {
      current++;
    }

    lmin = min(current, lmin);
    rmax = max(current, rmax);

    edges[t] = make_tuple(current, lmin, rmax);
