		mid = (st+en)>>1ll;
		ll co = mid; bool can = 0;
		for(ll i=0;i<q;i++) {
			if(co >= n||co<0) break;
			if(Q[i].f == A[co]) {
				co -= (Q[i].s == 'L');
				co += (Q[i].s == 'R');
			}
		}
		if(co>=n) can = 1;
		if(can) en = mid;
		else st = mid;
	}
	cerr << en << '\n';
	ll out = tmp + (n-en);
	cout << n-out << '\n';
}

