bool fallFromLeft(int s) {
    if (s==-1)return true;
    if (s==N)return false;
    int cpos=s;
    REP(i,Q)
        if (T[i][0]==S[cpos]) {
            if (D[i][0] == 'L') {
                if (--cpos < 0)return true;
            }else{
                if (++cpos >= N) return false;
            }
        }
    return false;
}
bool fallFromRight(int s) {
    if (s==-1)return false;
    if (s==N)return true;
    int cpos=s;
    REP(i,Q)
        if (T[i][0]==S[cpos]) {
            if (D[i][0] == 'L') {
                if (--cpos < 0)return false;
            }else{
                if (++cpos >= N) return true;
            }
        }
    return false;
}
int main() {
    cin >> N >> Q >> S;
    REP(i,Q)
        cin >> T[i] >> D[i];
    int l=-1,r=N;
    int ans=0;
    while(r-l>1) {
        int m=l+(r-l)/2;
        if (fallFromLeft(m))
            l=m;
        else
            r=m;
    }
    ans+=l+1;
    l=-1,r=N;
    while(r-l>1) {
        int m=l+(r-l)/2;
        if (fallFromRight(m))
            r=m;
        else
            l=m;
    }
    ans+=N-r;
    cout << N-min(ans, N) << endl;

    return 0;
}

