    for(int i=0; i<Q; i++){
        //cout << now << endl;
        if(c[now]==td[i][0]){
            now+=td[i][1];
        }
        if(now>=N){
            return bsR(l,mid);
        }else if(now<0){
            break;
        }
    }
    return bsR(mid,r);
}

