map<int, int> memo[200001][2];

int dfs(int level, int s_idx, char dire)
{
    if(level < 0 || s_idx < 0 || s_idx >= n) return 0;

    int nd = (dire == 'L' ? 0 : 1);
    if(memo[level][s_idx][nd]) return memo[level][s_idx][nd];

    //co << level << ' ' << s[s_idx] << ' ' << dire << en;

    int rec = 0;

    bool did = false;
    bool rec1add = true;

    for(int i = level; i >= 0; i--) {
	if(s[s_idx] == t[i] && dire == d[i]) {
	    rec += dfs(i - 1, s_idx + 1, 'L');
	    rec += dfs(i - 1, s_idx - 1, 'R');
	    did = true;
	} else if(did && s[s_idx] == t[i]) {
	    rec1add = false;
	}
    }

    if(did && rec1add) rec++;

    return memo[level][s_idx][nd] = rec;
}

