bool is_left_ok(ll i, std::string& s, std::vector< std::pair<char, ll> >& vq)
{
  for (auto q : vq) {
    if (s[i] == q.first) i += q.second;
    if (i < 0) return true;
    if (i >= (ll)s.size()) return false;
  }

  return false;
}

bool is_right_ok(ll i, std::string& s, std::vector< std::pair<char, ll> >& vq)
{
  for (auto q : vq) {
    if (s[i] == q.first) i += q.second;
    if (i < 0) return false;
    if (i >= (ll)s.size()) return true;
  }

  return false;
}


