class Mike{
  const int NUM_ALPHA = 26;
  inline int AlphaToInt(char a){return (int)(a - 'A');}

  private:
    int n, q;
    Vint SIZES;
    vector<queue<int>> KARI;
    Wint Positions;
    Vint Data;
  public:
    Mike(int nn, int qq){
      n = nn; q = qq;
      Data.resize(nn, 1);
      SIZES.resize(NUM_ALPHA, 0);
      KARI.resize(NUM_ALPHA);
      Positions.resize(NUM_ALPHA);
    }
    void inputStr(void){
      string s; cin >> s;
      REP(i, n){
        int K = AlphaToInt(s.at(i));
        SIZES.at(K)++;
        KARI.at(K).push(i);
      }
      REP(i, NUM_ALPHA){
        Positions.at(i).resize(SIZES.at(i));
        REP(j, SIZES.at(i)){
          Positions.at(i).at(j) = KARI.at(i).front();
          KARI.at(i).pop();
        }
      }
    }
    void Q(char a, char b){
      int u = AlphaToInt(a);
      int sz = SIZES.at(u);
      if(b == 'L'){
        REP(i, sz){
          int place = Positions.at(u).at(i);
          if(place != 0) Data.at(place - 1) += Data.at(place);
          Data.at(place) = 0;
        }
      }
      else{
        rREP(i, sz){
          int place = Positions.at(u).at(i);
          if(place != n-1) Data.at(place + 1) += Data.at(place);
          Data.at(place) = 0;
        }
      }
    }
    int SUM(void){
      int res = 0;
      vREP(ele, Data) res += ele;
      return res;
    }
};

int main(void){
  int n, q; cin >> n >> q;
  Mike Takashi(n, q);
  Takashi.inputStr();
  REP(_, q){
    char p, q;
    cin >> p >> q;
    //cout << p << " " << q;
    Takashi.Q(p, q);
  }
  cout << Takashi.SUM() << BR;
  return 0;
}

