        v.emplace_back(c, d == 'L');
        if (c == s[ll]) {
            if (d == 'L') ll--;
            else ll++;
        }
        if (c == s[rr]) {
            if (d == 'L') rr--;
            else rr++;
        }
    }

    int lpos = -1, rpos = -1;
    if (ll == 0) {
        int l = 1, r = n + 1;
        while (r - l > 1) {
            int m = (l + r) / 2;
            int pos = m;
            for (int i = 0; i < q; i++) {
                if (v[i].first == s[pos]) {
                    if (v[i].second) pos--;
                    else pos++;
                }
            }
            if (pos == 0) l = m;
            else r = m;
        }
        lpos = l;
    }

    if (rr == n + 1) {
        int l = 0, r = n;
        while (r - l > 1) {
            int m = (l + r) / 2;
            int pos = m;
            for (int i = 0; i < q; i++) {
                if (v[i].first == s[pos]) {
                    if (v[i].second) pos--;
                    else pos++;
