bool to_zero(string s, string sq, string dir, int pos) {
    pos -= 1;
    for(int i = 0; i < sq.size(); i++) { // O(q)
        if (s[pos] == sq[i]) {
            if (dir[i] == 'L')
                pos -= 1;
            else
                pos += 1;
            if (pos == -1)
                return true;
        }
    }
    return false;
}
bool to_N1(string s, string sq, string dir, int pos) {
    pos -= 1;
    for(int i = 0; i < sq.size(); i++) { // O(q)
        if (s[pos] == sq[i]) {
            if (dir[i] == 'R')
                pos += 1;
            else
                pos -= 1;
            if (pos == s.length())
                return true;
        }
    }
    return false;
}
int main() {
    int N, Q;
    cin >> N >> Q;
    string s;
    cin >> s;
    string sq, dir;
    char c1, c2;
    for(int i = 0; i < Q; i++) {
        cin >> c1 >> c2;
        sq += c1;
        dir += c2;
    }
    // find rightmost move to 0: binary search
    int l = 0, r = N; // edge case
    while (l < r) {
        int m = l + (r-l) / 2;
        if (to_zero(s, sq, dir, m) == true) {
            l = m;
            if (r == l+1) {
                r = (to_zero(s, sq, dir, r) == true) ? r : l;
                break;
            }
        } else {
            r = m-1;
        }
        // cout << "m = " << m << l << r << endl;
    }
    int ans = N - (r);
    // cout << "left: " << r << endl;
    // find leftmost move to N+1 : binary search
    l = 1, r = N+1; // edge case
    while (l < r) {
        int m = l + (r-l) / 2;
        if (to_N1(s, sq, dir, m) == false) {
            l = m+1;
        } else {
            r = m;
        }
    }
    // cout << "right:" << r << endl;
    ans -= (N-r+1);
    cout << ans << endl;

    return 0;
}

