bool binarySearch(int mid, int forward)
{
    if(mid > n-1 || mid < 0)
    {
        return 1;
    }
    int cur = mid;
    int ind = 0;
    for(int i=1; i<=q; i++)
    {
        // cout << i << " " << cur << endl;
        if(s[cur] == a[i])
        {
            if(b[i] == 'L')
            {
                cur --;
            }
            else
            {
                cur ++;
            }
        }
        if((cur == n && !forward) || (cur == -1 && forward))
        {
            break;
        }
    }
    if(cur == -1 && forward)
    {
        return 1;
    }
    else if(cur == n && !forward)
    {
        return 1;
    }
    else
    {
        return 0;
    }

}

