    cin >> s; 
    for(int i=1; i<=q; i++)
    {
        cin >> a[i] >> b[i];
    }
    int low = -1, high = n, mid;
    int forwardAns = -1;
    while(low <= high)
    {
        mid = (low + high)/2;
        // cout << "mid " << mid << endl;
        if(binarySearch(mid, 1))
        {
            low = mid + 1;
            forwardAns = mid;
        }
        else
        {
            high = mid - 1;
        }
    }

    // cout << forwardAns << endl;
    low = -1, high = n;
    int backwardAns = n;
    while(low <= high)
    {
        mid = (low + high)/2;
        // cout << "mid " << mid << " " << low << " " << high << endl;
        if(binarySearch(mid, 0))
        {
            high = mid-1;
            backwardAns = mid;
        }
        else
        {
            low = mid + 1;
        }
    }
    // cout << backwardAns << endl;
    if(backwardAns <= forwardAns)
    {
        cout << n << endl;
    }
    else
    {
        cout << backwardAns - forwardAns - 1 << endl;
    }
    return 0;
}

