    //printf("%d %d %d %d %d\n", a, b, c, xc, target);
    if(xc<target) a = c+1;
    else b = c;
  }

  int leftmost;
  if(fall(t,d,s,N,c)==target) leftmost = a;
  else {
    cout << N << endl;  // target not found, indicating no gorem is removed
    return 0;
  }

  // rightmost binary search
  a=0; b=N-1;
  while(true){
    //printf("%d %d %d %d %d\n", a, b, c, xc, target);
    if(a==b) break;

    c = (a+b+1)/2;
    int xc = fall(t,d,s,N,c);

    if(xc>target) b = c-1;
    else a = c;
  }

  int rightmost = a;

  //cout << leftmost << "\t" << rightmost << endl;

  cout << rightmost - leftmost + 1 << endl;

  return 0;
}

