		int mid = min + (max - min) / 2;
		int tmp = mid;
		for (int i = 0; i < Q; i++)
		{
			if (s[tmp] == t[i])
			{
				if (d[i] == 'L')
					tmp--;
				else
					tmp++;
			}
			if (tmp == -1)
			{
				break;
			}
			if (tmp == N)
			{
				check++;
				break;
			}
		}

		if (check == 0)
		{
			return BS2(mid, max);
		}
		else
		{
			return BS2(min, mid);
		}
	}
	else
	{
		int check1 = 0;
		int tmp = min;
		for (int i = 0; i < Q; i++)
		{
			if (s[tmp] == t[i])
			{
				if (d[i] == 'L')
					tmp--;
				else
					tmp++;
			}
			if (tmp == -1)
			{
				break;
			}
			if (tmp == N)
			{
				check1++;
				break;
			}
		}

		tmp = max;
		int check2 = 0;
		for (int i = 0; i < Q; i++)
		{
			if (s[tmp] == t[i])
			{
				if (d[i] == 'L')
					tmp--;
				else
					tmp++;
			}
			if (tmp == -1)
			{
				break;
			}
			if (tmp == N)
			{
				check2++;
				break;
			}
		}

		if (check1 == 1)
			return min;
		else if (check2 == 1)
			return max;
		else
			return max + 1;
	}
}

