          i--;
          if (i < 0) {
            return true;
          }
        } else {
          i++;
          if (s.size() <= i) {
            return false;
          }
        }
      }
    }
    return false;
  };
  auto check_r = [&](int32_t i) -> bool {
    for (const auto &j : td) {
      if (s[i] == j.first) {
        if (j.second == 'L') {
          i--;
          if (i < 0) {
            return false;
          }
        } else {
          i++;
          if (s.size() <= i) {
            return true;
          }
        }
      }
    }
    return false;
  };

  int32_t l_ans;
  if (!check_l(0)) {
    l_ans = -1;
  } else if (check_l(s.size() - 1)) {
    l_ans = s.size() - 1;
