bool left(const std::string S, const std::vector<char> ts, const std::vector<char> ds, int pos)
{
  // std::cout << pos << std::endl;

  if (pos < 0)
  {
    return true;
  }

  if (pos >= S.size())
  {
    return false;
  }

  for (int i = 0; i < ts.size(); i++)
  {
    if (S[pos] == ts[i])
    {
      pos += (ds[i] == 'L' ? -1 : +1);
    }

    // std::cout << pos << std::endl;

    if (pos < 0)
    {
      return true;
    }

    if (pos >= S.size())
    {
      return false;
    }
  }

  return false;
}

bool right(const std::string S, const std::vector<char> ts, const std::vector<char> ds, int pos)
{
  // std::cout << pos << std::endl;

  if (pos < 0)
  {
    return false;
  }

  if (pos >= S.size())
  {
    return true;
  }

  for (int i = 0; i < ts.size(); i++)
  {
    if (S[pos] == ts[i])
    {
      pos += (ds[i] == 'L' ? -1 : +1);
    }

    // std::cout << pos << std::endl;

    if (pos < 0)
    {
      return false;
    }

    if (pos >= S.size())
    {
      return true;
    }
  }

  return false;
}

