bool judge(int idx, int dst) {
    int dst2 = (dst == -1 ? n : -1);
    for (int i = 0; i < q; i++) {
        if (s[idx] == t[i]) {
            if (d[i] == 'R') idx++;
            else idx--;
        }
        if (idx == dst) return true;
        if (idx == dst2) return false;
    }
    return false;
}

int solve(int tar) {
    int ok = tar, ng = (tar == -1 ? n : -1);
    while (abs(ng - ok) > 1) {
        int mid = (ok + ng) / 2;
        if (judge(mid, tar)) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    return ok;
}

