signed main() {
  cin >> N >> Q >> s;
  l[s[0]].push_back(0);
  r[s[N-1]].push_back(N-1);

  rep(i, Q) {
    char c, dir;
    cin >> c >> dir;
    qs.emplace_back(c, dir);
  }
  reverse(begin(qs), end(qs));
  for (auto q : qs) {
    char c = q.first, dir = q.second;
