int solve(const string& s, const vector<pair<char, char>>& vp) {
    int k = 0;
    for (auto& p : vp) {
        char t = p.first;
        char d = p.second;
        if (k == 0) {
            if(s[0] == t && d == 'L')
                k = 1;
        } else {
            if (s[k - 1] == t && d == 'R') {
                k--;
                continue;
            }
            if (k < s.size() && s[k] == t && d == 'L') {
                k++;
                continue;
            }
        }
    }
    return k;
}

int my_main(int argc, char** argv)
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, q;
    cin >> n >> q;
    string s;
    cin >> s;

    vector<pair<char, char>> vp;
    for (int i = 0; i < q; i++) {
        char t, d;
        cin >> t >> d;
        vp.emplace_back(t, d);
    }

    reverse(all(vp));

    int l = solve(s, vp);

    for (auto& p : vp) {
        if (p.second == 'R')
            p.second = 'L';
        else
            p.second = 'R';
    }
    reverse(all(s));
    int r = solve(s, vp);

    int ans = n - min(l + r, n);
    dump(l);
    dump(r);
    cout << ans << endl;

    return 0;
}





