class Solve {
public:
    Int N, Q;
    string s;
    vector<char> t, d;

    void init() {
        cin >> N >> Q;
        cin >> s;
        t.resize(Q);
        d.resize(Q);
        for (int i = 0; i < Q; ++i) {
            cin >> t[i] >> d[i];
        }
    }

    bool ldie(int x) {
        int y = x;
        for (int i = 0; i < Q; ++i) {
            if (s[y] == t[i]) {
                if (d[i] == 'L') y--;
                else y++;
            }
            if (y < 0) return true;
            if (y >= N) return false;
        }

        return false;
    }

    bool rdie(int x) {
        int y = x;
        for (int i = 0; i < Q; ++i) {
            if (s[y] == t[i]) {
                if (d[i] == 'L') y--;
                else y++;
            }
            if (y < 0) return false;
            if (y >= N) return true;
        }

        return false;
    }

    int compute_ldie() {
        int ok = -1, ng = N + 1;
        while (ng - ok > 1) {
            int mid = (ok + ng) / 2;
//            if (mid == -1) {
//                return -1;
//            }
            if (ldie(mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        return ok;
    }

    int compute_rdie() {
        int ok = N + 1, ng = -1;
        while (ok - ng > 1) {
            int mid = (ok + ng) / 2;
            if (rdie(mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        return ok;
    }

    void solve() {
        int l = compute_ldie();
        int r = compute_rdie();
        if (l + 1 < r - 1) {
            int ans = r - 1 - (l + 1) + 1;
            cout << ans << endl;
        } else {
            cout << 0 << endl;
        }

    }
};

