	square* R;
};

int main() {
	int N, Q;
	cin >> N >> Q;

	//char* s = (char*)calloc(N + 1, sizeof(char));
	//cin >> s;
	string s;
	cin >> s;

	vector<square*> v[0x5A+1];

	square* prev = nullptr;
	for (int ii = 0; ii < N; ii++) {
		square* sq = new square();
		v[s[ii]].push_back(sq);

		if (prev != nullptr) {
			prev->R = sq;
			sq->L = prev;
		}
		prev = sq;
	}

	// 呪文ループ
	for (int ii = 0; ii < Q; ii++) {
		char t, d;
		cin >> t >> d;

		// 左へ移動であれば左の鱒から順に移動
		if (d == 'L') {
			for (int jj = 0; jj < v[t].size(); jj++) {
				if (v[t][jj]->L != nullptr) v[t][jj]->L->cnt += v[t][jj]->cnt;
				v[t][jj]->cnt = 0;
			}
		}
		// 右へ移動であれば右から順に移動
		else {
			for (int jj = v[t].size() - 1; jj >= 0; jj--) {
				if (v[t][jj]->R != nullptr) v[t][jj]->R->cnt += v[t][jj]->cnt;
				v[t][jj]->cnt = 0;
			}
		}
	}

	// 生き残りゴーレム和
	int total = 0;
	for (int ii = 0x41; ii < 0x5A; ii++) {
		for (auto square : v[ii]) {
			total += square->cnt;
		}
	}

	cout << total << endl;

	return 0;
}

