      if (query[i].c == target_c && query[i].d == 'L') {
        // Nothing
      } else if (query[i].c == target_c && query[i].d == 'R') {
        distinguished[target_i] = true;
        target_i--;
      }
    } else {
      if (query[i].c == target_c && query[i].d == 'R') {
        distinguished[target_i] = true;
        target_i--;
      } else if ((query[i].c == s[target_i + 1] && query[i].d == 'L')) {
        break;
      }
    }
  }

