bool can_remain(int now, const string &S, const vector<pair<char, int>> &ope) {
    int N = S.size();

    FOE(p, ope) {
        if (p.first == S[now]) {
            now += p.second;
        }

        if (now < 0 or now >= N) {
            return false;
        }
    }

    return true;
}

// 開区間(low, high)で条件を満たす一番左
int binary_search_left(long long low, long long high, const string &S, const vector<pair<char, int>> &ope) {
    // (low, high)
    while (high - low > 1) {
        long long middle = (low + high) / 2;
        if (can_remain(middle, S, ope)) {
            high = middle;
        }
        else {
            low = middle;
        }
    }

    return high;
}

// 開区間(low, high)で条件を満たす一番右
int binary_search_right(long long low, long long high, const string &S, const vector<pair<char, int>> &ope) {
    // (low, high)
    while (high - low > 1) {
        long long middle = (low + high) / 2;
        if (can_remain(middle, S, ope)) {
            low = middle;
        }
        else {
            high = middle;
        }
    }

    return low;
}

// 開区間(low, high)で条件を満たすindex
// なければ-1
int find(long long low, long long high, const string &S, const vector<pair<char, int>> &ope) {
    auto l = binary_search_left(low, high, S, ope);
    if (l != S.size()) {
        return l;
    }
    auto r = binary_search_left(low, high, S, ope);
    if (r != -1) {
        return r;
    }

    return -1;
}


