void solve0(){
  int64_t N, Q;
  scanf("%lld%lld", &N, &Q);
  vector<char> s(N);
  vector<pair<char, char>> td(Q);
  getc(stdin);
  for (int i = 0; i < N; i++)
  {
    s[i] = getc(stdin);
  }
  getc(stdin);
  for (int i = 0; i < Q; i++)
  {
    char t, d;
    scanf("%c %c\n", &t, &d);
    td[i] = make_pair(t, d);
    // print(t,d);
  }

  int L = 0;
  int R = N - 1;
  for (int i = Q - 1; i >= 0; i--)
  {
    char t = td[i].first;
    char d = td[i].second;
    if (L<N && d == 'L') L = L + (t == s[L]);
    else if (L<N && L > 0) L = L - (t == s[L - 1]);

    if (R>=0 && d == 'R') R = R - (t == s[R]);
    else if (R>=0 && R < N - 1) R = R + (t == s[R + 1]);
  }

  cout << (L <= R ? R - L + 1 : 0) << endl;
}

