bool check(string &s, int Q, int N, int pos, vector<char> &t, vector<char> &d, bool left_check)
{
  char c = s[pos];
  rep(i, Q){
    if(t[i] == c){
      pos += d[i] == 'L' ? -1 : 1;
      if(pos < 0) return left_check ^ true;
      if(pos >= N) return left_check ^ false;
      c = s[pos];
    }
  }
  return true;
}

int main()
{
  int N, Q;
  string s;
  cin >> N >> Q;
  cin >> s;
  vector<char> t(Q);
  vector<char> d(Q);
  rep(i, Q){
    cin >> t[i] >> d[i];
  }
  int ans = N;
  {
    int ok = N;
    int ng = -1;
    while(ok - ng > 1){
      int mid = (ok + ng) / 2;
      (check(s, Q, N, mid, t, d, true) ? ok : ng) = mid;
    }
    ans -= ng + 1;
  }
  {
    int ok = -1;
    int ng = N;
    while(ng - ok > 1){
      int mid = (ok + ng) / 2;
      (check(s, Q, N, mid, t, d, false) ? ok : ng) = mid;
    }
    ans -= N - ng;
  }
  cout << ans << endl;
  return 0;
}

