                    } else {
                        G[j-1] += G[j];
                    }
                    G[j] = 0;
                } else {
                    if(j == N - 1) {
                        Gcounter -= G[j];
                    } else {
                        G[j+1] += G[j];
                    }
                    G[j] = 0;
                }
            }
        }
