{
	int n, q; cin >> n >> q;
	string s; cin >> s;
	vector<char> t(q), d(q); rep(i, q) cin >> t[i] >> d[i];

	int left = solve_left(s, n, q, t, d);
	int right = solve_right(s, n, q, t, d);
	// printf("%d %d\n", left, right);

	int del = (left + 1) + (n - right);
	printf("%d\n", max(0, n - del));
	return 0;
}

