bool isOK_r(int index) {
  int pos = index;
  for (int i = 0; i < q; i++) {
    if (s[pos] == query[i].c) {
      if (query[i].d == 'L') {
        pos--;
      } else {
        pos++;
      }
    }
    if (pos == n)
      return true;
    else if (pos == -1)
      return false;
  }
  return false;
}
bool isOK_l(int index) {
  int pos = index;
  for (int i = 0; i < q; i++) {
    if (s[pos] == query[i].c) {
      if (query[i].d == 'L') {
        pos--;
      } else {
        pos++;
      }
    }
    if (pos == -1)
      return true;
    else if (pos == n)
      return false;
  }
  return false;
}

int binary_search_r(void) {
  int left  = -1;
  int right = n;
  while (right - left > 1) {
    int mid = left + (right - left) / 2;
    if (isOK_r(mid))
      right = mid;
    else
      left = mid;
  }

  return right;
}
int binary_search_l(void) {
  int left  = -1;
  int right = n;
  while (right - left > 1) {
    int mid = left + (right - left) / 2;
    if (!isOK_l(mid))
      right = mid;
    else
      left = mid;
  }

  return right;
}

