    else if (tmp == 'R')order[i] = +1;
    else assert(0);
  }
  int goneLeft = solve(n, in, pos, order, true);
  int goneRight = solve(n, in, pos, order ,false);
  cout << n - goneLeft - goneRight << endl;

  return 0;
}

