// 汎用的な二分探索のテンプレ
int binary_search1() {
    int ng = -1; //「index = 0」が条件を満たすこともあるので、初期値は -1
    int ok = n; // 「index = a.size()-1」が条件を満たさないこともあるので、初期値は a.size()

    /* ok と ng のどちらが大きいかわからないことを考慮 */
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;

        if (isOKleft(mid)) ok = mid;
        else ng = mid;
    }
    return ok;
}
int binary_search2() {
    int ng = -1; //「index = 0」が条件を満たすこともあるので、初期値は -1
    int ok = n; // 「index = a.size()-1」が条件を満たさないこともあるので、初期値は a.size()

    /* ok と ng のどちらが大きいかわからないことを考慮 */
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;

        if (isOKright(mid)) ok = mid;
        else ng = mid;
    }
    return ng;
}

