#define SIZE 200010

int n;
int si[SIZE];
pair<int, int> query[SIZE];

bool check(int now, int d2){

  for(auto v : query){
    int t = v.first;
    int d = v.second;

    if (si[now] == t) {
      if(d == 0) now++;
      else now--;
    }

    if(now == n) return d2 == 0;
    if(now == -1) return d2 == 1;
  }

  return false;
}

int main(){
