  }

  int L = -1, R = n;

  int l = -1, r = n;

  while(l < r){
    int mid = (l + r + 1 + 2) / 2 - 1;

    if(check(mid, 1))
      l = mid;
    else
      r = mid - 1;
  }

  L = l;


  l = -1, r = n;

  while(l < r){
    int mid = (l + r + 2) / 2 - 1;

    if(check(mid, 0))
      r = mid;
    else
      l = mid + 1;
  }

