  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll N, Q;
  IN(N,Q);
  string str;
  IN(str);
  vector<char> t(Q), d(Q);
  REP(i,Q) IN(t[i], d[i]);

  ll left_pos = -1;
  ll left_max = -1;
  ll right_pos = N;
  ll right_min = N;

  RREP(i,Q-1){
    if(left_pos+1 < N){
      if(t[i]==str[left_pos+1] && d[i]=='L'){
        left_pos += 1;
      }
    }
    if(left_pos-1>=0){
      if(t[i]==str[left_pos-1] && d[i]=='R'){
        left_pos -= 1;
      }
    }
    if(right_pos+1 < N){
      if(t[i]==str[right_pos+1] && d[i]=='L'){
