      }
    }
    if(right_pos-1>=0){
      if(t[i]==str[right_pos-1] && d[i]=='R'){
        right_pos -= 1;
      }
    }
    left_max = max(left_max, left_pos);
    right_min = min(right_min, right_pos);
  }

