int calc(char*s, vpii&td, int p)
{
	for(auto mtd:td)
	{
		if(mtd.first==s[p])
		{
			p+=mtd.second;

			if(s[p]=='\0') return 1-2*(p<0);
		}
	}
	return 0;
}


int bs(char*s, vpii&td, int n)
{
	int a=0, b=n-1;
	int ret=-1;

	while(a<=b)
	{
		int c=(a+b)/2;
		int r=calc(s, td, c);

		if(r<0)
		{
			a=c+1;
			ret=c;
		}
		else
		{
			b=c-1;
		}
	}
	return ret;
}


int bs2(char*s, vpii&td, int n)
{
	int a=0, b=n-1;
	int ret=n;

	while(a<=b)
	{
		int c=(a+b)/2;
		int r=calc(s, td, c);

		if(r>0)
		{
			b=c-1;
			ret=c;
		}
		else
		{
			a=c+1;
		}
	}
	return ret;
}


