		s[-1]=s[n]='\0';

		for(int i=0;i<q;i++)
		{
			char t[1+2], d[1+2];
			scanf("%1s%1s", t, d);

			td[i]=make_pair((int)t[0], (d[0]=='R')?1:-1);
		}

		int ans=n-min(bs(s, td, n)+1+n-bs2(s, td, n), n);
		printf("%d\n", ans);
	}
	return 0;
}

