vector< Op > ops;

bool check(int pos, char d, int step) {
  if(pos == 0) {
    return d == 'L';
  }
  if(pos == n+1) {
    return d == 'R';
  }
  if(step == q) {
    return false;
  }

  if(s[pos-1] != ops[step].first) {
    return check(pos, d, step+1);
  } else {
    if(ops[step].second == 'L') {
      return check(pos-1, d, step+1);
    } else {
      return check(pos+1, d, step+1);
    }
  }
}

int main(void) {
