  }

  int resl,resr;
  int ok,ng;

  ok = 0,ng = n+1;
  while((int)abs(ok - ng) > 1) {
    int md = (ok + ng)/2;
    if(check(md,'L',0)) {
      ok = md;
    } else {
      ng = md;
    }
  }
  resl = ok;
  //cout << resl << endl;

  ok = n+1,ng = 0;
  while((int)abs(ok - ng) > 1) {
    int md = (ok + ng)/2;
