  ll lt = 0, rt = N + 1;
  mark[lt] = true;
  mark[rt] = true;
  vector<p> R;

  for (ll i = 0; i < Q; i++) {
    char t, d;
    cin >> t >> d;
    if (d == 'L') {
      R.push_back(p(t, 'R'));
    } else {
      R.push_back(p(t, 'L'));
    }
