        rt--;
      }
    } else {
      if (S[lt] == t) {
        lt++;
      }
      if (rt < N && S[rt] == t) {
        rt++;
      }
    }
    mark[lt] = true;
    mark[rt] = true;
  }

  ll ans = N + 2;
  for (auto m : mark) {
