int func(string &s, vector<pair<char, char> > &vp, int pos)
{
  int N = s.size();
  int Q = vp.size();
  for (int i = 0; i < Q; ++i) {
    char t = vp[i].first;
    char d = vp[i].second;
    if (s[pos] == t) {
      if (d == 'L') --pos;
      else ++pos;
      if (pos < 0) return -1;
      if (pos >= N) return N;
    }
  }
  return pos;
}

int myfind(string &s, vector<pair<char, char> > &vp, int num)
{
  int N = s.size();
  int L = -1;
  int R = N;
  while (R - L > 1) {
    int M = (L + R) / 2;
    if (func(s, vp, M) < num) {
      L = M;
    }
    else {
      R = M;
    }
  }
  return R;
}

