#include <cassert>
#include <iostream>
#include <vector>

int checkDrop(int j, const std::string &arrayChar,
              const std::vector<char> &queryChar,
              const std::vector<char> &queryDirection) {
  const int numArray = arrayChar.length() - 1;
  const int numQuery = queryChar.size() - 1;
  assert(numQuery == static_cast<int>(queryDirection.size()) - 1);
  assert(1 <= j and j <= numArray);
  // move j by queries
  for (int i = 1; i <= numQuery; ++i) {
    // query hit
    if (queryChar[i] == arrayChar[j]) {
      switch (queryDirection[i]) {
      case 'L': // move left
        if (j == 1)
          return -1;
        --j;
        break;
      case 'R': // move right
        if (j == numArray)
          return +1;
        ++j;
        break;
      default:
        assert(false);
      }
    }
  }
  return 0;
}

int main() {
  // Input
  int numArray; // index: j
  int numQuery; // index: i
  std::cin >> numArray >> numQuery;
  assert(1 <= numArray and numArray <= 2 * 1.0e+5);
  assert(1 <= numQuery and numQuery <= 2 * 1.0e+5);
  std::string arrayChar;
  std::cin >> arrayChar;
  arrayChar.insert(arrayChar.begin(), '-');
  assert(static_cast<int>(arrayChar.length()) == 1 + numArray);
  std::vector<char> queryChar(1 + numQuery);
  std::vector<char> queryDirection(1 + numQuery);
  for (int i = 1; i <= numQuery; ++i) {
    std::cin >> queryChar[i] >> queryDirection[i];
    assert(queryDirection[i] == 'L' or queryDirection[i] == 'R');
  }

  // Check left drop
  int lDrop = 0;
  int lNotDrop = numArray + 1;
  int lDropMax = lDrop + (lNotDrop - lDrop) / 2;
  while (lDrop < lDropMax) {
    assert(lDropMax < lNotDrop);
    int m = checkDrop(lDropMax, arrayChar, queryChar, queryDirection);
    // left drop
    if (m == -1)
      lDrop = lDropMax;
    // left not drop
    else
      lNotDrop = lDropMax;
    lDropMax = lDrop + (lNotDrop - lDrop) / 2;
  }
  assert(lDrop == lDropMax);

  // Check right drop
  int rDrop = numArray + 1;
  int rNotDrop = 0;
  int rDropMin = rNotDrop + (rDrop - rNotDrop) / 2 + 1;
  while (rDropMin < rDrop) {
    assert(rNotDrop < rDropMin);
    int m = checkDrop(rDropMin, arrayChar, queryChar, queryDirection);
    // right drop
    if (m == +1)
      rDrop = rDropMin;
    // rght not drop
    else
      rNotDrop = rDropMin;
    rDropMin = rNotDrop + (rDrop - rNotDrop) / 2 + 1;
  }
  assert(rDrop == rDropMin);

  // std::cout << "lDropMax = " << lDropMax << std::endl;
  // std::cout << "rDropMin = " << rDropMin << std::endl;
  std::cout << rDropMin - lDropMax -1 << std::endl;

  return 0;
}

