bool checkL(ll n)
{
    REP(i, Q)
    {
        if (C[i].first == S[n])
        {
            if (C[i].second == 'L')
                n--;
            else
                n = std::min(n + 1, N - 1);
            if (n < 0)
                return true;
        }
    }
    return false;
}
bool checkR(ll n)
{
    REP(i, Q)
    {
        if (C[i].first == S[n])
        {
            if (C[i].second == 'L')
                n = std::max(0LL, n - 1);
            else
                n++;
            if (n > N - 1)
                return true;
        }
    }
    return false;
}

