    ll left = 0;
    {
        //! 左に落ちる最大値
        ll ok = 0, ng = N;
        while (abs(ok - ng) > 1)
        {
            ll mid = (ok + ng) / 2;
            if (checkL(mid))
                ok = mid;
            else
                ng = mid;
        }
        if (ok == 0 && !checkL(0))
            ok = -1;
        left = ok + 1;
    }
    ll right = 0;
    {
        //! 左に落ちる最大値
        ll ok = N - 1, ng = -1;
        while (abs(ok - ng) > 1)
        {
            ll mid = (ok + ng) / 2;
            if (checkR(mid))
                ok = mid;
            else
                ng = mid;
        }
        if (ok == N - 1 && !checkR(N - 1))
            ok = N;
        right = N - ok;
    }
    cout << N - std::min(N, left + right) << endl;
    return 0;
}

