using namespace std;

int N, Q;
string s;
vector<char> t, d;

const int downL = 0;
const int downR = INT_MAX;

int calc(int index)
{
	for (int i = 0; i < Q; i++) {
		if (s[index] != t[i])
			continue;

		if (d[i] == 'L')
			index--;
		else
			index++;

		if (index < 0)
			return downL;
		else if (index >= N)
			return downR;
	}

	return index + 1;
}

int main(void)
{
	cin >> N >> Q;

	cin >> s;

	t = vector<char>(Q);
	d = vector<char>(Q);
	for (int i = 0; i < Q; i++)
		cin >> t[i] >> d[i];

	int vL = calc(0);
	int vR = calc(N - 1);
	if (vL > N || vR < 1) {
		cout << 0 << endl;

		return 0;
	}

	int left = 0;
	if (vL == downL) {
		int l = 0;
		int r = N - 1;
		// left
		while (r - l > 1) {
			int mid = (l + r) / 2;
			int v = calc(mid);
			if (v == downL)
				l = mid;
			else
				r = mid;
		}

		left = r;
	}

	int right = N - 1;
	if (vR == downR) {
		int l = 0;
		int r = N - 1;
		// right
		while (r - l > 1) {
			int mid = (l + r) / 2;
			int v = calc(mid);
			if (v == downR)
				r = mid;
			else
				l = mid;
		}

		right = l;
	}

	cout << right - left + 1 << endl;

	return 0;
}

