// the final position of golem whose initiali position is i
int sim(int i, string S, int N, int Q, int* dist, char td_list[][2]) {
    int idx = i;
    for (int j = 0; j < Q; ++j) {
        if (dist[i] != -2) return dist[i];
        if (idx == -1 || idx == N) {
            dist[i] = idx;
            return dist[i];
        }
        if (td_list[j][0] == S[idx]) {
            if (td_list[j][1] == 'L') idx--;
            else idx++;
        }
    }
    dist[i] = idx;
    return dist[i];
}

