char Move(int position, int n, int q, string s, vector<char> &t, vector<char> &d)
{
	for (int i = 0; i < q; ++i) {
		if (s[position] == t[i]) {
			if (d[i] == 'L') {
				position--;
			}
			else {
				position++;
			}
		}
		if (0 > position) {
			return 'L';
		}
		if (n <= position) {
			return 'R';
		}
	}
	return ' ';
}

