			}
		}
		else {
			loop(j, 0, letters[index].size()) {
				int value = buffer[letters[index][j]];
				squares[letters[index][j]] -= value;
				if (letters[index][j] + 1 >= squares.size()) {
					N -= value;
				}
				else {
					squares[letters[index][j] + 1] += value;
				}
			}
		}
		buffer = squares;
	}

	dbl(N);

	wait();
}

