char _buf[200000 + 3];

void read_cr() {
    fgets(_buf, 256, stdin);
}

int solve(int N, int Q, string &s, vi&t, vi&q) {
    reverse(ALL(t));
    reverse(ALL(q));
    int x, rightmost=-1, leftmost=N, depth=-1;
    {
        queue<ii> qu;
        qu.emplace(-1,0);
        set<ii> visited;

        while (!qu.empty()) {
            if (found(visited, qu.front())) {
                qu.pop();
                continue;
            }
            ii p = qu.front(); qu.pop();
            visited.insert(p);
            x=p.first, depth=p.second;
            for (int i=depth; i<Q; ++i) {
                if (x >= N-1) {
                    goto good;
                }
                bool rem = true;
                if (IN(x,0,N-1) && s[x] == t[i]) {
                    rem = false;
                }
                if (IN(x+1,0,N-1) && s[x+1] == t[i] && q[i] == 'L') {
                    if (rem) {
                        qu.emplace(x,i+1);
                    }
                    x++;
                    rightmost=max(rightmost,x);
                }
                if (IN(x-1,0,N-1) && s[x-1] == t[i] && q[i] == 'R') {
                    if (rem) {
                        qu.emplace(x-1,i+1);
                    }
                }
                if (!rem) {
                    depth = -1;
                    break;
                }
            }
        }
        good:;
    }
    {
        queue<ii> qu;
        qu.emplace(N,0);
        set<ii> visited;

        while (!qu.empty()) {
            if (found(visited, qu.front())) {
                qu.pop();
                continue;
            }
            ii p = qu.front(); qu.pop();
            visited.insert(p);
            x=p.first, depth=p.second;
            for (int i=depth; i<Q; ++i) {
                if (x <= 0) {
                    goto good2;
                }
                bool rem = true;
                if (IN(x,0,N-1) && s[x] == t[i]) {
                    rem = false;
                }
                if (IN(x+1,0,N-1) && s[x+1] == t[i] && q[i] == 'L') {
                    if (rem) {
                        qu.emplace(x+1,i+1);
                    }
                }
                if (IN(x-1,0,N-1) && s[x-1] == t[i] && q[i] == 'R') {
                    if (rem) {
                        qu.emplace(x,i+1);
                    }
                    x--;
                    leftmost=min(leftmost,x);
                }
                if (!rem) {
                    depth = -1;
                    break;
                }
            }
        }
        good2:;
    }
    return leftmost - rightmost - 1;
}

