ll is_alive(ll x, ll N, str s,str &t, str &d) {
    REP(i, N) {
        if(s[x] == t[i]) {
            if(d[i] == 'L') x--;
            if(d[i] == 'R') x++;
        }
        if(x==-1) return -1;
        if(x==N) return 1;
    }
    return 0;
}

