        T[f] = a;
        D[f] = b;
    }
    ll lb = 0, ub = N;
    while(ub - lb > 1) {
        ll md = (lb + ub) / 2;
        if(is_alive(md, N, s, T, D)==-1) {
            lb = md;
        }else {
            ub = md;
        }
    }
    ll ans1 = ub;
    lb = 0, ub = N;
    while(ub - lb > 1) {
        ll md = (lb + ub) / 2;
        if(is_alive(md, N, s, T, D)!=1) {
            lb = md;
        }else {
            ub = md;
        }
    }
    ll ans2 = ub;
    out(ans2 - ans1);
}

