}

int solveL() {
    int l = 0, r = N + 1;
    while(r - l > 1) {
        int m = (l + r) / 2;
        if(C(m) == -1) l = m;
        else r = m;
    }
    return l;
}

int solveR() {
    int l = 0, r = N + 1;
    while(r - l > 1) {
        int m = (l + r) / 2;
        if(C(m) == 1) r = m;
        else l = m;
    }
    return r;
}

