int main() {
    int n, q;
    cin >> n >> q;

    string s;
    cin >> s;

    vector<char> t(q), d(q);
    for (int i = 0; i < q; i++) {
        cin >> t[i] >> d[i];
    }

    auto f = [&](int i) {
        for (int j = 0; j < q; j++) {
            if (t[j] == s[i]) {
                if (d[j] == 'L') {
                    i--;

                    if (i < 0) {
                        return -1;
                    }
                } else {
                    i++;

                    if (i >= n) {
                        return 1;
                    }
                }
            }
        }

        return 0;
    };

    int ans = n;

    if (f(0) == -1) {
        int ok = 0;
        int ng = n;

        while(ng - ok > 1) {
            int m = (ok + ng) / 2;

            if (f(m) == -1) {
                ok = m;   
            } else {
                ng = m;
            }
        }

        ans -= ok + 1;
    }

    if (f(n - 1) == 1) {
        int ok = n - 1;
        int ng = -1;

        while(ok - ng > 1) {
            int m = (ok + ng) / 2;

            if (f(m) == 1) {
                ok = m;   
            } else {
                ng = m;
            }
        }

        ans -= n - ok;
    }

    cout << ans << endl;
}

