#define REP(i, n) for(int i = 0; i < (int)(n); ++i)


int n;
int nQuery;
char buf[200000+10];
char cs[200000+10];
char ds[200000+10];

int detect(int idx) {
  REP(i, nQuery) {
    if(cs[i] == buf[idx]) {
      idx += (ds[i] == 'L' ? -1 : 1);
    }
    if(idx == n) {
      return 1;
    }
    if(idx == -1) {
      return -1;
    }
  }
  return 0;
}

int calcI2(void) { // 右に消える最初のidx
  int left = -1;
  int right = n;
  while(left + 1 < right) {
    int md = (left + right) / 2;
    if(detect(md) == 1) {
      right = md;
    } else {
      left = md;
    }
  }
  return right;
}

int calcI1(void) { // 左に消えない最初のidx
  int left = -1;
  int right = n;
  while(left + 1 < right) {
    int md = (left + right) / 2;
    if(detect(md) == -1) {
      left = md;
    } else {
      right = md;
    }
  }
  return right;
}

int main(void) {
  scanf("%d%d %s", &n, &nQuery, buf);
  REP(i, nQuery) {
    scanf(" %c %c", &cs[i], &ds[i]);
  }
  int i2 = calcI2();
  int i1 = calcI1();
  int res = i2 - i1;
  cout << res << endl;


  return 0;
}

