bool probaj(int x, bool p){
	for(int i = 0 ; i < q ; ++i){
		if(s[x] == c[i]){
			if(d[i] == 'L'){
				x--;
			}
			else{
				x++;
			}
			if(x <= 0 && !p)
				return 1;
			if(x > n && p)
				return 1;
		}
	}
	return 0;
}

int main(){
