	cin >> c[i] >> d[i];
}
int l = 1, r = n;
while(l <= r){
	int mid = (l + r) / 2;
	if(!probaj(mid, 0)){
		r = mid - 1;
	}
	else{
		l = mid + 1;
	}
}
//cout << l << ' ' << r << endl;
int sol = r;
l = 1;
r = n;
while(l <= r){
	int mid = (l + r) / 2;
	if(!probaj(mid, 1)){
		l = mid + 1;
	}
	else{
		r = mid - 1;
	}
}
sol += (n + 1 - l);
sol = n - sol;
cout << sol << endl;

return 0;
