const int MAX = 2e5+10;

int N, Q;
string s;
int S[MAX];
int t[MAX], d[MAX];

bool alive(int n, bool left) {
    REP (q, Q) if (S[n] == t[q]) {
        n += d[q];
        if (n < 0) return !left;
        if (n >= N) return left;
    }
    return true;
}

int main() {
    cin >> N >> Q >> s;
    REP (i, N) S[i] = s[i] - 'A';
    REP (q, Q) {
        char tt, dd;
        cin >> tt >> dd;
        t[q] = tt - 'A'; d[q] = (dd == 'L') ? -1 : 1;
    }

    int l = -1, // 左で死ぬ
        r = N-1; // 左で死なない
    while (r - l > 1) {
        int m = (r+l) / 2;
        if (alive(m, true)) r = m;
        else l = m;
    }
    int left = l;

    l = 0, // 右で死なない
    r = N; // 右で死ぬ
    while (r - l > 1) {
        int m = (r+l) / 2;
        if (alive(m, false)) l = m;
        else r = m;
    }
    cout << r - left - 1 << endl;
}

