void solve(char *str, int n, char *t, char *d, int q) {
    int cnt1, cnt2, cur, j;
    cnt1 = 0;
    for(cnt1 = 0; cnt1 < n; ++cnt1) {
        cur = cnt1;
        for(j = 0; j < q; ++j) {
            if(str[cur] == t[j]) {
                if(d[j] == 'R') { ++cur; }
                else { --cur; }
                if(cur < 0) { break; }
            }
        }
        if(cur >= 0) { break; }
    }

    for(cnt2 = n-1; cnt2 > -1; --cnt2) {
        cur = cnt2;
        for(j = 0; j < q; ++j) {
            if(str[cur] == t[j]) {
                if(d[j] == 'R') { ++cur; }
                else { --cur; }
                if(cur > n-1) { break; }
            }
        }
        if(cur <= n-1) { break; }
    }
    printf("%d\n", cnt2 - cnt1 + 1);
}

