void makeIndex(char *s, int *index, int *pos)
{
    int count[26];
    int i;

    for (i = 0; i < 26; i++) {
        count[i] = 0;
    }

    for (i = 0; s[i] != '\0'; i++) {
        count[s[i] - 'A']++;
    }

    index[0] = 0;
    for (i = 0; i < 26; i++) {
        index[i + 1] = index[i] + count[i];
    }

    for (i = 0; i < 26; i++) {
        count[i] = 0;
    }

    for (i = 0; s[i] != '\0'; i++) {
        int c = s[i] - 'A';
        int dest = index[c] + count[c];
        pos[dest] = i;
        count[c]++;
    }
}

