        const int c = t - 'A';
        const int jmin = index[c];
        const int jmax = index[c + 1];
        if (d == 'L') { // to left
            for (j = jmin; j < jmax; j++) {
                const int p = pos[j];
                g[p - 1] += g[p];
                g[p] = 0;
            }
        } else { // to right
            for(j = jmax - 1; j >= jmin; j--) {
                const int p = pos[j];
                g[p + 1] += g[p];
                g[p] = 0;
            }
        }
    }

    ans = n - golems[0] - golems[n + 1];

    printf("%d\n", ans);

    return 0;
}

