ll simulate(ll position)
{
	ll i = 0;
	while (i < q && position >= 1 && position <= n) {
		if (query[i].t == grid[position]) {
			if (query[i].d == 'L') {
				position--;
			}
			else if (query[i].d == 'R') {
				position++;
			}
		}

		i++;
	}

	if (position > n) {
		position = n + 1;
	}
	else if (position < 1) {
		position = 0;
	}

	return position;
}

ll bin_search(char mode)
{
	ll valid, invalid;
	ll mid;

	valid = (mode == 'L' ? 0 : n + 1);
	invalid = (mode == 'L' ? n + 1: 0);

	while (llabs(invalid - valid) > 1) {
		mid = (invalid + valid) / 2;

		if (simulate(mid) == (mode == 'L' ? 0 : n + 1)) {
			valid = mid;
		}
		else {
			invalid = mid;
		}
	}

	return valid;
}

