#define ABS(a) ((a) > (0) ? (a) : -(a))

i32 calc (i32 k,char *s, i32 n, char *t, char *d, i32 q) {
  for (i32 i = 0; i < q && 0 <= k && k < n; ++i) {
    if (s[k] == t[i]) {
      k += (d[i] == 'L' ? -1 : 1);
    }
  }
  return k;
}

void run (void) {
  i32 n, q;
  scanf ("%" SCNi32 "%" SCNi32, &n, &q);
  char *s = (char *) calloc (n + 1, sizeof (char));
  scanf ("%s", s);
  char *t = (char *) calloc (q + 1, sizeof (char));
  char *d = (char *) calloc (q + 1, sizeof (char));
  for (i32 i = 0; i < q; ++i) {
    scanf ("%s%s", t + i, d + i);
  }
  if (calc (n - 1, s, n, t, d, q) < 0 || calc (0, s, n, t, d, q) >= n) {
    puts("0");
    return;
  }
  i32 ans = n;
  i32 l = -1;
  i32 r = n - 1;
  while (r - l > 1) {
    i32 m = (l + r) / 2;
    if (calc (m, s, n, t, d, q) < 0) {
      l = m;
    } else {
      r = m;
    }
  }
  ans -= l + 1;
  l = 0;
  r = n;
  while (r - l > 1) {
    i32 m = (l + r) / 2;
    if (calc (m, s, n, t, d, q) >= n) {
      r = m;
    } else {
      l = m;
    }
  }
  ans -= n - r;
  printf ("%" PRIi32 "\n", ans);
}

int main (void) {
  run ();
  return 0;
}

