ll bin_search(char mode)
{
	ll valid, invalid;
	ll mid;

	if (mode == 'L') {
		invalid = n + 2;
		valid = 0;

		while (invalid - valid > 1) {
			mid = (invalid + valid) / 2;

			if (simulate(mid) < 1) {
				valid = mid;
			}
			else {
				invalid = mid;
			}
		}
	}
	else if (mode == 'R') {
		invalid = -1;
		valid = n + 1;

		while (valid - invalid > 1) {
			mid = (invalid + valid) / 2;

			if (simulate(mid) > n) {
				valid = mid;
			}
			else {
				invalid = mid;
			}
		}
	}

	return valid;
}

