//入力したマスbが、-1にたどり着くなら-1, nにたどり着くなら1を返す
int simulate(char *s, char *t, char *d, int n, int q, int b){
    int i;
    for(i = 0; i < q; ++i) {
        if(s[b] == t[i]) {
            b += ((d[i] == 'R') ? 1 : -1);
            if(b < 0)   { return -1; }
            if(b > n-1) { return  1; }
        }
    }
    return 0;
}

int main()
{
    int n, q, i, a, b, b_prev, c, l, r;
    char s[200000], t[200000], d[200000];
    scanf("%d %d", &n, &q);
    scanf("%s", s);
    for(i = 0; i < q; ++i) {
        scanf("\n %c %c", &t[i], &d[i]);
    }

    //二部探索
    //aには「-1にたどり着くマスの中で最も右にあるもの」が最終的に入る
    a = 0; b_prev = -1; c = n-1;
    while(1) {
        b = (a + c + 1)/2;
        //printf("a:%d b:%d c:%d\n", a, b, c);
        if(b == b_prev) { break; }
        if(simulate(s, t, d, n, q, b) < 0) { a = b; }
        else { c = b; }
        b_prev = b;
        //printf("a:%d c:%d\n", a, c);
    }
    l = a;
    //printf("\n");

    //二部探索
    //aには「nにたどり着かないマスの中で最も右にあるもの」が最終的に入る
    a = 0; b_prev = -1; c = n-1;
    while(1) {
        b = (a + c + 1)/2;
        //printf("a:%d b:%d c:%d\n", a, b, c);
        if(b == b_prev) { break; }
        if(simulate(s, t, d,n, q, b) > 0) { c = b; }
        else { a = b; }
        b_prev = b;
        //printf("a:%d c:%d\n", a, c);
    }
    r = a;
    //printf("\n");
    //printf("r: %d l: %d\n", r, l);
    printf("%d\n", r - l);
    return 0;
}

