	char d[2];
} magic;

//check life
int life(int N,int Q,char ss[],magic x[],int point){
	int i;
	for(i=0;i<Q;i++){
		if(ss[point]!=x[i].t[0]){
			continue;
		}
		if(x[i].d[0]=='L'){
			point--;
			if(point<0){
				return 0;
			}
		}else{
			point++;
			if(point==N){
				return N;
			}
		}
	}
	return -1;
}

