int can_stay(int start) {
    for (int i = 0; i < Q; i++) {
        if (s[start - 1] == t[i]) {
            if (d[i] == 'L') {
                start--;
                if (start == 0) return -1;
            }
            else if (d[i] == 'R') {
                start++;
                if (start == N + 1) {
                    return 1;
                }
            }
        }
    }
    return 0;
}

int main() {
    scanf("%d %d\n", &N, &Q);
    scanf("%s\n", s);
    for (int i = 0; i < Q; i++) {
        char t_, d_;
        scanf("%c %c\n", &t_, &d_);
        t[i] = t_;
        d[i] = d_;
    }

    int max_left = 0;
    int min_right = N + 1;
    int stay_max = -1;
    int stay_min = -1;

    while (max_left + 1 < min_right) {
        int start = (max_left + min_right) / 2;
        int state = can_stay(start);
        if (state == 0) {
            stay_max = start;
            stay_min = start;
            break;
        }
        if (state == -1) {
            max_left = start;
        } else {
            min_right = start;
        }
    }
    if (stay_max == -1) {
        printf("0\n");
    } else {
        while (max_left + 1 < stay_min) {
            int start = (max_left + stay_min) / 2;
            int state = can_stay(start);
            if (state == -1) {
                max_left = start;
            } else if (state == 0) {
                stay_min = start;
            } else {
                printf("DIE!");
                exit(1);
            }
        }
        while (stay_max + 1 < min_right) {
            int start = (stay_max + min_right) / 2;
            int state = can_stay(start);
            if (state == 1) {
                min_right = start;
            } else if (state == 0) {
                stay_max = start;
            } else {
                printf("DIE!");
                exit(1);
            }
        }
        printf("%d\n", N - max_left - (N + 1 - min_right));
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

//curにある場所のゴーレムの最終地点を返す
int check(char *str, int n, char *t, char *d, int q, int cur) {
    int i;
    if(cur == -1 || cur == n) { return cur; }
    for(i = 0; i < q; ++i) {
        if(t[i] == str[cur]) {
            if(d[i] == 'R') { ++cur; }
            else { --cur; }
            if(cur == -1 || cur == n) { break; }
        }
    }
    return cur;
}

void solve(char *str, int n, char *t, char *d, int q) {
    int cur1, cur2, cur;
    cur1 = cur2 = n/2;
    while((cur = check(str, n, t, d, q, cur1)) > -1) {
        //printf("cur1: %d cur: %d\n", cur1, cur);
        if(cur1 <= cur) { --cur1; }
        else { cur1 = --cur; }
    }
    //printf("\n");
    while((cur = check(str, n, t, d, q, cur2)) < n) {
        //printf("cur2: %d cur: %d\n", cur2, cur);
        if(cur <= cur2) { ++cur2; }
        else { cur2 = ++cur; }
    }
    //printf("cur2: %d cur1: %d\n", cur2, cur1);
    printf("%d\n", cur2-cur1-1);
}

int main(void)
{
    int n, q, i;
    scanf("%d %d", &n, &q);
    char *str = (char*)malloc((n+4)*sizeof(char));
    char *t = (char*)malloc((q+4)*sizeof(char));
    char *d = (char*)malloc((q+4)*sizeof(char));
    scanf("%s", str);
    fgetc(stdin);
    for(i = 0; i < q; ++i) {
        scanf("%c %c", &t[i], &d[i]);
        fgetc(stdin);
    }
    solve(str, n, t, d, q);
    return 0;
}

