#include <stdio.h>
#include <stdlib.h>

typedef enum { left, right } bool;


int trace(int N, int Q, char *s, char *s_t, bool *b_d, int origin, int dest, int l, int r)
{
    static int i;
    static int static_origin = -1000;
    static int index;


    index = origin;


    if(l > r)
    {
        if(static_origin == -1000)
        {
            if(dest == N)
                return N;
            else
                return -1;
        }
        else
        {
            return static_origin;
        }
    }
    else
    {
        for(i=0; i<Q && index >= 0 && index < N; i++)
        {
            if(s_t[i] == s[index])
            {
                if(b_d[i] == left)
                {
                    index--;
                }
                else
                {
                    index++;
                }
            }
        }

        if(index == dest)
        {
            static_origin = origin;
        }

        if((dest == N && index < N) || (dest == -1 && index < 0))
        {
            return trace(N, Q, s, s_t, b_d, origin+(r-origin+1)/2, dest, origin+1, r);
        }
        else
        {
            return trace(N, Q, s, s_t, b_d, origin-(origin-l+1)/2, dest, l, origin-1);
        }
    }
}

int main(void)
{
    int N, Q;
    char *s, *s_t;
    bool *b_d;
    int i, j;
