    int sum;


    scanf("%d%c%d", &N, &c, &Q);

    s = (char*)malloc(sizeof(char)*(N+1));

    s_t = (char*)malloc(sizeof(char)*Q);
    b_d = (bool*)malloc(sizeof(bool)*Q);


    sum = N;


    scanf("%s\n", s);


    for(i=0; i<Q; i++)
    {
        scanf("%c%c%c%c", &t, &c, &d, &c);


        s_t[i] = t;

        if(d == 'L')
        {
            b_d[i] = left;
        }
        else
        {
            b_d[i] = right;
        }
    }


    sum -= N-trace(N, Q, s, s_t, b_d, N/2, N, 0, N-1);
    sum -= trace(N, Q, s, s_t, b_d, N/2, -1, 0, N-1)+1;


    printf("%d\n", sum);


    free(s);
    free(s_t);
    free(b_d);


    //system("pause");


