int GetGolemCount(int position, int turn, const int n, const char s[], const char t[], const char d[]);

int main()
{
	int i, j, n, q, cnt;

	scanf("%d %d", &n, &q);

	char s[n], t[q], d[q];
	int g[n];

	for(i = 0; i < n; i++)
		g[i] = 1;

	scanf("%s", s);

	cnt = n;
	for(i = 0; i < q; i++){
		scanf("%s %s", &t[i], &d[i]);
	}

	int tmp;
	for(i = 0; i < q; i++){
		if(d[i] == 'L' && t[i] == s[0]){
			tmp = GetGolemCount(0, i, n, s, t, d);
			cnt -= tmp;
		}
		if(d[i] == 'R' && t[i] == s[n - 1]){
			tmp = GetGolemCount(n - 1, i, n, s, t, d);
			cnt -= tmp;
		}
	}

	printf("%d", cnt);


	return 0;
}

int GetGolemCount(int position, int turn, const int n, const char s[], const char t[], const char d[]){

	if(turn <= 0){
		return 1;
	}else{
		// 1ターン前の自マス及び隣接マスのゴーレム数を参照して現在のマスのゴーレム数を求める

		int cnt = 0;

		// 自マス(移動なしの場合1ターン前のそのマスのゴーレム数、ありの場合0)
		if(s[position] != t[turn - 1])
			cnt += GetGolemCount(position, turn - 1, n, s, t, d);

		// 左マス(左端マス以外 : R移動の場合1ターン前のそのマスのゴーレム数、それ以外の場合0)
		if(position > 0){
			if(s[position - 1] == t[turn - 1] && d[turn - 1] == 'R')
				cnt += GetGolemCount(position - 1, turn - 1, n, s, t, d);
		}

		// 右マス(右端マス以外 : L移動の場合1ターン前のそのマスのゴーレム数、それ以外の場合0)
		if(position < n - 1){
			if(s[position + 1] == t[turn - 1] && d[turn - 1] == 'L')
				cnt += GetGolemCount(position + 1, turn - 1, n, s, t, d);
		}

		return cnt;
	}
}

