void solve(char *str, int n, char *t, char *d, int q) {
    int cnt1, cnt2, cur, j, max, min;
    cnt1 = 0;
    for(cnt1 = 0; cnt1 < n; ++cnt1) {
        cur = cnt1; max = cnt1;
        for(j = 0; j < q; ++j) {
            if(str[cur] == t[j]) {
                if(d[j] == 'R') {
                    ++cur;
                    if(max < cur) { max = cur; }
                }
                else { --cur; }
                if(cur < 0) { break; }
            }
        }
        if(cur >= 0) { break; }
        cnt1 = max;
    }

    for(cnt2 = n-1; cnt2 > -1; --cnt2) {
        cur = cnt2; min = cnt2;
        for(j = 0; j < q; ++j) {
            if(str[cur] == t[j]) {
                if(d[j] == 'R') { ++cur; }
                else {
                    --cur;
                    if(cur < min) { min = cur; }
                }
                if(cur > n-1) { break; }
            }
        }
        if(cur <= n-1) { break; }
        cnt2 = min;
    }
    printf("%d\n", cnt2 - cnt1 + 1);
}

