typedef long long ll;
typedef struct {
	char t, d;
} Query;

ll n, q;
char grid[200005];
Query query[200005];

//初期位置を引数に取り、最終的位置を返す。n + 1のとき右に落ち、0のとき左に落ちる
ll simulate(ll position);
ll bin_search(char mode);

//VSのscanf()使わせてくれないやつ嫌い！！
ll input(const char* format, ...);

int main()
{

	input("%lld %lld", &n, &q);
	input("%s", grid + 1);
	for (ll i = 0; i < q; i++) {
		input("%c %c", &query[i].t, &query[i].d);
	}

	//printf("%lld : %lld\n", bin_search('L'), bin_search('R'));
	printf("%lld\n", max(0, bin_search('R') - bin_search('L') - 1));

	return EXIT_SUCCESS;
}

ll simulate(ll position)
{
	ll i = 0;
	while (i < q && position >= 1 && position <= n) {
		if (query[i].t == grid[position]) {
			if (query[i].d == 'L') {
				position--;
			}
			else if (query[i].d == 'R') {
				position++;
			}
		}

		i++;
	}

	return position;
}

ll bin_search(char mode)
{
	ll valid, invalid;
	ll mid;

	if (mode == 'L') {
		invalid = n + 1;
		valid = 0;

		while (invalid - valid > 1) {
			mid = (invalid + valid) / 2;

			if (simulate(mid) < 1) {
				valid = mid;
			}
			else {
				invalid = mid;
			}
		}
	}
	else if (mode == 'R') {
		invalid = 0;
		valid = n + 1;

		while (valid - invalid > 1) {
			mid = (invalid + valid) / 2;

			if (simulate(mid) > n) {
				valid = mid;
			}
			else {
				invalid = mid;
			}
		}
	}

	return valid;
}

ll input(const char* format, ...)
{
	va_list args;
	char buff[BUFSIZ];
	ll ret_val;

	fgets(buff, sizeof(buff) - 1, stdin);

	va_start(args, format);
	ret_val = vsscanf(buff, format, args);
	va_end(args);

	return ret_val;
}

