#include <stdio.h>

#define MAX_N 200000

typedef struct {
  int index;
  int num;
} instance;

static instance area1[MAX_N];
static instance area2[MAX_N];

static int n;
static char s[MAX_N + 2];

static instance *current_area;
static instance *temp_area;
static int area_cnt;

static void init_area() {
  for (int i = 0; i < n; i++) {
    area1[i].index = i;
    area1[i].num = 1;
  }
  current_area = area1;
  area_cnt = n;
  temp_area = area2;
}

static void move_left(char t) {
  int j = -1;
  for (int i = 0; i < area_cnt; i++) {
    if (s[current_area[i].index] == t) {
      current_area[i].index--;
      if (current_area[i].index < 0) {
        continue;
      }
      if (j >= 0 && current_area[i].index == temp_area[j].index) {
        temp_area[j].num += current_area[i].num;
        continue;
      }
    }
    temp_area[++j] = current_area[i];
  }
  area_cnt = j + 1;
  instance *tmp = temp_area;
  temp_area = current_area;
  current_area = tmp;
}

static void move_right(char t) {
  int j = area_cnt;
  for (int i = area_cnt - 1; i >= 0; i--) {
    if (s[current_area[i].index] == t) {
      current_area[i].index++;
      if (current_area[i].index >= n) {
        continue;
      }
      if (j < area_cnt && current_area[i].index == temp_area[j].index) {
        temp_area[j].num += current_area[i].num;
        continue;
      }
    }
    temp_area[--j] = current_area[i];
  }
  area_cnt = area_cnt - j;
  instance *tmp = temp_area + j;
  temp_area = current_area;
  current_area = tmp;
}

static int get_answer() {
  int ans = 0;
  for (int i = 0; i < area_cnt; i++) {
    ans += current_area[i].num;
  }
  return ans;
}

int main() {
  int q;
  scanf("%d%d", &n, &q);
  scanf("%s", s);
  init_area();
  for (int i = 0; i < q; i++) {
    char t, d;
    scanf(" %c %c", &t, &d);
    if (d == 'L') {
      move_left(t);
    } else if (d == 'R') {
      move_right(t);
    } else {
      return 1;
    }
  }
  int ans = get_answer();
  printf("%d\n", ans);
}

#include <stdio.h>
//--------------------------------------------------------------
// checkMove
// 受け取った文字列と呪文の文字列と一致するものを探す。
// あった場合に、呪文の移動の判定を行う。
// 移動した先が一番端だった場合、
// 最も左ならば-1を、最も右ならば1を返す関数
// どちらでもなかった場合には0を返す
//--------------------------------------------------------------
int checkMove(char *s, char *t, char *d, int n, int q, int b) {
	int i;
	for (i = 0; i < q; ++i) {
		if (s[b] == t[i]) {                           
			b += ((d[i] == 'R') ? 1 : -1);
			if (b < 0) {
				return -1;
			}
			if (b > n - 1) {
				return 1;
			}
		}
	}
	return 0;
}

int main(void) {
	int n, q, i;
    int dummy;

	scanf("%d %d", &n, &q);
	char s[n];
	scanf("%s", s);
	char t[q], d[q];
	for (i = 0; i < q; ++i) {
		scanf("\n %c %c", &t[i], &d[i]);
	}
	int a = 0, b_prev = -1, c = n - 1;
	int b;
	while(1) { // 左に行けるものの中で最も離れているものを探す => それまでのものはすべて消すことができる
		b = (a + c ) / 2;	// 二分探索の中央を求める
		if (b == b_prev) {		// 前回の探索と中央値が同じなら終わり
			break;              
		}
		if (checkMove(s, t, d, n, q, b) < 0) {	// チェックして、行くことができるものがあるならaに、なければcに
            //bの位置にあったものが-1まで行った場合bより左に居たゴーレムはすべて死亡
			a = b;
		} else {
			c = b;
		}
		b_prev = b;
	}
	int left = a;
	a = 0;
	b_prev = -1;
	c = n - 1;
	while(1) { // 左の時と同様に最も右に行くことができるかどうかの判定
		b = (a + c + 1) / 2;
		if (b == b_prev) {
			break;
		}
		if (checkMove(s, t, d, n, q, b) > 0) {
			c = b;
		} else {
			a = b;                  
		}
		b_prev = b;
	}
	int right = c;
    if(left == 0){
		if (checkMove(s, t, d, n, q, 0) < 0) {
           	printf("%d\n", right - left - 1); // 右のものと左のものを引くと、残りが現れるので、それが残りのゴーレムの数
        } else {
            printf("%d\n", right - left ); // 右のものと左のものを引くと、残りが現れるので、それが残りのゴーレムの数
        }
    }else {
        printf("%d\n", right - left - 1); // 右のものと左のものを引くと、残りが現れるので、それが残りのゴーレムの数
    }




	return 0;
}

