int n, qq;

bool can_left(int x) {
  int cur = x;
  for (int i = 0; i < qq; i++) {
    if (t[i] == a[cur]) {
      if (dir[i] == 'L') {
        cur--;
      } else {
        cur++;
      }
      if (cur == -1) {
        return true;
      }
    }
  }
  return false;
}

bool can_right(int x) {
  int cur = x;
  for (int i = 0; i < qq; i++) {
    if (t[i] == a[cur]) {
      if (dir[i] == 'L') {
        cur--;
      } else {
        cur++;
      }
      if (cur == n) {
        return true;
      }
    }
  }
  return false;
}

