  scanf("%s", a);
  for (int i = 0; i < qq; i++) {
    scanf(" %c %c", &t[i], &dir[i]);
  }
  int lo = -1, hi = n;
  int ans = n;
  while (lo + 1 < hi) {
    int mid = (lo + hi) / 2;
    if (can_left(mid)) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  ans -= lo + 1;
  lo = -1;
  hi = n;
  while (lo + 1 < hi) {
    int mid = (lo + hi) / 2;
    if (can_right(mid)) {
      hi = mid;
    } else {
      lo = mid;
    }
  }
  ans -= n - hi;
  printf("%d\n", ans);
  return 0;
}

