#include <stdio.h>

int main(){
	int n,q;
	int i,j;
	scanf("%d %d",&n,&q);
	char s[200004];
		scanf("%s",&s);
	char t[200001],d[200001];
	for(i=0;i<q;i++){
		scanf("\n%c %c",&t[i],&d[i]);
	}
	int check(int k){
		/*
		マス目kにあるゴレが生存するかどうかを調べる
		左に消える場合は1を返す
		右に消える場合は2を返す		
		消えない場合は0を返す
		*/
		int cur = k;
		for(i=0;i<q;i++){
			if(t[i]==s[cur]){
				switch(d[i]){
				case'R':
					if(cur==(n-1)){
						return 2;
					}
					cur++;
					break;
				case'L':
					if(cur==0){
						return 1;
					}
					cur--;
					break;
				}
			}
		}
		return 0;
	}
	/*
	左に消えるゴーレムのマス目を二分探索で調べる
	*/

	int checkleft(){
		int low  = 0;
		int high = n-1;
		int mid;
		if(check(low)!=1){
			return -1;
		}
		if(check(high)==1){
			return high;
			//すべて左に消える
		}
		mid = (low+high)/2;
		while(mid>low){
			if(check(mid) ==1){
				low = mid;
				mid = (low+high)/2;
			}else{
				high = mid;
				mid = (low+high)/2;
			}
		}
		return mid;
	}


	int checkright(){
		int low  = 0;
		int high = n-1;
		int mid;
		if(check(low)==2){
			return low;
			//すべて右に消える
		}
		if(check(high)!=2){
			return n;
			//一つも右に消えない
		}
		mid = (low+high)/2;
		while(mid>low){
			if(check(mid) ==2){
				high = mid;
				mid = (low+high)/2;
			}else{
				low = mid;
				mid = (low+high)/2;
			}
		}
		return mid+1;
	}

	/*
	左からleftまで消滅
	右からrightまで消滅
	*/
	int left =checkleft();
	int right=checkright();
	int ans = n - (left+1) -(n- right);
	//printf("left  = %d\n",left);
	//printf("right = %d\n",right);
	printf("%d",ans);
	return 0;
}

