#include <stdio.h>
#include <stdlib.h>

typedef enum { left, right } bool;


int trace(int N, int Q, char *s, char *s_t, bool *b_d, int origin, int static_origin, int dest, int l, int r)
{
    static int i;
    static int index;


    if(l > r)
    {
        return static_origin;
    }
    else
    {
        index = origin;


        for(i=0; i<Q && index >= 0 && index < N; i++)
        {
            if(s_t[i] == s[index])
            {
                if(b_d[i] == left)
                {
                    index--;
                }
                else
                {
                    index++;
                }
            }
        }

        if(index == dest)
        {
            static_origin = origin;
        }

        if((dest == N && index < N) || (dest == -1 && index < 0))
        {
            return trace(N, Q, s, s_t, b_d, origin+(r-origin+1)/2, static_origin, dest, origin+1, r);
        }
        else
        {
            return trace(N, Q, s, s_t, b_d, l+(origin-l)/2, static_origin, dest, l, origin-1);
        }
    }
}

