        if(d == 'L')
        {
            b_d[i] = left;
        }
        else
        {
            b_d[i] = right;
        }
    }


    sum -= N-trace(N, Q, s, s_t, b_d, N/2, N, N, 0, N-1);
    sum -= trace(N, Q, s, s_t, b_d, N/2, -1, -1, 0, N-1)+1;

    printf("%d\n", sum);


