#define SIZE 27
#define ODR(ch) ((int)(ch - 'A'))

int sub(bool **list, int n, char t, char d) {
    int i, ans = 0;
    if(d == 'L') {
        for(i = 0; i < n; ++i) {
            if(list[i][ODR(t)] == true) {
                if(i == 0) { ++ans; }
                else { list[i-1][ODR(t)] = true; }
                list[i][ODR(t)] = false;
            }
        }
    } else if(d == 'R') {
        for(i = n-1; i >= 0; --i ) {
            if(list[i][ODR(t)] == true) {
                if(i == n-1) { ++ans; }
                else { list[i+1][ODR(t)] = true; }
                list[i][ODR(t)] = false;
            }
        }
    }
    return ans;
}

void init(char *str, int n, bool **list) {
    int i;
    for(i = 0; i < n; ++i) { list[i][ODR(str[i])] = true; }
}

void plist(bool **list, int n) {
    int i, j;
    for(i = 0; i < n; ++i) {
        for(j = 0; j < SIZE; ++j) {
            if(list[i][j] == true) { printf(" 1"); }
            else { printf(" 0"); }
        }
        printf("\n");
    }
}

