ll simulate(ll position)
{
	ll i = 0;
	while (i < q && position >= 1 && position <= n) {
		if (query[i].t == grid[position]) {
			if (query[i].d == 'L') {
				position--;
			}
			else if (query[i].d == 'R') {
				position++;
			}
		}

		i++;
	}

	return position;
}

ll bin_search(char mode)
{
	ll valid, invalid;
	ll mid;

	if (mode == 'L') {
		invalid = n + 2;
		valid = 0;

		while (invalid - valid > 1) {
			mid = (invalid + valid) / 2;

			if (simulate(mid) < 1) {
				valid = mid;
			}
			else {
				invalid = mid;
			}
		}
	}
	else if (mode == 'R') {
		invalid = -1;
		valid = n + 1;

		while (valid - invalid > 1) {
			mid = (invalid + valid) / 2;

			if (simulate(mid) > n) {
				valid = mid;
			}
			else {
				invalid = mid;
			}
		}
	}

	return valid;
}

