void move_golems_right(int *golems, char *cells, int N, char target){
    int increase_cells[N];
    for(int i=0; i<N; i++){
        increase_cells[i] = 0;
    }
    for(int i=0; i<N; i++){
        if(cells[i] == target){
            if(i != N-1){
                increase_cells[i+1] = golems[i];
            }
            golems[i] = 0;
        }
    }
    for(int i=0; i<N; i++){
        golems[i] += increase_cells[i];
    }
}

void move_golems_left(int *golems, char *cells, int N, char target){
    int increase_cells[N];
    for(int i=0; i<N; i++){
        increase_cells[i] = 0;
    }
    for(int i=0; i<N; i++){
        if(cells[i] == target){
            if(i != 0){
                increase_cells[i-1] = golems[i];
            }
            golems[i] = 0;
        }
    }
    for(int i=0; i<N; i++){
        golems[i] += increase_cells[i];
    }
}

