int simulate(char *s, char *t, char *d, int n, int q, int b){
    int i;
    for(i = 0; i < q; ++i) {
        if(s[b] == t[i]) {
            b += ((d[i] == 'R') ? 1 : -1);
            if(b < 0)   { return -1; }
            if(b > n-1) { return  1; }
        }
    }
    return 0;
}

