int sub(char *str, int *list, int n, char t, char d) {
    int i, ans = 0;
    if(d == 'L') {
        for(i = 0; i < n; ++i){
            if(str[i] == t) {
                if(i == 0) { ans += list[i]; list[i] = 0;}
                else {
                    list[i-1] += list[i]; list[i] = 0;
                }
            }
        }
    }
    else if(d == 'R'){
        for(i = n-1; i >=0; --i) {
            if(str[i] == t) {
                if(i == n-1) { ans += list[i]; list[i] = 0;}
                else {
                    list[i+1] += list[i]; list[i] = 0;
                }
            }
        }
    }
    return ans;
}

