  }
}

static void move_right(char t) {
  if (s[n - 1] == t) {
    ng[n - 1] = 0;
  }
  for (int i = n - 2; i >= 0; i--) {
    if (s[i] == t) {
      ng[i + 1] += ng[i];
      ng[i] = 0;
    }
  }
}

