private tailrec fun callSpell(spells: List<Spell>, golems: List<Golem>, strings: List<String>, limit: Int): List<Golem> {
    if (spells.isEmpty()) {
        return golems
    }
    val spell = spells.first()
    val newGolems = golems.mapNotNull { golem ->
        if (spell.s == golem.s) {
            // 動く
            val forward = if (spell.toRight) 1 else -1
            golem.position += forward
            if (golem.position < 0 || golem.position >= limit) {
                // はみ出た
                return@mapNotNull null
            }
            // 文字変更
            golem.s = strings[golem.position]
            golem
        } else {
            // 対象外
            golem
        }
    }
    return callSpell(spells.takeLast(spells.size - 1), newGolems, strings, limit)
}

