fun isDropFromRight(start: Int, state: String, order: Iterable<Pair<Char, Direction>>): Boolean {
    var current = start
    for ((t, d) in order) if (state[current] == t) {
        when(d){
            Direction.Left -> current--
            Direction.Right -> current++
        }
        if (current !in state.indices) return current > 0
    }
    return false
}
fun isDropFromLeft(start: Int, state: String, order: Iterable<Pair<Char, Direction>>): Boolean {
    var current = start
    for ((t, d) in order) if (state[current] == t){
        when(d){
            Direction.Left -> current--
            Direction.Right -> current++
        }
        if (current !in state.indices) return current < 0
    }
    return false
}
inline fun lowerBound(from: Int, to: Int, predicate: (value: Int) -> Boolean): Int {
    var left = from
    var right = to
    while(left < right){
        val mid = (left + right) / 2
        if (predicate(mid)){
            right = mid
        }else {
            left = mid + 1
        }
    }
    return right
}
