        int[] board = new int[n];
        for(int i = 0;i < n;i++){
            board[i] = 1;
        }

        Map<Character, List<Integer>> map = new HashMap<>();
        for(int i = 0;i < n;i++){
            char key = s.charAt(i);
            List<Integer> list = map.containsKey(key) ? map.get(key) : new ArrayList<>();
