					break;
				}
				else if(i==Q-1 && (0<=now && now<N)) {
					totatu=false;
					break;
				}
			}
			if(totatu) {
				min1=mid;
			}
			else {
				max1=mid;
			}
		}
		int jikken2=max1;//より右側にあるもの
		int hdr=0;
		for(int i=0; i<Q; i++) {
			if(move[i][0]==place[jikken2]) {
				if(move[i][1]==1) {
					jikken2++;
				}
				else if(move[i][1]==-1) {
					jikken2--;
				}
			}
			if(jikken2>=N) {
				int tmpj=min1;
				for(int k=0; k<Q; k++) {
					if(move[k][0]==place[tmpj])
					{
						if(move[k][1]==1) {
							tmpj++;
						}
						else if(move[k][1]==-1) {
