				pos++;
				count++;
				target=str.charAt(pos);
				max=Math.max(max, count);
			}
			if(cc2=='R' && !s.empty()&&cc1==s.peek()) {
				pos--;
				count--;
				target=s.pop();
			}
		}

		pos=str.length()-1;
		target=str.charAt(pos);
		int max2=0;
		s=new Stack();
		count=0;
		for(int i=c1.length-1;i>=0;i--) {
			char cc1=c1[i];
