				pos--;
				count++;

				target=str.charAt(pos);
				max2=Math.max(max2, count);
			}
			if(cc2=='L' && !s.empty()&&cc1==s.peek()) {
				pos++;
				count--;
				target=s.pop();
			}
		}


		int k=str.length()-max-max2;

