			t[i] = tokens[0].charAt(0);
			d[i] = tokens[1].charAt(0);
		}
		in.close();
	}

	void calc() {
		int left = -1;
		int right = N;
		for (int i = Q - 1; i >= 0; --i) {
			char c = t[i];
			char dir = d[i];
			if (dir == 'L') {
				if (left <= N - 2 && s.charAt(left + 1) == c) {
					++left;
				}
				if (right <= N - 1 && s.charAt(right) == c) {
					right++;
				}
			} else {
				if (right > 0 && s.charAt(right - 1) == c) {
					--right;
				}
				if (left >= 0 && s.charAt(left) == c) {
					left--;
				}
			}
		}
		this.result = N;
		if (left >= 0)

		{
			this.result -= (left + 1);
		}
		if (right <= N - 1) {
			this.result -= (N - right);
		}
		this.result = Math.max(0, this.result);

