		int Q = sc.nextInt();
		String s = sc.next();
		Map map = new Map();
		for(int i = 0;i<N;i++) {
			map.add(new Square(s.charAt(i)));
		}

		for(int i = 0;i<Q;i++) {
			String t = sc.next();
			String d = sc.next();
			map.move(t.charAt(0),d.charAt(0));
			if(map.count() == 0)break;
		}

		System.out.println(map.count());
	}

