import java.util.Scanner;

class Main {

  public enum Status {
    LEFT, RIGHT, OK;
  }

  public static Status LeftRightOk(String s, String[] t, String[] d, int index) {
    char currchar = s.charAt(index);
    for (int i = 0; i < t.length; i++) {
      if (currchar == t[i].charAt(0)) {
        if (d[i].equals("R")) {
          if (index != s.length() - 1) {
            currchar = s.charAt(++index);
          } else {
            return Status.RIGHT;
          }
        } else {
          if (index != 0) {
            currchar = s.charAt(--index);
          } else {
            return Status.LEFT;
          }
        }
      }
    }
    return Status.OK;
  }

  public static int searchLeftOkIdx(String s, String[] t, String[] d) {
    int ok = s.length() - 1;
    int left = 0;
    int mid = (ok + left) / 2;
    while (ok - left > 1) {
      if (LeftRightOk(s, t, d, mid) == Status.LEFT) {
        left = mid;
      } else {
        ok = mid;
      }
      mid = (ok + left) / 2;
    }
    return ok;
  }

  public static int searchRightOkIdx(String s, String[] t, String[] d) {
    int ok = 0;
    int right = s.length() - 1;
    int mid = (ok + right) / 2;
    while (right - ok > 1) {
      if (LeftRightOk(s, t, d, mid) == Status.RIGHT) {
        right = mid;
      } else {
        ok = mid;
      }
      mid = (ok + right) / 2;
    }
    return ok;
  }

  public static void main(String[] args) {
    {
      {
        Scanner scanner = new Scanner(System.in);
        int N = Integer.parseInt(scanner.next());
        int Q = Integer.parseInt(scanner.next());
        String s = scanner.next();
        String[] t = new String[Q];
        String[] d = new String[Q];
        for (int i = 0; i < Q; i++) {
          t[i] = scanner.next();
          d[i] = scanner.next();
        }
        scanner.close();
        int leftiOkdx = searchLeftOkIdx(s, t, d);
        int rightOkidx = searchRightOkIdx(s, t, d);
        int ans = rightOkidx - leftiOkdx >= 0 ? rightOkidx - leftiOkdx + 1 : 0;
        System.out.println(ans);

      }
    }
  }

}

import java.util.Arrays;
import java.util.LinkedList;
import java.util.Scanner;

public class Main {
	private class Move {
		public char alpha;
		public char move;
		public Move(String alpha, String move) {
			this.alpha = alpha.charAt(0);
			this.move = move.charAt(0);
		}
	}

	private char getAlpha(String s, int index) {
		if (index < 0 || index >= s.length()) {
			return ' ';
		} else {
			return s.charAt(index);
		}
	}

	private int calcDropNum(String s, LinkedList<Move> moves, char left) {
		int pos = -1;

		for (Move move : moves) {
			if (move.move == left) {
				char srcAlpha = getAlpha(s, pos+1);
				if (srcAlpha == move.alpha) {
					pos++;
				}
			} else {
				// move right
				char srcAlpha = getAlpha(s, pos-1);
				if (srcAlpha == move.alpha) {
					pos--;
				}
			}
		}

		return pos+1;
	}

	public void solve() {
		Scanner in = new Scanner(System.in);
		in.nextInt();
		int Q = in.nextInt();
		String s = in.next();

		LinkedList<Move> moves = new LinkedList<Move>();
		for (int i=0; i<Q; i++) {
			moves.addFirst(new Move(in.next(), in.next()));
		}
		in.close();

		int dropLeft = calcDropNum(s, moves, 'L');

		String invS = (new StringBuffer(s)).reverse().toString();
		int dropRight = calcDropNum(invS, moves, 'R');

		int totalDrop = Math.min(s.length(), dropLeft+dropRight);

		System.out.println(s.length() - totalDrop);
	}

	public void solve2() {
		Scanner in = new Scanner(System.in);
		in.nextInt();
		int Q = in.nextInt();
		String s = in.next();
		int[] nums = new int[s.length()];
		Arrays.fill(nums, 1);

		for (int i=0; i<Q; i++) {
			char alpha = in.next().charAt(0);
			char move = in.next().charAt(0);

			if (move == 'L') {
				for (int j=0; j<s.length(); j++) {
					if (s.charAt(j) == alpha) {
						if (j-1 >= 0) {
							nums[j-1] += nums[j];
						}
						nums[j] = 0;
					}
				}
			} else {
				for (int j=s.length()-1; j>=0; j--) {
					if (s.charAt(j) == alpha) {
						if (j+1 <= s.length()-1) {
							nums[j+1] += nums[j];
						}
						nums[j] = 0;
					}
				}
			}
		}
		in.close();

		System.out.println(sum(nums));
	}

	private int sum(int[] nums) {
		int sum = 0;
		for (int i=0; i<nums.length; i++) {
			sum += nums[i];
		}
		return sum;
	}

	public static void main(String[] args) {
		Main main = new Main();
		main.solve2();
	}
}

