import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.util.StringTokenizer;
class Main{
	static String s;
	static int N,Q;
	static int[][] move;
	static int[] place;
	public static void main(String[] args) {
		SC sc=new SC(System.in);
		N=sc.nextInt();
		Q=sc.nextInt();
		s=sc.next();
		move=new int[Q][2];
		place=new int[N];
		for(int i=0; i<N; i++) {
			place[i]=s.charAt(i)-'A';
		}
		for(int i=0; i<Q; i++) {
			move[i][0]=((sc.next()).charAt(0))-'A';
			move[i][1]=0;
			String tmp=sc.next();
			if(tmp.charAt(0)=='L') {
				move[i][1]=-1;
			}
			else if(tmp.charAt(0)=='R') {
				move[i][1]=1;
			}
		}
		int MIGI=0;
		int HIDARI=0;
		int min=0;
		int max=N;
		while(max-min>1) {	//二分探索でどこまで落ちるかを考える	→
			int mid=(max+min)/2;
			boolean totatu=migi(mid);
			if(totatu) {
				max=mid;
			}
			else {
				min=mid;
			}
		}
		boolean minok=migi(min);
		boolean maxok=migi(max);
		if(minok) {
			MIGI=min;
		}
		else if(maxok) {
			MIGI=max;
		}
		else {
			MIGI=-1;
		}

		min=0;
		max=N;
		while(max-min>1) {
			int mid=(max+min)/2;
			boolean totatu=hidari(mid);
			if(totatu) {
				min=mid;
			}
			else {
				max=mid;
			}
		}
		minok=hidari(min);
		maxok=hidari(max);
		if(maxok) {
			HIDARI=max;
		}
		else if(minok) {
			HIDARI=min;
		}
		else {
			HIDARI=-1;
		}
		int ans=N;
		if(MIGI>=0) {
			ans-=(N-MIGI);
		}
		if(HIDARI>=0) {
			ans-=(HIDARI+1);
		}
		pl(ans);
	}
	static boolean migi(int mid) {
		int now=mid;
		if(mid==N) {
			return true;
		}
		else {
			for(int i=0; i<Q; i++) {
				if(move[i][0]==place[now]) {
					if(move[i][1]==1) {
						now++;
					}
					else if(move[i][1]==-1) {
						now--;
					}
				}
				if(now==N) {
					return true;
				}
				else if(now<0) {
					return false;
				}
			}
			return false;
		}
	}

	static boolean hidari(int mid) {
		int now=mid;
		if(mid==N) {
			return false;
		}
		else {
			for(int i=0; i<Q; i++) {
				if(move[i][0]==place[now]) {
					if(move[i][1]==1) {
						now++;
					}
					else if(move[i][1]==-1) {
						now--;
					}
				}
				if(now<0) {
					return true;
				}
				else if(now>=N) {
					return false;
				}
			}
			return false;
		}
	}
	static class SC {
		private BufferedReader reader = null;
		private StringTokenizer tokenizer = null;
		public SC(InputStream in) {
			reader = new BufferedReader(new InputStreamReader(in));
		}
		public String next() {
			if (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new UncheckedIOException(e);
				}
			}
			return tokenizer.nextToken();
		}
		public int nextInt() {
			return Integer.parseInt(next());
		}
		public long nextLong() {
			return Long.parseLong(next());
		}
	}
	public static void pl(Object o) {
		System.out.println(o);
	}
	public static void pl() {
		System.out.println();
	}
	public static void p(Object o) {
		System.out.print(o);
	}
}

import java.util.List;
import java.util.Scanner;
import java.util.function.Function;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final int q = scanner.nextInt();
        final String s = scanner.next();

        final List<Query> queries = IntStream.range(0, q)
            .mapToObj(i -> new Query(scanner.next().charAt(0), scanner.next().charAt(0) == 'L' ? -1 : 1))
            .collect(Collectors.toList());

        final Function<Integer, SimulationResult> simulate = current -> {
            for (final Query query : queries) {
                if (s.charAt(current) != query.symbol) {
                    continue;
                }

                if (current == 0 && query.direction == -1) {
                    return SimulationResult.LEFT_FALL;
                } else if (current == s.length() - 1 && query.direction == 1) {
                    return SimulationResult.RIGHT_FALL;
                }

                current += query.direction;
            }

            return SimulationResult.REMAIN;
        };

        if (simulate.apply(n - 1) == SimulationResult.LEFT_FALL || simulate.apply(0) == SimulationResult.RIGHT_FALL) {
            System.out.println(0);
            return;
        }

        final int mostLeft = simulate.apply(0) == SimulationResult.LEFT_FALL ? binarySearchLeft(0, n - 1, simulate) : 0;
        final int mostRight = simulate.apply(n - 1) == SimulationResult.RIGHT_FALL ? binarySearchRight(0, n - 1, simulate) : n;
        if (mostLeft >= mostRight) {
            System.out.println(0);
        } else {
            System.out.println(mostRight - mostLeft);
        }
    }

    private static int binarySearchLeft(final int begin, final int end, final Function<Integer, SimulationResult> simulate) {
        if (end - begin <= 1) {
            return end;
        }
        final int mid = (begin + end) / 2;
        final SimulationResult result = simulate.apply(mid);
        if (result == SimulationResult.LEFT_FALL) {
            return binarySearchLeft(mid, end, simulate);
        } else {
            return binarySearchLeft(begin, mid, simulate);
        }
    }

    private static int binarySearchRight(final int begin, final int end, final Function<Integer, SimulationResult> simulate) {
        if (end - begin <= 1) {
            return end;
        }
        final int mid = (begin + end) / 2;
        final SimulationResult result = simulate.apply(mid);
        if (result == SimulationResult.RIGHT_FALL) {
            return binarySearchRight(begin, mid, simulate);
        } else {
            return binarySearchRight(mid, end, simulate);
        }
    }

    private enum SimulationResult {
        LEFT_FALL, RIGHT_FALL, REMAIN
    }

    private static class Query {
        final char symbol;
        final int direction;

        Query(final char symbol, final int direction) {
