		int q = sc.nextInt();
		String s = sc.next();

		HashMap<Integer, TreeSet<Integer>> spells = new HashMap<>();
		for (int i=0;i<52;i++) {
			spells.put(i, new TreeSet<Integer>());
		}

		for (int i=0;i<q;i++) {
			String t = sc.next();
			String d = sc.next();
			if (d.charAt(0)=='L') {
				spells.get(((t.charAt(0)-'A')*2)).add(i);
			} else {
				spells.get(((t.charAt(0)-'A')*2+1)).add(i);
			}
		}

		int right = 0;
		int pos = q;
		while (true) {

			 if (spells.get((s.charAt(right)-'A')*2).lower(pos) == null) {
				 break;
