import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            new Main().solve(sc);
        }
    }

    void solve(Scanner sc) {
        int n = sc.nextInt();
        int q = sc.nextInt();

        char[] s = sc.next().toCharArray();
        List<Set<Integer>> keyToIndexList = new ArrayList<>('Z' - 'A' + 1);
        for (int i = charToIndex('A'); i <= charToIndex('Z'); i++) {
            keyToIndexList.add(new HashSet<Integer>());
        }

        for (int i = 0; i < s.length; i++) {
            keyToIndexList.get(charToIndex(s[i])).add(i);
        }

        int[] golems = new int[n];
        Arrays.fill(golems, 1);
        int remain = n;
        for (int i = 0; i < q; i++) {
            char t = sc.next().charAt(0);
            char d = sc.next().charAt(0);

            Set<Integer> indexList = keyToIndexList.get(charToIndex(t));
            int[] tmpArray = Arrays.copyOf(golems, n);
            for (Integer index : indexList) {
                if (index == 0 && d == 'L') {
                    remain -= golems[0];
                    golems[0] = 0;
                } else if (index == n - 1 && d == 'R') {
                    remain -= golems[n - 1];
                    golems[n - 1] = 0;
                } else {
                    golems[index] = 0;
                }
            }

            for (Integer index : indexList) {
                if (d == 'L' && index != 0) {
                    golems[index - 1] += tmpArray[index];
                } else if (d == 'R' && index != n - 1) {
                    golems[index + 1] += tmpArray[index];
                }
            }
        }

        System.out.println(remain);
    }

    int charToIndex(char c) {
        return c - 'A';
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.Function;

public class Main {

    static int N, Q;
    static String S;
    static char[] T, D;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        Q = sc.nextInt();
        S = sc.next();
        T = new char[Q];
        D = new char[Q];
        for (int i = 0; i < Q; i++) {
            T[i] = sc.next().charAt(0);
            D[i] = sc.next().charAt(0);
        }

        System.out.println(solve());
    }

    static int solve() {
        int l = -1;
        int r = N;
        for (int i = Q-1; i >= 0; i--) {
            char t = T[i];
            char d = D[i];

            if( d == 'L' && l < N-1) {
                char next = S.charAt(l+1);
                if( next == t ) l++;
            } else if( d == 'R' && r > 0 ){
                char next = S.charAt(r-1);
                if( next == t ) r--;
            }
        }

        int ans = N;
        if( l != -1 ) {
            ans -= l+1;
        }
        if( r != N ) {
            ans -= N-r;
        }
        return ans;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

