        outputs[0] = true;
        outputs[n + 1] = true;
        trueIndex.add(0);
        trueIndex.add(n + 1);
        int tmp;
        int size;
        for (int i = q; i > 0; i--) {
            size = trueIndex.size();
            if (directions[i - 1]) {
                for (int j = 0; j < size; j++) {
                    tmp = trueIndex.get(j);
                    if (tmp != 0 && chars[i - 1] == s.charAt(tmp - 1) && !outputs[tmp - 1]) {
                        outputs[tmp - 1] = true;
                        trueIndex.add(tmp - 1);
                    }

                }
            } else {
                for (int j = 0; j < size; j++) {
                    tmp = trueIndex.get(j);
                    if (tmp != n + 1 && chars[i - 1] == s.charAt(tmp + 1) && !outputs[tmp + 1]) {
                        outputs[tmp + 1] = true;
                        trueIndex.add(tmp + 1);
                    }

                }
            }

        }
        System.out.println(n - trueIndex.size() + 2);
    }
}

