        }

        int ng=-1,ok=N-1;
        while( Math.abs(ng-ok) > 1){
            int mid = (ng+ok)/2;
            if(isOKLeft(mid,spells,s)){
                ok = mid;
            }else{
                ng = mid;
            }
        }

        int leftOK = ok;

        ng=N;ok=0;
        while( Math.abs(ng-ok) > 1){
            int mid = (ng+ok)/2;
            if(isOKRight(mid,spells,s)){
                ok = mid;
            }else{
                ng = mid;
            }
        }

        int rightOK = ok;


        System.out.println(rightOK-leftOK+1);
    }


    static    boolean isOKLeft(int mid,char[][] spells ,char[] s){
        for (int i = 0; i < spells.length; i++) {
            if(spells[i][0] == s[mid]){
                if(spells[i][1]=='L'){
                    mid--;
                }else{
                    mid++;
                }
                if(mid ==-1) {
                    return false;
                }
            }
        }
        return true;
    }

    static    boolean isOKRight(int mid,char[][] spells ,char[] s){
        for (int i = 0; i < spells.length; i++) {
            if(spells[i][0] == s[mid]){
                if(spells[i][1]=='L'){
                    mid--;
                }else{
                    mid++;
                }
                if(mid ==s.length) {
                    return false;
                }
            }
        }
        return true;
    }


    static    boolean isOK(int mid,char[][] spells ,char[] s, int drop ){
        for (int i = 0; i < spells.length; i++) {
            if(spells[i][0] == s[mid]){
                if(spells[i][1]=='L'){
                    mid--;
                }else{
                    mid++;
                }
                if(mid ==drop) {
                    return false;
                }
            }
        }
        return true;
    }

}

