		Q = Integer.parseInt(sc.next());
		s = sc.next();
		int n;
		String Golem[] = new String[N];
		for (n = 0; n < N; n++) {
			Golem[n] = s.substring(n, n + 1);
		}
		int l = 0;
		int L = 0;
		int r = N - 1;
		int R = 0;
