 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int q = in.readInt();

            int[] chars = in.readString().chars().map(x -> x - 'A').toArray();

            int[] t = new int[q];
            int[] d = new int[q];
            for (int i = 0; i < q; i++) {
                t[i] = in.readString().charAt(0) - 'A';
                d[i] = in.readString().equals("L") ? -1 : 1;
            }

            int cnt = calc(n, q, chars, t, d);

            for (int i = 0; i < n / 2; i++) {
                int tmp = chars[i];
                chars[i] = chars[n - 1 - i];
                chars[n - 1 - i] = tmp;
            }
            for (int i = 0; i < q; i++) {
                d[i] = -d[i];
            }

            cnt += calc(n, q, chars, t, d);

            out.printLine(n - Math.min(cnt, n));
        }

        private int calc(int n, int q, int[] chars, int[] t, int[] d) {
            int high = n;
            int low = -1;
            while (high - low > 1) {
                int mid = (high + low) / 2;

                int pos = mid;
                boolean flg = false;
                for (int i = 0; i < q; i++) {
                    if (chars[pos] == t[i]) {
                        pos += d[i];
                        if (pos < 0) {
                            flg = true;
                            break;
                        }
                        if (pos >= n) {
                            break;
                        }
                    }
                }

                if (flg) {
                    low = mid;
                } else {
                    high = mid;
                }
            }
            return high;
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(int i) {
            writer.println(i);
        }

    }
}

