            if (d == 'L') {
                diff--;
                diffMin = Math.min(diffMin, diff);
                diffMinMap.put(t, diffMin);
            } else {
                diff++;
                diffMax = Math.max(diffMax, diff);
                diffMaxMap.put(t, diffMax);
            }
