import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    private static int n;
    private static int q;
    private static String[] s;
    private static List<String> t = new ArrayList<>();
    private static List<String> d = new ArrayList<>();

    private static int calcBorder(boolean asc) {
        for (int i = 0; i < n - 1; i++) {
            int golemPos;
            if (asc) {
                golemPos = i;
            } else {
                golemPos = n - i - 1;
            }
            boolean falled = false;
            for (int j = 0; j < q; j++) {
                String tj = t.get(j);
                String dj = d.get(j);
                if (!tj.equals(s[golemPos])) {
                    continue;
                }
                if ("L".equals(dj)) {
                    golemPos--;
                } else {
                    golemPos++;
                }
                if (asc && golemPos < 0 || !asc && golemPos > n - 1) {
                    falled = true;
                    break;
                }
            }
            if (!falled) {
                return i;
            }
        }
        return 0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        q = sc.nextInt();
        s = sc.next().split("");
        for (int i = 0; i < q; i++) {
            t.add(sc.next());
            d.add(sc.next());
        }

        int startBorder = calcBorder(true);
        int endBorder = n - 1 - calcBorder(false);
        System.out.println(endBorder - startBorder + 1);

    }

}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		final Scanner scanner = new Scanner(System.in);
		final int length = scanner.nextInt();
		final int counter = scanner.nextInt();
		scanner.nextLine();
		final String string = scanner.nextLine();

		final Map<Character, List<Integer>> map = new HashMap<>();
		for (int i = 0; i < length; i++) {
			map.computeIfAbsent(string.charAt(i), s -> new ArrayList<>())
				.add(i);
		}

		final int[] array = new int[length];
		for (int i = 0; i < length; i++) {
			array[i] = 1;
		}

		for (int i = 0; i < counter; i++) {
			final String[] order = scanner.nextLine()
				.split(" ");
			final List<Integer> intList = map.get(order[0].charAt(0));
			if(intList == null) {
				continue;
			}
			if (order[1].equals("L")) {
				for (int j = 0; j < intList.size(); j++) {
					final int index = intList.get(j);
					if (index == 0) {
						array[0] = 0;
					} else {
						array[index - 1] += array[index];
						array[index] = 0;
					}
				}
			} else {
				for (int j = intList.size() - 1; j >= 0; j--) {
					final int index = intList.get(j);
					if (index == length - 1) {
						array[index] = 0;
					} else {
						array[index + 1] += array[index];
						array[index] = 0;
					}
				}
			}
		}

		int result = 0;
		for (int value : array) {
			result += value;
		}

		System.out.println(result);

		scanner.close();

	}

}

