public class Main {
    InputStream is;

    int __t__ = 1;
    int __f__ = 0;
    int __FILE_DEBUG_FLAG__ = __f__;
    String __DEBUG_FILE_NAME__ = "src/A1";

    FastScanner in;
    PrintWriter out;

    public void solve() {
        int N = in.nextInt();
        int Q = in.nextInt();
        String s = in.next();
        char[] t = new char[Q];
        char[] d = new char[Q];
        for (int i = 0; i < Q; i++) {
            t[i] = in.next().charAt(0);
            d[i] = in.next().charAt(0);
        }

        int left;
        {
            int lo = -1, hi = N;
            while (hi - lo > 1) {
                int mid = (hi + lo) / 2;
                if (sim(s, t, d, mid) == -1) {
                    lo = mid;
                } else {
                    hi = mid;
                }
            }
            left = lo;
        }
        int right;
        {
            int lo = -1, hi = N;
            while (hi - lo > 1) {
                int mid = (hi + lo) / 2;
                if (sim(s, t, d, mid) == N) {
                    hi = mid;
                } else {
                    lo = mid;
                }
            }
            right = hi;
        }

        System.out.println((right - left - 1));
    }

    private int sim(String s, char[] t, char[] d, int pos) {
        for (int i = 0; i < t.length; i++) {
            if (t[i] == s.charAt(pos)) {
                pos += d[i] == 'R' ? 1 : -1;
            }
            if (pos == -1 || pos == s.length()) {
