    static class CSnukeTheWizard {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int n = in.ints(), q = in.ints();
            String s = in.string();
            char[] t = new char[q], d = new char[q];
            for (int i = 0; i < q; i++) {
                t[i] = in.string().charAt(0);
                d[i] = in.string().charAt(0);
            }

            int l = -1, r = n;
