                            if(g[a2] == a){
                                g[a2] = (g[a2] - 1);
                            }
                        }
                    }

                    if(d[i].equals(R)){
                        for(int a2 = 0; a2 < N ; a2++){
                            if(g[a2] == a){
                                g[a2] = (g[a2] + 1);
                            }
                        }
                    }
                }

            }

        }

