public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int q = sc.nextInt();
        char[] s = sc.nextChars();
        char[] t = new char[q];
        boolean[] d = new boolean[q];
        for (int i = 0; i < q; i++) {
            t[i] = sc.nextChars()[0];
            d[i] = sc.nextChars()[0] == 'L';
        }

        int l1 = -1, r1 = n;
        while (r1 - l1 > 1) {
            int m = (l1 + r1) >> 1;
            int k = m;
            boolean b = false;
            for (int i = 0; i < q; i++) {
                if (t[i] == s[k]) {
                    k = d[i] ? k - 1 : k + 1;
                    if (k < 0) {
                        b = true;
                        break;
                    } else if (k >= n) break;
                }
            }
            if (b) l1 = m;
            else r1 = m;
        }

        int l2 = -1, r2 = n;
        while (r2 - l2 > 1) {
            int m = (l2 + r2) >> 1;
            int k = m;
            boolean b = false;
            for (int i = 0; i < q; i++) {
                if (t[i] == s[k]) {
                    k = d[i] ? k - 1 : k + 1;
                    if (k >= n) {
                        b = true;
                        break;
                    } else if (k < 0) break;
                }
            }
            if (b) r2 = m;
            else l2 = m;
        }

        out.writeln(r2 - l1 - 1);
    }
}


