    for (int i=0; i<N; i++) {
      if (!map.containsKey(s.charAt(i))) map.put(s.charAt(i), new ArrayList());

      map.get(s.charAt(i)).add(i);
    }

    int removedCount = 0;

    for (int cnt=0; cnt<Q; cnt++) {
      char t = sc.next().charAt(0);
      char d = sc.next().charAt(0);

      if (!map.containsKey(t)) continue;

      for (int i : map.get(t)) {
        if (d == 'L') {
          if (i != 0) {
            board[i-1] += board[i];
          } else {
            removedCount += board[i];
          }
          board[i] = 0;
        } else {
          if (i != N-1) {
            board[i+1] += board[i];
          } else {
            removedCount += board[i];
          }
          board[i] = 0;
        }
      }
    }

    System.out.println(N - removedCount);

  }

