        {int[] a = r.ii(); N = a[0]; Q = a[1];}
        String s = r.s();

        String[][] spell = new String[Q][];
        for(int i = 0; i < Q; i++)
            spell[i] = r.ss();

        int left = 0;
        int right = N+1;

        while(left + 1 < right){
            int golem = (right+left)/2;
            int next = golem;
            boolean flag = false;

            for(String[] sp : spell){
                if(s.charAt(golem-1) == sp[0].charAt(0)){
                    golem += sp[1].equals("R") ? 1 : -1;
                    if(golem < 1){
                        flag = true;
                        break;
                    }
                }
            }
            if(flag)
                left = next;
            else
                right = next;
        }

        int ans = N-left;

        right = N+1;
        left = 0;

        while(left + 1 < right){
            int golem = (right+left)/2;
            int next = golem;
            boolean flag = false;

            for(String[] sp : spell){
                if(s.charAt(golem-1) == sp[0].charAt(0)){
                    golem += sp[1].equals("R") ? 1 : -1;
                    if(golem > N){
                        flag = true;
                        break;
                    }
                }
            }
