/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author mikit
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        CSnukeTheWizard solver = new CSnukeTheWizard();
        solver.solve(1, in, out);
        out.close();
    }

    static class CSnukeTheWizard {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int n = in.ints(), q = in.ints();
            String s = in.string();
            char[] t = new char[q], d = new char[q];
            for (int i = 0; i < q; i++) {
                t[i] = in.string().charAt(0);
                d[i] = in.string().charAt(0);
            }

            int l = -1, r = n;
            for (int i = q - 1; i >= 0; i--) {
                if (r - l <= 1) {
                    out.ansln(0);
                    return;
                }
                if (d[i] == 'L') {
                    if (s.charAt(l + 1) == t[i]) {
                        l++;
                    }
                } else {
                    if (s.charAt(r - 1) == t[i]) {
                        r--;
                    }
                }
            }

            IntUnaryOperator move = x -> {
                int cur = x;
                for (int i = 0; i < q; i++) {
                    if (cur >= n) {
                        return n;
                    } else if (cur < 0) {
                        return -1;
                    }
                    if (s.charAt(cur) == t[i]) {
                        if (d[i] == 'L') {
                            cur--;
                        } else {
                            cur++;
                        }
                    }
                }
                return cur;
            };

            int min = -1, max = n;
            outer:
            while (max - min > 1) {
                int mid = (min + max + 1) / 2;
                if (r <= move.applyAsInt(mid)) {
                    max = mid;
                } else {
                    min = mid;
                }
            }
            int rangeMax = min;


            min = -1;
            max = n;
            outer:
            while (max - min > 1) {
                int mid = (min + max + 1) / 2;
                if (move.applyAsInt(mid) <= l) {
                    min = mid;
                } else {
                    max = mid;
                }
            }
            int rangeMin = min + 1;


            //System.out.println("(" + l + ", " + r + ")");
            //System.out.println("[" + rangeMin + ", " + rangeMax + "]");

            out.ansln(Math.max(0, rangeMax - rangeMin + 1));
        }

    }

    static class LightWriter implements AutoCloseable {
        private final Writer out;
        private boolean autoflush = false;
        private boolean breaked = true;

        public LightWriter(Writer out) {
            this.out = out;
        }

        public LightWriter(OutputStream out) {
            this(new BufferedWriter(new OutputStreamWriter(out, Charset.defaultCharset())));
        }

        public LightWriter print(char c) {
            try {
                out.write(c);
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter print(String s) {
            try {
                out.write(s, 0, s.length());
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter ans(String s) {
            if (!breaked) {
                print(' ');
            }
            return print(s);
        }

        public LightWriter ans(int i) {
            return ans(Integer.toString(i));
        }

        public LightWriter ansln(int... n) {
            for (int n1 : n) {
                ans(n1).ln();
            }
            return this;
        }

        public LightWriter ln() {
            print(System.lineSeparator());
            breaked = true;
            if (autoflush) {
                try {
                    out.flush();
                } catch (IOException ex) {
                    throw new UncheckedIOException(ex);
                }
            }
            return this;
        }

        public void close() {
            try {
                out.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

    }
}

import java.util.Scanner;
import java.util.Stack;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int Q = scanner.nextInt();
    char[] s = scanner.next().toCharArray();
    char[][] queries = new char[Q][2];
    for (int i = 0; i < Q; i++) {
      queries[Q - i - 1][0] = scanner.next().charAt(0);
      queries[Q - i - 1][1] = scanner.next().charAt(0);
    }

    Stack<Character> stack = new Stack<>();
    int i = s.length - 1;
    for (int j = 0; j < Q; j++) {
      if (i >= 0 && s[i] == queries[j][0] && queries[j][1] == 'R') {
        stack.push(s[i]);
        i--;
      }
      if (!stack.isEmpty() && stack.peek() == queries[j][0] && queries[j][1] == 'L') {
        stack.pop();
        i++;
      }
    }
    int mr = stack.size();

    stack.clear();
    i = 0;
    for (int j = 0; j < Q; j++) {
      if (i < N && s[i] == queries[j][0] && queries[j][1] == 'L') {
        stack.push(s[i]);
        i++;
      }
      if (!stack.isEmpty() && stack.peek() == queries[j][0] && queries[j][1] == 'R') {
        stack.pop();
        i--;
      }
    }
    int ml = stack.size();

    System.out.println(N - Math.min(ml + mr, N));
  }
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		Main main = new Main();
		main.solve(sc);
		sc.close();
	}

	void solve(Scanner sc) {
		int N = sc.nextInt();
		int Q = sc.nextInt();
		String s = sc.next();
		String[] M = new String[N];
		int[] G = new int[N];

		for (int i = 0; i < N; i++) {
			M[i] = Character.toString(s.charAt(i));
			G[i] = 1;
		}

		for (int i = 0; i < Q; i++) {
			String ABC = sc.next();
			String LR = sc.next();

			for (int k = 0; k < N; k++) {
				if (M[k].equals(ABC)) {
					if (G[k] == 0) {
						continue;
					}
					if (LR.equals("L")) {
						if (k == 0) {
							G[k] = 0;
						} else {
							G[k - 1] += G[k];
							G[k] = 0;
						}
					} else {
						if (k == N - 1) {
							G[k] = 0;
						} else {
							G[k + 1] += G[k];
							G[k] = 0;
						}
					}
				} else {
					continue;
				}
			}
		}
		int sum = 0;
		for (int i = 0; i < N; i++) {
			sum += G[i];
		}
		System.out.println(sum);

	}
}

