            if (d[i].equals("L") && t[i].charAt(0) == current) {
                leftMaxIndex = index;
                index++;
                current = s.charAt(index);
                if (leftMaxIndex == s.length() - 1) {
                    break;
                }
            }
        }

        // find rightDroppedMinIndex
