class Solver {
	int N;
	int cnt;

	public void init() {
		N = 0;
		cnt = 0;
	}

	public void readHead(String str) {
		String[] strArr = str.split(" ");
		N = Integer.parseInt(strArr[0]);
		// System.out.println(N);
		Q = Integer.parseInt(strArr[1]);
		G = new int[N + 1];
		for (int i = 1; i <= N; i++)
			G[i] = 1;
	}

	int Q;
	int[] G;

	public void readS(String str) {
		Idx = new HashMap<Character, ArrayList<Integer>>();
		for (int i = 0; i < N; i++) {
			if (!Idx.containsKey(str.charAt(i))) {
				Idx.put(str.charAt(i), new ArrayList<Integer>());
			}
			Idx.get(str.charAt(i)).add(i + 1);
		}
	}

	HashMap<Character, ArrayList<Integer>> Idx;

	public boolean hasNext() {
		// return cnt < N;
		return cnt < Q;
	}

	public void readBody(String str) {
		// System.out.println(str);
		String[] strArr = str.split(" ");
		char t = strArr[0].charAt(0);
		char d = strArr[1].charAt(0);
		if (Idx.containsKey(t)) {
			for (int i : Idx.get(t)) {
				if (d == 'L') {
					if (i > 0)
						G[i - 1] += G[i];
				} else {
					if (i < N)
						G[i + 1] += G[i];
				}
				G[i] = 0;
			}
		}
		cnt++;
	}

	public void solve() {
		int ans = 0;
		for (int i = 1; i <= N; i++)
			ans += G[i];
		System.out.println(ans);
	}
}

import java.util.Scanner;

class C {
    public static void main(String... args) {
        final Scanner sc = new Scanner(System.in);
        final int N = sc.nextInt();
        final int Q = sc.nextInt();
        final char[] s = sc.next().toCharArray();
        final char[] t = new char[Q];
        final char[] d = new char[Q];
        for (int i = 0; i < Q; i++) {
            t[i] = sc.next().charAt(0);
            d[i] = sc.next().charAt(0);
        }
        final int l = left(N, Q, s, t, d);
        final int r = right(N, Q, s, t, d);
        System.out.println(r - l - 1);
    }

    static int left(final int N, final int Q, final char[] s, final char[] t, final char[] d) {
        int lo = 0;
        int hi = N;
        while (hi - lo > 1) {
            final int x = (hi + lo) / 2;
            if (check(x, N, Q, s, t, d) < 0)
                lo = x;
            else
                hi = x;
        }
        return (hi + lo) / 2;
    }

    static int right(final int N, final int Q, final char[] s, final char[] t, final char[] d) {
        int lo = 1;
        int hi = N + 1;
        while (hi - lo > 1) {
            final int x = (hi + lo + 1) / 2;
            if (check(x, N, Q, s, t, d) > 0)
                hi = x;
            else
                lo = x;
        }
        return (hi + lo + 1) / 2;
    }

    static int check(int idx, final int N, final int Q, final char[] s, final char[] t, final char[] d) {
        for (int i = 0; i < Q; i++)
            if (s[idx - 1] == t[i]) {
                if (d[i] == 'L')
                    idx--;
                else
                    idx++;
                if (idx < 1)
                    return -1;
                else if (idx > N)
                    return 1;
            }
        return 0;
    }
}
public class Main {
    public static void main(String...args) {
        C.main();
    }
}

