		int q = sc.nextInt();
		String s = sc.next();
		Map<String, List<Integer>> map = new HashMap<String, List<Integer>>();
		for (int i = 0; i < n; i++) {
			String str = s.substring(i, i + 1);
			List<Integer> list = map.get(str);
			if (list == null) {
				list = new ArrayList<Integer>();
				map.put(str, list);
			}
			list.add(i);
		}

		int ans = 0;
		int[] cnt = new int[n];
		Arrays.fill(cnt, 1);
		for (int i = 0; i < q; i++) {
			String t = sc.next();
			String d = sc.next();
			List<Integer> list = map.get(t);
			if (list == null) {
				continue;
			}
			if ("L".equals(d)) {
				for (int j = 0; j < list.size(); j++) {
					int idx = list.get(j);
