				}
			} else {
				for (int j = list.size() - 1; j >= 0; j--) {
					int idx = list.get(j);
					if (idx == n - 1) {
						ans += cnt[idx];
					} else {
						cnt[idx + 1] += cnt[idx];
					}
					cnt[idx] = 0;
				}
			}
		}
		sc.close();

		System.out.println(n - ans);
	}
}

