    static class TaskC {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int q = in.readInt();

            int[] chars = in.readString().chars().map(x -> x - 'A').toArray();

            int[] t = new int[q];
            int[] d = new int[q];
            for (int i = 0; i < q; i++) {
                t[i] = in.readString().charAt(0) - 'A';
                d[i] = in.readString().equals("L") ? -1 : 1;
            }

            int cnt = calc(n, q, chars, t, d);

            ArrayUtils.reverse(chars);
            d = Arrays.stream(d).map(x -> -x).toArray();

            cnt += calc(n, q, chars, t, d);

            out.printLine(n - cnt);
        }

        private int calc(int n, int q, int[] chars, int[] t, int[] d) {
            int high = n;
            int low = -1;
            while (high - low > 1) {
                int mid = (high + low) / 2;

                int pos = mid;
                boolean flg = false;
                for (int i = 0; i < q; i++) {
                    if (chars[pos] == t[i]) {
                        pos += d[i];
                        if (pos < 0) {
                            flg = true;
                            break;
                        }
                        if (pos >= n) {
                            break;
                        }
                    }
                }

                if (flg) {
                    low = mid;
                } else {
                    high = mid;
                }
            }
            return high;
        }

    }

