	static char test(int n) {
		int tmp = n;
		for (int i=0;i<Q;i++) {
			if (s.charAt(tmp)==t[i]) {
				if (d[i]=='R') {
					tmp++;
				} else if (d[i]=='L') {
					tmp--;
				}
			}
			if (tmp<0) {
				return 'L';
			}else if(tmp>N-1) {
				return 'R';
			}
		}
		return 'A';
	}
}

