        var pos =
            Enumerable.Range(0, 26)
            .Select(x => new List<int>())
            .ToArray();
        foreach(var item in Console.ReadLine().Select((Value, Index) => new {Value, Index}))
        {
            pos[item.Value - 'A'].Add(item.Index);
        }
        int[] dp = Enumerable.Repeat(1, n).ToArray();
        foreach(int i in Enumerable.Range(0, q))
        {
            inputs = Console.ReadLine().Split();
            if(inputs[1] == "L")
                foreach(int j in pos[inputs[0][0] - 'A'])
