            foreach (var index in indexList)
            {
                int targetIndex = direction == 'L' ? index - 1 : index + 1;
                if (this.matrix[index] > 0)
                {
                    // ゴーレムが居る
                    if (targetIndex >= 0 &&
                        targetIndex < this.matrix.Count())
                    {
                        // 移動
                        this.matrix[targetIndex] += this.matrix[index];
                        this.matrix[index] = 0;
                    }
                    else
                    {
                        // 消滅
                        this.matrix[index] = 0;
                    }
                }
            }
        }
        private List<int> GetIndexList(List<char> list, char searchCharactor)
        {
            List<int> indexList;
            if (this.cache.ContainsKey(searchCharactor))
            {
                indexList = this.cache[searchCharactor];
            }
            else
            {
                indexList = new List<int>();
                for (var index = 0; index < list.Count; index++)
                {
                    if (list[index] == searchCharactor)
                    {
                        indexList.Add(index);
                    }
                }

                this.cache[searchCharactor] = indexList;
            }

            return indexList;
        }
    }
}

