class Program
{
  static void Main()
  {
    int[] NQ=ReadLine().Split(' ').Select(int.Parse).ToArray();
    string s=ReadLine();
    char[] t=new char[NQ[1]];
    char[] d=new char[NQ[1]];
    for(int i=0;i<NQ[1];i++)
    {
       var line =ReadLine();
       t[i]=line[0];
       d[i]=line[2];
    }
    int min=NQ[0]/2;
    int max=NQ[0]/2;
    int ng=0;
    int ok=NQ[0];
    while(ok-ng!=1)
    {
       char r=Alive(min,s,NQ[1],t,d);
       if(r=='L')ng=min;
       else ok=min;
       min=(ng+ok)/2;
    }
    min=ng;

    ng=NQ[0];
    ok=0;
    while(ng-ok!=1)
    {
       char r=Alive(max,s,NQ[1],t,d);
       if(r=='R')ng=max;
       else ok=max;
       max=(ng+ok)/2;
    }
    max=ng;
    WriteLine(max- min-1);
  }
  static char Alive(int idx,string s,int Q,char[]t,char[]d)
  {
     for(int i=0;i<Q;i++)
      {
        if(s[idx]==t[i]&&d[i]=='R')idx++;
        else if(s[idx]==t[i]&&d[i]=='L')idx--;
        if(idx>=s.Length)return 'R';
        if(idx<0)return 'L';
      }
      return 'A';
  }
}

