            s = Console.ReadLine();



            for (int i = 0; i < nq[1]; i++)
            {
                string[] td = Console.ReadLine().Split().ToArray();
               tdlst.Add(td);
            }

            int l = GetLeftBnd(0, nq[0] - 1);
            int r= GetRightBnd(0, nq[0] - 1);
            int ans = Math.Max(r-l+1,0);

            Console.WriteLine(ans);

        }

        public static int GetLeftBnd(int l,int r)
        {
            if (l == r)
            {
                if (IsLeftBnd(l))
                {
                    return l + 1;
                }
                else
                {
                    return l;
                }
            }
            else if (r - l == 1)
            {
                if (IsLeftBnd(r))
                {
                    return r + 1;
                }
                else if (IsLeftBnd(l))
                {
                    return r;
                }
                else
                {
                    return l;
                }
            }
            else
            {
                int mid = (l + r) / 2;
                if (IsLeftBnd(mid))
                {
                    l = mid;
                    return GetLeftBnd(l, r);
                }
                else
                {
                    r = mid;
                    return GetLeftBnd(l, r);
                }
            }
        }

        public static int GetRightBnd(int l, int r)
        {
            if (l == r)
            {
                if (IsRightBnd(r))
                {
                    return r - 1;
                }
                else
                {
                    return r;
                }
            }
            else if (r - l == 1)
            {
                if (IsRightBnd(l))
                {
                    return l-1;
                }
                else if (IsRightBnd(r))
                {
                    return l;
                }
                else
                {
                    return r;
                }
            }
            else
            {
                int mid = (l + r) / 2;
                if (IsRightBnd(mid))
                {
                    r = mid;
                    return GetRightBnd(l, r);
                }
                else
                {

                    l = mid;
                    return GetRightBnd(l, r);
                }
            }
        }

        public static bool IsLeftBnd(int idx)
        {
            bool isBnd = false;
            char nowChar = s[idx];
            int nowPos = idx;
            for (int i = 0; i < nq[1]; i++)
            {
                if (tdlst[i][0][0] == nowChar)
