                    if (tdlst[i][1][0] == 'L')
                    {
                        nowPos -= 1;
                        if (nowPos == -1)
                        {
                            isBnd = true;

                            break;
                        }
                        else
                        {
                            nowChar = s[nowPos];
                        }
                    }
                    else
                    {
                        nowPos += 1;
                        if (nowPos == nq[0])
                        {
                            break;
                        }

                    }
                }

            }

            return isBnd;
        }

        public static bool IsRightBnd(int idx)
        {
            bool isBnd = false;
