            GetInput(out s, out spells);
            Console.WriteLine(Solve(s, spells));

        }

        private static int Solve(string s, Spell[] spells)
        {

            int[] counts = new int[s.Length];
            for (int i = 0; i < counts.Length; i++)
            {
                counts[i] = 1;
            }


            foreach (Spell spell in spells)
            {
                if (spell.D == 'L')
                {
                    for (int i = 0; i < counts.Length; i++)
                    {
                        if (s[i] == spell.T)
                        {
                            if (i > 0)
                            {
                                counts[i - 1] += counts[i];
                            }
                            counts[i] = 0;
                        }
                    }
                }
                else
                {
                    for (int i = counts.Length-1; i >=0; i--)
                    {
                        if (s[i] == spell.T)
                        {
                            if (i < counts.Length - 1)
                            {
                                counts[i + 1] += counts[i];
                            }
                            counts[i] = 0;
                        }
                    }
                }
            }
            return counts.Sum();
        }

