namespace Exa2019C
{
    internal class Program
    {
        public static void Main(string[] args)
        {
            long[] nq = Console.ReadLine().Split(' ').Select(a => long.Parse(a)).ToArray();
            string s = Console.ReadLine();
            char[][] qs = new char[nq[1]][];
            for (int i = 0; i < nq[1]; i++)
            {
                qs[i] = Console.ReadLine().Split(' ').Select(a => char.Parse(a)).ToArray();
            }

            Array.Reverse(qs);

            Dictionary<char, List<long>> dic = new Dictionary<char, List<long>>();

            for (int i = 0; i < nq[0]; i++)
            {
                if (!dic.ContainsKey(s[i]))
                {
                    dic.Add(s[i], new List<long>());
                }

                dic[s[i]].Add(i);
            }

            bool[][] dp = new bool[nq[1] + 1][];
            dp[0] = new bool[nq[0]];
            for (int i = 0; i < nq[0]; i++)
            {
                dp[0][i] = false;
            }

            for (int i = 1; i <= nq[1]; i++)
            {
                char[] query = qs[i - 1];
                dp[i] = new bool[nq[0]];
                for (int j = 0; j < nq[0]; j++)
                {
                    dp[i][j] = dp[i - 1][j];
                }

                if (!dic.ContainsKey(query[0]))
                {
                    continue;
                }

                if (query[1] == 'R')
                {
                    for (int j = 0; j < dic[query[0]].Count; j++)
                    {
                        long cur = dic[query[0]][j];
                        if (cur == nq[0] - 1)
                        {
                            dp[i][nq[0] - 1] = true;
                            continue;
                        }

                        dp[i][cur] = dp[i - 1][cur + 1];
                    }
                }

                if (query[1] == 'L')
                {
                    for (int j = 0; j < dic[query[0]].Count; j++)
                    {
                        long cur = dic[query[0]][j];

                        if (cur == 0)
                        {
                            dp[i][0] = true;
                            continue;
                        }

                        dp[i][cur] = dp[i - 1][cur - 1];
                    }
                }
            }

            long ans = nq[0];
            for (int i = 0; i < nq[0]; i++)
            {
                if (dp[nq[1]][i])
                {
                    ans--;
                }
            }

            Console.WriteLine(ans);
        }
    }
}

