using System.Linq;

namespace ExaWizC {
    class Program {
        static void Main(string[] args) {
            var input = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            var n = input[0];
            var q = input[1];
            var s = Console.ReadLine();
            var res = Enumerable.Repeat(1,n).ToArray();
            var keys = new SortedDictionary<char, List<int>>();

            for (int i = 0; i < q; i++) {
                var x = Console.ReadLine();
                var t = x[0];
                if (!keys.ContainsKey(t)) {
                    keys.Add(t,new List<int>());
                    var index = 0;
                    while (true) {
                        index = s.IndexOf(t,index);
                        if (index == -1) break;
                        keys[t].Add(index);
                        index++;
                    }
                }

                var d = x[2];
                foreach (var index in keys[t]) {
                    if (d == 'L') {
                        if (index != 0) res[index - 1] += res[index];
                    } else {
                        if (index < n-1) res[index + 1] += res[index];
                    }
                    res[index] = 0;
                }
            }
            Console.WriteLine(res.Sum());
        }
    }
}

using System;
using System.Collections.Generic;
using static System.Console;
using static System.Math;
using System.Linq;
using System.IO;

namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            new Program().Solve(new ConsoleInput(Console.In, ' '));
            Console.Out.Flush();
#if DEBUG
            ReadLine();
#endif
        }


        void Solve(ConsoleInput cin)
        {
            int n = cin.ReadInt;
            int q = cin.ReadInt;

            string s = cin.Read;
            List<Tuple<char, bool>> query = new List<Tuple<char, bool>>();
            for (int i = 0; i < q; i++)
            {
                char c = cin.Read[0];
                bool b = cin.Read == "R"; //true R, false L
                query.Add(new Tuple<char, bool>(c, b));
            }
            query.Reverse();

            char lastRight = (char)0;
            char right = s[n - 1];
            char lastLeft = (char)0;
            char left = s[0];
            int rightCnt = 0;
            int leftCnt = 0;
            int maxRightCnt = 0;
            int maxLeftCnt = 0;
            for (int j = 0; j < q; j++)
            {
                //右から落ちる
                if (query[j].Item1 == right)
                {
                    if (query[j].Item2)
                    {
                        rightCnt++;
                        if (n - rightCnt - 1 >= 0)
                        {
                            lastRight = right;
                            right = s[n - rightCnt - 1];
                        }
                    }
                }
                else if (query[j].Item1 == lastRight)
                {
                    if (!query[j].Item2)
                    {
                        rightCnt = 0;
                        lastRight = (char)0;
                        right = s[n - 1];
                    }
                }

                //左から落ちる
                if (query[j].Item1 == left)
                {
                    if (!query[j].Item2)
                    {
                        leftCnt++;
                        if (leftCnt < n)
                        {
                            lastLeft = left;
                            left = s[leftCnt];
                        }
                    }
                }
                else if (query[j].Item1 == lastLeft)
                {
                    if (query[j].Item2)
                    {
                        leftCnt = 0;
                        lastLeft = (char)0;
                        left = s[0];
                    }
                }
                if (maxRightCnt < rightCnt)
                    maxRightCnt = rightCnt;
                if (maxLeftCnt < leftCnt)
                    maxLeftCnt = leftCnt;
            }

            if (maxLeftCnt + maxRightCnt < n)
            {
                Console.WriteLine(n - (maxLeftCnt + maxRightCnt));
            }
            else
            {
                Console.WriteLine(0);
            }
        }

        class ConsoleInput
        {
            private readonly System.IO.TextReader _stream;
            private char _separator = ' ';
            private Queue<string> inputStream;

            public ConsoleInput(System.IO.TextReader stream, char separator = ' ')
            {
                this._separator = separator;
                this._stream = stream;
                inputStream = new Queue<string>();
            }

            public string Read
            {
                get
                {
                    if (inputStream.Count != 0) return inputStream.Dequeue();
                    string[] tmp = _stream.ReadLine().Split(_separator);
                    for (int i = 0; i < tmp.Length; ++i)
                        inputStream.Enqueue(tmp[i]);
                    return inputStream.Dequeue();
                }
            }

            public string ReadLine { get { return _stream.ReadLine(); } }
            public int ReadInt { get { return int.Parse(Read); } }
            public long ReadLong { get { return long.Parse(Read); } }
            public double ReadDouble { get { return double.Parse(Read); } }
            public string[] ReadStrArray(long N) { var ret = new string[N]; for (long i = 0; i < N; ++i) ret[i] = Read; return ret; }
            public int[] ReadIntArray(long N) { var ret = new int[N]; for (long i = 0; i < N; ++i) ret[i] = ReadInt; return ret; }
            public long[] ReadLongArray(long N) { var ret = new long[N]; for (long i = 0; i < N; ++i) ret[i] = ReadLong; return ret; }
        }
    }
}

using System;
using System.Text;
using System.Collections.Generic;

public class MainCls
{
	public static void Main(string[] args)
	{
		string[] a = Console.ReadLine().Split(' ');
		int n = int.Parse(a[0]);
		int q = int.Parse(a[1]);
		string s = Console.ReadLine();
		Dictionary<char,List<int>> d = new Dictionary<char,List<int>>();
		for(int i = 0; i < s.Length; i++)
		{
			if(!d.ContainsKey(s[i]))
				d.Add(s[i], new List<int>());
			d[s[i]].Add(i);
		}

		for(int i = 0; i < q; i++)
		{
			string[] c = Console.ReadLine().Split(' ');
			if(!d.ContainsKey(c[0][0]))
				continue;

			var k = d[c[0][0]];
			List<int> newData = new List<int>(k.Count);

			for(int j = 0; j < k.Count; j++)
			{
				if((uint)k[j] < s.Length)
				{
					if(c[1] == "L")
						k[j]--;
					else
						k[j]++;

					if((uint)k[j] < s.Length)
					{
						if(s[k[j]]==c[0][0])newData.Add(k[j]);
						else
							d[s[k[j]]].Add(k[j]);
					}
				}
				d[c[0][0]] = newData;
			}
		}

		int output = 0;
		foreach(var m in d.Values)
		{
			foreach(int o in m)
			{
				if(o > -1 && o < s.Length)
					output++;
			}
		}
		Console.WriteLine(output);
	}

}

