                        counter_LL += check_L(i, j, N, used_List_L);
                        if (counter_LL > 1) counter_LL = 1;
                        }
                    }
                if (counter_LL == 1) ansL++;
               // Console.WriteLine(i+" "+counter_LL);
                 counter_LL = 0;
                }
            }
            //Console.WriteLine("ansL="+ansL);
            Console.WriteLine(N-ansR-ansL);
        }
        public static int check_L(int i,int j,int N,List<int>[] used_List_L)
        {
           int counter_L = 0;
            if (i == 0)
            {
                return 1;
            }else if (i == N - 1)
            {
                return 0;
            }
            else
            {
                int x = i + 1;//右隣のマス
                foreach(int num in used_List_L[x])
                {
                    if(num < j)//右隣のマスに大きな呪文番号があるなら
                    {
                        counter_L = 1;
                        break;
                    }
                }
                return counter_L;
            }
        }
        //指定されたマスの右横に大きな数字が入っているか
        // i 今見ているマス　j今見ているマスの呪文番号
        public static int check_R(int i,int j,int N,List<int>[] used_List_R)
        {
            int counter_R = 0;
            if (i == N-1)
            {
                return 1;
            }
            else
            {
                int x = i + 1;//右隣のマス
                foreach(int num in used_List_R[x])
                {
                    if((num > j)&&(num!=max))//右隣のマスに大きな呪文番号があるなら
                    {
                        counter_R = 1;
                        break;
                    }
                }
