		public static void C()
		{
			Scanner cin = new Scanner();

			int n = cin.NextInt();
			int ne = n - 1;

			int q = cin.NextInt();
			string s = cin.Next();
			int[] g = new int[n];
			for (int i = 0; i < n; ++i) {
				g[i] = 1;
			}

