								g[j] = 0;
							} else {
								g[j - 1] += g[j];
								g[j] = 0;
							}
						} else {
							if (j == ne) {
								g[ne] = 0;
							} else {
								g[j + 1] += g[j];
								g[j] = 0;
							}
						}

					}
				}

			}

