    public static void Main(string[] args)
    {
        int N = Scanner.Int;
        int Q = Scanner.Int;

        string s = Scanner.String;

        int[] t = new int[Q];
        bool[] d = new bool[Q];
        foreach (int q in Enumerable.Range(0, Q))
        {
            t[q] = Scanner.String[0];
            d[q] = Scanner.String[0] == 'L';
        }

        Func<int, bool> isOk = (i) =>
        {
            int now = s[i];
            foreach(int q in Enumerable.Range(0, Q))
            {
                if(now == t[q])
                {
                    if(d[q])
                    {
                        i--;
                    }
                    else
                    {
                        i++;
                    }

                    if (i < 0 || i >= N) return false;

                    now = s[i];
                }
            }

            return true;
        };

        int L = Enumerable.Range(0, N).LeftBinarySearchIndex(isOk);
        int R = Enumerable.Range(0, N).RightBinarySearchIndex(isOk);

        if (L == R)
        {
            Console.WriteLine(isOk(L) ? 1 : 0);
        }
        else
        {
            Console.WriteLine(R - L + 1);
        }

        Console.ReadLine();
    }
}

