using System;
using System.Collections.Generic;
using System.Linq;
using BitArray = System.Collections.BitArray;
using BigInteger = System.Numerics.BigInteger;

namespace AtCoderProject
{
    public class Program
    {
        public object Calc()
        {
            var line = consoleReader.ReadLineSplitInt32();
            var N = line[0];
            var Q = line[1];

            var s = consoleReader.ReadLine();
            var golems = Enumerable.Repeat(1, N).ToArray();

            var tds = consoleReader.RepeatReadLinesSplit(Q);

            var sum = N;


            var dicIndex = new Dictionary<char, List<int>>();
            for (int i = 0; i < s.Length; i++)
            {
                List<int> list;
                if (dicIndex.TryGetValue(s[i], out list))
                {
                    list.Add(i);
                }
                else
                {
                    dicIndex[s[i]] = new List<int> { i };
                }
            }


            foreach (var td in tds)
            {
                var t = td[0][0];
                var toRight = td[1] == "R";

                foreach (var i in ((IList<int>)dicIndex.GetOrDefault(t) ?? Array.Empty<int>()))
                {
                    if (toRight)
                    {
                        if (i != N - 1)
                            golems[i + 1] += golems[i];
                        else
                            sum -= golems[i];
                    }
                    else
                    {
                        if (i != 0)
                            golems[i - 1] += golems[i];
                        else
                            sum -= golems[i];
                    }
                    golems[i] = 0;
                }
            }

            return sum;
        }

        private readonly ConsoleReader consoleReader;
        public Program() : this(new ConsoleReader()) { }
        public Program(ConsoleReader consoleReader) { this.consoleReader = consoleReader; }
        static void Main() => Console.WriteLine(new Program().Calc());
    }

    public class ConsoleReader
    {
        public virtual string ReadLine() => Console.ReadLine();
        public int ReadLineInt32() => int.Parse(ReadLine());
        public long ReadLineInt64() => long.Parse(ReadLine());
        public ulong ReadLineUInt64() => ulong.Parse(ReadLine());
        public double ReadLineDouble() => double.Parse(ReadLine());
        public string[] ReadLineSplit() => ReadLine().Split().ToArray();
        public int[] ReadLineSplitInt32() => ReadLine().Split().Select(s => int.Parse(s)).ToArray();
        public long[] ReadLineSplitInt64() => ReadLine().Split().Select(s => long.Parse(s)).ToArray();
        public ulong[] ReadLineSplitUInt64() => ReadLine().Split().Select(s => ulong.Parse(s)).ToArray();
        public double[] ReadLineSplitDouble() => ReadLine().Split().Select(s => double.Parse(s)).ToArray();

        public IEnumerable<string> RepeatReadLines(int count)
        {
            for (int i = 0; i < count; i++)
                yield return ReadLine();
        }
        public IEnumerable<int> RepeatReadLinesInt32(int count)
        {
            for (int i = 0; i < count; i++)
                yield return ReadLineInt32();
        }
        public IEnumerable<long> RepeatReadLinesInt64(int count)
        {
            for (int i = 0; i < count; i++)
                yield return ReadLineInt64();
        }
        public IEnumerable<string[]> RepeatReadLinesSplit(int count)
        {
            for (int i = 0; i < count; i++)
                yield return ReadLineSplit();
        }
    }
    static class DicExt
    {
        public static V GetOrDefault<K, V>(this Dictionary<K, V> dic, K key, V defaultValue = default(V))
        {
            V val;
            return dic.TryGetValue(key, out val) ? val : defaultValue;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Text;


class Program
{
    public static void Main(string[] args)
    {
        var ss = Console.ReadLine().Split();
        var N = int.Parse(ss[0]);
        var Q = int.Parse(ss[1]);
        var s = Console.ReadLine();

        var curr = new int[N];
        for (int i = 0; i < N; i++)
            curr[i] = 1;

        var mojitable = new List<int>[26];
        for (int i = 0; i < 26; i++)
            mojitable[i] = new List<int>();

        for (int i = 0; i < N; i++)
            mojitable[s[i] - 'A'].Add(i);

        for (int i = 0; i < Q; i++)
        {
            var sss = Console.ReadLine().Split();
            var mark = sss[0][0] - 'A';
            var inc = sss[1][0] == 'L' ? -1 : 1;

            foreach (var index in mojitable[mark])
            {
                var cn = curr[index];
                curr[index] = 0;
                switch (inc)
                {
                    case -1:
                        if (index > 0)
                            curr[index - 1] += cn;
                        break;
                    case 1:
                        if (index < (N - 1))
                            curr[index + 1] += cn;
                        break;
                }
            }
        }

        Console.WriteLine(curr.Sum());
    }
}

using System;
using System.Collections.Generic;
