namespace AtCoderTemplate {
    class Program {
        static void Main (string[] args) {
            var NQ = ReadInts ();
            var N = NQ[0];
            var Q = NQ[1];
            var s = Console.ReadLine ();
            var t = new char[Q];
            var d = new char[Q];
            foreach (var i in Enumerable.Range (0, Q)) {
                var td = Console.ReadLine ();
                t[i] = td[0];
                d[i] = td[2];
            }

            var indexesDirectory = new Dictionary<char, Queue<int>> ();
            var rightIndexesDirectory = new Dictionary<char, Stack<int>> ();
            foreach (var c in Enumerable.Range ('A', 'Z' - 'A' + 1).Select (i => (char) i)) {
                indexesDirectory.Add (c, new Queue<int> ());
                rightIndexesDirectory.Add (c, new Stack<int> ());
            }
            foreach (var i in Enumerable.Range (0, N)) {
                indexesDirectory[s[i]].Enqueue (i);
                rightIndexesDirectory[s[i]].Push (i);
            }

            var golems = Enumerable.Repeat (1, N).ToArray ();

            foreach (var i in Enumerable.Range (0, Q)) {
                if (d[i] == 'L') {
                    foreach (var index in indexesDirectory[t[i]]) {
                        if (index == 0) {
                            golems[index] = 0;
                        } else {
                            golems[index - 1] += golems[index];
                            golems[index] = 0;
                        }
                    }
                } else {
                    foreach (var index in rightIndexesDirectory[t[i]]) {
                        if (index == N - 1) {
                            golems[index] = 0;
                        } else {
                            golems[index + 1] += golems[index];
                            golems[index] = 0;
                        }
                    }
                }
            }

            Console.WriteLine (golems.Sum ());
        }
