class Program
{
    public static void Main(string[] args)
    {
        var ss = Console.ReadLine().Split();
        var N = int.Parse(ss[0]);
        var Q = int.Parse(ss[1]);
        var s = Console.ReadLine();

        var antPositions = new Dictionary<int, int>();
        for (int i = 0; i < N; i++)
            antPositions[i] = 1;

        var mojitable = new List<int>[26];
        for (int i = 0; i < 26; i++)
            mojitable[i] = new List<int>();

        for (int i = 0; i < N; i++)
            mojitable[s[i] - 'A'].Add(i);

        for (int i = 0; i < Q; i++)
        {
            var sss = Console.ReadLine().Split();
            var mark = sss[0][0] - 'A';
            var inc = sss[1][0] == 'L' ? -1 : 1;

            foreach (var index in mojitable[mark])
            {
                if (!antPositions.Keys.Contains(index))
                    continue;
                var cn = antPositions[index];
                antPositions.Remove(index);
                switch (inc)
                {
                    case -1:
                        if (index > 0)
                        {
                            if (antPositions.Keys.Contains(index - 1))
                            {
                                antPositions[index - 1] += cn;
                            }
                            else
                            {
                                antPositions[index - 1] = cn;
                            }
                        }
                        break;
                    case 1:
                        if (index < (N - 1))
                        {
                            if (antPositions.Keys.Contains(index + 1))
                            {
                                antPositions[index + 1] += cn;
                            }
                            else
                            {
                                antPositions[index + 1] = cn;
                            }
                        }
                        break;
                }
            }
            if (antPositions.Count == 0)
                break;
        }

        Console.WriteLine(antPositions.Values.Sum());
    }
}

