            var Q = NQ[1];
            var s = Console.ReadLine ();
            var t = new List<char> ();
            var d = new List<char> ();
            foreach (var i in Enumerable.Range (0, Q)) {
                var td = Console.ReadLine ();
                t.Add (td[0]);
                d.Add (td[2]);
            }

            var indexesDirectory = new Dictionary<char, IEnumerable<int>> ();
            foreach (var c in Enumerable.Range ('A', 'Z' - 'A' + 1).Select (i => (char) i)) {
                indexesDirectory.Add (c, new List<int> ());
            }
            foreach (var i in Enumerable.Range (0, N)) {
                indexesDirectory[s[i]] = indexesDirectory[s[i]].Append (i);
            }

            var golems = Enumerable.Repeat (1, N).ToList ();

            foreach (var i in Enumerable.Range (0, Q)) {
