namespace AtCoderProject
{
    public class Program
    {
        public object Calc()
        {
            var line = consoleReader.ReadLineSplitInt32();
            var N = line[0];
            var Q = line[1];

            var s = consoleReader.ReadLine();
            var golems = Enumerable.Repeat(1, N).ToArray();

            var tds = consoleReader.RepeatReadLinesSplit(Q);

            var sum = N;


            var dicIndex = new Dictionary<char, List<int>>();
            for (int i = 0; i < s.Length; i++)
            {
                List<int> list;
                if (dicIndex.TryGetValue(s[i], out list))
                {
                    list.Add(i);
                }
                else
                {
                    dicIndex[s[i]] = new List<int> { i };
                }
            }


            foreach (var td in tds)
            {
                var t = td[0][0];
                var toRight = td[1] == "R";

                List<int> list;
                if (!dicIndex.TryGetValue(t, out list)) continue;

                if (toRight)
                {
                    foreach (var i in Enumerable.Reverse(list))
                    {
                        if (i != N - 1)
                            golems[i + 1] += golems[i];
                        else
                            sum -= golems[i];
                        golems[i] = 0;
                    }
                }
                else
                {
                    foreach(var i in list)
                    {
                        if (i != 0)
                            golems[i - 1] += golems[i];
                        else
                            sum -= golems[i];
                        golems[i] = 0;
                    }
                }
            }

            return sum;
        }

        private readonly ConsoleReader consoleReader;
        public Program() : this(new ConsoleReader()) { }
        public Program(ConsoleReader consoleReader) { this.consoleReader = consoleReader; }
        static void Main() => Console.WriteLine(new Program().Calc());
    }

