		public static void C()
		{
			Scanner cin = new Scanner();

			int n = cin.NextInt();
			int ne = n - 1;

			int q = cin.NextInt();
			string s = cin.Next();
			int[] s2 = new int[n];
			for (int j = 0; j < n; ++j) {
				s2[j] = s[j];
			}

			int[] t = new int[q];
			int[] d = new int[q];
			for (int i = 0; i < q; ++i) {
				t[i] = (int)cin.Next()[0];
				d[i] = cin.Next()[0] == 'L' ? -1 : 1;
			}

			int count = n;

			int p = 0;
			int dead = 0;
			for (int i = q - 1; i >= 0; --i) {
				if (p < n) {
					if (t[i] == s2[p] && d[i] == -1) {
						++dead;
						++p;
					} else if (p > 0) {
						if (t[i] == s2[p - 1] && d[i] == 1) {
							dead = 0;
							p = 0;
						}
					}
				}
			}

			count -= dead;

			int p2 = p;
			p = n - 1;
			dead = 0;
			for (int i = q - 1; i >= 0; --i) {
				if (p > p2) {
					if (t[i] == s2[p] && d[i] == 1) {
						++dead;
						--p;
					} else if (p < n - 1) {
						if (t[i] == s2[p + 1] && d[i] == -1) {
							dead = 0;
							p = n - 1;
						}
					}
				}
			}

			count -= dead;

