        public static int GetLeftBnd(int l,int r)
        {
            if (l == r)
            {
                if (IsLeftBnd(l))
                {
                    return l + 1;
                }
                else
                {
                    return l;
                }
            }
            else if (r - l == 1)
            {
                if (IsLeftBnd(r))
                {
                    return r + 1;
                }
                else if (IsLeftBnd(l))
                {
                    return r;
                }
                else
                {
                    return l;
                }
            }
            else
            {
                int mid = (l + r) / 2;
                if (IsLeftBnd(mid))
                {
                    l = mid;
                    return GetLeftBnd(l, r);
                }
                else
                {
                    r = mid;
                    return GetLeftBnd(l, r);
                }
            }
        }

        public static int GetRightBnd(int l, int r)
        {
            if (l == r)
            {
                if (IsRightBnd(r))
                {
                    return r - 1;
                }
                else
                {
                    return r;
                }
            }
            else if (r - l == 1)
            {
                if (IsRightBnd(l))
                {
                    return l-1;
                }
                else if (IsRightBnd(r))
                {
                    return l;
                }
                else
                {
                    return r;
                }
            }
            else
            {
                int mid = (l + r) / 2;
                if (IsRightBnd(mid))
                {
                    r = mid;
                    return GetRightBnd(l, r);
                }
                else
                {

                    l = mid;
                    return GetRightBnd(l, r);
                }
            }
        }

