    class Program
    {
        static void Main(string[] args)
        {
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            new Program().Solve(new ConsoleInput(Console.In, ' '));
            Console.Out.Flush();
#if DEBUG
            ReadLine();
#endif
        }


        void Solve(ConsoleInput cin)
        {
            int n = cin.ReadInt;
            int q = cin.ReadInt;

            string s = cin.Read;
            List<Tuple<char, bool>> query = new List<Tuple<char, bool>>();
            for (int i = 0; i < q; i++)
            {
                char c = cin.Read[0];
                bool b = cin.Read == "R"; //true R, false L
                query.Add(new Tuple<char, bool>(c, b));
            }
            query.Reverse();

            char right = s[n - 1];
            char left = s[0];
            int rightCnt = 0;
            int leftCnt = 0;
            for (int j = 0; j < q; j++)
            {
                //右から落ちる
                if (query[j].Item1 == right)
                {
                    if (query[j].Item2)
                    {
                        rightCnt++;
                        if (n - rightCnt - 1 >= 0)
                            right = s[n - rightCnt - 1];
                    }
                }

                //左から落ちる
                if (query[j].Item1 == left)
                {
                    if (!query[j].Item2)
                    {
                        leftCnt++;
                        if (leftCnt < n)
                            left = s[leftCnt];
                    }
                }
            }

            if (leftCnt + rightCnt < n)
            {
                Console.WriteLine(n - (leftCnt + rightCnt));
            }
            else
            {
                Console.WriteLine(0);
            }
        }

