class Solver
{
    public void Solve(Scanner sc)
    {
        int N, Q;
        sc.Make(out N, out Q);
        var S = ReadLine();
        var TD = new Pair<char, char>[Q];
        for (var i = 0; i < Q; i++) TD[i] = new Pair<char, char>(sc.Next<char>(), sc.Next<char>());
        int lr = N, ll = -1;
        while (lr - ll > 1)
        {
            var m = (lr + ll) >> 1;
            int now = m;
            for (int j = 0; j < Q; j++)
            {
                if (TD[j].v1 != S[now]) continue;
                if (TD[j].v2 == 'L') now--;
                else now++;
                if (now < 0 || N <= now) break;
            }
            if (now == -1) ll = m;
            else lr = m;
        }
        int rr = N, rl = -1;
        while (rr - rl > 1)
        {
            var m = (rr + rl) >> 1;
            int now = m;
            for (int j = 0; j < Q; j++)
            {
                if (TD[j].v1 != S[now]) continue;
                if (TD[j].v2 == 'L') now--;
                else now++;
                if (now < 0 || N <= now) break;
            }
            if (now == N) rr = m;
            else rl = m;
        }
        WriteLine(rl - lr+1);
    }
}
