				if (i < 0 || i >= n) break;
			}
			return i;
		};

		int ll = 0, lr = n;
		while (ll < lr)
		{
			var m = (ll + lr + 1) / 2;
			if (move(m - 1) == -1) ll = m;
			else lr = m - 1;
		}

		int rl = 0, rr = n;
		while (rl < rr)
		{
			var m = (rl + rr + 1) / 2;
			if (move(n - m) == n) rl = m;
			else rr = m - 1;
		}
		Console.WriteLine(n - ll - rl);
	}
}

