        var s = Console.ReadLine();

        var antPositions = new int[N];
        for (int i = 0; i < N; i++)
            antPositions[i] = 1;

        var mojitable = new List<int>[26];
        for (int i = 0; i < 26; i++)
            mojitable[i] = new List<int>();

        for (int i = 0; i < N; i++)
            mojitable[s[i] - 'A'].Add(i);

        for (int i = 0; i < Q; i++)
        {
            var sss = Console.ReadLine().Split();
            var mark = sss[0][0] - 'A';
            var inc = sss[1][0] == 'L' ? -1 : 1;

            foreach (var index in mojitable[mark])
            {
                if (antPositions[index] == 0)
                   continue;
                var cn = antPositions[index];
                antPositions[index] = 0;
                switch (inc)
                {
                    case -1:
                        if (index > 0)
                        {
                            antPositions[index - 1] += cn;
                        }
                        break;
                    case 1:
                        if (index < (N - 1))
                        {
                            antPositions[index + 1] += cn;
                        }
                        break;
                }
            }
            if (antPositions.All(n => n == 0))
            {
                Console.WriteLine(0);
                return;
            }
        }

