        public object Calc()
        {
            var line = consoleReader.ReadLineSplitInt32();
            var N = line[0];
            var Q = line[1];

            var s = consoleReader.ReadLine();
            var golems = Enumerable.Repeat(1, N).ToArray();

            var tds = consoleReader.RepeatReadLinesSplit(Q);

            var sum = N;

            foreach (var td in tds)
            {
                var t = td[0][0];
                var toRight = td[1] == "R";

                for (int i = 0; i < N; i++)
                {
                    if (t == s[i])
                    {
                        if (toRight)
                        {
                            if (i != N - 1)
                                golems[i+1] += golems[i];
                            else
                                sum -= golems[i]; 
                        }
                        else
                        {
                            if (i != 0)
                                golems[i - 1] += golems[i];
                            else
                                sum -= golems[i];
                        }
                        golems[i] = 0;
                    }
                }
            }

            return sum;
        }

