            var dict = new Dictionary<char, List<int>>();
            foreach (var letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ") dict[letter] = new List<int>();
            for (int i = 0; i < N; i++) dict[s[i]].Add(i);

            var cells = Replicate(N, 1).ToList();

            var moves = Q.Times(() => new { place = ReadString(), direction = ReadString() }).ToList();

            foreach (var move in moves) {
                var places = dict[move.place[0]];
                if (move.direction == "L") {
                    foreach (var place in places.OrderBy(x => x)) {
                        if (place != 0) cells[place - 1] += cells[place];
                        cells[place] = 0;
                    }
                } else {
                    foreach (var place in places.OrderByDescending(x => x)) {
                        if (place != N - 1) cells[place + 1] += cells[place];
                        cells[place] = 0;
                    }
                }
            }

            cells.Sum().WriteLine();
        }
    }
}

