    class Square
    {
        char name;
        Square left = null;
        Square right = null;
        int stack = 1;
        int removeStack = 0;
        int addStack = 0;

        public int Stack { get => stack; set => stack = value; }

        public Square(int pos, Square[] squares)
        {
            if (pos != 0)
            {
                left = squares[pos - 1];
                left.Connect(this);
            }
        }
        public void Connect(Square right)
        {
            this.right = right;
        }
        public void ClearStack()
        {
            Stack += addStack;
            Stack -= removeStack;
            removeStack = 0;
            addStack = 0;
        }
        public void MovedFrom(int golems)
        {
            addStack += golems;
        }
        public void MoveLeft()
        {
            if (left != null)
                left.MovedFrom(Stack);
            removeStack = Stack;
        }
        public void MoveRight()
        {
            if (right != null)
                right.MovedFrom(Stack);
            removeStack = Stack;
        }
    }

