using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
static string[] input = Console.ReadLine().Split(' ');
static int n = int.Parse(input[0]);
static int q = int.Parse(input[1]);
static string s = Console.ReadLine();
static char[] aas = new char[q];
static char[] bbs = new char[q];
static int leftDrop = 0;
static int rightDrop = 0;

	static void Main()
	{
    for(int i = 0; i < q; i++)
    {
      var nums = Console.ReadLine().Split(' ');//１行ごとに受け取る
      aas[i] = nums[0][0];
      bbs[i] = nums[1][0];
    }

    leftDrop = SearchLeft(0, n);
    rightDrop = SearchRight(0, n);

    //Console.WriteLine(n+" " +leftDrop+" "+rightDrop);
    Console.WriteLine(n-leftDrop-rightDrop);  
	}

  static int SearchLeft(int min, int max)//二分探索法で最大値を求める
  {
    while (true)
    {
      int mid = min + (max - min) / 2;
      if(CheckLeft(mid)) min = mid;//さらに大きくても成り立つかも
      else max = mid;

      if(max - min <= 1)
      {
        if(CheckLeft(max)) 
        {
          return max;//最大値で成り立つかの確認を優先
        }
        else
        {
          return min;
        }
      break;
      }  
    }
  }

  static int SearchRight(int min, int max)//二分探索法で最大値を求める
  {
    while (true)
    {
      int mid = min + (max - min) / 2;
      if(CheckRight(mid)) min = mid;//さらに大きくても成り立つかも
      else max = mid;

      if(max - min <= 1)
      {
        if(CheckRight(max)) 
        {
          return max;//最大値で成り立つかの確認を優先
        }
        else
        {
          return min;
        }
      break;
      }  
    }
  }

  static bool CheckLeft(int testNum)
  {
    int nowPosition = testNum-1;
    if(nowPosition < 0) return true;

    for(int i = 0; i < q; i++)
    {
      if(aas[i] == s[nowPosition])
      {
        if(bbs[i] == 'L') nowPosition--;
        else nowPosition++;
      }
      if(nowPosition < 0) return true;
      else if(nowPosition >= n) return false;
    }

    return false;
  }

  static bool CheckRight(int testNum)
  {
    int nowPosition = n-testNum;
    if(nowPosition >= n) return true;

    for(int i = 0; i < q; i++)
    {
      if(aas[i] == s[nowPosition])
      {
        if(bbs[i] == 'L') nowPosition--;
        else nowPosition++;
      }
      if(nowPosition >= n) return true;
      else if(nowPosition < 0) return false;
    }

    return false;
  }

}

