                if (query[1] == 'L')
                {
                    if (s[dp[i][0]] == query[0])
                    {
                        dp[i][0]++;
                    }
                }
            }

            long ans = nq[0];
            ans -= dp[nq[1]][0];
            ans -= nq[0] - dp[nq[1]][1] - 1;

            Console.WriteLine(ans);
        }
    }
