class AtCoder
{
    const int MOD = 1000000007;
    int LastPos(int start, string cells, string[][] command)
    {
        int pos = start;
        foreach(var cmd in command)
        {
            if(cmd[0][0] == cells[pos])
            {
                if(cmd[1] == "L")
                    pos--;
                else
                    pos++;
            }
            if(pos < 0 || pos >= cells.Length)
                break;
        }
        return pos;
    }
    public void Slove()
    {
        var inputs = Console.ReadLine().Split();
        int n = int.Parse(inputs[0]);
        int q = int.Parse(inputs[1]);

        string cells = Console.ReadLine();
        string[][] command =
            Enumerable.Range(0, q)
            .Select(x => Console.ReadLine().Split())
            .ToArray();
        int right = -1, left = n;
        for(int start = 0, end = n - 1, mid = (start + end) / 2;start <= end; mid = (start + end) / 2)
        {
            int p = LastPos(mid, cells, command);
            if(p == -1)
            {
                right = mid;
                start = mid + 1;                
            }
            else
            {
                end = mid - 1;
            }
        }
        for(int start = 0, end = n - 1, mid = (start + end) / 2;start <= end; mid = (start + end) / 2)
        {
            int p = LastPos(mid, cells, command);
            if(p == n)
            {
                left = mid;
                end = mid - 1;                
            }
            else
            {
                start = mid + 1;
            }
        }
        //System.Console.WriteLine($"{right} {left}");
        int result = left - right - 1;
        System.Console.WriteLine(result);
    }
    static void Main()
    {
        var ac = new AtCoder();
        ac.Slove();
    }
}

using System;
