using System.Diagnostics;

static class CodeJam
{
    class Query
    {
        public readonly char t;
        public readonly char d;
        public Query(string[] args)
        {
            t = args[0][0];
            d = args[1][0];
        }
    }

    static int Go(int i, int N, string s, Query[] queries)
    {
        foreach (var q in queries)
        {
            if (s[i] == q.t)
            {
                switch (q.d)
                {
                case 'L': if (--i < 0) { return -1; } break;
                case 'R': if (++i >= N) { return 1; } break;
                }
            }
        }
        return 0;
    }

    static int Solve(int N, int Q, string s, Query[] queries)
    {
        int l;
        {
            if (Go(0, N, s, queries) >= 0) { l = 0; }
            else if (Go(N - 1, N, s, queries) < 0) { l = N; }
            else
            {
                int ng = 0;
                int ok = N - 1;
                while (ok - ng >= 2)
                {
                    int m = (ng + ok) / 2;
                    if (Go(m, N, s, queries) >= 0) { ok = m; } else { ng = m; }
                }
                l = ok;
            }
        }
        int r;
        {
            if (Go(0, N, s, queries) > 0) { r = -1; }
            else if (Go(N - 1, N, s, queries) <= 0) { r = N - 1; }
            else
            {
                int ok = 0;
                int ng = N - 1;
                while (ng - ok >= 2)
                {
                    int m = (ng + ok) / 2;
                    if (Go(m, N, s, queries) <= 0) { ok = m; } else { ng = m; }
                }
                r = ok;
            }
        }
        return Math.Max(r - l + 1, 0);
    }

    static void Main(string[] args)
    {
        int[] V1 = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        int N = V1[0], Q = V1[1];
        var s = Console.ReadLine();
        var queries = new Query[Q];
        for (int i = 0; i < Q; ++i)
        {
            queries[i] = new Query(Console.ReadLine().Split());
        }
        Console.WriteLine(Solve(N, Q, s, queries));
    }
}

