namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' '); 
            int n = Int32.Parse(input[0]);
            int q = Int32.Parse(input[1]);
            string s = Console.ReadLine();
            int[] glm = new int[n];

            //init glm
            for(int i = 0; i < n; i++)
            {
                glm[i] = 1;
            }

            Dictionary<char, int[]> dict = new Dictionary<char, int[]>(); 
            List<int> ls;
            for(int i = 0; i < s.Length; i++)
            {
                if(dict.ContainsKey(s[i]))
                {
                    continue;
                }

                ls = new List<int>();

                int index = -1;
                while(true)
                {
                    index = s.IndexOf(s[i], index + 1);

                    if(index > -1){
                        ls.Add(index);
                    }else
                    {
                        break;
                    }
                }

                dict.Add(s[i], ls.ToArray());
            }

            char[] t = new char[q];
            char[] d = new char[q];
            for(int i = 0; i < q; i++)
            {
                input = Console.ReadLine().Split(' ');

                t[i] = input[0][0];
                d[i] = input[1][0];
            }

            int cnt = n;            
            for(int i = 0; i < q; i++)
            {
                if(!s.Contains(t[i]))
                {
                    continue;
                }

                if(d[i] == 'L')
                {
                    var indexList = dict[t[i]];
                    foreach(int j in indexList)
                    {
                        if(s[j] == t[i])
                        {
                            if(j > 0)
                            {
                                glm[j-1] += glm[j];
                            }
                            else
                            {
                                cnt -= glm[j];
                            }

                            glm[j] = 0;
                        }
                    }
                }
                else
                {
                    var indexList = dict[t[i]];
                    for(int k = indexList.Length - 1;  k > -1; k--)
                    {
                        int j = indexList[k];

                        if(s[j] == t[i])
                        {
                            if(j + 1 < s.Length)
                            {
                                glm[j+1] += glm[j];
                            }
                            else
                            {
                                cnt -= glm[j];
                            }

                            glm[j] = 0;
                        }
                    }
                }
            }

            Console.WriteLine(cnt);
        }      
    }
}

