                }

                memo[s[i]].Add(i + 1);
            }

            foreach (var td in tdList)
            {
                var t = td[0][0];
                var d = td[1][0];
                var dd = d == 'L' ? -1 : 1;

                if (!memo.ContainsKey(t)) continue;

                foreach (var i in memo[t])
                {
                    var next = i + dd;
                    golemCountList[next] += golemCountList[i];
                    golemCountList[i] = 0;
                }
            }

            var output = s.Length - golemCountList[0] - golemCountList.Last();
            Console.WriteLine(output);
        }
    }
}

