using static System.Console;

class Program
{
    static void Main()
    {
        var NQ = ReadLine().Split().Select(int.Parse).ToArray();
        var N = NQ[0];
        var Q = NQ[1];
        var s = ReadLine();
        var t = new char[Q];
        var d = new char[Q];
        for (int i = 0; i < Q; i++)
        {
            var line = ReadLine();
            t[i] = line[0];
            d[i] = line[2];
        }

        var min = N / 2;
        var max = N / 2;
        var ng = 0;
        var ok = N;
        while (ok - ng != 1)
        {
            var r = Alive(min, s, Q, t, d);
            if (r == 'L')
            {
                ng = min;
            }
            else
            {
                ok = min;
            }
            min = (ng + ok) / 2;
        }
        min = ng;
        ok = 0;
        ng = N;
        while (ng - ok != 1)
        {
            var r = Alive(max, s, Q, t, d);
            if (r == 'R')
            {
                ng = max;
            }
            else
            {
                ok = max;
            }
            max = (ng + ok) / 2;
        }
        max = ng;
        WriteLine(max - min - 1);
    }

    static char Alive(int idx, string s, int Q, char[] t, char[] d)
    {
        for (int i = 0; i < Q; i++)
        {
            if (s[idx] == t[i])
            {
                if (d[i] == 'R') idx++;
                else idx--;
                if (idx == s.Length) return 'R';
                if (idx == -1) return 'L';
            }
        }
        return 'A';
    }
}

