{
    private static IEnumerator<string> enumerator = Enumerator();
    private static IEnumerator<string> Enumerator()
    {
        while (true)
        {
            foreach (string s in Console.ReadLine().Split(' '))
            {
                yield return s;
            }
        }
    }

    public static string String
    {
        get
