namespace AtCoder {
    using VI = VectorInt2;

    static class Program {

        static void Main() {
            var N = ReadInt();
            var Q = ReadInt();
            var s = ReadString();

            var dict = new Dictionary<char, List<int>>();
            foreach (var letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ") dict[letter] = new List<int>();
            for (int i = 0; i < N; i++) dict[s[i]].Add(i);

            var cells = Replicate(N, 1).ToList();

            var moves = Q.Times(() => new { place = ReadString(), direction = ReadString() }).ToList();

            var sortedMoves = moves.Select(move => new {
                direction = move.direction,
                    ascendingPlaces = dict[move.place[0]].OrderBy(Id).ToList(),
                    descendingPlaces = dict[move.place[0]].OrderByDescending(Id).ToList()
            }).ToList();

            foreach (var move in sortedMoves) {
                if (move.direction == "L") {
                    foreach (var place in move.ascendingPlaces) {
                        if (place != 0) cells[place - 1] += cells[place];
                        cells[place] = 0;
                    }
                } else {
                    foreach (var place in move.descendingPlaces) {
                        if (place != N - 1) cells[place + 1] += cells[place];
                        cells[place] = 0;
                    }
                }
            }

            cells.Sum().WriteLine();
        }
    }
}

