using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        var input = Console.ReadLine().Split(' ');
        var N = int.Parse(input[0]);
        var Q = int.Parse(input[1]);
        var s = Console.ReadLine().ToCharArray();

        int[] arr = new int[N];
        for (var i = 0; i < N; i++) {
            arr[i] = 1;
        }

        for (var i = 0; i < Q; i++) {
            input = Console.ReadLine().Split(' ');
            var t = Convert.ToChar(input[0]);
            var d = Convert.ToChar(input[1]);

            if (!s.Contains(t)) continue;

            for (var j = 0; j < N; j++) {
                if (s[j] == t) {
                    if (arr[j] == 0) {
                        continue;
                    }

                    // 左端
                    if (j == 0 && d == 'L') {
                        arr[j] = 0;
                    // 右端
                    } else if (j == (N - 1) && d == 'R') {
                        arr[N - 1] = 0;
                    } else if (d == 'L') {
                        arr[j - 1] += arr[j];
                        arr[j] = 0;
                    } else if (d == 'R') {
                        arr[j + 1] += arr[j];
                        arr[j] = 0;
                    }
                }   
            }
        }

        var cnt = 0;
        for (var i = 0; i < N; i++) {
            cnt += arr[i];
        }

        Console.WriteLine(cnt);
    }
}

