	public class Program
	{
		static void Main(string[] args)
		{
			C();
		}

		public static void C()
		{
			Scanner cin = new Scanner();

			int n = cin.NextInt();
			int ne = n - 1;

			int q = cin.NextInt();
			string s = cin.Next();
			int[] s2 = new int[n];
			for (int j = 0; j < n; ++j) {
				s2[j] = s[j];
			}

			int[] t = new int[q];
			int[] d = new int[q];
			for (int i = 0; i < q; ++i) {
				t[i] = (int)cin.Next()[0];
				d[i] = cin.Next()[0] == 'L' ? -1 : 1;
			}

			int count = n;

			int p = 0;
			int dead = 0;
			for (int i = q - 1; i >= 0; --i) {
				if (t[i] == s2[p] && d[i] == -1) {
					++dead;
					++p;
				} else if (p > 0) {
					if (t[i] == s2[p - 1] && d[i] == 1) {
						dead = 0;
						p = 0;
					}
				}
			}

			count -= dead;

			p = n - 1;
			dead = 0;
			for (int i = q - 1; i >= 0; --i) {
				if (t[i] == s2[p] && d[i] == 1) {
					++dead;
					--p;
				} else if (p < n - 1) {
					if (t[i] == s2[p + 1] && d[i] == -1) {
						dead = 0;
						p = n - 1;
					}
				}
			}

			count -= dead;

			Console.WriteLine(count);
		}






	}

	public class Scanner
	{
		string[] s;
		int i;

		char[] cs = new char[] { ' ' };

		public Scanner()
		{
			s = new string[0];
			i = 0;
		}

		public string Next()
		{
			if (i < s.Length) return s[i++];
			string st = Console.ReadLine();
			while (st == "") st = Console.ReadLine();
			s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
			if (s.Length == 0) return Next();
			i = 0;
			return s[i++];
		}

		public int NextInt()
		{
			return int.Parse(Next());
		}
		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = NextInt() + add;
			}
			return Array;
		}

		public long NextLong()
		{
			return long.Parse(Next());
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = NextLong() + add;
			}
			return Array;
		}

