namespace C_Answer
{
    class Program
    {
        static void Main(string[] args)
        {
            var a = Console.ReadLine().Split(' ');
            int N = int.Parse(a[0]);
            int Q = int.Parse(a[1]);
            var field = Console.ReadLine();
            string[] op;
            List<char> t = new List<char>();
            List<char> d = new List<char>();
            for(int i = 0; i < Q; i++)
            {
                op = Console.ReadLine().Split(' ');
                t.Add(char.Parse(op[0]));
                d.Add(char.Parse(op[1]));
            }

            int min = N / 2;
            int max = N / 2;
            int ng = 0;
            int ok = N;
            while(ok - ng != 1)
            {
                var b = BinSearch(min, field, Q, t, d);
                if (b == 'L')
                {
                    ng = min;
                }
                else
                {
                    ok = min;
                }
                min = (ng + ok) / 2;
            }
            min = ng;
            ng = N;
            ok = 0;
            while(ng - ok != 1)
            {
                var c = BinSearch(max, field, Q, t, d);
                if(c == 'R')
                {
                    ng = max;
                }
                else
                {
                    ok = max;
                }
                max = (ng + ok) / 2;
            }
            max = ng;

            Console.WriteLine(max - min - 1);
        }

        static char BinSearch(int threshold,string s,int q, List<char> t, List<char> d)
        {
            for(int i = 0; i < q; i++)
            {
                if(s[threshold] == t[i])
                {
                    if (d[i] == 'L') threshold--;
                    else threshold++;

                    if (threshold < 0) return 'L';
                    if (threshold >= s.Length) return 'R';
                }
            }
            return 'A';
        }
    }
}

