namespace EXAWIZARDS2019C
{
    public partial class Program
    {
        void Solve(StreamScanner ss, StreamWriter sw)
        {
            //---------------------------------
            var N = ss.Next(int.Parse);
            var Q = ss.Next(int.Parse);
            var S = "0" + ss.Next() + "0";
            var qs = ss.Next(2, Q).Select(a => new{T = a[0][0], D = a[1][0]});

            var left = 1;
            var right = N + 1;

            foreach (var q in qs.Reverse())
            {
                if (q.D == 'L')
                {
                    if (q.T == S[left]) left++;
                    if (q.T == S[right]) right++;
                }
                if (q.D == 'R')
                {
                    if (q.T == S[left - 1]) left--;
                    if (q.T == S[right - 1]) right--;
                }
            }

            sw.WriteLine(right - left);
            //---------------------------------
        }
    }

    public class StreamScanner
    {
        static readonly char[] Separator = {' '};
        readonly StreamReader streamReader;

        string[] line = new string[0];
        int index = 0;

        public StreamScanner(Stream stream)
        {
            this.streamReader = new StreamReader(stream);
        }

        public string Next()
        {
            return Next(s => s);
        }

        public string[] Next(int x)
        {
            return Next(s => s, x);
        }

        public string[][] Next(int x, int y)
        {
            return Next(s => s, x, y);
        }

        public T Next<T>(Func<string, T> parser)
        {
            if (index < line.Length) return parser(line[index++]);
            index = 0;
            line = streamReader.ReadLine()?.Split(Separator, StringSplitOptions.RemoveEmptyEntries);
            return Next(parser);
        }

        public T[] Next<T>(Func<string, T> parser, int x)
        {
            var ret = new T[x];
            for (var i = 0; i < x; ++i) ret[i] = Next(parser);
            return ret;
        }

        public T[][] Next<T>(Func<string, T> parser, int x, int y)
        {
            var ret = new T[y][];
            for (var i = 0; i < y; ++i) ret[i] = Next(parser, x);
            return ret;
        }
    }

