namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' '); 
            int n = Int32.Parse(input[0]);
            int q = Int32.Parse(input[1]);
            string s = Console.ReadLine();
            int[] glm = new int[n];

            //init glm
            for(int i = 0; i < n; i++)
            {
                glm[i] = 1;
            }

            for(int i = 0; i < q; i++)
            {
                input = Console.ReadLine().Split(' ');

                Char t = input[0][0];

                if(input[1] == "L")
                {
                    for(int j = 0;  j < s.Length; j++)
                    {
                        if(s[j] == t)
                        {
                            if(j > 0)
                            {
                                glm[j-1] += glm[j];
                            }

                            glm[j] = 0;
                        }
                    }
                }
                else
                {
                    for(int j = s.Length - 1;  j > -1; j--)
                    {
                        if(s[j] == t)
                        {
                            if(j + 1 < s.Length)
                            {
                                glm[j+1] += glm[j];
                            }

                            glm[j] = 0;
                        }
                    }
                }
            }

            int cnt = 0;
            for(int i = 0; i < n; i++)
            {
