    class Program
    {
        private int N, Q;
        private string S;
        private char[] t, d;
        public void Solve()
        {
            var sc = new Scanner();
            N = sc.NextInt();
            Q = sc.NextInt();
            S = sc.Next();

            t = new char[Q];
            d = new char[Q];
            for (int i = 0; i < Q; i++)
            {
                t[i] = sc.Next()[0];
                d[i] = sc.Next()[0];
            }

            //右から落ちる
            int ok = N;
            int ng = -1;

            while (ok - ng > 1)
            {
                int med = (ok + ng) / 2;
                if (right(med))
                {
                    ok = med;
                }
                else
                {
                    ng = med;
                }

            }

            int ook = -1;
            int nng = N;
            while (nng - ook > 1)
            {
                int med = (ook + nng) / 2;
                if (left(med))
                {
                    ook = med;
                }
                else
                {
                    nng = med;
                }
            }
            //Console.WriteLine(left(0));
            //Console.WriteLine($"{ok} {ook}");
            Console.WriteLine(Math.Max(0, ng - ook));
        }

        bool right(int index)
        {
            for (int i = 0; i < Q; i++)
            {
                if (S[index] == t[i])
                {
                    if (d[i] == 'L')
                    {
                        index--;
                    }
                    else if (d[i] == 'R')
                    {
                        index++;
                    }

                    if (index >= N) return true;
                    if (index < 0) return false;
                }
            }

            return false;
        }

        bool left(int index)
        {
            for (int i = 0; i < Q; i++)
            {
                if (S[index] == t[i])
                {
                    if (d[i] == 'L')
                    {
                        index--;
                    }
                    else if (d[i] == 'R')
                    {
                        index++;
                    }

                    if (index >= N) return false;
                    if (index < 0) return true;
                }
            }

            return false;
        }

        static void Main(string[] args) => new Program().Solve();
    }

