    while (magic_num > counter) {
        magic = stdin[counter+2].split(" ")
        result = []
        masu.forEach((elem, index) => {
            if (elem[0] == magic[0]) {
                if (magic[1] == "L") {
                    point = index - 1
                    if (0 > point) {
                        masu[index][1] = 0
                        next
                    }
                    result.push([point, elem[1]])
