function main(input) {
  const o = new I(input, String);

  const N = Number(o.a());
  const Q = Number(o.a());
  const s = o.a();
  const t = [];
  const d = [];

  for (let i=0; i<Q;i++) {
    t.push(o.a());
    d.push(o.a());
  }

  function testStatus(index) {
    let currentIndex = index;
    let currentChar = s[currentIndex];
    for ( let i = 0; i < Q; i++) {
      if (t[i] === currentChar) {
        if (d[i] === 'L') {
          currentIndex -= 1;
          if (currentIndex < 0) return "LDis";
