    T = Array(Q); D = Array(Q);

    golem = {};
    S = lines.shift().split("");

    for (var i = 0; i < N; i++) {
        golem[i] = {
            now: i,
            alphabet: S[i],
        }
    }

    for (var i = 0; i < Q; i++) {
        tmp = lines[i].split(" ");
        T[i] = tmp[0]; D[i] = tmp[1];
    }
    a = Math.ceil(binary_search(-1, N, "L"));
    b = Math.ceil(binary_search(-1, N, "R"));
    console.log(N - a - Math.abs(b-N));

