func solve(w io.Writer, r io.Reader) {
  sc := NewScanner(r)
  N := sc.nextInt()
  Q := sc.nextInt()
  s := sc.nextString()

  mp := make(map[byte][]int)
  mc := make([]int, N)

  for i, v := range s {
    mp[byte(v)] = append(mp[byte(v)], i)
    mc[i] = 1
  }

  c := N
  for i := 0; i < Q; i++ {
    ts := sc.nextString()
    ds := sc.nextString()
    t, d := ts[0], ds[0]

	var tmp []int
    for _, k := range mp[t] {
      if mc[k] == 0 {
        continue
      }
      var p int
      if d == 'L' {
        if k > 0 {
          p = k - 1
        } else {
          c, mc[k] = c - mc[k], 0
          if c == 0 {
            fmt.Fprint(w, c)
            return
          }
          continue
        }
      } else {
        if k < N-1 {
          p = k + 1
        } else {
          c, mc[k] = c - mc[k], 0
          if c == 0 {
            fmt.Fprint(w, c)
            return
          }
          continue
        }
      }
      if mc[p] == 0 {
        mp[s[p]] = append(mp[s[p]], p)
      }
      mc[p], mc[k] = mc[p] + mc[k], 0
      if s[p] == t {
        tmp = append(tmp, p)
      }
    }
    mp[t] = tmp
  }
  fmt.Fprint(w, c)
}

