	var s string
	fmt.Scan(&s)
	sList := strings.Split(s, "")
	// 呪文の数ループ
	for i := 0; i < q; i++ {
		var t, d string
		fmt.Scan(&t, &d)
		// 移動対象のインデックスたち
		shiftIndexes := make([]int, 0, len(sList))
		// マスの分ループ
		for j := 0; j < len(sList); j++ {
			// 動かす対象か
			if strings.Contains(sList[j], t) {
				shiftIndexes = append(shiftIndexes, j)
			}
		}
		// fmt.Println("sList = ", sList, " shiftIndexes = ", shiftIndexes)
		if d == "L" {
			// 左
			shiftLeft(sList, shiftIndexes)
		} else {
			// 右
			shiftRight(sList, shiftIndexes)
		}
	}
	// fmt.Println("sList = ", sList)
	fmt.Println(countGolem(sList))
}

