const MOD = 1000000000 + 7
const ALPHABET_NUM = 26

var n, q int
var S []rune
var T, D []rune

func main() {
	n, q = ReadInt(), ReadInt()
	S = ReadRuneSlice()
	T, D = make([]rune, q), make([]rune, q)
	for i := 0; i < q; i++ {
		t, d := ReadRuneSlice(), ReadRuneSlice()
		T[i], D[i] = t[0], d[0]
	}

	ng, ok := -1, len(S)
	for int(math.Abs(float64(ok-ng))) > 1 {
		mid := (ok + ng) / 2
		if isRightFall(mid) {
			ok = mid
		} else {
			ng = mid
		}
	}
	right := ok

	ng, ok = len(S), -1
	for int(math.Abs(float64(ok-ng))) > 1 {
		mid := (ok + ng) / 2
		if isLeftFall(mid) {
			ok = mid
		} else {
			ng = mid
		}
	}
	left := ok

	ans := right - left - 1
	fmt.Println(ans)
}

func isRightFall(index int) bool {
	finalIdx := simulate(index)

	if finalIdx == n {
		return true
	}
	return false
}

func isLeftFall(index int) bool {
	finalIdx := simulate(index)

	if finalIdx == -1 {
		return true
	}
	return false
}

func simulate(index int) int {
	curIdx := index

	for i := 0; i < q; i++ {
		t, d := T[i], D[i]
		if S[curIdx] != t {
			continue
		}

		if d == 'L' {
			curIdx--
		} else {
			curIdx++
		}

		if curIdx == -1 || curIdx == n {
			return curIdx
		}
	}

	return curIdx
}

