func shiftLeftToIndex(list []string, index int) {
	if index == 0 {
		list[0] = ""
	} else {
		tmp := list[index]
		list[index] = ""
		list[index-1] += tmp
	}
}

func shiftLeft(list []string, indexList []int) {
	for _, i := range indexList {
		shiftLeftToIndex(list, i)
	}
}

func shiftRightToIndex(list []string, index int) {
	if index == len(list)-1 {
		list[len(list)-1] = ""
	} else {
		tmp := list[index]
		list[index] = ""
		list[index+1] += tmp
	}
}

func shiftRight(list []string, indexList []int) {
	sort.Sort(sort.Reverse(sort.IntSlice(indexList)))
	for _, i := range indexList {
		shiftRightToIndex(list, i)
	}
}

func countGolem(list []string) int {
	count := 0
	for _, v := range list {
		count += len(v)
	}
	return count
}

