  s := input.NextLine()
  x := make([]int,n+2)
  t := make([]int,q)
  d := make([]int,q)
  for i:=1;i<n+1;i++ { x[i] = int([]rune(s[i-1:i])[0])-64 }
  for i:=0;i<q;i++ { t[i],d[i] = input.NextStrings() }
  l,sup := 0,n+1
  for sup-l > 1 {
    m := (sup+l)/2
    y := m
    for i:=0;i<q;i++ {
      if x[y] == t[i] { y += d[i] }
    }
    if y == 0 {
      l = m
    } else {
      sup = m
    }
  }
  inf,r := 0,n+1
  for r-inf > 1 {
    m := (r+inf)/2
    y := m
    for i:=0;i<q;i++ {
      if x[y] == t[i] { y += d[i] }
    }
    if y == n+1 {
      r = m
    } else {
      inf = m
    }
  }
  fmt.Println(r-l-1)
}

type Input struct { reader *bufio.Reader }
func(i *Input) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := i.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextStrings() (int,int) {
  s := strings.Split(i.NextLine()," ")
  n := int([]rune(s[0])[0])-64
  m := 1
  if s[1] == "L" { m = -1 }
  return n,m
}
func(i *Input) NextInts() (int,int) {
  s := strings.Split(i.NextLine()," ")
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  return x,y
}

