		if pos == -1 {
			return -1
		} else if pos == len(s) {
			return 1
		}
	}
	return 0
}

func solve(s string, qs []Pair) int {
	n := len(s)
	var low, high int

	low, high = -1, n
	for high-low > 1 {
		mid := (high + low) / 2
		if simulate(s, qs, mid) == -1 {
			low = mid
		} else {
			high = mid
		}
	}
	nLeftFall := high

	low, high = -1, n
	for high-low > 1 {
		mid := (high + low) / 2
		if simulate(s, qs, mid) == 1 {
			high = mid
		} else {
			low = mid
		}
	}
	nRightFall := n - 1 - low

	return n - (nLeftFall + nRightFall)
}

