func main() {
	protagonist(os.Stdin, os.Stdout)
}

func protagonist(reader basicIO.Reader, writer basicIO.Writer) {
	io := NewIO(reader, writer)
	//	N, _ := io.nextInt()
	//	Q, _ := io.nextInt()
	//	str := io.nextString()
	var N int
	var Q int
	var s string
	fmt.Scan(&N, &Q, &str)
	t := make([]byte, Q)
	d := make([]byte, Q)

	for i := 0; i < Q; i++ {
		t[i] = io.nextString()[0]
		d[i] = io.nextString()[0]
	}

	if N == 1 {
		if DriftToSection(0, N, Q, str, t, d) == 'M' {
			io.PutInt(0)
		} else {
			io.PutInt(1)
		}
	}

	if DriftToSection(0, N, Q, str, t, d) == 'R' || DriftToSection(N-1, N, Q, str, t, d) == 'L' {
		io.PutInt(0)
		return
	}

	fl := FlowLeft(N, Q, str, t, d)
	fr := FlowRight(N, Q, str, t, d)
	io.PutInt(N - fr - fl)
}

func DriftToSection(n int, N int, Q int, str string, t []byte, d []byte) byte {
	for i := 0; i < Q; i++ {
		if str[n] == t[i] {
			if d[i] == 'L' {
				n--
			} else {
				n++
			}
			if n < 0 {
				return 'L'
			}
			if n >= N {
				return 'R'
			}
		}
	}
	return 'M'
}

func FlowLeft(N int, Q int, str string, t []byte, d []byte) int {
	l := 0
	r := N - 1
	if DriftToSection(l, N, Q, str, t, d) == 'M' {
		return 0
	}
	for (r - l) > 1 {
		m := int((l + r) / 2)
		switch DriftToSection(m, N, Q, str, t, d) {
		case 'L':
			l = m
		case 'R':
			l = m
		case 'M':
			r = m
		}
	}
	return r
}
func FlowRight(N int, Q int, str string, t []byte, d []byte) int {
	l := 0
	r := N - 1
	if DriftToSection(r, N, Q, str, t, d) == 'M' {
		return 0
	}
	for (r - l) > 1 {
		m := int((l + r) / 2)
		switch DriftToSection(m, N, Q, str, t, d) {
		case 'L':
			l = m
		case 'R':
			r = m
		case 'M':
			l = m
		}
	}
	return N - l - 1
}

