import (
    "fmt"
)

var n, q int
var s []byte
var qs [][]byte

func main() {
    fmt.Scan(&n, &q)
    fmt.Scan(&s)

    qs = make([][]byte, q)
    for i := 0; i < q; i++ {
        var ts, ds []byte
        fmt.Scan(&ts, &ds)
        qs[i] = []byte{ts[0], ds[0]}
    }
    lp := bl(-1, n)
    rp := br(-1, n)
    fmt.Println(rp - lp - 1)
}

func bl(l, r int) int {
    if r-l <= 1 {
        return l
    }
    p := int((l + r) / 2)
    if left(p) {
        return bl(p, r)
    } else {
        return bl(l, p)
    }
}

func br(l, r int) int {
    if r-l <= 1 {
        return r
    }
    p := int((l + r) / 2)
    if right(p) {
        return br(l, p)
    } else {
        return br(p, r)
    }
}

func left(pos int) bool {
    if pos == -1 {
        return true
    }
    if pos == n {
        return false
    }
    for i := 0; i < q; i++ {
        t := qs[i][0]
        d := qs[i][1]
        if s[pos] == t {
            switch d {
            case 'L':
                pos--
                if pos == -1 {
                    return true
                }
            case 'R':
                pos++
                if pos == n {
                    return false
                }
            }
        }
    }
    return false
}

func right(pos int) bool {
    if pos == -1 {
        return false
    }
    if pos == n {
        return true
    }
    for i := 0; i < q; i++ {
        t := qs[i][0]
        d := qs[i][1]
        if s[pos] == t {
            switch d {
            case 'L':
                pos--
                if pos == -1 {
                    return false
                }
            case 'R':
                pos++
                if pos == n {
                    return true
                }
            }
        }
    }
    return false
}

