			} else if b[i] == n-1 && tempM == "R" {
				result[n-1] = 0
			} else {
				if tempM == "L" {
					result[b[i]-1] += result[b[i]]
					result[b[i]] = 0
				} else {
					result[b[i]+1] += result[b[i]]
					result[b[i]] = 0
				}
			}
