func isRightFall(index int) bool {
	finalIdx := simulate(index)

	if finalIdx == n {
		return true
	}
	return false
}

func isLeftFall(index int) bool {
	finalIdx := simulate(index)

	if finalIdx == -1 {
		return true
	}
	return false
}

func simulate(index int) int {
	curIdx := index

	for i := 0; i < q; i++ {
		t, d := T[i], D[i]
		if S[curIdx] != t {
			continue
		}

		if d == 'L' {
			curIdx--
		} else {
			curIdx++
		}

		if curIdx == -1 || curIdx == n {
			return curIdx
		}
	}

	return curIdx
}

