var N, Q int
var s string
var t, d []string

func simulate(pos int) int {
	for i := 0; i < Q; i++ {
		if string(s[pos]) != t[i] {
			continue
		}
		if d[i] == "R" {
			pos++
			if pos == N {
				return 1
			}
		}
		if d[i] == "L" {
			pos--
			if pos == -1 {
				return -1
			}
		}
	}
	return 0
}

func solve() int {
	l := sort.Search(N, func(i int) bool { return simulate(i) >= 0 })
	if l >= N {
		return 0
	}

	r := sort.Search(N, func(i int) bool { return simulate(i) >= 1 })
	r = MinInts(r, N)

	return r - l
}

