	r := N
	for i := Q - 1; i >= 0; i-- {
		if l < N-1 && str[l+1] == t[i] && d[i] == 'L' {
			l++
		}
		if r > 0 && str[r-1] == t[i] && d[i] == 'R' {
			r--
