		index[s[i]] = append(index[s[i]], i)
		golems[i] = 1
	}
	for i := 0; i < Q; i++ {
		prev := make([]int, N)
		copy(prev, golems)
		var t, d string
		fmt.Scanf("%s %s", &t, &d)
		for j := 0; j < len(index[t]); j++ {
			idx := index[t][j]
			if d == "L" && idx == 0 {
				golems[idx] = remove(golems[idx], prev[idx])
				continue
			}
			if d == "R" && idx == N-1 {
				golems[idx] = remove(golems[idx], prev[idx])
				continue
			}
			if d == "L" {
				golems[idx-1] = golems[idx-1] + prev[idx]
			}
			if d == "R" {
				golems[idx+1] = golems[idx+1] + prev[idx]
			}
			golems[idx] = remove(golems[idx], prev[idx])
		}
	}
	count := 0
	for i := 0; i < N; i++ {
		count += golems[i]
	}
	fmt.Println(count)
}

func remove(golem, prev int) int {
	if golem > prev {
		return golem - prev
	} else {
		return 0
	}
}

