func protagonist(reader basicIO.Reader, writer basicIO.Writer) {
	io := NewIO(reader, writer)
	var N int
	var Q int
	var str string
	//	N, _ = io.nextInt()
	//	Q, _ = io.nextInt()
	//	str = io.nextString()
	fmt.Scan(&N, &Q, &str)
	t := make([]byte, Q)
	d := make([]byte, Q)

	for i := 0; i < Q; i++ {
		t[i] = io.nextString()[0]
		d[i] = io.nextString()[0]
	}

	if N <= 3 {
		count := 0
		for i := 0; i < N; i++ {
			if DriftToSection(i, N, Q, str, t, d) == 'M' {
				count++
			}
		}
		io.PutInt(count)
	}

	if DriftToSection(0, N, Q, str, t, d) == 'R' || DriftToSection(N-1, N, Q, str, t, d) == 'L' {
		io.PutInt(0)
		return
	}

	fl := FlowLeft(N, Q, str, t, d)
	fr := FlowRight(N, Q, str, t, d)
	io.PutInt(N - fr - fl)
}

func DriftToSection(n int, N int, Q int, str string, t []byte, d []byte) byte {
	for i := 0; i < Q; i++ {
		if str[n] == t[i] {
			if d[i] == 'L' {
				n--
			} else {
				n++
			}
			if n < 0 {
				return 'L'
			}
			if n >= N {
				return 'R'
			}
		}
	}
	return 'M'
}

func FlowLeft(N int, Q int, str string, t []byte, d []byte) int {
	l := 0
	r := N - 1
	if DriftToSection(l, N, Q, str, t, d) == 'M' {
		return 0
	}
	for (r - l) > 1 {
		m := int((l + r) / 2)
		switch DriftToSection(m, N, Q, str, t, d) {
		case 'L':
			l = m
		case 'R':
			l = m
		case 'M':
			r = m
		}
	}
	return r
}
func FlowRight(N int, Q int, str string, t []byte, d []byte) int {
	l := 0
	r := N - 1
	if DriftToSection(r, N, Q, str, t, d) == 'M' {
		return 0
	}
	for (r - l) > 1 {
		m := int((l + r) / 2)
		switch DriftToSection(m, N, Q, str, t, d) {
		case 'L':
			l = m
		case 'R':
			r = m
		case 'M':
			l = m
		}
	}
	return N - l - 1
}

type IO struct {
	Scanner *bufio.Scanner
	Writer  basicIO.Writer
}

func NewIO(r basicIO.Reader, w basicIO.Writer) *IO {
	s := bufio.NewScanner(r)
	s.Split(bufio.ScanWords)
	return &IO{
		Scanner: s,
		Writer:  w,
	}
}

func (io *IO) nextString() string {
	io.Scanner.Scan()
	return io.Scanner.Text()
}

func (io *IO) nextInt() (int, error) {
	io.Scanner.Scan()
	i, err := strconv.Atoi(io.Scanner.Text())
	return i, err
}

func (io *IO) PutInt(v int) {
	fmt.Fprintf(io.Writer, "%d\n", v)
}

func (io *IO) PutString(s string) {
	fmt.Fprintf(io.Writer, "%s\n", s)
}

