		move := 0
		for i := 0; i < q; i++ {
			if s[m+move] == t[i][0] {
				if d[i][0] == 'R' {
					move++
				} else {
					move--
				}
			}
			if m+move < 0 || m+move >= n {
				break
			}
		}
		if m+move < 0 {
			l = m + 1
		} else {
			r = m - 1
		}
	}

	deleted := 0
	if r >= 0 {
		deleted += r + 1
	}
	l = 0
	r = n - 1
	for l <= r {
		m := (l + r) / 2
		move := 0
		for i := 0; i < q; i++ {
