type Pair struct {
	first  string
	second string
}

func simulate(s string, qs []Pair, pos int) int {
	for _, query := range qs {
		if query.first != string(s[pos]) {
			continue
		}
		if query.second == "R" {
			pos++
		} else {
			pos--
		}

		if pos == -1 {
			return -1
		} else if pos == len(s) {
			return 1
		}
	}
	return 0
}

func solve(s string, qs []Pair) int {
	l := sort.Search(len(s), func(i int) bool { return simulate(s, qs, i) == 0 })
	if l >= len(s) {
		l = 0
	}

	r := sort.Search(len(s), func(i int) bool { return simulate(s, qs, i) == 1 })
	if r >= len(s) {
		r = len(s)
	}

	return r - l
}

func main() {
	var n, q int
	fmt.Scan(&n, &q)

	var s string
	fmt.Scan(&s)

	qs := make([]Pair, q)
	for i := 0; i < q; i++ {
		fmt.Scan(&qs[i].first, &qs[i].second)
	}

	fmt.Println(solve(s, qs))
}

