type Scanner struct {
  sc *bufio.Scanner
  buf []byte
}

func NewScanner(r io.Reader) *Scanner {
  s := &Scanner{
    sc: bufio.NewScanner(r),
  }
  s.sc.Split(bufio.ScanWords)
  s.sc.Buffer(s.buf, 300000)
  return s
}

func (s *Scanner) nextInt() int {
  if s.sc.Scan() {
    i, err := strconv.Atoi(s.sc.Text())
    if err != nil {
      panic(err)
    }
    return i
  }
  panic("failed to scan")
}

func (s *Scanner) nextString() string {
  if s.sc.Scan() {
    return s.sc.Text()
  }
  panic("failed to scan")
}


func solve(w io.Writer, r io.Reader) {
  sc := NewScanner(r)
  N := sc.nextInt()
  Q := sc.nextInt()
  s := sc.nextString()

  mp := make(map[byte][]int)
  mc := make([]int, N)

  for i, v := range s {
    mp[byte(v)] = append(mp[byte(v)], i)
    mc[i] = 1
  }

  c := N
  for i := 0; i < Q; i++ {
    ts := sc.nextString()
    ds := sc.nextString()
    t, d := ts[0], ds[0]

	var tmp []int
    for _, k := range mp[t] {
      if mc[k] == 0 {
        continue
      }
      var p int
      if d == 'L' {
        if k > 0 {
          p = k - 1
        } else {
          c, mc[k] = c - mc[k], 0
          if c == 0 {
            fmt.Fprint(w, c)
            return
          }
          continue
        }
      } else {
        if k < N-1 {
          p = k + 1
        } else {
          c, mc[k] = c - mc[k], 0
          if c == 0 {
            fmt.Fprint(w, c)
            return
          }
          continue
        }
      }
      if mc[p] == 0 {
        mp[s[p]] = append(mp[s[p]], p)
      }
      mc[p], mc[k] = mc[p] + mc[k], 0
      if s[p] == t {
        tmp = append(tmp, p)
      }
    }
    mp[t] = tmp
  }
  fmt.Fprint(w, c)
}

