  }
  auto bs(long ok, long ng, long e) {
    while(abs(ok - ng) > 1) {
      auto m = (ok + ng) / 2;
      if(test(m, 0, e)) {
        ok = m;
      } else {
        ng = m;
      }
    }
    return ok;
  }
  long l = bs(-1, n, -1);
  long r = bs(n, -1, n);
  writeln(n - (l+1) - (n-r));
}

