            else ++i;
        }
        if (i > 0 && i-1 < N && q.t == TS[i-1] && q.d > 0) --i;
    }
    r += max(i, 0);
    i = N;
    foreach_reverse (q; QS) {
        if (i > 0 && q.t == TS[min(i-1, N-1)] && q.d > 0) {
            if (i > N) i = N-1;
            else --i;
        }
        if (i > 0 && i < N && q.t == TS[i] && q.d < 0) ++i;
    }
    r += (N-min(i, N));
    writeln(N-r);
}

