long calc(long s, long g)
{
    long pos = (s+g)/2;
    foreach(q; qs)
    {
        if(q.t!=S[pos-1])continue;
        pos += q.d=='R'?1:-1;
        if(pos==0)break;
        if(pos==N+1)break;
    }
    if(s==g)
    {
        if(pos==0)
            return s;
        else
            return 0;
    }
    if(abs(s-g)==1)
    {
        return max(calc(s, s) , calc(g, g));
    }
    return pos==0 ? calc((s+g)/2, g) : calc(s, (s+g)/2);
}
long calc2(long s, long g)
{
    if(abs(s-g)==1)
    {
        return max(calc2(s, s) , calc2(g, g));
    }

    long pos = (s+g)/2;
    foreach(q; qs)
    {
        if(q.t!=S[pos-1])continue;
        pos += q.d=='R'?1:-1;
        if(pos==N+1)break;
        if(pos==0)break;
    }
    if(s==g)
    {
        if(pos==N+1)
            return N-s+1;
        else
            return 0;
    }
    return pos==N+1 ? calc2(s, (s+g)/2) : calc2((s+g)/2, g);
}
