    for i in countdown(mm - 1, 0):
      var newidx = idxtochar[i]- 1
      if newidx == 0:
        hidari += 1
      else:
        var newchar = idxtochar[newidx]
        chartoidx[newchar].add(newidx)
      chartoidx[t].delete(i, i)
  if d == "R":
    var mm = chartoidx[t].len
    for i in countdown(mm - 1, 0):
      var newidx = idxtochar[i] + 1
      if newidx == N + 1:
        migi += 1
      else:
        var newchar = idxtochar[newidx]
        chartoidx[newchar].add(newidx)
      chartoidx[t].delete(i, i)

echo N - (hidari + migi)

