import strutils, sequtils, future

type T = object
  t: char
  d: char

proc enoughRight(initialPos: int, s: string, tdi: seq[T]): bool =
  var k = initialPos
  for td in tdi:
    if td.t == s[k]:
      if td.d == 'L':
        k -= 1
      else:
        k += 1
    if k < 0:
      return false
  return true

proc enoughLeft(initialPos: int, s: string, tdi: seq[T]): bool =
  var k = initialPos
  for td in tdi:
    if td.t == s[k]:
      if td.d == 'L':
        k -= 1
      else:
        k += 1
    if k >= s.len:
      return false
  return true

proc solve(ch: char, idxs: seq[int], s: string, tdi: seq[T]): int =
  if idxs.len == 0:
    return 0
  var
    ng = -1
    ok = idxs.len             # 左側はここまで残る
  while ok - ng > 1:
    let md = (ok + ng) div 2
    if enoughRight(idxs[md], s, tdi):
      ok = md
    else:
      ng = md
  if ok == idxs.len: # ぜんぶ落ちた
    return 0
  let left = ok

  ng = idxs.len
  ok = -1                     # 右側はここまで残る
  while ng - ok > 1:
    let md = (ok + ng) div 2
    if enoughLeft(idxs[md], s, tdi):
      ok = md
    else:
      ng = md
  if ok == -1: # ぜんぶ落ちた
    return 0
  let right = ok
  return max(0, right - left + 1)

proc main() =
  let
    nq = stdin.readLine.strip.split.map(parseInt)
    (n, q) = (nq[0], nq[1])
    s = stdin.readLine.strip
  var tdi = newSeq[T](q)
  for i in 0..<q:
    let td = stdin.readLine.strip.split.map(it => it[0])
    tdi[i] = T(t: td[0], d: td[1])

  var idxs = newSeqWith(26, newSeq[int]())
  for i, ch in s:
    idxs[ch.ord - 'A'.ord].add(i)

  var ans = 0
  for ch in 'A'..'Z':
    ans += solve(ch, idxs[ch.ord - 'A'.ord], s, tdi)
  echo ans

main()

