proc judge(x: int, dir: int): bool =
  var x = x
  for i in 1..Q:
    if S[x] == T[i]:
      if D[i] == 'L':
        x -= 1
      else:
        x += 1
  if (x == 0 and dir == 1) or (x == N + 1 and dir == 2):
    return true
  else:
    return false

proc myBinarySearch(dir: int): int =
  var ok: int # 落ちる
  var ng: int # 落ちない
  if dir == 1:
    (ok, ng) = (0, N + 1)
  else:
    (ok, ng) = (N + 1, 0)
  while abs(ok - ng) > 1:
    var mid = (ok + ng) div 2
    if judge(mid, dir) == true:
      ok = mid
    else:
      ng = mid
  return ng

