type T = object
  t: char
  d: char

proc enoughRight(initialPos: int, s: string, tdi: seq[T]): bool =
  var k = initialPos
  for td in tdi:
    if s[k] == td.t:
      if td.d == 'L':
        k -= 1
      else:
        k += 1
      if k < 0:
        return false
  return true

proc enoughLeft(initialPos: int, s: string, tdi: seq[T]): bool =
  var k = initialPos
  for td in tdi:
    if s[k] == td.t:
      if td.d == 'L':
        k -= 1
      else:
        k += 1
      if k >= s.len:
        return false
  return true

