    pos = len(s) - 1
    while True:
        if pos < 1 or len(s) <= pos:
            pos = -1
            break
        prev = pos
        ret1 = is_vanished_from_left(s, pos, spells)
        ret2 = is_vanished_from_left(s, pos - 1, spells)
