    # lower_bound of search_result[i][1] == True or N
    def isOK(i):
        return search(i)[1]
    # lower_bound of search_result[i][0] == False or 0
    left, right = -1, N
    while (right - left > 1):
        mid = left + (right - left) // 2
        if (isOK(mid)):
            right = mid
        else:
            left = mid
    return right


