# シミュレーション関数
def to_end(num, board, query, goal):
    for (qs, qd) in query:
        if qs == board[num]:
            if qd == 'L':
                num -= 1
            elif qd == 'R':
                num += 1

            if num == goal:
                return True

    return False


# 左へ二分探索
def find_rightest_left(board, query):
    left = 0
    right = len(board)-1

    while right-left > 1:
        mid = (left+right) // 2
        if to_end(mid, board, query, 0):
            left = mid
        else:
            right = mid

    return left

# 右へ二分探索
def find_leftest_right(board, query):
    R = len(board)-1
    left = 0
    right = R

    while right-left > 1:
        mid = (left+right) // 2
        if to_end(mid, board, query, R):
            right = mid
        else:
            left = mid

    return R - right

