def if_survive(idx):
    """
    Args :
        idx : position of gorem
        max_ : max value of position idx
        min_ : min value of position idx
    Return : 
        +1 : 右側に落ちた時
        -1 : 左側に落ちた時
        0 : 落ちなかった時
    """
    max_ = len(s) - 1
    min_ = 0
    target_moji = s[idx]
    current_position = idx

    for t, d in zip(t_list, d_list):
        if t == target_moji:
            if d == "L":
                current_position -= 1
            elif d == "R":
                current_position += 1

            if current_position > max_:
                return 1
