        print('-------------', t, d)
        for i, r in enumerate(B):
            print(i, S[i], r)

    for i, r in enumerate(B):
        print(i, r)

    ans = N - len(B[-1]) - len(B[N])
    return ans


@mt
def slv(N, Q, S, TD):

    # L
    f = False
    i = 0
    lmi = 0
    for t, d in reversed(TD):
        if not f and t == S[0] and d == 'L':
            f = True
            i = 1
        elif f and t == S[i] and d == 'L':
            i += 1
    else:
        lmi = max(lmi, i)

    # R
    f = False
    i = N
    rmi = N  - 1
    for t, d in reversed(TD):
        if not f and t  == S[N-1] and d == 'R':
            f = True
            i = N-2
        elif f and t == S[i] and d == 'R':
            i -= 1
    else:
        rmi = min(rmi, i)

    ans = N - lmi - (N-rmi-1)
    return ans


