def bisect_left_withkey(a, x, key=lambda x: x):
    right_max = len(a)-1
    right = right_max
    left = 0
    kx = key(x)
    while left + 1 < right:
        new = (left + right)//2
        kn = key(a[new])
        if kx <= kn:
            right = new
        else:
            left = new
    if right == right_max and kx > key(a[right]):
        return right + 1
    else:
        return right

def bisect_right_withkey(a, x, key=lambda x: x):
    right_max = len(a)-1
    right = right_max
    left = 0
    kx = key(x)
    while left + 1 < right:
        new = (left + right)//2
        kn = key(a[new])
        if kx < kn:
            right = new
        else:
            left = new
    if right == right_max and kx >= key(a[right]):
        return right + 1
    else:
        return right

