def solve(N, Q, S, TDs):
    f_index = -1
    l_index = N
    ans = N
    for q in TDs[::-1]:
        t, d = q
        if d == "L" and 0 <= f_index + 1 < N and S[f_index + 1] == t:
            f_index += 1
            ans -= 1
        elif d == "R" and 0 <= l_index - 1 < N and S[l_index - 1] == t:
            l_index -= 1
            ans -= 1

        elif d == "R" and 0 <= f_index < N and S[f_index] == t:
            f_index = -10
        elif d == "L" and 0 <= l_index < N and S[l_index] == t:
            l_index = -10

    return max(0, ans)

