    while a + 1 < b:
        if checkleft(int((a + b) / 2)):
            a = int((a + b) / 2)
        else:
            b = int((a + b) / 2)
    return a

def bisection_R_Method(a, b):
    while a + 1 < b:
        if checkright(int((a + b) / 2)):
            b = int((a + b) / 2)
        else:
            a = int((a + b) / 2)
    return b

