def leftsearch(N, q, data):
    x = 0

    for spell in q:
        now = data[N]
        if now==spell[0]:
            if spell[1]=='R':
                N+=1
            else:
                N-=1
            if N==0:
                x = 1
                break
            elif N==len(data):
                break
    return(x)
def rightsearch(N, q, data):
    x = 0    
    for spell in q:
        now = data[N]
        if now==spell[0]:
            if spell[1]=='R':
                N+=1
            else:
                N-=1
            if N >= len(data):
                x = 1
                break
            elif N == 0:
                break
    return(x)

