def disappear(place):
    if place == -1:
        return (False, False)
    else:
        left = False
        right = False
        for i in range(Q):
            current_char = S[place]
            t, d = move_list[i]
            if t == current_char:
                if d == 'R':
                    place += 1
                else:
                    place -= 1
                if place < 0:
                    left = True
                    break
                elif place > N-1:
                    right = True
                    break
        return (left, right)


def bisect_left():
    start, end = -1, N
    while end - start > 1:
        t = start + (end-start)//2
        if disappear(t)[0]:
            start = t
        else:
            end = t
    return start


def bisect_right():
    start, end = -1, N
    while end - start > 1:
        t = start + (end-start)//2
        if disappear(t)[1]:
            end = t
        else:
            start = t
    return start


