    if start==end:
        if vanish_check(mid)==1:
            return mid
        else:
            return mid-1
    if vanish_check(mid) == 1:
        start = mid+1
        mid = (start + end)//2
        find_most_right_returns_1(start,mid,end)
    else:
        end = mid-1
        mid = (start + end)//2
        find_most_right_returns_1(start,mid,end)

def find_most_left_returns_2(start,mid,end):
    if start==end:
        if vanish_check(mid)==2:
            return mid
        else:
            return mid+1
    if vanish_check(mid) ==2:
        end = mid-1
        mid = (start+end)//2
        find_most_left_returns_2(start,mid,end)
    else:
