def move_golems_right(golems, group_index, N):
    increase_cells = {}
    if N-1 in group_index:
        for i in group_index:
            if i != N-1:
                increase_cells[i+1] = golems[i]
            golems[i] = 0
        for i in group_index:
            if i != N-1:
                golems[i+1] += increase_cells[i+1]
        return golems
    for i in group_index:
        increase_cells[i+1] = golems[i]
        golems[i] = 0
    for i in group_index:
        golems[i+1] += increase_cells[i+1]
    return golems

def move_golems_left(golems, group_index, N):
    increase_cells = {}
    if 0 in group_index:
        for i in group_index:
            if i != 0:
                increase_cells[i-1] = golems[i]
            golems[i] = 0
        for i in group_index:
            if i != 0:
                golems[i-1] += increase_cells[i-1]
        return golems
    for i in group_index:
        increase_cells[i-1] = golems[i]
        golems[i] = 0
    for i in group_index:
        golems[i-1] += increase_cells[i-1]
    return golems

