def simulation(x, N, S, incantations):
    for t, d in incantations:
        if x < 0 or x >= N:
            return x
        if S[x] == t:
            if d == 'R':
                x += 1
            else:
                x -= 1
    return x


def solve(N, S, incantations):
    # 左側に落ちるロボットの範囲: (-inf, ok_left]
    ok_left, ng_left = -1, N
    while ng_left - ok_left > 1:
        mid = (ok_left + ng_left) // 2
        if simulation(mid, N, S, incantations) < 0:
            ok_left = mid
        else:
            ng_left = mid
    # 右側に落ちるロボットの範囲: [ok_right, inf)
    ok_right, ng_right = N, -1
    while ok_right - ng_right > 1:
        mid = (ok_right + ng_right) // 2
        if simulation(mid, N, S, incantations) >= N:
            ok_right = mid
        else:
            ng_right = mid
    print(ok_right - ok_left - 1)


def main():
    N, Q = list(map(int, input().split()))
    S = input()
    incantations = [input().split() for _ in range(Q)]
    solve(N, S, incantations)


