def func(n):
    pos = n
    for x in t:
        if x[0] == s[pos]:
            if x[1] == 'L':
                pos -= 1
                if pos < 0:
                    return 'L'
            else:
                pos += 1
                if pos == N:
                    return 'R'
    return 'T'


def calcl(pl, pr):
    if pl == pr:
        return pl
    else:
        p = (pr + pl) // 2
        a = func(p)
        if a == 'T':
            return calcl(pl, p)
        else:
            return calcl(p+1, pr)


def calcr(pl, pr):
    if pl == pr:
        return pl
    else:
        p = (pr + pl + 1) // 2
        a = func(p)
        if a == 'T':
            return calcr(p, pr)
        else:
            return calcr(pl, p - 1)


pl = 0
