def snuke_the_wizard(N: int, Q: int, s: str, queries: list)->int:
    l, r = -1, N
    for t, d in reversed(queries):
        if d == 'R' and s[r-1] == t:
            r -= 1
        elif d == 'L' and s[l+1] == t:
            l += 1
    return r - l - 1 if l < r else 0


