def bisect_left_withkey(a, x, key=lambda x: x):
    right = len(a)
    left = 0
    kx = key(x)
    while left + 1 < right:
        new = (left + right)//2
        kn = key(a[new])
        if kx <= kn:
            right = new
        else:
            left = new
    return right

def bisect_right_withkey(a, x, key=lambda x: x):
    right = len(a)
    left = 0
    kx = key(x)
    while left + 1 < right:
        new = (left + right)//2
        kn = key(a[new])
        if kx < kn:
            right = new
        else:
            left = new
    return right

