def slv(N, Q, S, TD):
    def reachable(i):
        if i < 0:
            return -1
        elif i >= N:
            return 1
        for t, d in TD:
            if S[i] == t:
                if d == 'L':
                    i -= 1
                else:
                    i += 1
            if i == -1:
                return -1
            elif i == N:
                return 1
        return 0
    ans = N
    lo = 0
    hi = N
    while lo < hi:
        mid = (lo+hi)//2
        if reachable(mid) < 0: lo = mid+1
        else: hi = mid
    ans -= lo


    lo = 0
    hi = N
    while lo < hi:
        mid = (lo+hi)//2
        if 0 < reachable(mid): hi = mid
        else: lo = mid+1
    ans -= N - lo
    return ans



