        return i - 1 if b[1] == 'L' else i + 1
    else:
        return i
def ar(i):
    for j in range(Q):
        i = a(A[j],i)
        if i == Q:
            return False
    return True
def al(i):
    for j in range(Q):
        i = a(A[j],i)
        if i == -1:
            return False
    return True

def bir(i,j):
    if i + 1 == j:
        return i
    if ar((i+j)//2):
        return bir((i+j)//2,j)
    else:
