def left(g, t):
    l = deepcopy(g)
    index = index_dict[t]
    for i in index:
        if g[i] > 0:
            l[i] -= g[i]
            if i != 0:
                l[i-1] += g[i]
    return l

def right(g, t):
    l = deepcopy(g)
    index = index_dict[t]
    for i in index:
        if g[i] > 0:
            l[i] -= g[i]
            if i != len_s - 1:
                l[i+1] += g[i]
    return l

