def check(t,d,S,LR):
    start = 0
    end = len(S)-1
    while start!=end:
        index = (start+end)//2
        for i in range(len(t)):
            if len(t)-i<index or len(t)-i<len(S)-(index+1):
                break
            if S[index] == t[i]:
                if d[i]=="L":
                    index -= 1
                else:
                    index += 1
            if index<=0 or index>=len(S)-1:
                break
        if LR=="L":
            if index <= 0:
                start = (start+end)//2+1
            else:
                end = (start+end)//2
        else:
            if index >= len(S)-1:
                end = (start+end)//2
            else:
                start = (start+end)//2+1
    return start

