fn main() {
    input! {
        n: usize,
        q: usize,
        s: chars,
        td: [(chars, chars); q]
    }

    let pos = |x: i64| -> i64 {
        let mut cur = x;
        for &(ref t, ref d) in &td {
            let t = t[0];
            let d = d[0];
            let in_range = 0 <= cur && cur < s.len() as i64;
            if in_range && s[cur as usize] == t {
                if d == 'L' {
                    cur -= 1;
                } else if d == 'R' {
                    cur += 1;
                }
            }
        }
        cur
    };

    let l = {
        let mut l = -1;
        let mut r = n as i64;

        while (r - l) > 1 {
            let m = (l + r) / 2;
            if pos(m) < 0 {
                l = m;
            } else {
                r = m;
            }
        }

        l
    };

    let r = {
        let mut l = -1;
        let mut r = n as i64;

        while (r - l) > 1 {
            let m = (l + r) / 2;
            if pos(m) >= n as i64 {
                r = m;
            } else {
                l = m;
            }
        }

        r
    };

    println!("{}", r - l - 1);
}

