    let s = get!(String).chars().collect::<Vec<_>>();
    let tdt = get!(String, String; q);
    let mut td = Vec::new();
    for (t, d) in tdt {
        td.push((t.into_bytes()[0] as char, d.into_bytes()[0] as char));
    }
    let mut count = 0;

    let mut l = 0;
    let mut r = n+1;
    while l < r {
        let mid = (l+r)/2;
        let mut po = mid;
        for &(t,d) in td.iter() {
            if po == 0 || po == n+1 {
                break;
            }
            if s[po-1] == t {
                if d == 'L' {
                    po -= 1;
                } else {
                    po += 1;
                }
            }
        }
        if po == 0 {
            if l == mid {
                break;
            }
            l = mid;
        } else {
            r = mid;
        }
    }
    if r != 0 && r != n+1 {
        count += l;
    }

    let mut l = 0;
    let mut r = n+1;
    while l < r {
        let mid = (l+r)/2;
        let mut po = mid;
        for &(t,d) in td.iter() {
            if po == 0 || po == n+1 {
                break;
            }
            if s[po-1] == t {
                if d == 'L' {
                    po -= 1;
                } else {
                    po += 1;
                }
            }
        }
        if po == n+1 {
            r = mid;
        } else {
            if l == mid {
                break;
            }
            l = mid;
        }
    }
    if r != 0 && r != n+1 {
        count += n-l;
    }

    println!("{}", n-count);

