fn main() {
    let (N, Q) = read!(usize, usize);
    let S = rl().chars().collect::<Vec<_>>();
    let T = read!(String, String; Q)
        .into_iter()
        .map(|(t, d)| (t.chars().next().unwrap(), d.chars().next().unwrap()))
        .collect::<Vec<_>>();

    // 0..l のゴーレムがすべて左に消える
    let mut l = 0;

    // r..N のゴーレムがすべて右に消える
    let mut r = N;

    for &(t, d) in T.iter().rev() {
        if d == 'L' && l < N && S[l] == t {
            l += 1;
        }
        if d == 'R' && r >= 1 && S[r - 1] == t {
            r -= 1;
        }
    }

    // l > r に注意。例:
    // S = A
    // T = (A, L), (A, R)
    r = max(r, l);

    let k = N - l - (N - r);

    println!("{}", k)
}

