fn solve() -> usize {
    input! {
        n: usize,
        q: usize,
        s: chars,
        mut queries: [(chars, chars); q],
    }
    queries.reverse();
    let mut l = 0usize;
    let mut r = n - 1;
    for (t, d) in queries {
        let t = t[0];
        let d = d[0];
        if d == 'L' {
            if s[l] == t {
                l += 1;
            }
            if r < n - 1 && s[r + 1] == t {
                r += 1;
            }
        } else {
            if s[r] == t {
                r -= 1;
            }
            if l > 0 && s[l - 1] == t {
                l -= 1;
            }
        }
        if l == r {
            return 0;
        }
    }
    r - l + 1
}

