        (t[0], d[0])
    }).collect::<Vec<(char, char)>>();

    let mut result = 0;
    {
        let mut left: i32 = -10;
        let mut right: i32 = n as i32 + 10;
        let mut tmp = 0;
        while right - left > 1 {
            let mut med = (right + left) / 2;
            if med < 0 {
                left = med;
                continue;
            }
            if med >= n as i32 {
                right = med;
                continue;
            }

            let res = escape(med as usize, n, &s, &td);
            if res.0 && res.1 == 'L' {
                left = med;
                tmp = (med + 1) as usize;
            } else {
                right = med;
            }
        }
        result += tmp;
    }

    {
        let mut left: i32 = -10;
        let mut right: i32 = n as i32 + 10;
        let mut tmp = 0;
        while right - left > 1 {
            let mut med = (right + left) / 2;
            if med < 0 {
