    parse!(it, n: usize, q: usize, s: String, mut td: [(char,char); q]);
    td.reverse();
    let mut s = s.chars().collect::<std::collections::VecDeque<_>>();
    s.push_front('a');
    s.push_back('a');
    let mut l = 0;
    for i in 0..q {
        let (t, d) = td[i];
        if t == s[l] && d == 'R' {
