    let stdin = std::io::stdin();
    let stdout = std::io::stdout();
    solve(&mut stdin.lock(), &mut BufWriter::new(stdout.lock()));
}

fn solve<R: BufRead, W: Write>(stdin: &mut R, stdout: &mut BufWriter<W>) {
    let (n, q): (usize, usize) = stdin.gets().split(' ').values();
    let mut map = stdin.gets().into_bytes();
    for i in 0..n {
        map[i] = map[i] - b'A';
    }
    let mut sp = Vec::new();
    for line in stdin.lines().take(q).map(|x| x.unwrap().into_bytes()) {
        let (t, d) = (line[0] - b'A',
                      if line[2] == b'R' { 1 } else { -1 });
        sp.push((t, d));
    }
    let (mut left, mut right) = (0, n);
    while left < right {
        let mid = (left + right) / 2;
        let t = alive(n, &map, &sp, mid);
        if t == -1 {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    let leftmost = left;
    let (mut left, mut right) = (0, n);
    while left < right {
        let mid = (left + right) / 2;
        let t = alive(n, &map, &sp, mid);
        if t == 1 {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    let rightmost = right;
    writeln!(stdout, "{}", rightmost - leftmost).unwrap();
}

fn alive(n: usize, map: &[u8], sp: &[(u8, isize)], mut p: usize) -> isize {
    for &(t, d) in sp {
        if map[p] == t {
            let next = p.wrapping_add(d as usize);
            if next >= n {
                return d;
            }
            p = next;
        }
    }
    0
}

