            res >= 0
        },
    };
    let r = bs.lower_bound() as usize;
    for i in 0..r {
        dead[i] = true;
    }

    let bs = BinarySearch {
        lower: 0,
        upper: n as i64,
        p: |i:i64| {
            let res = simulate(((n-1) as i64 - i) as usize);
            res <= 0
        }
    };
    let r = bs.lower_bound() as usize;
    for i in 0..r {
        dead[n-1-i] = true;
    }

    let mut cnt = 0;
    for i in 0..n {
        if !dead[i] { cnt += 1; }
    }
    println!("{}", cnt);
}
#[doc = "lower,upper are inclusive range"]
pub struct BinarySearch<F> {
    pub p: F,
    pub lower: i64,
    pub upper: i64,
}
impl<F: Fn(i64) -> bool> BinarySearch<F> {
    #[doc = "O(log(upper-lower))"]
    pub fn lower_bound(&self) -> i64 {
        let lower = self.lower;
        let upper = self.upper;
        assert!(lower <= upper);
        let mut lb = lower - 1;
        let mut ub = upper + 1;
        while ub - lb > 1 {
            let mid = (lb + ub) / 2;
            if (self.p)(mid) {
                ub = mid;
            } else {
                lb = mid;
            }
        }
        let latter = ub;
        latter
    }
}

