fn upper_bound<F>(lb: usize, ub: usize, criterion: F) -> Option<usize>
    where 
        F: Fn(usize) -> bool 
{
    let mut lb = lb;
    let mut ub = ub;
    let umax = ub;
    while ub - lb > 1 {
        debug!(lb,ub);
        let mid = lb + (ub-lb)/2;
        if criterion(mid) {
            ub = mid;
        } else {
            lb = mid;
        }
    }
    debug!(lb, ub);
    if umax == ub {
        None
    } else {
        Some(ub)
    }
}


fn solve() {
    let (n, q) = get!(usize, usize);
    let s = get!(String).chars().collect::<Vec<_>>();
    let tdt = get!(String, String; q);
    let mut td = Vec::new();
    for (t, d) in tdt {
        td.push((t.into_bytes()[0] as char, d.into_bytes()[0] as char));
    }
    let mut count = 0;

    let right = |key| {
        let mut po = key;
        for &(t,d) in td.iter() {
            if po == 0 || po == n+1 {
                break;
            }
            if s[po-1] == t {
                if d == 'L' {
                    po -= 1;
                } else {
                    po += 1;
                }
            }
        }
        if po == n+1 {
            true
        } else {
            false
        }
    };

    let ub = upper_bound(0, n+1, right);
    debug!(ub);
    if let Some(v) = ub {
        count += n-v+1;
    }

    let left = |key| {
        let mut po = key;
        for &(t,d) in td.iter() {
            if po == 0 || po == n+1 {
                break;
            }
            if s[n-po] == t {
                if d == 'L' {
                    po += 1;
                } else {
                    po -= 1;
                }
            }
        }
        if po == n+1 {
            true
        } else {
            false
        }
    };

    let ub = upper_bound(0, n+1, left);
    debug!(ub);
    if let Some(v) = ub {
        count += n-v+1;
    }

    println!("{}", n-count);
}

