// bias: +1
fn sim(n: usize, s: &[char], mut v: usize, td: &[(char, char)]) -> usize {
    for &(t, d) in td {
        if s[v] == t {
            if d == 'L' {
                if v == 0 {
                    return 0;
                }
                v -= 1;
            } else {
                v += 1;
                if v >= n {
                    return n + 1;
                }
            }
        }
    }
    v + 1
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize, q: usize,
        s: chars,
        td: [(chars, chars); q],
    }
    let td: Vec<(char, char)> = td.into_iter().map(|(a, b)| (a[0], b[0])).collect();
    let mut pass = n + 1;
    let mut fail = 0;
    while pass - fail > 1 {
        let mid = (pass + fail) / 2;
        if sim(n, &s, mid - 1, &td) > 0 {
            pass = mid;
        } else {
            fail = mid;
        }
    }
    let fst = pass;
    pass = 0;
    fail = n + 1;
    while fail - pass > 1 {
        let mid = (pass + fail) / 2;
        if sim(n, &s, mid - 1, &td) < n + 1 {
            pass = mid;
        } else {
            fail = mid;
        }
    }
    let snd = pass;
    puts!("{}\n", if snd >= fst { snd + 1 - fst } else { 0 });

}

