fn func(a: usize, s: &Vec<char>, t: &Vec<char>, d: &Vec<bool>) -> usize {
    let mut a = a;
    for i in 0..t.len() {
        if a == 0 || a > s.len() {
            return a;
        }
        if s[a-1] == t[i] {
            if d[i] {
                a -= 1;
            } else {
                a += 1;
            }
        }
    }
    return a;
}

