use std::io::{stdin, Read, StdinLock};
use std::str::FromStr;

fn main() {
    let cin = stdin();
    let cin = cin.lock();
    let mut scan = Scanner::new(cin);

    let n = scan.read::<usize>();
    let q = scan.read::<usize>();
    let s = scan.chars();
    let mut t = vec![];
    let mut d = vec![];
    for _ in 0..q {
        t.push(scan.chars()[0]);
        d.push(scan.chars()[0]);
    }

    let env = Env {n: n, q: q, s: s, t: t, d: d};
    println!("{}", env.n as i32 - (env.left_most() + 1 + env.n as i32 - env.right_most()));
}

struct Env {
    n: usize,
    q: usize,
    s: Vec<char>,
    t: Vec<char>,
    d: Vec<char>
}

impl Env {
    fn left_most(&self) -> i32 {
        let mut ok = -1i32;
        let mut ng = self.n as i32;
        while (ok - ng).abs() > 1 {
            let mid = (ok + ng) / 2;
            if self.left_reach(mid) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        ok
    }

    fn left_reach(&self, mut i: i32) -> bool {
        for j in 0..self.q {
            if i < self.n as i32 && self.t[j] == self.s[uz(i)] {
                match self.d[j] {
                    'L' => i-=1,
                    _ => i+=1
                }
            }
            if i < 0 {return true}
        }
        false
    }

    fn right_most(&self) -> i32 {
        let mut ok = self.n as i32;
        let mut ng = -1i32;
        while (ok - ng).abs() > 1 {
            let mid = (ok + ng) / 2;
            if self.right_reach(mid) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        ok
    }

    fn right_reach(&self, mut i: i32) -> bool {
        for j in 0..self.q {
            if i >= 0 && self.t[j] == self.s[uz(i)] {
                match self.d[j] {
                    'L' => i-=1,
                    _ => i+=1
                }
            }
            if i >= self.n as i32 {return true}
        }
        false
    }
}

