use std::cmp::{min, max};

fn main() {
    read!();
    read!(s = String);
    let s = s.chars().collect::<Vec<_>>();
    let rmax = s.len() - 1;
    let moves = readx::<Move>();
    let initial_range = moves
        .into_iter()
        .rev()
        .fold(Some((0, rmax)), |range, m| {
            range.and_then(|(l, r)| {
                let l_s = l as isize;
                let next_l = match m.dir {
                    L => if s[l] == m.ch { l_s + 1 } else { l_s },
                    R => if l > 0 && s[l-1] == m.ch { l_s - 1 } else { l_s }
                };
                let r_s = r as isize;
                let next_r = match m.dir {
                    R => if s[r] == m.ch { r_s - 1 } else { r_s },
                    L => if r < rmax && s[r+1] == m.ch { r_s + 1 } else { r_s }
                };

                if next_l <= rmax as isize && 0 <= next_r && next_l <= next_r {
                    Some((max(0, next_l) as usize,
                          min(rmax as isize, next_r) as usize))
                } else {
                    None
                }
            })
        });
    let ans = initial_range.map(|(l, r)| r - l + 1).unwrap_or(0);
    println!("{}", ans);
}

