fn simulate(ps: &[(char, char)], s: &[char], idx: usize) -> isize {
    let mut cur = idx;
    let n = s.len();
    for &(c, d) in ps {
        if s[cur] == c {
            if d == 'L' {
                if cur == 0 {
                    return -1;
                }
                cur -= 1;
            }
            if d == 'R' {
                if cur == n - 1 {
                    return n as isize;
                }
                cur += 1;
            }
        }
    }
    cur as isize
}

fn run() {
    input! {
        n: usize,
        q: usize,
        s: chars,
        ps: [(String, String); q],
    }

    let ps = ps
        .into_iter()
        .map(|(a, b)| (a.chars().next().unwrap(), b.chars().next().unwrap()))
        .collect::<Vec<_>>();

    let mut answer = 0;
    let mut lb = 0;
    let mut ub = n + 1;
    while ub - lb > 1 {
        let mid = (lb + ub) / 2;
        let idx = mid - 1;
        if simulate(&ps, &s, idx) == -1 {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    answer += lb;

    let mut lb = 0;
    let mut ub = n + 1;
    while ub - lb > 1 {
        let mid = (lb + ub) / 2;
        let idx = n - mid;
        if simulate(&ps, &s, idx) == n as isize {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    answer += lb;
    answer = n - answer;

    println!("{}", answer);
}

