#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input! {
        n: usize,
        q: usize,
        s: chars,
        td: [(chars, chars); q],
    }

    let pos = |m: i64| -> i64 {
        let mut cur = m;
        for &(ref t, ref d) in td.iter() {
            if cur >= 0 && cur < s.len() as i64 && s[cur as usize] == t[0] {
                if d[0] == 'L' {
                    cur -= 1;
                } else {
                    cur += 1;
                }
            }
        }
        cur
    };

    let l = {
        let mut l = -1;
        let mut r = n as i64;

        while (r - l) > 1 {
            let m = (l + r) / 2;
            if pos(m) < 0 {
                l = m;
            } else {
                r = m;
            }
        }

        l
    };

    let r = {
        let mut l = -1;
        let mut r = n as i64;

        while (r - l) > 1 {
            let m = (l + r) / 2;
            if pos(m) >= n as i64 {
                r = m;
            } else {
                l = m;
            }
        }

        r
    };

    let ans = r - l - 1;

    println!("{}", ans);
}

