#[allow(unused)]
const A: &'static str = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

#[allow(unused)]
fn simulate(S: &[char], T: &[(char, char)]) -> usize {
    let N = S.len();

    let mut G = (0..N).collect::<Vec<_>>();

    for &(t, d) in T {
        for i in 0..N {
            if G[i] == N {
                continue;
            }
            if S[G[i]] != t {
                continue;
            }
            if d == 'L' && G[i] == 0 {
                G[i] = N;
                continue;
            }
            if d == 'L' {
                G[i] -= 1;
                continue;
            }
            if d == 'R' && G[i] + 1 == N {
                G[i] = N;
                continue;
            }
            if d == 'R' {
                G[i] += 1;
                continue;
            }
        }
    }

    G.into_iter().filter(|&i| i != N).count()
}

#[allow(unused)]
fn verify() {
    for N in 1..10 {
        let mut S = vec!['\0'; N];
        for i in 0..N {
            for x in 0..A.len() {
                S[i] = A.as_bytes()[x] as char;
                for Q in 1..10 {
                    let mut T = vec![('A', 'L'); Q];
                    for q in 0..Q {
                        for x in 0..A.len() {
                            for &d in &['L', 'R'] {
                                T[q] = (A.as_bytes()[x] as char, d);

                                assert_eq!(
                                    Solver {
                                        S: S.clone(),
                                        T: T.clone()
                                    }
                                    .solve(),
                                    simulate(&S, &T),
                                    "S={:?} T={:?}",
                                    S,
                                    T
                                );
                            }
                        }
                    }
                }
            }
        }
    }
}

enum Status {
    Left,
    Right,
    Live,
}

struct Solver {
    S: Vec<char>,
    T: Vec<(char, char)>,
}

impl Solver {
    fn simulate(&self, mut i: usize) -> Status {
        for &(t, d) in &self.T {
            if self.S[i] != t {
                continue;
            }
            if d == 'L' && i == 0 {
                return Status::Left;
            }
            if d == 'L' {
                i -= 1;
            }
            if d == 'R' && i + 1 == self.S.len() {
                return Status::Right;
            }
            if d == 'R' {
                i += 1;
            }
        }
        Status::Live
    }

    fn solve(&self) -> usize {
        let N = self.S.len();

        // 消えるゴーレムの個数
        let mut k = 0;

        {
            // 0..l のゴーレムが全て左に消える

            let mut l = 0; // ok
            let mut r = N + 1; // ng
            while r - l > 1 {
                let m = (l + r) / 2;

                let ok = match self.simulate(m - 1) {
                    Status::Left => true,
                    _ => false,
                };
                if ok {
                    l = m;
                } else {
                    r = m;
                }
            }

            k += l;
        }

        {
            // r..N のゴーレムがすべて右に消える

            let mut l = -1_isize; // ng
            let mut r = N as isize; // ok
            while r - l > 1 {
                let m = (l + r) / 2;

                let ok = match self.simulate(m as usize) {
                    Status::Right => true,
                    _ => false,
                };
                if ok {
                    r = m;
                } else {
                    l = m;
                }
            }

            k += N - r as usize;
        }

        N - k
    }
}

fn main() {
    let (_, Q) = read!(usize, usize);
    let S = rl().chars().collect::<Vec<_>>();
    let T = read!(String, String; Q)
        .into_iter()
        .map(|(t, d)| (t.chars().next().unwrap(), d.chars().next().unwrap()))
        .collect::<Vec<_>>();

    println!("{}", Solver { S: S, T: T }.solve())
}

use std::io;

fn main() {
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    let mut n_and_q = buf.split_whitespace();
    n_and_q.next().unwrap();
    let q_len = n_and_q.next().unwrap().parse::<usize>().unwrap();
    drop(n_and_q);

    buf.clear();
    io::stdin().read_line(&mut buf).unwrap();
    buf.pop().unwrap();
    let s = buf;

    let mut spells = vec![String::new(); q_len];
    for spell in spells.iter_mut() {
        io::stdin().read_line(spell).unwrap();
    }

    let spells: Vec<_> = spells
        .into_iter()
        .map(|spell| {
            let mut iter = spell.split_whitespace();
            let t = iter.next().unwrap().chars().next().unwrap();
            let d = iter.next().unwrap().chars().next().unwrap();
            (t, d)
        })
        .collect();

    let mut indices = Vec::with_capacity(s.len());
    let mut golems = vec![1_u32; s.len()];
    for (t, d) in spells.into_iter() {
        s.chars()
            .enumerate()
            .map(|(i, s)| if s == t { indices.push(i); });

        indices
            .iter()
            .map(|&index| {
                match d {
                    'R' => {
                        if index != s.len() - 1 {
                            golems[index+1] += golems[index];
                        }
                        golems[index] = 0;
                    }
                    'L' => {
                        if index != 0 {
                            golems[index-1] += golems[index];
                        }
                        golems[index] = 0;
                    }
                    e @ _ => panic!("unexpected char '{}'", e),
                }
            });

        indices.clear();

    }

    println!("{}", golems.iter().sum::<u32>());
}

