}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};
    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    use std::collections::HashMap;
    input! {
        n: usize,
        q: usize,
        s: chars,
        td: [[char;2];q]
    }
    let mut m = HashMap::new();
    for (i, c) in s.iter().enumerate() {
        m.entry(c).or_insert(vec![]).push(i);
    }
    let mut o = vec![];
    for _ in 0..n {
        o.push(1 as i32);
    }
    for td in td {
        let t = td[0];
        let d = td[1];
        if let Some(v) = m.get(&t) {
            for v in v {
                if o[*v] == 0 {
                    continue;
                }
                if d == 'L' {
                    let a = o[*v];
                    o[*v] = 0;
                    if *v != 0 {
                        o[*v - 1] += a;
                    }
                } else {
                    let a = o[*v];
                    o[*v] = 0;
                    if *v + 1 < n {
                        o[*v + 1] += a;
                    }
                }
            }
        }
    }
    let mut count = 0;
    for i in o {
        count += i
    }
    println!("{}", count)
}

