fn main() {
    let line = read_vector::<usize>();
    let (n, q) = (line[0], line[1]);
    let s = read_chars();
    let mut operation = vec![];
    for _ in 0..q {
        let line = read_chars();
        operation.push((line[0], line[2]));
    }
    let mut left = -1;
    let mut max_right = -1;
    let mut right = n as i32;
    let mut min_left = n as i32;
    for i in (0..q).rev() {
        if operation[i].1 == 'L' {
            if left + 1 < n as i32 {
                let index = (left + 1) as usize;
                if s[index] == operation[i].0 {
                    left = index as i32;
                    max_right = max(max_right, left);
                }
            }
            if right + 1 < n as i32 {
                let index = (right + 1) as usize;
                if s[index] == operation[i].0 {
                    right = index as i32
                }
            }
        } else {
            if left - 1 >= 0 {
                let index = (left - 1) as usize;
                if s[index] == operation[i].0 {
                    left = index as i32;
                }
            }
            if right - 1 >= 0 {
                let index = (right - 1) as usize;
                if s[index] == operation[i].0 {
                    right = index as i32;
                    min_left = min(min_left, right);
                }
            }
        }
    }

    println!("{}", n as i32 - min(max_right + 1 + n as i32 - min_left, n as i32));
}

