fn solve_left(s: &Vec<char>, queries: &Vec<(char, char)>, mut idx: usize) -> bool {
    let n = s.len();
    for &(c, lr) in queries {
        if s[idx] == c {
            if lr == 'L' {
                if idx == 0 {
                    return true;
                }
                idx -= 1;
            } else {
                if idx == n-1 {
                    return false;
                }
                idx += 1;
            }
        }
    }
    false
}


fn solve_right(s: &Vec<char>, queries: &Vec<(char, char)>, mut idx: usize) -> bool {
    let n = s.len();
    for &(c, lr) in queries {
        if s[idx] == c {
            if lr == 'L' {
                if idx == 0 {
                    assert!(false, "Cannot be here");
                }
                idx -= 1;
            } else {
                if idx == n-1 {
                    return true;
                }
                idx += 1;
            }
        }
    }
    false
}

fn main() {
    input! {
        n: usize, q: usize,
        s: chars,
        queries: [(char, char); q]
    };
    let mut fallen = 0;

    // 1 to n
    let mut ok = 0;
    let mut ng = n+1;
    while ng - ok > 1 {
        let med = (ok + ng) / 2;
        if solve_left(&s, &queries, med-1) {
            ok = med;
        } else {
            ng = med;
        }
    }
    fallen = ok;

    let mut ng = ok;
    let mut ok = n+1;
    while ok - ng > 1 {
        let med = (ok + ng) / 2;
        if solve_right(&s, &queries, med-1) {
            ok = med;
        } else {
            ng = med;
        }
    }
    fallen += (n+1)-ok;

    println!("{}", n-fallen);
}

use std::io;

fn main() {
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    let q_len = {
        let mut n_and_q = buf.split_whitespace();
        n_and_q.next().unwrap();
        n_and_q.next().unwrap().parse::<usize>().unwrap()
    };

    buf.clear();
    io::stdin().read_line(&mut buf).unwrap();
    buf.pop().unwrap();
    let s = buf;

    let mut spells = vec![String::new(); q_len];
    for spell in spells.iter_mut() {
        io::stdin().read_line(spell).unwrap();
    }

    let spells: Vec<_> = spells
        .into_iter()
        .map(|spell| {
            let mut iter = spell.split_whitespace();
            let t = iter.next().unwrap().chars().next().unwrap();
            let d = iter.next().unwrap().chars().next().unwrap();
            (t, d)
        })
        .collect();

    let mut indices = Vec::with_capacity(s.len());
    let mut golems = vec![1_u32; s.len()];
    for (t, d) in spells.into_iter() {
        for (i, s) in s.chars().enumerate() {
            if s == t { indices.push(i); }
        }

        for &index in indices.iter() {
            match d {
                'R' => {
                    if index != s.len() - 1 {
                        golems[index+1] += golems[index];
                    }
                    golems[index] = 0;
                }
                'L' => {
                    if index != 0 {
                        golems[index-1] += golems[index];
                    }
                    golems[index] = 0;
                }
                e @ _ => panic!("unexpected char '{}'", e),
            }
        }

        indices.clear();
    }

    println!("{}", golems.iter().sum::<u32>());
}

