const CUSTOM_STACK_SIZE_MEBIBYTES: Option<usize> = None;

fn main() {
  fn exec_solver() {
    let stdin = std::io::stdin();
    let stdout = std::io::stdout();
    #[cfg(not(debug_assertions))]
    let mut writer = std::io::BufWriter::new(stdout.lock());
    #[cfg(debug_assertions)]
    let mut writer = stdout.lock();
    solve(stdin.lock(), &mut writer);
    writer.flush().unwrap();
  }

  if let Some(stack_size_mebibytes) = CUSTOM_STACK_SIZE_MEBIBYTES {
    std::thread::Builder::new()
      .name("exec_solver".to_owned())
      .stack_size(stack_size_mebibytes * 1024 * 1024)
      .spawn(exec_solver)
      .unwrap()
      .join()
      .unwrap();
  } else {
    exec_solver();
  }
}

fn solve<R: BufRead, W: Write>(reader: R, mut writer: W) {
  let mut _scanner = spella::io::Scanner::new(reader);

  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.next::<$T>().unwrap().unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($($T:ty),+; $n:expr $(; $m:expr)*) => {{
      (0..$n).map(|_| scan!($($T),+ $(; $m)*)).collect::<Vec<_>>()
    }};
  }

  #[allow(unused_macros)]
  macro_rules! scan_iter {
    ($T:ty; $n:expr) => {
      (0..$n).map(|_| scan!($T))
    };
  }

  #[allow(unused_macros)]
  macro_rules! print {
    ($fmt:expr) => {
      write!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      write!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! println {
    ($fmt:expr) => {
      writeln!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      writeln!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprint {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprintln {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! dbg {
    ($($x:expr),+) => {{
      eprint!("[{}:{}] ", file!(), line!());
      eprintln!(concat!($(stringify!($x), " = {:?}; "),+), $($x),+);
    }};
  }

  let (_n, q) = scan!(usize, usize);
  let s = scan!(ByteString);

  let mut s = s.into_byte_chars();
  s.insert(0, ByteChar::new(b' '));
  s.push(ByteChar::new(b' '));
  let s = ByteString::from(s);

  let mut l_map = HashMap::<ByteChar, HashMap<ByteChar, usize>>::new();
  let mut r_map = HashMap::<ByteChar, HashMap<ByteChar, usize>>::new();
  let mut cnt_map = HashMap::<ByteChar, usize>::new();

  let alphabets = || (b'A'..b'Z' + 1).chain(iter::once(b' ')).map(ByteChar::new);

  for c in alphabets() {
    cnt_map.insert(c, 0);
    l_map.insert(c, HashMap::new());
    r_map.insert(c, HashMap::new());
    for c2 in alphabets() {
      l_map.get_mut(&c).unwrap().insert(c2, 0);
      r_map.get_mut(&c).unwrap().insert(c2, 0);
    }
  }

  for i in 1..s.len() - 1 {
    *l_map.get_mut(&s[i]).unwrap().get_mut(&s[i - 1]).unwrap() += 1;
  }
  for i in 1..s.len() - 1 {
    *r_map.get_mut(&s[i]).unwrap().get_mut(&s[i + 1]).unwrap() += 1;
  }
  for i in 0..s.len() {
    *cnt_map.get_mut(&s[i]).unwrap() += 1;
  }

  dbg!(l_map, r_map, cnt_map);

  for _ in 0..q {
    let (t, d) = scan!(ByteChar, ByteChar);

    match d.into_byte() {
      b'L' => {
        dbg!(t, d);
        for (&l_c, &cnt) in l_map[&t].iter() {
          dbg!(l_c, cnt);
          let cnt = cnt_map[&t] * cnt;
          dbg!(cnt);
          *cnt_map.get_mut(&t).unwrap() -= cnt;
          *cnt_map.get_mut(&l_c).unwrap() += cnt;
        }
      }
      b'R' => {
        dbg!(t, d);
        for (&r_c, &cnt) in r_map[&t].iter() {
          dbg!(r_c, cnt);
          let cnt = cnt_map[&t] * cnt;
          dbg!(cnt);
          *cnt_map.get_mut(&t).unwrap() -= cnt;
          *cnt_map.get_mut(&r_c).unwrap() += cnt;
        }
      }
      _ => unreachable!(),
    }

    dbg!(cnt_map);
  }

  let ans = cnt_map
    .iter()
    .filter(|&(&c, _)| c.into_byte() != b' ')
    .map(|(_, &cnt)| cnt)
    .sum::<usize>();

  println!("{}", ans);
}

