    let s: Vec<char> = sc.cin::<String>().chars().collect();
    let qs: Vec<(char, char)> = (0..q).map(|_|
        (sc.cin::<String>().chars().nth(0).unwrap(),
         sc.cin::<String>().chars().nth(0).unwrap())).collect();

    // for p in 0..n { trace!(simu(&s, p, &qs)); }

    if simu(&s, n - 1, &qs) == Limit::Left {
        put!(0);
        return;
    }
    if simu(&s, 0, &qs) == Limit::Right {
        put!(0);
        return;
    }

    let mut a0 = 0;  // most left alive
    {
        if simu(&s, 0, &qs) == Limit::Alive {
            a0 = 0;
        } else { // bisec
            let mut left = 0;
            let mut right = n - 1;
            for _ in 0..1000 {
                let mid = (left + right) / 2;
                if simu(&s, mid, &qs) == Limit::Left {
                    left = mid;
                } else {
                    right = mid;
                }
            }
            a0 = right;
        }
    }
    // trace!(a0);

    let mut a1 = n-1; // most right alive
    {
        if simu(&s, n-1, &qs) == Limit::Alive {
            a1 = n - 1;
        } else { //bisec
            let mut left = 0;
            let mut right = n-1;
            for _ in 0..1000 {
                let mid = (left + right) / 2;
                if simu(&s, mid, &qs) == Limit::Right {
                    right = mid;
                } else {
                    left = mid;
                }
            }
            a1 = left;
        }
    }
    // trace!(a1);

    put!(a1 - a0 + 1);
}

