fn main() {
    let (N, Q) = get!(usize, usize);
    let S = get!(String).chars().collect();
    let TD = get!(char, char; Q);

    let mut ok: isize = -1;
    let mut ng: isize = N as isize;

    while ng - ok > 1 {
        let mid: isize = (ok + ng) / 2;
        if isOkLeft(N, &S, mid, &TD) {
            ok = mid;
        } else {
            ng = mid
        }
    }

    let mut ans: isize = ng;
    ok = N as isize;
    ng = -1 as isize;

    while ok - ng > 1 {
        let mid: isize = (ok + ng) / 2;
        if isOkRight(N, &S, mid, &TD) {
            ok = mid;
        } else {
            ng = mid;
        }
    }

    ans += (N as isize) - ok;
    println!("{}", N - (ans as usize));
}

fn isOkLeft(N: usize, S: &Vec<char>, mid: isize, TD: &Vec<(char, char)>) -> bool {
    let mut now: isize = mid as isize;

    for td in TD.iter() {
        if S[now as usize] == td.0 {
            if td.1 == 'L' {
                now -= 1;
            } else {
                now += 1;
            }
        }

        if now < 0 {
            return true;
        }
    }

    false
}

fn isOkRight(N: usize, S: &Vec<char>, mid: isize, TD: &Vec<(char, char)>) -> bool {
    let mut now: isize = mid as isize;

    for td in TD.iter() {
        if S[now as usize] == td.0 {
            if td.1 == 'L' {
                now -= 1;
            } else {
                now += 1;
            }
        }

        if (now as usize) >= N {
            return true;
        }
    }

    false
}

