#[derive(PartialEq, Eq, Debug)]
enum Limit { Left, Alive, Right }

fn simu(s: &Vec<char>, i: usize, qs: &Vec<(char, char)>) -> Limit {
    let mut pos = i;
    for &(a, d) in qs.iter() {
        if s[pos] != a { continue }
        if d == 'L' {
            if pos == 0 {
                return Limit::Left
            }
            pos -= 1;
        } else {
            if pos == s.len() - 1 {
                return Limit::Right
            }
            pos += 1
        }
    }
    Limit::Alive
}

