    let s: String = input!(r, String);
    use std::collections::HashMap;
    let mut hm: HashMap<char, Vec<usize>> = HashMap::with_capacity(27);
    for (idx, c) in s.char_indices() {
        let mut en = hm.entry(c).or_insert(vec![]);
        en.push(idx);
    }
    let mut gorems: Vec<usize> = vec![1; n];
    for _ in 0..q {
        let (c, dir): (String, String) = input!(r, String, String);
        let (c, dir): (char, char) = (c.chars().nth(0).unwrap(), dir.chars().nth(0).unwrap());
        let tiles: &Vec<usize> = hm.get(&c).unwrap();
        let moved_gorems: Vec<(usize, usize)> = tiles.iter().map(|&i| (i, gorems[i])).collect();
        for m in &moved_gorems {
            gorems[m.0] = 0;
        }
        if dir == 'L' {
            for m in moved_gorems {
                if m.0 == 0 {
                    continue;
                }
                gorems[m.0 - 1] += m.1;
            }
        } else if dir == 'R' {
            for m in moved_gorems {
                if m.0 == n - 1 {
                    continue;
                }
                gorems[m.0 + 1] += m.1;
            }
        }
    }
    println!("{}", gorems.into_iter().sum::<usize>());
}

