#[derive(PartialEq, Debug)]
enum GolemStat {
    Alive,
    DeadLeft,
    DeadRight,
}

// Pマス目のゴーレムが生き残るかチェックする。
fn check_golem_stat(
    mut p: usize,
    n: usize,
    s: &Vec<char>,
    spells: &Vec<Spell>
) -> GolemStat {
    for &Spell{t, d} in spells.iter() {
        if t != s[p] {
            continue;
        }

        if p == 0 && d == 'L' {
            return GolemStat::DeadLeft;
        }
        if p == n-1 && d == 'R' {
            return GolemStat::DeadRight;
        }

        p = if d == 'L' {p-1} else {p+1};
    }

    GolemStat::Alive
}

