        let _: char = iter.next().unwrap();
        let d: char = iter.next().unwrap();

        spells.push(Spell{t: t, d: d});
    }

    /*
    for i in 0..n {
        println!("{}:{:?}", i, check_golem_stat(i, n, &s, &spells));
    }
    // */

    let mut lb = -1;
    let mut ub = n as isize;
    while ub - lb > 1 {
        let mid = (lb + ub) / 2;
        // println!("lb:{}, ub:{}, mid:{}", lb, ub, mid);
        let stat = check_golem_stat(mid as usize, n, &s, &spells);
        if stat == GolemStat::DeadLeft {
            lb = mid as isize;
        }
        else {
            ub = mid as isize;
        }
    }
    let dead_left = (lb + 1) as usize;

    let mut lb = -1;
    let mut ub = n as isize;
    while ub - lb > 1 {
        let mid = (lb + ub) / 2;
        // println!("lb:{}, ub:{}, mid:{}", lb, ub, mid);
