});

fn reaches(mut i: usize, dest: usize, s: &[char], moves: &[Move]) -> bool {
    for &m in moves {
        if s[i] == m.ch {
            i = (i as isize + m.delta) as usize;
        }
    }
    i == dest
}

fn find_left(s: &[char], moves: &[Move]) -> usize {
    let mut l = 0;
    let mut r = s.len() - 1;
    while r-l > 1 {
        let mid = (l+r) / 2;
        if reaches(mid, 0, s, moves) {
            l = mid;
        } else {
            r = mid;
        }
    }
    l
}

fn find_right(s: &[char], moves: &[Move]) -> usize {
    let mut l = 0;
    let mut r = s.len() - 1;
    while r-l > 1 {
        let mid = (l+r) / 2;
        if reaches(mid, s.len() - 1, s, moves) {
            r = mid;
        } else {
            l = mid;
        }
    }
    r
}

