fn read_as_vec<T>() -> Vec<T>
where T: FromStr, <T as FromStr>::Err : Debug{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().split_whitespace().map(|c| T::from_str(c).unwrap()).collect()
}

fn read_as_string() -> String{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().to_string()
}

fn is_dead_left(s: &[char], spells: &[(char, char)], n: usize) -> bool{
    let mut current = n;
    for &(trout, mov) in spells{
        if trout == s[current]{
            if mov == 'L'{
                if current > 0{
                    current -= 1;
                }else{
                    return true;
                }
            }else{
                if current < s.len()-1{
                    current += 1;
                }else{
                    return false;
                }
            }
        }
    }
    return false;
}

fn is_dead_right(s: &[char], spells: &[(char, char)], n: usize) -> bool{
    let mut current = n;
    for &(trout, mov) in spells{
        if trout == s[current]{
            if mov == 'L'{
                if current > 0{
                    current -= 1;
                }else{
                    return false;
                }
            }else{
                if current < s.len()-1{
                    current += 1;
                }else{
                    return true;
                }
            }
        }
    }
    return false;
}

fn main(){
    let line: Vec<usize> = read_as_vec();
    let (n, q) = (line[0], line[1]);
    let s = read_as_string().chars().collect::<Vec<char>>();

    let mut spells: Vec<(char, char)> = vec![];

    for _ in 0..q{
        //let line: Vec<char> = read_as_vec();
        let line: Vec<char> = read_as_string().chars().filter(|c| *c != ' ').collect();
        spells.push((line[0], line[1]));
    }

    let mut lb = -1;
    let mut ub = n as i32;

    while lb+1 < ub{
        let mid = (ub+lb)/2;

        if is_dead_left(&s, &spells, mid as usize){
            lb = mid;
        }else{
            ub = mid;
        }
    }

    let left = lb;


    let mut lb = -1;
    let mut ub = n as i32;

    while lb+1 < ub{
        let mid = (ub+lb)/2;
        //println!("lb = {}, ub = {}, mid = {}", lb, ub, mid);
        if is_dead_right(&s, &spells, mid as usize){
            ub = mid;
        }else{
            lb = mid;
        }
    }
    let right = ub;

    println!("{}", right-left-1);


}

