fn f(s: &Vec<char>, qs: &Vec<(char, char)>, i: i64) -> i64 {
    if i < 0 {
        return -1;
    }
    if i >= s.len() as i64 {
        return 1;
    }
    let mut i = i;
    for &(t, d) in qs.iter() {
        if s[i as usize] == t && d == 'L' {
            if i == 0 {
                return -1;
            }
            i -= 1;
        } else if s[i as usize] == t && d == 'R' {
            if i as usize == s.len() - 1 {
                return 1;
            }
            i += 1;
        }
    }
    0
}

use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        q: usize,
        s: chars,
        qs: [(char1, char1); q],
    }
    // eprintln!("qs = {:?}", qs);
    let mut left = -1;
    for i in (0..40).rev() {
        let new_left = left + (1 << i);
        if f(&s, &qs, new_left) == -1 {
            left = new_left;
        }
    }
    let mut right = n as i64;
    for i in (0..40).rev() {
        let new_right = right - (1 << i);
        if f(&s, &qs, new_right) == 1 {
            right = new_right;
        }
    }
    // eprintln!("left = {}, right = {}", left, right);
    let res = right - left - 1;
    writeln!(buf, "{}", res);
    buf
}

fn escape(src: usize, n: usize, s: &Vec<char>, q: &Vec<(char, char)>) -> (bool, char) {
    let mut pos = src as i32;
    for &(t, d) in q.into_iter() {
        let p = s[pos as usize];
        if t == p {
            if d == 'L' {
                pos -= 1;
            } else {
                pos += 1;
            }
        }
        if pos < 0 {
            return (true, 'L');
        }
        if pos >= n as i32 {
            return (true, 'R');
        }
    }
    return (false, 'N');
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let q: usize = sc.read();
    let s = sc.chars();
    let td = (0..q).map(|_| {
        let t: char = sc.read();
        let d: char = sc.read();
        (t, d)
    }).collect::<Vec<(char, char)>>();

    let mut result = 0;
    {
        let mut left: i32 = -10;
        let mut right: i32 = n as i32 + 10;
        let mut tmp = 0;
        while right - left > 1 {
            let mut med = (right + left) / 2;
            if med < 0 {
                left = med;
                continue;
            }
            if med >= n as i32 {
                right = med;
                continue;
            }

            let res = escape(med as usize, n, &s, &td);
            if res.0 && res.1 == 'L' {
                left = med;
                tmp = (med + 1) as usize;
            } else {
                right = med;
            }
        }
        result += tmp;
    }

    {
        let mut left: i32 = -10;
        let mut right: i32 = n as i32 + 10;
        let mut tmp = 0;
        while right - left > 1 {
            let mut med = (right + left) / 2;
            if med < 0 {
                left = med;
                continue;
            }
            if med >= n as i32 {
                right = med;
                continue;
            }

            let res = escape(med as usize, n, &s, &td);
            if res.0 && res.1 == 'R' {
                right = med;
                tmp = (n as i32 - med) as usize;
            } else {
                left = med;
            }
        }
        result += tmp;
    }
    println!("{}", n - result);
}

