// A1 B1
// ...
// AQ BQ => let A = get!(usize, usize; Q)

fn main() {
    let (N, Q) = get!(usize, usize);
    let S = get!(String).chars().collect();
    let TD = get!(String, String; Q);

    let mut ok: isize = -1;
    let mut ng: isize = N as isize;
    while ng - ok > 1 {
        let mid: isize = (ok + ng) / 2;
        if isOkLeft(N, &S, mid, &TD) {
            ok = mid;
        } else {
            ng = mid
        }
    }
    let left: isize = ng;

    ok = N as isize;
    ng = -1 as isize;
    while ok - ng > 1 {
        let mid: isize = (ok + ng) / 2;
        if isOkRight(N, &S, mid, &TD) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    let right: isize = (N as isize) - ok;

    println!("{}", N - ((left + right) as usize));
}

fn isOkLeft(N: usize, S: &Vec<char>, mid: isize, TD: &Vec<(String, String)>) -> bool {
    let mut now: isize = mid as isize;

    for td in TD.iter() {
        if S[now as usize].to_string() == td.0 {
            if td.1 == "L" {
                now -= 1;
            } else {
                now += 1;
            }
        }

        if now < 0 {
            return true;
        }

        if (now as usize) >= N {
            return false;
        }
    }

    false
}

fn isOkRight(N: usize, S: &Vec<char>, mid: isize, TD: &Vec<(String, String)>) -> bool {
    let mut now: isize = mid as isize;

    for td in TD.iter() {
        if S[now as usize].to_string() == td.0 {
            if td.1 == "L" {
                now -= 1;
            } else {
                now += 1;
            }
        }

        if now < 0 {
            return false;
        }

        if (now as usize) >= N {
            return true;
        }
    }

    false
}

fn escape(src: usize, n: usize, s: &Vec<char>, q: &Vec<(char, char)>) -> (bool, char) {
    let mut pos = src as i32;
    for (t, d) in q.into_iter() {
        let p = s[pos as usize];
        if *t == p {
            if *d == 'L' {
                pos -= 1;
            } else {
                pos += 1;
            }
        }
        if pos < 0 {
            return (true, 'L');
        }
        if pos >= n as i32 {
            return (true, 'R');
        }
    }
    return (false, 'N');
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let q: usize = sc.read();
    let s = sc.chars();
    let td = (0..q).map(|_| {
        let t: char = sc.read();
        let d: char = sc.read();
        (t, d)
    }).collect::<Vec<(char, char)>>();

    let mut result = 0;
    {
        let mut left: i32 = -10;
        let mut right: i32 = n as i32 + 10;
        let mut tmp = 0;
        while right - left > 1 {
            let mut med = (right + left) / 2;
            if med < 0 {
                left = med;
                continue;
            }
            if med >= n as i32 {
                right = med;
                continue;
            }

            let res = escape(med as usize, n, &s, &td);
            if res.0 && res.1 == 'L' {
                left = med;
                tmp = (med + 1) as usize;
            } else {
                right = med;
            }
        }
        result += tmp;
    }

    {
        let mut left: i32 = -10;
        let mut right: i32 = n as i32 + 10;
        let mut tmp = 0;
        while right - left > 1 {
            let mut med = (right + left) / 2;
            if med < 0 {
                left = med;
                continue;
            }
            if med >= n as i32 {
                right = med;
                continue;
            }

            let res = escape(med as usize, n, &s, &td);
            if res.0 && res.1 == 'R' {
                right = med;
                tmp = (n as i32 - med) as usize;
            } else {
                left = med;
            }
        }
        result += tmp;
    }
    println!("{}", n - result);
}

