fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (n, q) = i.read2::<usize, usize>();
    let gs_last = n + 1;

    let mut gs = vec![1; n + 2];
    let mut table = vec![Vec::new(); 26];

    fn to_idx(c: u8) -> usize {
        (c - b'A') as usize
    }

    {
        let s = i.read_line().as_bytes();
        gs[0] = 0;
        gs[gs_last] = 0;

        for i in 0..n {
            table[to_idx(s[i])].push(i + 1);
        }
    }
    for _ in 0..q {
        let (t, d) = i.read2::<char, char>();
        let it = to_idx(t as u8);
        if d == 'L' {
            for &ig in &table[it] {
                gs[ig - 1] += gs[ig];
                gs[ig] = 0;
            }
        } else {
            for &ig in table[it].iter().rev() {
                gs[ig + 1] += gs[ig];
                gs[ig] = 0;
            }
        }
    }
    let ans = n - gs[0] - gs[gs_last];
    writeln!(o, "{}", ans).unwrap();
}

