// [l, r]
fn binary_search<F>(mut l: usize, mut r: usize, f: &F) -> Option<usize>
  where F: Fn(usize) -> bool
  {
    assert!(l <= r);
    r += 1;
    let r_bound = r;
    while r > l {
        let m = l + (r - l) / 2;  // avoid overflow
        if f(m) {
          r = m;
        } else {
          if l == m { break; }
          l = m;
        }
    }
    if r == r_bound { None } else { Some(r) }
}

fn main() {
    input!{
      n: usize,
      q: usize,
      s: chars,
      tds: [(chars, chars); q],
    }

    // 左に落ちるならfalse
    let f = |mut idx| {
        for i in 0..q {
            let t = tds[i].0[0];
            let d = tds[i].1[0];

            if s[idx] != t {
                continue;
            }
            if d == 'L' {
                if idx == 0 {
                    return false;
                }
                idx -= 1;
            } else {
                idx += 1;
            }
        }
        true
    };
    let left_index = binary_search(0, n-1, &f);


    // 右に落ちるならtrue
    let f = |mut idx| {
        for i in 0..q {
            let t = tds[i].0[0];
            let d = tds[i].1[0];

            if s[idx] != t {
                continue;
            }
            if d == 'L' {
                if idx == 0 {
                    return false;
                }
                idx -= 1;
            } else {
                idx += 1;
                if idx >= n {
                    return true;
                }
            }
        }
        false
    };
    let right_index = binary_search(0, n-1, &f);

    let mut ans = 0;
    if let Some(l) = left_index {
        ans += l;
    }
    if let Some(r) = right_index {
        ans += n-r;
    }
    println!("{}", n-ans);
}

