fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (_n, q) = i.read2::<usize, usize>();
    let s: Vec<_> = i.read_line().as_bytes().iter().cloned().collect();
    let mut td = Vec::new();

    for _ in 0..q {
        let mut tdi = i.read_line().split(' ');
        let t = tdi.next().unwrap().as_bytes()[0];
        let d = tdi.next().unwrap().as_bytes()[0];
        let d = if d == b'L' { Dir::L } else { Dir::R };
        td.push((t, d));
    }
    let ans = solve(&s, &td);
    writeln!(o, "{}", ans).unwrap();
}
#[derive(Eq, PartialEq, Clone, Copy)]
enum Dir {
    L,
    R,
}
fn solve(s: &[u8], td: &[(u8, Dir)]) -> usize {
    let mut l = 0;
    let mut r = 0;
    for &(t, d) in td.iter().rev() {
        match d {
            Dir::L => {
                if s[l] == t {
                    l += 1;
                }
            }
            Dir::R => {
                if s[s.len() - r - 1] == t {
                    r += 1;
                }
            }
        }
        if l + r == s.len() {
            break;
        }
    }
    s.len() - (l + r)
}

