fn solve() {
    let (n, q) = get!(usize, usize);
    let s = get!(String).chars().collect::<Vec<_>>();
    let tdt = get!(String, String; q);
    let mut td = Vec::new();
    for (t, d) in tdt {
        td.push((t.into_bytes()[0] as char, d.into_bytes()[0] as char));
    }

    let mut l = 0;
    let mut count = 0;
    let mut tmp = 0;
    for (i, &(t, d)) in td.iter().enumerate().rev() {
        if d =='L' && s[l] == t {
            count += 1;
            l += 1;
            tmp = i;
            if l == n-1 {
                break;
            }
        }
    }

    if l > 0 {
        let mut tcount = 0i64;
        for i in (0..tmp).rev() {
            if td[i].0 == s[l-1] {
                if td[i].1 == 'R'{
                    tcount -= 1;
                } else {
                    tcount += 1;
                }
            }
        }
        if tcount < 0 {
            count -= 1;
        }
    }

    let mut r = n-1;
    tmp = 0;
    for (i, &(t, d)) in td.iter().enumerate().rev() {
        if d == 'R' && s[r] == t {
            count += 1;
            r -= 1;
            tmp = i;
            if r == 0 {
                break;
            }
        }
    }

    if r < n-1 {
        let mut tcount = 0i64;
        for i in (0..tmp).rev() {
            if td[i].0 == s[r+1] {
                if td[i].1 == 'L' {
                    tcount -= 1;
                } else {
                    tcount += 1;
                }
            }
        }
        if tcount < 0 {
            count -= 1;
        }
    }

    println!("{}", n-count);
}

