    let mut r = StdinReader::new(handle.lock());
    let (n, q): (usize, usize) = input!(r, usize, usize);
    let mut s: VecDeque<char> = input!(r, String).chars().collect();
    let mut magics: Vec<(char, char)> = vec![];
    let mut nf = UnionFind::new(n+2);
    for _ in 0..q {
        let magic: (char, char) = to_char(input!(r, String, String));
        magics.push(magic);
    }

    let mut dame_l = false;
    let mut dame_r = false;
    for m in magics.into_iter().rev() {
        if m.1 == 'L' {
            let mut is_delete = false;
            if let Some(&f) = s.front() {
                if f == m.0 && !dame_l {
                    is_delete = true;
                } else if let Some(&b) = s.back() {
                    if b == m.0 {
                        dame_l = true;
                    }
                }
            }
            if is_delete && !dame_l { s.pop_front(); }
        } else if m.1 == 'R' {
            let mut is_delete = false;
            if let Some(&b) = s.back() {
                if b == m.0 {
                    is_delete = true;
                } else if let Some(&f) = s.front() {
                    if f == m.0 {
                        dame_r = true;
                    }
                }
            }
            if is_delete && !dame_r { s.pop_back(); }
        }
    }
