#[derive(Clone, Copy)]
struct Move {
    ch: char,
    delta: isize
}

readable!(Move, 2, |ws| Move {
    ch: ws[0].chars().next().unwrap(),
    delta: if ws[1].chars().next().unwrap() == 'L' { -1 } else { 1 }
});

fn main() {
    read!();
    read!(s = String);
    let s = s.chars().collect::<Vec<_>>();
    let moves = readx::<Move>();
    let initial_range = moves
        .into_iter()
        .rev()
        .fold(Some((0, s.len()-1)), |range, m| {
            range.and_then(|(l, r)| {
                if s[l] == m.ch && m.delta < 0 {
                    if l < r { Some((l+1, r)) } else { None }
                } else if s[r] == m.ch && m.delta > 0 {
                    if l < r { Some((l, r-1)) } else { None }
                } else {
                    Some((l, r))
                }
            })
        });
    let ans = initial_range.map(|(l, r)| r - l + 1).unwrap_or(0);
    println!("{}", ans);
}
